function normalizeOutreachChannel(value: unknown) {
  const channel = cleanText(value)?.toLowerCase() || "";
  if (["email", "whatsapp", "whatsapp_group"].includes(channel)) return channel;
  if (!channel || channel === "all") return "";
  return "";
}
