function applyRateSearchFilter(query: any, search: string) {
  const term = cleanText(search);
  if (!term) return query;
  return query.or(RATE_SEARCH_COLUMNS.map((field) => `${field}.ilike.%${term}%`).join(","));
}

function bulkNumericValue(value: unknown) {
  const cleaned = cleanRateText(value);
  if (!cleaned) return null;
  const number = Number(cleaned);
  return Number.isFinite(number) ? number : null;
}

function bulkHasNumericValue(value: unknown) {
  const number = bulkNumericValue(value);
  return number !== null && number > 0;
}

function bulkHasSplitRate(row: Record<string, unknown>) {
  return ["mx_linehaul", "us_linehaul", "fsc", "border_crossing_fee"].some((field) => bulkHasNumericValue(row[field]));
}

function bulkNeedsNumericRate(row: Record<string, unknown>) {
  return !bulkHasNumericValue(row.all_in_rate) && !bulkHasNumericValue(row.mx_linehaul) && !bulkHasNumericValue(row.us_linehaul);
}

function bulkNeedsLocationMatch(row: Record<string, unknown>) {
  const originMatched = Boolean(row.origin_market || row.origin_zip_prefix || row.origin_state || row.origin_country);
  const destinationMatched = Boolean(row.destination_market || row.destination_zip_prefix || row.destination_state || row.destination_country);
  return !originMatched || !destinationMatched;
}

function bulkHasVendorMatch(row: Record<string, unknown>) {
  return Boolean(cleanText(row.vendor_id));
}

function bulkHasAllInText(row: Record<string, unknown>) {
  return /[a-z]/i.test(String(row.all_in_rate || ""));
}

function bulkSplitRateTotal(row: Record<string, unknown>) {
  const values = ["mx_linehaul", "us_linehaul", "fsc", "border_crossing_fee"]
    .map((field) => bulkNumericValue(row[field]))
    .filter((value): value is number => value !== null && value > 0);
  if (!values.length) return null;
  return values.reduce((sum, value) => sum + value, 0);
}

function bulkHasSplitAllInConflict(row: Record<string, unknown>) {
  const allIn = bulkNumericValue(row.all_in_rate);
  const splitTotal = bulkSplitRateTotal(row);
  if (allIn === null || splitTotal === null || allIn <= 0 || splitTotal <= 0) return false;
  return Math.abs(allIn - splitTotal) > Math.max(25, allIn * 0.05);
}

function bulkServiceModeKey(value: unknown) {
  const text = catalogKey(value).toLowerCase();
  if (/\b(rt|round trip|roundtrip|round)\b/.test(text)) return "roundtrip";
  if (/\b(ow|one way|oneway)\b/.test(text)) return "oneway";
  return "";
}

function bulkHasSourceServiceConflict(row: Record<string, unknown>) {
  const evidence = objectRecord(row.source_evidence);
  const sourceMode = bulkServiceModeKey([evidence.service, evidence.lane, evidence.source_service].filter(Boolean).join(" "));
  const stagedMode = bulkServiceModeKey(row.service);
  return Boolean(sourceMode && stagedMode && sourceMode !== stagedMode);
}

function bulkHasCurrencyGap(row: Record<string, unknown>) {
  return (bulkHasNumericValue(row.all_in_rate) || bulkHasSplitRate(row)) && !cleanText(row.currency);
}

function bulkHasReviewConflict(row: Record<string, unknown>) {
  return bulkHasAllInText(row) || bulkHasSplitAllInConflict(row) || bulkHasSourceServiceConflict(row) || bulkHasCurrencyGap(row) || !cleanText(row.operation) || !cleanText(row.service);
}

function bulkHasSourceAuditIssue(row: Record<string, unknown>) {
  const confidence = objectRecord(row.field_confidence);
  return (Array.isArray(row.audit_flags) && row.audit_flags.length > 0)
    || (Array.isArray(row.extraction_warnings) && row.extraction_warnings.length > 0)
    || Object.values(confidence).some((value) => Number(value) < 0.75);
}

function bulkIsReadyForApproval(row: Record<string, unknown>) {
  return !bulkNeedsNumericRate(row)
    && !bulkHasAllInText(row)
    && !bulkNeedsLocationMatch(row)
    && bulkHasVendorMatch(row)
    && Boolean(cleanText(row.quote_date))
    && Boolean(cleanText(row.operation))
    && Boolean(cleanText(row.service))
    && !bulkHasReviewConflict(row);
}

function bulkColumnText(row: Record<string, unknown>, field: string) {
  if (field === "vendor") return [row.vendor_domain].filter(Boolean).join(" ");
  if (field === "origin") {
    return [
      row.origin,
      row.normalized_origin,
      row.origin_city,
      row.origin_state,
      row.origin_zip_prefix,
      row.origin_market,
      row.origin_region,
      row.origin_country
    ].filter(Boolean).join(" ");
  }
  if (field === "destination") {
    return [
      row.destination,
      row.normalized_destination,
      row.destination_city,
      row.destination_state,
      row.destination_zip_prefix,
      row.destination_market,
      row.destination_region,
      row.destination_country
    ].filter(Boolean).join(" ");
  }
  return String(row[field] ?? "");
}

function bulkColumnValues(row: Record<string, unknown>, field: string) {
  const vendor = objectRecord(row.vendors);
  if (field === "vendor") return [vendor.vendor_name, row.vendor_domain, vendor.domain].filter(Boolean);
  if (field === "hazmat" || field === "temperature_controlled") return [row[field] ? "Yes" : "No"];
  if (field === "origin") {
    return [
      row.origin,
      row.normalized_origin,
      row.origin_city,
      row.origin_state,
      row.origin_zip_prefix,
      row.origin_market,
      row.origin_region,
      row.origin_country
    ].filter(Boolean);
  }
  if (field === "destination") {
    return [
      row.destination,
      row.normalized_destination,
      row.destination_city,
      row.destination_state,
      row.destination_zip_prefix,
      row.destination_market,
      row.destination_region,
      row.destination_country
    ].filter(Boolean);
  }
  return [row[field]].filter(Boolean);
}

function objectRecord(value: unknown): Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

function relationRecord(value: unknown): Record<string, unknown> {
  if (Array.isArray(value)) return objectRecord(value[0]);
  return objectRecord(value);
}

const OUTREACH_MESSAGE_SELECT = "*, vendors(vendor_name,domain,primary_email,whatsapp_phone,whatsapp_group_name,whatsapp_group_url,whatsapp_group_status,whatsapp_do_not_contact), vendor_whatsapp_groups(group_name,group_url,verification_status,do_not_contact), outreach_campaigns(name,notes,whatsapp_target_mode,group_delivery_policy), rfx_events(rfx_id,name), rfx_lanes(origin,destination,equipment,trailer,operation,service), rfx_lane_vendors(id,invitation_status,invitation_token,invitation_token_encrypted,award_role,bid_rate,currency,responded_at)";
const OUTREACH_MESSAGE_COMPACT_SELECT = "id,created_at,updated_at,campaign_id,template_id,rfx_event_id,rfx_lane_id,rfx_lane_vendor_id,vendor_id,channel,recipient_email,recipient_phone,subject,gmail_compose_url,whatsapp_url,status,sent_at,last_contacted_at,metadata,sender_email,sender_label,sender_connection_status,provider_message_id,delivery_error,delivered_by,bounce_detected_at,bounce_status,whatsapp_target_mode,whatsapp_connection_id,normalized_recipient_phone,vendor_whatsapp_group_id,provider,meta_whatsapp_group_id,whatsapp_template_name,whatsapp_template_language,delivery_status,delivered_at,read_at,failed_at,manual_sent_at,manual_sent_by,ratebook_share_id,send_attempt_id,send_started_at,send_completed_at,gmail_connection_id,sender_address,sender_connection_type,provider_response_status,contact_key,outcome_reason,next_action,next_action_at,suppressed_at,suppression_reason,organization_id, vendors(vendor_name,domain,primary_email,whatsapp_phone,whatsapp_group_name,whatsapp_group_url,whatsapp_group_status,whatsapp_do_not_contact), vendor_whatsapp_groups(group_name,group_url,verification_status,do_not_contact), outreach_campaigns(name,whatsapp_target_mode,group_delivery_policy), rfx_events(rfx_id,name), rfx_lanes(origin,destination,equipment,trailer,operation,service), rfx_lane_vendors(id,invitation_status,award_role,bid_rate,currency,responded_at)";
const OUTREACH_MESSAGE_EVENT_SELECT = "id,created_at,updated_at,campaign_id,template_id,rfx_event_id,rfx_lane_id,rfx_lane_vendor_id,vendor_id,channel,recipient_email,recipient_phone,subject,status,sent_at,last_contacted_at,metadata,sender_email,provider_message_id,delivery_error,bounce_detected_at,bounce_status,delivery_status,delivered_at,read_at,failed_at,manual_sent_at,provider_response_status,contact_key,outcome_reason,next_action,next_action_at,suppressed_at,suppression_reason";
const OUTREACH_TRACKING_STATES = ["drafted", "queued", "sending", "sent", "delivered", "read", "manual_sent", "delivery_unknown", "failed", "replied", "quoted", "bounced", "suppressed", "archived"] as const;
type OutreachTrackingState = typeof OUTREACH_TRACKING_STATES[number];
const OUTREACH_SENT_OR_RESOLVED_STATUSES = new Set(["sent", "delivered", "read", "replied", "quoted", "manual_sent"]);
const OUTREACH_DO_NOT_AUTO_REQUEUE_STATUSES = new Set(["queued", "sending", "delivery_unknown", "failed", "bounced", ...OUTREACH_SENT_OR_RESOLVED_STATUSES]);
const OUTREACH_AUDIENCE_MODES = new Set(["all_eligible", "saved_segment", "selected_carriers"]);
const OUTREACH_SEQUENCE_MODES = new Set(["manual", "email_then_whatsapp"]);

function normalizeOutreachTrackingStatus(value: unknown): OutreachTrackingState | null {
  const normalized = cleanText(value)?.toLowerCase();
  return OUTREACH_TRACKING_STATES.includes(normalized as OutreachTrackingState) ? normalized as OutreachTrackingState : null;
}

function outreachMessageTrackingState(message: Record<string, unknown>): OutreachTrackingState {
  const metadata = objectRecord(message.metadata);
  const invitation = relationRecord(message.rfx_lane_vendors);
  const invitationStatus = cleanText(invitation.invitation_status)?.toLowerCase() || "";
  // An empty numeric field must not become zero and look like a submitted quote.
  // Supabase commonly returns an unfilled bid as null, but imports and older rows
  // can contain an empty string.
  const hasBid = hasSubmittedCarrierBid(invitation.bid_rate);
  // Legacy rows can carry a quoted-like invitation state with a default zero
  // rate. A carrier only becomes quoted when Rateware has an actual positive
  // all-in amount to compare and award.
  if (hasBid) return "quoted";
  const signal = [
    message.status,
    message.provider_response_status,
    message.delivery_error,
    metadata.delivery_status,
    metadata.provider_response_status,
    metadata.last_event
  ].map((value) => String(value || "").toLowerCase()).join(" ");
  if (/archived/.test(signal)) return "archived";
  if (/suppressed|do_not_contact|do-not-contact|blocked contact/.test(signal)) return "suppressed";
  if (/bounc|mailer-daemon|undeliverable/.test(signal)) return "bounced";
  if (/failed|error|rejected/.test(signal)) return "failed";
  if (["replied", "responded", "quoted", "bid_submitted", "awarded", "award_pending"].includes(invitationStatus) || invitation.responded_at || /replied|responded/.test(signal)) return "replied";
  if (/manual_sent/.test(signal)) return "manual_sent";
  if (/delivery_unknown/.test(signal)) return "delivery_unknown";
  if (/read/.test(signal)) return "read";
  if (/delivered/.test(signal)) return "delivered";
  if (/sending/.test(signal)) return "sending";
  if (/queued/.test(signal)) return "queued";
  if (/sent|accepted/.test(signal)) return "sent";
  return "drafted";
}

function outreachDedupeContactKey(message: Record<string, unknown>) {
  const vendorId = cleanText(message.vendor_id);
  const email = cleanText(message.recipient_email)?.toLowerCase();
  const phone = phoneForWhatsapp(message.normalized_recipient_phone || message.recipient_phone);
  if (vendorId && email) return `vendor:${vendorId}|email:${email}`;
  if (vendorId && phone) return `vendor:${vendorId}|phone:${phone}`;
  if (vendorId) return `vendor:${vendorId}`;
  if (email) return `email:${email}`;
  if (phone) return `phone:${phone}`;
  return "";
}

function outreachEventDedupeKey(message: Record<string, unknown>) {
  const eventId = cleanText(message.rfx_event_id);
  const channel = cleanText(message.channel)?.toLowerCase();
  const contactKey = outreachDedupeContactKey(message);
  return eventId && channel && contactKey ? `${eventId}|${channel}|${contactKey}` : "";
}

function outreachHistoryByContact(rows: Record<string, unknown>[]) {
  const index = new Map<string, Record<string, unknown>>();
  for (const row of rows) {
    if (!outreachBlocksAutoDraft(row)) continue;
    const key = outreachEventDedupeKey(row);
    if (key && !index.has(key)) index.set(key, row);
  }
  return index;
}

function firstEligibleOutreachEmail(
  vendor: Record<string, unknown>,
  suppressedEmails: Set<string>,
  eventId: string,
  vendorId: string,
  historyByContact = new Map<string, Record<string, unknown>>()
) {
  for (const email of vendorContactEmailCandidates(vendor)) {
    if (suppressedEmails.has(email)) continue;
    const history = historyByContact.get(outreachEventDedupeKey({
      rfx_event_id: eventId,
      channel: "email",
      vendor_id: vendorId,
      recipient_email: email
    }));
    if (!history || !outreachBlocksAutoDraft(history)) return email;
  }
  return "";
}

function outreachBlocksAutoDraft(message: Record<string, unknown>) {
  const status = cleanText(message.status)?.toLowerCase() || "";
  const trackingState = outreachMessageTrackingState(message);
  return OUTREACH_DO_NOT_AUTO_REQUEUE_STATUSES.has(status) || ["queued", "sending", "sent", "delivered", "read", "manual_sent", "delivery_unknown", "replied", "quoted", "failed", "bounced", "suppressed"].includes(trackingState);
}

function outreachAutoDraftSkipReason(message: Record<string, unknown>) {
  const status = cleanText(message.status)?.toLowerCase() || "";
  const trackingState = outreachMessageTrackingState(message);
  if (status === "bounced" || trackingState === "bounced") return "This contact bounced. Choose or add another valid carrier contact to create a recovery invitation.";
  if (trackingState === "suppressed") return "This contact is suppressed. Unsuppress it or choose another contact before creating a new invitation.";
  if (status === "failed" || trackingState === "failed") return "Previous delivery failed. Review or retry the existing contact instead of creating a duplicate invitation.";
  if (["queued", "sending"].includes(status)) return "Existing outreach send is already in progress for this contact.";
  if (status === "delivery_unknown") return "Previous outreach delivery is still unknown. Review it before sending again.";
  if (trackingState === "delivery_unknown") return "Previous outreach delivery is still unknown. Review it before sending again.";
  if (OUTREACH_SENT_OR_RESOLVED_STATUSES.has(status) || ["sent", "delivered", "read", "manual_sent", "replied", "quoted"].includes(trackingState)) {
    return "Already sent for this RFx, contact, and channel. Preserved to prevent a duplicate invitation.";
  }
  return "Existing outreach preserved to prevent duplicate carrier contact.";
}

function outreachNextAction(message: Record<string, unknown>) {
  const stored = cleanText(message.next_action);
  if (stored) return stored;
  const status = cleanText(message.status)?.toLowerCase() || "drafted";
  const tracking = outreachMessageTrackingState(message);
  if (status === "archived") return "No action";
  if (tracking === "bounced") return "Replace contact";
  if (tracking === "suppressed") return "Keep suppressed";
  if (tracking === "failed") return "Review delivery failure";
  if (tracking === "replied") return "Review reply";
  if (tracking === "quoted") return "Review quote";
  if (tracking === "delivery_unknown") return "Review delivery status";
  if (["sent", "delivered", "read", "manual_sent"].includes(tracking)) return "Await response";
  if (["queued", "sending"].includes(status)) return "Wait for delivery result";
  return "Review and send";
}

function outreachOutcomeReason(message: Record<string, unknown>) {
  const stored = cleanText(message.outcome_reason);
  if (stored) return stored;
  const status = cleanText(message.status)?.toLowerCase() || "drafted";
  const tracking = outreachMessageTrackingState(message);
  if (tracking === "bounced") return "Delivery bounced or address is no longer valid";
  if (tracking === "suppressed") return "Contact is suppressed and should not receive outreach";
  if (tracking === "failed") return "Provider rejected or failed to deliver the message";
  if (tracking === "quoted") return "Carrier submitted a bid";
  if (tracking === "replied") return "Carrier replied";
  if (tracking === "read") return "Carrier opened the WhatsApp message; awaiting carrier response";
  if (tracking === "manual_sent") return "Marked manually sent; awaiting carrier response";
  if (tracking === "delivery_unknown") return "Provider accepted the attempt, but delivery is not confirmed";
  if (["sent", "delivered"].includes(tracking)) return "Delivered to provider; awaiting carrier response";
  if (["queued", "sending"].includes(status)) return "Queued for the selected channel";
  return "Eligible contact ready for review";
}

function outreachContactKey(message: Record<string, unknown>) {
  return cleanText(message.contact_key) || outreachDedupeContactKey(message);
}

function enrichOutreachMessage(message: Record<string, unknown>) {
  return {
    ...message,
    contact_key: outreachContactKey(message),
    tracking_state: outreachMessageTrackingState(message),
    next_action: outreachNextAction(message),
    outcome_reason: outreachOutcomeReason(message)
  };
}

function outreachCarrierKey(message: Record<string, unknown>) {
  const vendorId = cleanText(message.vendor_id);
  if (vendorId) return `vendor:${vendorId}`;
  const vendor = relationRecord(message.vendors);
  const email = cleanText(message.recipient_email || vendor.primary_email)?.toLowerCase();
  if (email) return `email:${email}`;
  const phone = phoneForWhatsapp(message.recipient_phone || vendor.whatsapp_phone);
  if (phone) return `phone:${phone}`;
  return cleanText(message.id) ? `message:${message.id}` : "";
}

const OUTREACH_CARRIER_STATE_PRIORITY: Record<OutreachTrackingState, number> = {
  drafted: 10,
  queued: 20,
  sending: 30,
  sent: 40,
  delivered: 50,
  read: 60,
  manual_sent: 50,
  delivery_unknown: 35,
  failed: 70,
  bounced: 70,
  suppressed: 65,
  replied: 80,
  quoted: 90,
  archived: 0
};

function uniqueOutreachCarrierStates(rows: Record<string, unknown>[]) {
  const carrierStates = new Map<string, OutreachTrackingState>();
  for (const row of rows) {
    const key = outreachCarrierKey(row);
    if (!key) continue;
    const state = outreachMessageTrackingState(row);
    const previous = carrierStates.get(key);
    if (!previous || OUTREACH_CARRIER_STATE_PRIORITY[state] > OUTREACH_CARRIER_STATE_PRIORITY[previous]) {
      carrierStates.set(key, state);
    }
  }
  const states = Object.fromEntries(OUTREACH_TRACKING_STATES.map((status) => [status, 0])) as Record<OutreachTrackingState, number>;
  for (const state of carrierStates.values()) states[state] += 1;
  return { total: carrierStates.size, states };
}

function outreachMessageMatchesSearch(message: Record<string, unknown>, searchTerms: string[]) {
  if (!searchTerms.length) return true;
  const metadata = objectRecord(message.metadata);
  const vendor = relationRecord(message.vendors);
  const lane = relationRecord(message.rfx_lanes);
  const event = relationRecord(message.rfx_events);
  const invitation = relationRecord(message.rfx_lane_vendors);
  const haystack = [
    message.recipient_email,
    message.recipient_phone,
    message.subject,
    message.status,
    message.channel,
    metadata.vendor_name,
    metadata.vendor_domain,
    metadata.contact_name,
    metadata.recipient_email,
    metadata.lane_rows_text,
    metadata.event_name,
    metadata.rfx_id,
    vendor.vendor_name,
    vendor.domain,
    vendor.primary_email,
    lane.origin,
    lane.destination,
    event.rfx_id,
    event.name,
    invitation.invitation_status
  ].map((value) => String(value || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()).join(" ");
  return searchTerms.every((term) => haystack.includes(term));
}

function scopedOutreachMessagesQuery(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  body: Record<string, unknown>
) {
  const channels = Array.isArray(body.channels)
    ? body.channels.map((value: unknown) => cleanText(value)?.toLowerCase()).filter(Boolean)
    : [];
  const requestedTrackingStatus = cleanText(body.tracking_status)?.toLowerCase();
  const outreachSelect = body.view === "event_context"
    ? OUTREACH_MESSAGE_EVENT_SELECT
    : body.compact === true
      ? OUTREACH_MESSAGE_COMPACT_SELECT
      : OUTREACH_MESSAGE_SELECT;
  let query: any = supabase
    .from("outreach_messages")
    .select(outreachSelect)
    .eq("owner_email", user.owner_email)
    .order("created_at", { ascending: false })
    .order("id", { ascending: false });
  if (body.campaign_id) query = query.eq("campaign_id", body.campaign_id);
  if (body.rfx_event_id) query = query.eq("rfx_event_id", body.rfx_event_id);
  if (body.status) query = query.eq("status", body.status);
  if (!body.status && requestedTrackingStatus === "archived") query = query.eq("status", "archived");
  if (!body.status && requestedTrackingStatus !== "archived" && !body.include_archived) query = query.neq("status", "archived");
  if (body.created_after) query = query.gte("created_at", body.created_after);
  if (body.channel) query = query.eq("channel", body.channel);
  if (channels.length) query = query.in("channel", channels);
  return query;
}

async function allScopedOutreachMessages(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  body: Record<string, unknown>
) {
  const rows: Record<string, unknown>[] = [];
  const pageSize = 1000;
  for (let offset = 0; ; offset += pageSize) {
    const result = await scopedOutreachMessagesQuery(supabase, user, body).range(offset, offset + pageSize - 1);
    if (result.error) throw result.error;
    const pageRows = (result.data || []) as Record<string, unknown>[];
    rows.push(...pageRows);
    if (pageRows.length < pageSize) return hydrateOutreachInvitationTokens(supabase, rows);
  }
}

async function allScopedRfxOutreachMessages(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  body: Record<string, unknown>
) {
  const rows = await allScopedOutreachMessages(supabase, user, body);
  const eventId = cleanText(body.rfx_event_id);
  if (!eventId || body.enforce_rfx_event_scope !== true) return rows;

  // Delivery Queue is event-specific. A legacy message can retain an event id
  // after its invitation was moved or removed, so verify it still belongs to a
  // current lane/vendor invitation before showing it in this event's history.
  const invitations = await fetchAllRfxLaneVendorRows(
    supabase,
    eventId,
    "id,vendor_id,rfx_lane_id,invitation_status,bid_rate,responded_at"
  );
  const invitationIds = new Set(invitations.map((row) => cleanText(row.id)).filter(Boolean));
  const vendorIds = new Set(invitations.map((row) => cleanText(row.vendor_id)).filter(Boolean));
  return rows.filter((message) => {
    const linkedInvitationIds = messageInvitationIds(message);
    if (linkedInvitationIds.length) return linkedInvitationIds.some((id) => invitationIds.has(id));
    return vendorIds.has(cleanText(message.vendor_id));
  });
}

function outreachSuppressionContactValues(vendor: Record<string, unknown>, channel: string) {
  const values = new Set<string>();
  if (channel === "email") {
    vendorContactEmailCandidates(vendor).forEach((value) => values.add(value));
  }
  if (channel === "whatsapp") {
    const phone = phoneForWhatsapp(vendor.whatsapp_phone);
    if (phone) values.add(phone);
  }
  return values;
}

async function outreachSuppressionsForVendors(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  vendorIds: string[]
) {
  const rows: Record<string, unknown>[] = [];
  const globalResult = await supabase
    .from("outreach_contact_suppressions")
    .select("id,vendor_id,channel,contact_value,reason,active")
    .eq("owner_email", user.owner_email)
    .eq("active", true)
    .is("vendor_id", null);
  if (globalResult.error) throw new Error(`Outreach suppression load failed: ${globalResult.error.message}`);
  rows.push(...((globalResult.data || []) as Record<string, unknown>[]));
  if (!vendorIds.length) return rows;
  for (const vendorChunk of chunkValues(vendorIds, 200)) {
    const result = await supabase
      .from("outreach_contact_suppressions")
      .select("id,vendor_id,channel,contact_value,reason,active")
      .eq("owner_email", user.owner_email)
      .eq("active", true)
      .in("vendor_id", vendorChunk);
    if (result.error) throw new Error(`Outreach suppression load failed: ${result.error.message}`);
    rows.push(...((result.data || []) as Record<string, unknown>[]));
  }
  return rows;
}

function outreachSuppressionReason(
  suppressions: Record<string, unknown>[],
  channel: string,
  contactValue: string,
  vendorId = ""
) {
  const normalizedContact = cleanText(contactValue)?.toLowerCase() || "";
  const normalizedVendorId = cleanText(vendorId) || "";
  const match = suppressions.find((suppression) => {
    const suppressionChannel = cleanText(suppression.channel)?.toLowerCase() || "all";
    const value = cleanText(suppression.contact_value)?.toLowerCase() || "";
    const suppressionVendorId = cleanText(suppression.vendor_id) || "";
    return (!suppressionVendorId || suppressionVendorId === normalizedVendorId)
      && ["all", channel].includes(suppressionChannel)
      && (value === "*" || Boolean(normalizedContact && value === normalizedContact));
  });
  return match ? cleanText(match.reason) || "Contact is suppressed" : "";
}

type ApiErrorInfo = {
  message: string;
  name: string | null;
  code: string | null;
  details: string | null;
  hint: string | null;
  stage: string | null;
  table: string | null;
  constraint: string | null;
  cause_chain: string[];
  stack: string | null;
};

function apiErrorInfo(error: unknown, depth = 0, seen = new Set<unknown>()): ApiErrorInfo {
  const fallback: ApiErrorInfo = {
    message: "Rateware API request failed.",
    name: null,
    code: null,
    details: null,
    hint: null,
    stage: null,
    table: null,
    constraint: null,
    cause_chain: [],
    stack: null
  };
  if (depth > 5 || (typeof error === "object" && error !== null && seen.has(error))) return fallback;
  if (typeof error === "object" && error !== null) seen.add(error);

  const record = objectRecord(error);
  const nestedValue = record.cause ?? record.error;
  const nested = nestedValue !== undefined && nestedValue !== null && nestedValue !== error
    ? apiErrorInfo(nestedValue, depth + 1, seen)
    : null;
  const scalarError = nestedValue !== undefined && nestedValue !== null && typeof nestedValue !== "object"
    ? cleanText(nestedValue)
    : null;
  const message = cleanText(errorMessage(error))
    || nested?.message
    || scalarError
    || cleanText(errorMessage(record.details))
    || cleanText(errorMessage(record.hint))
    || fallback.message;
  const causeChain = [message, ...(nested?.cause_chain || [])]
    .map((value) => cleanText(value))
    .filter((value, index, values): value is string => Boolean(value) && values.indexOf(value) === index)
    .slice(0, 6);

  return {
    message,
    name: cleanText(error instanceof Error ? error.name : record.name) || nested?.name || null,
    code: cleanText(record.code) || cleanText(record.status) || nested?.code || null,
    details: cleanText(errorMessage(record.details)) || nested?.details || null,
    hint: cleanText(errorMessage(record.hint)) || nested?.hint || null,
    stage: cleanText(record.stage) || cleanText(record.operation) || nested?.stage || null,
    table: cleanText(record.table) || nested?.table || null,
    constraint: cleanText(record.constraint) || nested?.constraint || null,
    cause_chain: causeChain,
    stack: cleanText(error instanceof Error ? error.stack : record.stack) || nested?.stack || null
  };
}

function safeOperationalError(value: unknown, limit = 500) {
  const raw = errorMessage(value) || "Rateware API request failed.";
  return raw
    .replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/gi, "Bearer [redacted]")
    .replace(/([?&](?:token|access_token|refresh_token|api_key|key|secret)=)[^&\s]+/gi, "$1[redacted]")
    .replace(/\b(?:sk|sb_secret|GOCSPX)-[A-Za-z0-9._~-]+\b/gi, "[redacted-secret]")
    .replace(/\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g, "[redacted-jwt]")
    .replace(/((?:access|refresh|client|app|api|verify)[_-]?(?:token|secret|key)|authorization)\s*[:=]\s*[^\s,;]+/gi, "$1=[redacted]")
    .slice(0, limit);
}

function safeOperationalValue(value: unknown, limit = 500) {
  const text = errorMessage(value);
  return text ? safeOperationalError(text, limit) : null;
}

function safeOperationalList(values: unknown[], limit = 500) {
  return values
    .map((value) => safeOperationalValue(value, limit))
    .filter((value, index, list): value is string => Boolean(value) && list.indexOf(value) === index)
    .slice(0, 6);
}

function apiErrorStatus(info: ReturnType<typeof apiErrorInfo>) {
  const code = cleanText(info.code)?.toLowerCase() || "";
  const message = cleanText(info.message)?.toLowerCase() || "";
  const explicitAuthFailure = [
    "bearer token is required",
    "invalid bearer token",
    "jwt expired",
    "invalid jwt",
    "token has expired",
    "authentication required",
    "unauthorized"
  ].some((marker) => message.includes(marker));
  if (code === "401" || explicitAuthFailure) return 401;
  if (code === "403" || message.includes("forbidden") || message.includes("not allowed")) return 403;
  if (code === "404" || message.includes("not found")) return 404;
  return 500;
}

function bulkFilterKey(value: unknown) {
  const text = cleanText(value) || "(blank)";
  return text.toLowerCase();
}

function matchesBulkColumnFilters(row: Record<string, unknown>, filters: Record<string, unknown>) {
  return Object.entries(filters).every(([field, value]) => {
    const rowValues = bulkColumnValues(row, field).map((item) => cleanText(item)).filter(Boolean) as string[];
    const candidates = rowValues.length ? rowValues : ["(blank)"];
    if (Array.isArray(value)) {
      const selected = new Set(value.map(bulkFilterKey));
      if (!selected.size) return true;
      return candidates.some((candidate) => selected.has(bulkFilterKey(candidate)));
    }
    const needle = cleanText(value)?.toLowerCase();
    if (!needle) return true;
    return candidates.join(" ").toLowerCase().includes(needle);
  });
}

function matchesBulkReviewFilter(row: Record<string, unknown>, filter: unknown) {
  const value = cleanText(filter);
  if (!value || value === "all") return true;
  if (value === "needs-location") return bulkNeedsLocationMatch(row);
  if (value === "needs-rate") return bulkNeedsNumericRate(row);
  if (value === "needs-vendor") return !bulkHasVendorMatch(row);
  if (value === "conflicts") return bulkHasReviewConflict(row);
  if (value === "source-audit") return bulkHasSourceAuditIssue(row);
  if (value === "ready") return bulkIsReadyForApproval(row);
  if (value === "all-in") return bulkHasNumericValue(row.all_in_rate);
  if (value === "split-rate") return bulkHasSplitRate(row);
  return true;
}

function matchesBulkRatewareQuickFilter(row: Record<string, unknown>, filter: unknown) {
  const value = cleanText(filter);
  if (!value || value === "all") return true;
  if (value === "cross-border") return isCrossBorderRate(row);
  if (value === "all-in") return bulkHasNumericValue(row.all_in_rate) && !bulkHasSplitRate(row);
  if (value === "split-rate") return bulkHasSplitRate(row);
  if (value === "with-capacity") return Boolean(cleanText(row.weekly_capacity));
  if (value === "conflicts") return bulkHasReviewConflict(row);
  return true;
}

const SQL_RATE_FILTER_FIELDS = new Set([
  "status",
  "raw_upload_id",
  "vendor_domain",
  "rfx_id",
  "row_id",
  "origin_zip_prefix",
  "origin_state",
  "origin_market",
  "origin_region",
  "origin_country",
  "destination_zip_prefix",
  "destination_state",
  "destination_market",
  "destination_region",
  "destination_country",
  "equipment",
  "trailer",
  "hazmat",
  "temperature_controlled",
  "config",
  "operation",
  "service",
  "mx_border_crossing_point",
  "us_border_crossing_point",
  "mx_linehaul",
  "us_linehaul",
  "fsc",
  "border_crossing_fee",
  "all_in_rate",
  "currency",
  "weekly_capacity",
  "quote_date"
]);

function sqlRateFilterField(field: unknown) {
  const value = cleanText(field);
  return value && SQL_RATE_FILTER_FIELDS.has(value) ? value : null;
}

function normalizeColumnFilterValues(value: unknown) {
  if (Array.isArray(value)) return value.map(cleanText).filter(Boolean) as string[];
  const text = cleanText(value);
  return text ? [text] : [];
}

function isBlankFilterValue(value: string) {
  return value === "(blank)";
}

function isSqlCompatibleColumnFilters(columnFilters: Record<string, unknown>) {
  return Object.entries(columnFilters).every(([field, value]) => {
    const column = sqlRateFilterField(field);
    if (!column) return false;
    const values = normalizeColumnFilterValues(value);
    const hasBlank = values.some(isBlankFilterValue);
    const hasRealValues = values.some((item) => !isBlankFilterValue(item));
    return !(hasBlank && hasRealValues);
  });
}

function isSqlCompatibleReviewFilter(filter: unknown) {
  const value = cleanText(filter) || "all";
  return ["all", "needs-vendor"].includes(value);
}

function isSqlCompatibleRatewareQuickFilter(filter: unknown) {
  const value = cleanText(filter) || "all";
  return ["all", "cross-border", "with-capacity"].includes(value);
}

function hasActiveRatewareFilters(filters: Record<string, unknown>) {
  const columnFilters = objectRecord(filters.column_filters);
  return Boolean(
    cleanText(filters.search) ||
    cleanText(filters.operation) ||
    cleanText(filters.service) ||
    filters.needs_vendor === true ||
    (cleanText(filters.quick_filter) || "all") !== "all" ||
    Object.keys(columnFilters).length
  );
}

function canUseSqlRateFilters(filters: Record<string, unknown>) {
  const columnFilters = objectRecord(filters.column_filters);
  if (!isSqlCompatibleColumnFilters(columnFilters)) return false;
  const mode = cleanText(filters.mode);
  if (mode === "rateware") return isSqlCompatibleRatewareQuickFilter(filters.quick_filter);
  return isSqlCompatibleReviewFilter(filters.review_filter);
}

function applySqlColumnFilter(query: any, field: string, value: unknown) {
  const column = sqlRateFilterField(field);
  if (!column) return query;
  const values = normalizeColumnFilterValues(value);
  if (!values.length) return query;

  if (column === "hazmat" || column === "temperature_controlled") {
    const bools = new Set(values.map((item) => item.toLowerCase()).map((item) => item === "yes" || item === "true" ? "true" : item === "no" || item === "false" ? "false" : ""));
    bools.delete("");
    if (bools.size !== 1) return query;
    return query.eq(column, bools.has("true"));
  }

  if (values.length === 1 && isBlankFilterValue(values[0])) return query.is(column, null);
  if (Array.isArray(value)) return query.in(column, values.filter((item) => !isBlankFilterValue(item)));
  return query.ilike(column, `%${values[0]}%`);
}

function applySqlColumnFilters(query: any, columnFilters: Record<string, unknown>) {
  return Object.entries(columnFilters).reduce((current, [field, value]) => applySqlColumnFilter(current, field, value), query);
}

function applySqlDerivedRateFilters(query: any, filters: Record<string, unknown>) {
  if (filters.needs_vendor === true) query = query.is("vendor_id", null);

  const mode = cleanText(filters.mode);
  if (mode === "rateware") {
    const quickFilter = cleanText(filters.quick_filter) || "all";
    if (quickFilter === "cross-border") {
      return query.or("operation.ilike.%cross%,operation.ilike.%export%,operation.ilike.%import%,service.ilike.%cross%,mx_border_crossing_point.not.is.null,us_border_crossing_point.not.is.null");
    }
    if (quickFilter === "with-capacity") return query.not("weekly_capacity", "is", null);
    return query;
  }

  const reviewFilter = cleanText(filters.review_filter) || "all";
  if (reviewFilter === "needs-vendor") return query.is("vendor_id", null);
  return query;
}

function applyBulkRateBaseFilters(query: any, filters: Record<string, unknown>) {
  const mode = cleanText(filters.mode);
  if (mode === "rateware") {
    query = query.eq("status", "approved");
  } else {
    const status = cleanText(filters.status);
    if (status) query = query.eq("status", status);
  }
  if (filters.exclude_archived === true) query = query.neq("status", "archived");

  const rawUploadId = cleanText(filters.raw_upload_id);
  if (rawUploadId) query = query.eq("raw_upload_id", rawUploadId);

  const operation = cleanText(filters.operation);
  if (operation) query = query.ilike("operation", operation);

  const service = cleanText(filters.service);
  if (service) query = query.ilike("service", service);

  const search = cleanText(filters.search);
  if (search) query = applyRateSearchFilter(query, search);
  return query;
}

function applySqlRateFilters(query: any, filters: Record<string, unknown>) {
  query = applyBulkRateBaseFilters(query, filters);
  query = applySqlColumnFilters(query, objectRecord(filters.column_filters));
  query = applySqlDerivedRateFilters(query, filters);
  return query;
}

async function fetchSqlRateFilterValues(
  supabase: RatewareSupabaseClient,
  filters: Record<string, unknown>,
  field: string,
  valueSearch = "",
  limit = 1000,
  ownerEmail: string | null = null
) {
  const column = sqlRateFilterField(field);
  if (!column || !canUseSqlRateFilters(filters)) return null;
  const scopedOwnerEmail = cleanText(ownerEmail)?.toLowerCase();
  if (!scopedOwnerEmail) throw new Error("Workspace owner is required for rate filter values.");

  const values = new Map<string, string>();
  const pageSize = 1000;
  const hardLimit = 50000;
  let offset = 0;
  let databaseCount = 0;
  const needle = valueSearch.toLowerCase();

  while (offset < hardLimit && values.size < limit) {
    let query = supabase
      .from("rate_staging")
      .select(column, { count: offset === 0 ? "exact" : undefined })
      .eq("owner_email", scopedOwnerEmail)
      .order(column, { ascending: true, nullsFirst: true })
      .range(offset, offset + pageSize - 1);
    query = applySqlRateFilters(query, filters);

    const result = await query;
    if (result.error) throw result.error;
    if (offset === 0) databaseCount = result.count || 0;

    const page = (result.data || []) as unknown as Record<string, unknown>[];
    for (const row of page) {
      let label = cleanText(row[column]) || "(blank)";
      if (column === "hazmat" || column === "temperature_controlled") label = row[column] ? "Yes" : "No";
      if (needle && !label.toLowerCase().includes(needle)) continue;
      const key = bulkFilterKey(label);
      if (!values.has(key)) values.set(key, label);
    }
    if (page.length < pageSize) break;
    offset += pageSize;
  }

  const sorted = [...values.values()].sort((a, b) => a.localeCompare(b));
  return {
    field,
    values: sorted.slice(0, limit),
    total: sorted.length,
    database_count: databaseCount,
    hard_limit_reached: offset >= hardLimit && databaseCount > offset
  };
}

function matchesBulkRateRow(row: Record<string, unknown>, filters: Record<string, unknown>) {
  const mode = cleanText(filters.mode);
  const columnFilters = objectRecord(filters.column_filters);
  if (!matchesBulkColumnFilters(row, columnFilters)) return false;
  if (mode === "rateware") return matchesBulkRatewareQuickFilter(row, filters.quick_filter);
  return matchesBulkReviewFilter(row, filters.review_filter);
}

function mergeRpcColumnFilterValue(existing: unknown, value: string) {
  const next = cleanText(value);
  if (!next) return existing;
  const current = normalizeColumnFilterValues(existing);
  if (!current.length) return [next];
  if (current.some((item) => item.toLowerCase() === next.toLowerCase())) return current;
  return ["__rateware_no_match__"];
}

function normalizedRpcRateFilters(filters: Record<string, unknown>) {
  const columnFilters = { ...objectRecord(filters.column_filters) };
  const operation = cleanText(filters.operation);
  const service = cleanText(filters.service);
  if (operation) columnFilters.operation = mergeRpcColumnFilterValue(columnFilters.operation, operation);
  if (service) columnFilters.service = mergeRpcColumnFilterValue(columnFilters.service, service);
  return {
    mode: cleanText(filters.mode) || "staging",
    status: cleanText(filters.status),
    raw_upload_id: cleanText(filters.raw_upload_id),
    search: cleanText(filters.search),
    operation: null,
    service: null,
    quick_filter: cleanText(filters.quick_filter) || "all",
    review_filter: cleanText(filters.review_filter) || "all",
    column_filters: columnFilters,
    exclude_archived: filters.exclude_archived === true
  };
}

async function fetchRateRowIdsByFilter(
  supabase: RatewareSupabaseClient,
  filters: Record<string, unknown>,
  options: { limit?: number; offset?: number; ownerEmail?: string | null } = {}
) {
  const limit = Math.min(Math.max(Number(options.limit) || 50000, 1), 50000);
  const offset = Math.max(Number(options.offset) || 0, 0);
  const ownerEmail = cleanText(options.ownerEmail)?.toLowerCase();
  if (!ownerEmail) throw new Error("Workspace owner is required for rate filtering.");

  if (canUseSqlRateFilters(filters)) {
    let query = supabase
      .from("rate_staging")
      .select("id", { count: "exact" })
      .eq("owner_email", ownerEmail)
      .order("created_at", { ascending: false })
      .order("id", { ascending: false })
      .range(offset, offset + limit - 1);

    query = applySqlRateFilters(query, filters);
    const result = await query;
    if (result.error) throw result.error;
    const ids = (result.data || []).map((row: Record<string, unknown>) => cleanText(row.id)).filter(Boolean) as string[];
    const databaseCount = result.count || ids.length;
    return {
      ids,
      rows: ids.map((id) => ({ id })),
      database_count: databaseCount,
      hard_limit_reached: databaseCount > offset + ids.length && ids.length >= limit
    };
  }

  const rpcFilters = normalizedRpcRateFilters(filters);
  const result = await supabase.rpc("rateware_filtered_rate_ids", {
    p_mode: rpcFilters.mode,
    p_status: rpcFilters.status,
    p_raw_upload_id: rpcFilters.raw_upload_id,
    p_search: rpcFilters.search,
    p_operation: rpcFilters.operation,
    p_service: rpcFilters.service,
    p_quick_filter: rpcFilters.quick_filter,
    p_review_filter: rpcFilters.review_filter,
    p_column_filters: rpcFilters.column_filters,
    p_exclude_archived: rpcFilters.exclude_archived,
    p_owner_email: ownerEmail,
    p_limit: limit,
    p_offset: offset
  });
  if (result.error) throw result.error;

  const data = (result.data || []) as Record<string, unknown>[];
  const ids = data.map((row) => cleanText(row.row_id || row.id)).filter(Boolean) as string[];
  const databaseCount = Number(data[0]?.total_count || 0);
  return {
    ids,
    rows: ids.map((id) => ({ id })),
    database_count: databaseCount,
    hard_limit_reached: databaseCount > offset + ids.length && ids.length >= limit
  };
}

async function collectRateRowIdsByFilter(
  supabase: RatewareSupabaseClient,
  filters: Record<string, unknown>,
  options: { maxRows?: number; pageSize?: number; ownerEmail?: string | null } = {}
) {
  const maxRows = Math.min(Math.max(Number(options.maxRows) || 100000, 1), 100000);
  const pageSize = Math.min(Math.max(Number(options.pageSize) || 5000, 1), 5000);
  const ids: string[] = [];
  let offset = 0;
  let databaseCount = 0;
  let hardLimitReached = false;

  while (ids.length < maxRows) {
    const limit = Math.min(pageSize, maxRows - ids.length);
    const filtered = await fetchRateRowIdsByFilter(supabase, filters, {
      limit,
      offset,
      ownerEmail: options.ownerEmail
    });
    if (!databaseCount) databaseCount = filtered.database_count;
    hardLimitReached = hardLimitReached || filtered.hard_limit_reached;
    if (!filtered.ids.length) break;
    ids.push(...filtered.ids);
    offset += filtered.ids.length;
    if (filtered.ids.length < limit || offset >= filtered.database_count) break;
  }

  return {
    ids,
    database_count: databaseCount || ids.length,
    hard_limit_reached: hardLimitReached || ids.length >= maxRows && (databaseCount || 0) > ids.length,
    max_rows: maxRows
  };
}

async function fetchRateRowsForIds(
  supabase: RatewareSupabaseClient,
  ids: string[],
  select = RATE_ROW_LIST_SELECT,
  ownerEmail: string | null = null
) {
  const scopedOwnerEmail = cleanText(ownerEmail)?.toLowerCase();
  if (!scopedOwnerEmail) throw new Error("Workspace owner is required for rate rows.");
  const rows: Record<string, unknown>[] = [];
  for (const chunk of chunkValues(ids, 500)) {
    const result = await supabase
      .from("rate_staging")
      .select(select)
      .eq("owner_email", scopedOwnerEmail)
      .in("id", chunk);
    if (result.error) throw result.error;
    rows.push(...((result.data || []) as unknown as Record<string, unknown>[]));
  }
  const byId = new Map(rows.map((row) => [cleanText(row.id), row]));
  return ids.map((id) => byId.get(id)).filter(Boolean) as Record<string, unknown>[];
}

async function fetchRatewareRowsBySql(
  supabase: RatewareSupabaseClient,
  filterPayload: Record<string, unknown>,
  limit: number,
  offset: number,
  ownerEmail: string | null
) {
  const scopedOwnerEmail = cleanText(ownerEmail)?.toLowerCase();
  if (!scopedOwnerEmail) throw new Error("Workspace owner is required for Rateware rows.");
  let query = supabase
    .from("rate_staging")
    .select(RATE_ROW_LIST_SELECT, { count: "exact" })
    .eq("owner_email", scopedOwnerEmail)
    .eq("status", "approved")
    .order("quote_date", { ascending: false, nullsFirst: false })
    .order("created_at", { ascending: false })
    .range(offset, offset + limit - 1);

  query = applySqlRateFilters(query, filterPayload);

  const result = await query;
  if (result.error) throw result.error;
  const total = result.count || 0;
  const rows = result.data || [];
  return {
    rows,
    total,
    limit,
    offset,
    has_more: offset + rows.length < total,
    fallback: "sql"
  };
}

async function fetchRateFilterValuesByRpc(
  supabase: RatewareSupabaseClient,
  filters: Record<string, unknown>,
  field: string,
  valueSearch = "",
  limit = 1000,
  ownerEmail: string | null = null
) {
  const scopedOwnerEmail = cleanText(ownerEmail)?.toLowerCase();
  if (!scopedOwnerEmail) throw new Error("Workspace owner is required for rate filter values.");
  const rpcFilters = normalizedRpcRateFilters(filters);
  const result = await supabase.rpc("rateware_filtered_rate_values", {
    p_field: field,
    p_mode: rpcFilters.mode,
    p_status: rpcFilters.status,
    p_raw_upload_id: rpcFilters.raw_upload_id,
    p_search: rpcFilters.search,
    p_operation: rpcFilters.operation,
    p_service: rpcFilters.service,
    p_quick_filter: rpcFilters.quick_filter,
    p_review_filter: rpcFilters.review_filter,
    p_column_filters: rpcFilters.column_filters,
    p_exclude_archived: rpcFilters.exclude_archived,
    p_owner_email: scopedOwnerEmail,
    p_value_search: cleanText(valueSearch),
    p_limit: Math.min(Math.max(Number(limit) || 1000, 1), 5000)
  });
  if (result.error) throw result.error;

  const rows = (result.data || []) as unknown as Record<string, unknown>[];
  const values = rows.map((row) => cleanText(row.value)).filter(Boolean) as string[];
  const total = Number(rows[0]?.total_count || values.length);
  return {
    field,
    values: values.slice(0, limit),
    total,
    database_count: total,
    hard_limit_reached: total > values.length
  };
}

function chunkValues<T>(values: T[], size = 500) {
  const chunks: T[][] = [];
  for (let index = 0; index < values.length; index += size) chunks.push(values.slice(index, index + size));
  return chunks;
}

async function mapWithConcurrency<T, R>(
  values: T[],
  concurrency: number,
  worker: (value: T, index: number) => Promise<R>
) {
  if (!values.length) return [] as R[];
  const results = new Array<R>(values.length);
  let nextIndex = 0;
  const run = async () => {
    while (nextIndex < values.length) {
      const index = nextIndex;
      nextIndex += 1;
      results[index] = await worker(values[index], index);
    }
  };
  const workerCount = Math.min(Math.max(1, Math.floor(concurrency)), values.length);
  await Promise.all(Array.from({ length: workerCount }, () => run()));
  return results;
}

function numericAmount(value: unknown) {
  const cleaned = cleanRateText(value);
  return cleaned ? Number(cleaned) : null;
}

function vendorSearchText(vendor: Record<string, unknown>) {
  return [
    vendor.vendor_name,
    vendor.legal_name,
    vendor.domain,
    vendor.primary_email,
    vendor.coverage_notes,
    vendor.notes,
    ...arrayValues(vendor.tags)
  ].filter(Boolean).join(" ");
}

function createVendorMetricsFromLinkedRates(linkedRates: Record<string, unknown>[]) {
  const approvedRates = linkedRates.filter((row) => row.status === "approved");
  const crossborderRates = linkedRates.filter(isCrossBorderRate);
  const d2dImportExportRates = linkedRates.filter(isD2dImportExportRate);
  const mexicoRates = linkedRates.filter(isMexicoRate);
  const rateAmounts = linkedRates.map((row) => numericAmount(row.all_in_rate)).filter((value): value is number => typeof value === "number" && Number.isFinite(value));
  const costPerMileValues = linkedRates.map((row) => biNumber(row, "cost_per_mile")).filter((value): value is number => typeof value === "number" && Number.isFinite(value));
  const costPerKmValues = linkedRates.map((row) => biNumber(row, "cost_per_km")).filter((value): value is number => typeof value === "number" && Number.isFinite(value));
  const marketSet = new Set<string>();
  const laneSet = new Set<string>();
  const equipmentSet = new Set<string>();
  const borderSet = new Set<string>();
  let lastQuoteDate: string | null = null;

  for (const row of linkedRates) {
    [row.origin_market, row.destination_market].map(cleanText).filter(Boolean).forEach((value) => marketSet.add(value as string));
    [row.equipment, row.trailer].map(cleanText).filter(Boolean).forEach((value) => equipmentSet.add(value as string));
    [row.mx_border_crossing_point && row.us_border_crossing_point ? `${row.mx_border_crossing_point} / ${row.us_border_crossing_point}` : null]
      .map(cleanText)
      .filter(Boolean)
      .forEach((value) => borderSet.add(value as string));
    const lane = [row.origin || row.normalized_origin, row.destination || row.normalized_destination].map(cleanText).filter(Boolean).join(" -> ");
    if (lane) laneSet.add(lane);
    const quoteDate = cleanText(row.quote_date);
    if (quoteDate && (!lastQuoteDate || quoteDate > lastQuoteDate)) lastQuoteDate = quoteDate;
  }

  return {
    linked_rates: linkedRates.length,
    approved_rates: approvedRates.length,
    pending_rates: linkedRates.filter((row) => row.status === "pending_review").length,
    crossborder_rates: crossborderRates.length,
    d2d_import_export_rates: d2dImportExportRates.length,
    mexico_rates: mexicoRates.length,
    avg_all_in_rate: rateAmounts.length ? Math.round(rateAmounts.reduce((sum, value) => sum + value, 0) / rateAmounts.length) : null,
    avg_cost_per_mile: costPerMileValues.length ? Math.round((costPerMileValues.reduce((sum, value) => sum + value, 0) / costPerMileValues.length) * 100) / 100 : null,
    avg_cost_per_km: costPerKmValues.length ? Math.round((costPerKmValues.reduce((sum, value) => sum + value, 0) / costPerKmValues.length) * 100) / 100 : null,
    markets: [...marketSet].slice(0, 8),
    lanes: [...laneSet].slice(0, 6),
    equipment: [...equipmentSet].slice(0, 6),
    border_pairs: [...borderSet].slice(0, 6),
    last_quote_date: lastQuoteDate
  };
}

function createVendorMetrics(vendor: Record<string, unknown>, rates: Record<string, unknown>[]) {
  const vendorDomain = normalizeDomain(vendor.domain);
  const emails = vendorEmails(vendor);
  const linkedRates = rates.filter((row) => {
    if (row.vendor_id && vendor.id && row.vendor_id === vendor.id) return true;
    const rowDomain = normalizeDomain(row.vendor_domain);
    return Boolean(rowDomain && (rowDomain === vendorDomain || emails.some((email) => email.endsWith(`@${rowDomain}`))));
  });
  return createVendorMetricsFromLinkedRates(linkedRates);
}

function emptyVendorMetrics() {
  return {
    linked_rates: 0,
    approved_rates: 0,
    pending_rates: 0,
    crossborder_rates: 0,
    d2d_import_export_rates: 0,
    mexico_rates: 0,
    avg_all_in_rate: null,
    avg_cost_per_mile: null,
    avg_cost_per_km: null,
    markets: [],
    lanes: [],
    equipment: [],
    border_pairs: [],
    last_quote_date: null
  };
}

function normalizeVendorMetricRow(row: Record<string, unknown> | undefined) {
  if (!row) return emptyVendorMetrics();
  const numericValue = (value: unknown, decimals = 0) => {
    const numberValue = Number(value);
    if (!Number.isFinite(numberValue)) return null;
    const factor = 10 ** decimals;
    return Math.round(numberValue * factor) / factor;
  };
  return {
    linked_rates: Number(row.linked_rates || 0),
    approved_rates: Number(row.approved_rates || 0),
    pending_rates: Number(row.pending_rates || 0),
    crossborder_rates: Number(row.crossborder_rates || 0),
    d2d_import_export_rates: Number(row.d2d_import_export_rates || 0),
    mexico_rates: Number(row.mexico_rates || 0),
    avg_all_in_rate: numericValue(row.avg_all_in_rate),
    avg_cost_per_mile: numericValue(row.avg_cost_per_mile, 2),
    avg_cost_per_km: numericValue(row.avg_cost_per_km, 2),
    markets: arrayValues(row.markets).slice(0, 8),
    lanes: arrayValues(row.lanes).slice(0, 6),
    equipment: arrayValues(row.equipment).slice(0, 6),
    border_pairs: arrayValues(row.border_pairs).slice(0, 6),
    last_quote_date: cleanText(row.last_quote_date)
  };
}

async function fetchVendorRateMetrics(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  options: { baseStage?: string | null; vendorIds?: unknown } = {}
) {
  const vendorIds = normalizeUuidList(options.vendorIds);
  if (!vendorIds.length) return new Map<string, Record<string, unknown>>();
  const result = await supabase.rpc("vendor_rate_metrics_for_owner_ids", {
    p_owner_email: user.owner_email,
    p_vendor_ids: vendorIds,
    p_base_stage: cleanText(options.baseStage) || null
  });
  if (result.error) throw result.error;
  const metrics = new Map<string, Record<string, unknown>>();
  for (const row of result.data || []) {
    const id = cleanText((row as Record<string, unknown>).vendor_id);
    if (id) metrics.set(id, normalizeVendorMetricRow(row as Record<string, unknown>));
  }
  return metrics;
}

