function base64ToBytes(value: string) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

function bytesToBase64(bytes: Uint8Array) {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

function bytesToBase64Url(bytes: Uint8Array) {
  return bytesToBase64(bytes).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

async function gmailCryptoKey(usages: KeyUsage[]) {
  const secret = Deno.env.get("GMAIL_TOKEN_ENCRYPTION_KEY");
  if (!secret) throw new Error("GMAIL_TOKEN_ENCRYPTION_KEY is not configured.");
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(secret));
  return crypto.subtle.importKey("raw", digest, "AES-GCM", false, usages);
}

async function encryptGmailToken(value: string) {
  const key = await gmailCryptoKey(["encrypt"]);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ciphertext = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, new TextEncoder().encode(value));
  return `v1:${bytesToBase64(iv)}:${bytesToBase64(new Uint8Array(ciphertext))}`;
}

async function decryptGmailToken(value: unknown) {
  const text = cleanText(value);
  if (!text) throw new Error("Gmail token is missing.");
  const [version, ivText, ciphertextText] = text.split(":");
  if (version !== "v1" || !ivText || !ciphertextText) throw new Error("Gmail token format is invalid.");
  const key = await gmailCryptoKey(["decrypt"]);
  const plain = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: base64ToBytes(ivText) },
    key,
    base64ToBytes(ciphertextText)
  );
  return new TextDecoder().decode(plain);
}

async function rfxMagicLinkCryptoKey(usages: KeyUsage[]) {
  // Keep RFI link recovery independent where possible, while preserving
  // compatibility with deployments that already protect Gmail credentials.
  const secret = Deno.env.get("RFX_RFI_LINK_ENCRYPTION_KEY") || Deno.env.get("GMAIL_TOKEN_ENCRYPTION_KEY");
  if (!secret) throw new Error("Customer RFI link encryption is not configured.");
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(secret));
  return crypto.subtle.importKey("raw", digest, "AES-GCM", false, usages);
}

async function encryptRfxMagicLinkToken(value: string) {
  const key = await rfxMagicLinkCryptoKey(["encrypt"]);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ciphertext = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, new TextEncoder().encode(value));
  return `v1:${bytesToBase64(iv)}:${bytesToBase64(new Uint8Array(ciphertext))}`;
}

async function decryptRfxMagicLinkToken(value: unknown) {
  const text = cleanText(value);
  if (!text) return null;
  const [version, ivText, ciphertextText] = text.split(":");
  if (version !== "v1" || !ivText || !ciphertextText) throw new Error("Customer RFI link token format is invalid.");
  const key = await rfxMagicLinkCryptoKey(["decrypt"]);
  const plain = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: base64ToBytes(ivText) },
    key,
    base64ToBytes(ciphertextText)
  );
  return new TextDecoder().decode(plain);
}

async function rfxInvitationCryptoKey(usages: KeyUsage[]) {
  if (!RFX_INVITATION_TOKEN_ENCRYPTION_KEY) throw new Error("Bid Room invitation token encryption is not configured.");
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(RFX_INVITATION_TOKEN_ENCRYPTION_KEY));
  return crypto.subtle.importKey("raw", digest, "AES-GCM", false, usages);
}

async function hashRfxInvitationToken(value: string) {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
  return bytesToBase64(new Uint8Array(digest));
}

async function encryptRfxInvitationToken(value: string) {
  const key = await rfxInvitationCryptoKey(["encrypt"]);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ciphertext = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, new TextEncoder().encode(value));
  return `v1:${bytesToBase64(iv)}:${bytesToBase64(new Uint8Array(ciphertext))}`;
}

async function decryptRfxInvitationToken(value: unknown) {
  const text = cleanText(value);
  if (!text) return null;
  const [version, ivText, ciphertextText] = text.split(":");
  if (version !== "v1" || !ivText || !ciphertextText) throw new Error("Bid Room invitation token format is invalid.");
  const key = await rfxInvitationCryptoKey(["decrypt"]);
  const plain = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: base64ToBytes(ivText) },
    key,
    base64ToBytes(ciphertextText)
  );
  return new TextDecoder().decode(plain);
}

async function newRfxInvitationTokenFields() {
  const token = randomToken();
  return {
    invitation_token: null,
    invitation_token_hash: await hashRfxInvitationToken(token),
    invitation_token_encrypted: await encryptRfxInvitationToken(token)
  };
}

async function migrateLegacyRfxInvitationToken(
  supabase: RatewareSupabaseClient,
  row: Record<string, unknown>,
  token: string
) {
  if (!cleanText(row.id) || cleanText(row.invitation_token_hash)) return;
  try {
    const result = await supabase
      .from("rfx_lane_vendors")
      .update({
        invitation_token_hash: await hashRfxInvitationToken(token),
        invitation_token_encrypted: await encryptRfxInvitationToken(token),
        invitation_token: null,
        updated_at: new Date().toISOString()
      })
      .eq("id", row.id)
      .is("invitation_token_hash", null);
    if (result.error) console.error("Bid Room legacy invitation token migration failed", result.error.message);
  } catch (error) {
    console.error("Bid Room legacy invitation token migration skipped", errorMessage(error, "Unknown error"));
  }
}

async function hydrateRfxInvitationTokens(
  supabase: RatewareSupabaseClient,
  rows: Record<string, unknown>[]
) {
  const hydrated: Record<string, unknown>[] = [];
  for (const row of rows) {
    const legacyToken = cleanText(row.invitation_token);
    const token = legacyToken || await decryptRfxInvitationToken(row.invitation_token_encrypted);
    if (!token) continue;
    if (legacyToken) await migrateLegacyRfxInvitationToken(supabase, row, token);
    const { invitation_token_encrypted: _encrypted, invitation_token_hash: _hash, ...safeRow } = row;
    hydrated.push({ ...safeRow, invitation_token: token });
  }
  return hydrated;
}

async function hydrateOutreachInvitationTokens(
  supabase: RatewareSupabaseClient,
  rows: Record<string, unknown>[]
) {
  const hydrated: Record<string, unknown>[] = [];
  for (const row of rows) {
    const invitation = relationRecord(row.rfx_lane_vendors);
    if (!Object.keys(invitation).length) {
      hydrated.push(row);
      continue;
    }
    const legacyToken = cleanText(invitation.invitation_token);
    const token = legacyToken || await decryptRfxInvitationToken(invitation.invitation_token_encrypted);
    if (!token) {
      const { invitation_token_encrypted: _encrypted, ...safeInvitation } = invitation;
      hydrated.push({ ...row, rfx_lane_vendors: safeInvitation });
      continue;
    }
    if (legacyToken) await migrateLegacyRfxInvitationToken(supabase, invitation, token);
    const { invitation_token_encrypted: _encrypted, ...safeInvitation } = invitation;
    hydrated.push({ ...row, rfx_lane_vendors: { ...safeInvitation, invitation_token: token } });
  }
  return hydrated;
}

async function whatsappCryptoKey(usages: KeyUsage[]) {
  if (!WHATSAPP_TOKEN_ENCRYPTION_KEY) {
    throw new Error("WhatsApp tenant credential storage is not enabled for this deployment.");
  }
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(WHATSAPP_TOKEN_ENCRYPTION_KEY));
  return crypto.subtle.importKey("raw", digest, "AES-GCM", false, usages);
}

async function encryptWhatsappSecret(value: string) {
  const key = await whatsappCryptoKey(["encrypt"]);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ciphertext = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, new TextEncoder().encode(value));
  return `v1:${bytesToBase64(iv)}:${bytesToBase64(new Uint8Array(ciphertext))}`;
}

async function decryptWhatsappSecret(value: unknown, label = "WhatsApp credential") {
  const text = cleanText(value);
  if (!text) throw new Error(`${label} is missing.`);
  const [version, ivText, ciphertextText] = text.split(":");
  if (version !== "v1" || !ivText || !ciphertextText) throw new Error(`${label} format is invalid.`);
  const key = await whatsappCryptoKey(["decrypt"]);
  const plain = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: base64ToBytes(ivText) },
    key,
    base64ToBytes(ciphertextText)
  );
  return new TextDecoder().decode(plain);
}

function encodedSubject(subject: unknown) {
  const text = cleanText(subject) || "Rateware invitation";
  return `=?UTF-8?B?${bytesToBase64(new TextEncoder().encode(text))}?=`;
}

function safeHeader(value: unknown) {
  return String(value || "").replace(/[\r\n]+/g, " ").trim();
}

function gmailPayloadHeader(message: Record<string, unknown>, headerName: string) {
  const payload = objectRecord(message.payload);
  const headers = Array.isArray(payload.headers) ? payload.headers : [];
  const header = headers.find((item) => cleanText(objectRecord(item).name)?.toLowerCase() === headerName.toLowerCase());
  return safeHeader(objectRecord(header).value);
}

function gmailMessageTimestamp(message: Record<string, unknown>) {
  const internalDate = Number(message.internalDate);
  if (Number.isFinite(internalDate) && internalDate > 0) return internalDate;
  const date = Date.parse(gmailPayloadHeader(message, "Date"));
  return Number.isFinite(date) ? date : 0;
}

function gmailReplySubject(subject: unknown, fallback: string) {
  const value = cleanText(subject) || fallback;
  return /^(re|aw|sv|fw|fwd)\s*:/i.test(value) ? value : `Re: ${value}`;
}

function gmailRawMessage(message: Record<string, unknown>, senderEmail: string) {
  const to = safeHeader(message.recipient_email);
  const subject = encodedSubject(message.subject);
  const metadata = objectRecord(message.metadata);
  const inReplyTo = safeHeader(metadata.gmail_in_reply_to);
  const references = safeHeader(metadata.gmail_references || inReplyTo);
  const textBody = cleanText(message.text_body) || htmlToText(cleanText(message.html_body) || "");
  const htmlBody = cleanText(message.html_body) || `<pre>${String(textBody || "").replace(/&/g, "&amp;").replace(/</g, "&lt;")}</pre>`;
  const boundary = `rateware_${crypto.randomUUID().replace(/-/g, "")}`;
  const mime = [
    `To: ${to}`,
    `From: ${safeHeader(senderEmail)}`,
    `Subject: ${subject}`,
    ...(inReplyTo ? [`In-Reply-To: ${inReplyTo}`, `References: ${references}`] : []),
    "MIME-Version: 1.0",
    `Content-Type: multipart/alternative; boundary="${boundary}"`,
    "",
    `--${boundary}`,
    'Content-Type: text/plain; charset="UTF-8"',
    "Content-Transfer-Encoding: 8bit",
    "",
    textBody || "",
    "",
    `--${boundary}`,
    'Content-Type: text/html; charset="UTF-8"',
    "Content-Transfer-Encoding: 8bit",
    "",
    htmlBody || "",
    "",
    `--${boundary}--`
  ].join("\r\n");
  return bytesToBase64Url(new TextEncoder().encode(mime));
}

async function gmailAccessToken(supabase: RatewareSupabaseClient, user: { owner_email: string | null }, senderEmail: string) {
  if (senderEmail.toLowerCase() !== GMAIL_ALLOWED_SENDER) {
    throw new Error(`Only ${GMAIL_ALLOWED_SENDER} can send Bid Room email.`);
  }
  const result = await supabase
    .from("gmail_mailbox_connections")
    .select("*")
    .eq("owner_email", user.owner_email)
    .eq("mailbox_email", GMAIL_ALLOWED_SENDER)
    .eq("status", "connected")
    .maybeSingle();
  if (result.error) throw result.error;
  const connection = result.data;
  if (!connection) throw new Error(`Connect ${GMAIL_ALLOWED_SENDER} in Settings before sending email.`);

  const expiresAt = connection.token_expires_at ? new Date(connection.token_expires_at).getTime() : 0;
  if (connection.access_token_encrypted && expiresAt > Date.now() + 120_000) {
    return await decryptGmailToken(connection.access_token_encrypted);
  }

  const clientId = Deno.env.get("GOOGLE_CLIENT_ID");
  const clientSecret = Deno.env.get("GOOGLE_CLIENT_SECRET");
  if (!clientId || !clientSecret) throw new Error("Google OAuth client is not configured.");
  const refreshToken = await decryptGmailToken(connection.refresh_token_encrypted);
  const tokenResponse = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      client_id: clientId,
      client_secret: clientSecret,
      refresh_token: refreshToken,
      grant_type: "refresh_token"
    })
  });
  const tokenData = await tokenResponse.json();
  if (!tokenResponse.ok || !tokenData.access_token) {
    const message = cleanText(tokenData.error_description) || cleanText(tokenData.error) || "Google token refresh failed.";
    await supabase
      .from("gmail_mailbox_connections")
      .update({ status: "error", last_error: message, updated_at: new Date().toISOString() })
      .eq("owner_email", user.owner_email)
      .eq("mailbox_email", GMAIL_ALLOWED_SENDER);
    throw new Error(message);
  }

  const accessToken = String(tokenData.access_token);
  const expiresIn = Number(tokenData.expires_in) || 3600;
  const update = await supabase
    .from("gmail_mailbox_connections")
    .update({
      access_token_encrypted: await encryptGmailToken(accessToken),
      token_expires_at: new Date(Date.now() + expiresIn * 1000).toISOString(),
      last_error: null,
      updated_at: new Date().toISOString()
    })
    .eq("owner_email", user.owner_email)
    .eq("mailbox_email", GMAIL_ALLOWED_SENDER);
  if (update.error) throw update.error;
  return accessToken;
}

function gmailCanReadMailbox(connection: Record<string, unknown> | null | undefined) {
  const scopes = Array.isArray(connection?.scopes) ? connection.scopes.map((scope) => String(scope)) : [];
  return scopes.includes("https://www.googleapis.com/auth/gmail.readonly")
    || scopes.includes("https://www.googleapis.com/auth/gmail.modify")
    || scopes.includes("https://mail.google.com/");
}

function decodeGmailBody(data: unknown) {
  const value = cleanText(data);
  if (!value) return "";
  try {
    const normalized = value.replace(/-/g, "+").replace(/_/g, "/");
    const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, "=");
    const binary = atob(padded);
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
    return new TextDecoder().decode(bytes);
  } catch {
    return "";
  }
}

function gmailMessageHeaders(message: Record<string, unknown>) {
  const payload = objectRecord(message.payload);
  const headers = Array.isArray(payload.headers) ? payload.headers : [];
  const normalized: Record<string, string> = {};
  for (const header of headers) {
    const row = objectRecord(header);
    const name = cleanText(row.name)?.toLowerCase();
    if (name) normalized[name] = cleanText(row.value) || "";
  }
  return normalized;
}

function gmailPayloadText(payload: Record<string, unknown>): string {
  const body = objectRecord(payload.body);
  const direct = decodeGmailBody(body.data);
  const parts = Array.isArray(payload.parts) ? payload.parts : [];
  const nested = parts
    .map((part) => gmailPayloadText(objectRecord(part)))
    .filter(Boolean)
    .join("\n");
  return [direct, nested].filter(Boolean).join("\n");
}

function isDeliveryFailureNotice(headers: Record<string, string>, bodyText: string) {
  const from = `${headers.from || ""} ${headers.sender || ""}`.toLowerCase();
  const subject = String(headers.subject || "").toLowerCase();
  const body = bodyText.toLowerCase();
  return from.includes("mailer-daemon")
    || from.includes("mail delivery subsystem")
    || from.includes("postmaster")
    || subject.includes("delivery status notification")
    || subject.includes("delivery incomplete")
    || subject.includes("undeliverable")
    || subject.includes("message not delivered")
    || body.includes("final-recipient:")
    || body.includes("delivery has failed")
    || body.includes("couldn't be delivered");
}

function bounceRecipientEmails(headers: Record<string, string>, bodyText: string) {
  const directLines = [
    headers["x-failed-recipients"],
    ...(bodyText.match(/(?:final-recipient|original-recipient|x-failed-recipients|failed recipient|recipient address|recipient):[^\r\n]+/gi) || []),
    ...(bodyText.match(/(?:message to|your message to)\s+[^\s<>;,"']+@[^\s<>;,"']+/gi) || [])
  ].filter(Boolean).join("\n");
  // Delivery notices often contain sender, postmaster, and forwarded addresses.
  // Only act on an explicitly declared failed recipient.
  const candidates = normalizeEmailList(directLines);
  return candidates.filter((email) => {
    if (email === GMAIL_ALLOWED_SENDER) return false;
    if (email.startsWith("mailer-daemon@") || email.startsWith("postmaster@")) return false;
    if (email.includes("googlemail.com") || email.includes("google.com")) return false;
    return true;
  });
}

function classifyBounce(headers: Record<string, string>, bodyText: string) {
  const text = `${headers.subject || ""}\n${bodyText}`.toLowerCase();
  if (/status:\s*5\./.test(text)
    || /\b5\d\d\b/.test(text)
    || /user unknown|no such user|does not exist|address not found|recipient address rejected|invalid recipient|mailbox unavailable|unknown recipient|unrouteable address/.test(text)) {
    return "hard_bounce";
  }
  if (/status:\s*4\./.test(text)
    || /delivery incomplete|temporar|deferred|delayed|mailbox full|quota|rate limit|greylist/.test(text)) {
    return "delivery_incomplete";
  }
  return "soft_bounce";
}

function bounceReason(headers: Record<string, string>, bodyText: string) {
  const diagnostic = bodyText.match(/diagnostic-code:[^\r\n]+/i)?.[0]
    || bodyText.match(/status:\s*[245]\.[^\r\n]+/i)?.[0]
    || bodyText.match(/(?:address not found|user unknown|does not exist|mailbox unavailable|delivery incomplete|couldn't be delivered)[^\r\n.]*/i)?.[0]
    || headers.subject
    || "Delivery failure detected.";
  return cleanText(diagnostic)?.slice(0, 500) || "Delivery failure detected.";
}

async function vendorRowsForEmail(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  email: string
) {
  const [primaryResult, secondaryResult] = await Promise.all([
    supabase
      .from("vendors")
      .select("id,vendor_name,primary_email,secondary_emails,tags,profile_data")
      .eq("owner_email", user.owner_email)
      .eq("primary_email", email)
      .limit(25),
    supabase
      .from("vendors")
      .select("id,vendor_name,primary_email,secondary_emails,tags,profile_data")
      .eq("owner_email", user.owner_email)
      .contains("secondary_emails", [email])
      .limit(25)
  ]);
  if (primaryResult.error) throw primaryResult.error;
  if (secondaryResult.error) throw secondaryResult.error;
  const byId = new Map<string, Record<string, unknown>>();
  for (const row of [...(primaryResult.data || []), ...(secondaryResult.data || [])]) byId.set(String(row.id), row);
  return [...byId.values()];
}

async function quarantineVendorEmail(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  email: string,
  reason: string
) {
  const rows = await vendorRowsForEmail(supabase, user, email);
  const updatedVendorIds: string[] = [];
  for (const vendor of rows) {
    const secondary = normalizeEmailList(vendor.secondary_emails).filter((item) => item !== email);
    let primary = cleanText(vendor.primary_email)?.toLowerCase() || "";
    if (primary === email) primary = secondary.shift() || "";
    const profileData = objectRecord(vendor.profile_data);
    const bouncedEmails = Array.isArray(profileData.bounced_emails) ? profileData.bounced_emails : [];
    const nextProfileData = {
      ...profileData,
      bounced_emails: [
        { email, reason, detected_at: new Date().toISOString(), source: "gmail_bounce" },
        ...bouncedEmails.filter((item) => objectRecord(item).email !== email)
      ].slice(0, 25)
    };
    const tags = Array.from(new Set([...normalizeTags(vendor.tags), "email_bounce"]));
    const update = await supabase
      .from("vendors")
      .update({
        primary_email: primary,
        secondary_emails: secondary,
        tags,
        profile_data: nextProfileData,
        updated_at: new Date().toISOString()
      })
      .eq("id", vendor.id)
      .eq("owner_email", user.owner_email);
    if (update.error) throw update.error;
    updatedVendorIds.push(String(vendor.id));
  }
  return updatedVendorIds;
}

async function syncGmailBounces(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null },
  input: Record<string, unknown> = {}
) {
  const connectionResult = await supabase
    .from("gmail_mailbox_connections")
    .select("*")
    .eq("owner_email", user.owner_email)
    .eq("mailbox_email", GMAIL_ALLOWED_SENDER)
    .eq("status", "connected")
    .maybeSingle();
  if (connectionResult.error) throw connectionResult.error;
  const connection = connectionResult.data;
  if (!connection) throw new Error(`Connect ${GMAIL_ALLOWED_SENDER} in Settings before syncing delivery failures.`);
  if (!gmailCanReadMailbox(connection)) {
    throw new Error("Reconnect Gmail in Settings to allow Rateware to read delivery failure notices. No password is required.");
  }

  const accessToken = await gmailAccessToken(supabase, user, GMAIL_ALLOWED_SENDER);
  const limit = Math.max(1, Math.min(Number(input.limit) || 50, 100));
  const query = cleanText(input.query) || 'newer_than:45d (from:mailer-daemon@googlemail.com OR from:postmaster OR "Delivery Status Notification" OR "Delivery incomplete" OR "Message not delivered" OR Undeliverable)';
  const listUrl = new URL("https://gmail.googleapis.com/gmail/v1/users/me/messages");
  listUrl.searchParams.set("q", query);
  listUrl.searchParams.set("maxResults", String(limit));
  const listResponse = await fetch(listUrl.toString(), {
    headers: { Authorization: `Bearer ${accessToken}` }
  });
  const listData = await listResponse.json();
  if (!listResponse.ok) {
    throw new Error(cleanText(listData?.error?.message) || `Gmail delivery failure lookup failed (${listResponse.status}).`);
  }

  const now = new Date().toISOString();
  const gmailMessages = Array.isArray(listData.messages) ? listData.messages : [];
  const detected = new Map<string, Record<string, unknown>>();
  let scanned = 0;

  for (const gmailMessage of gmailMessages) {
    const gmailMessageId = cleanText(objectRecord(gmailMessage).id);
    if (!gmailMessageId) continue;
    const detailResponse = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me/messages/${encodeURIComponent(gmailMessageId)}?format=full`, {
      headers: { Authorization: `Bearer ${accessToken}` }
    });
    const detail = await detailResponse.json();
    if (!detailResponse.ok) continue;
    scanned += 1;
    const headers = gmailMessageHeaders(detail);
    const bodyText = gmailPayloadText(objectRecord(detail.payload));
    if (!isDeliveryFailureNotice(headers, bodyText)) continue;
    const status = classifyBounce(headers, bodyText);
    const reason = bounceReason(headers, bodyText);
    const recipients = bounceRecipientEmails(headers, bodyText);
    for (const email of recipients) {
      detected.set(email, {
        email,
        status,
        reason,
        gmail_message_id: gmailMessageId,
        gmail_thread_id: cleanText(detail.threadId),
        subject: headers.subject || "",
        detected_at: now
      });
    }
  }

  if (!detected.size) {
    return { scanned, detected: 0, blocked: 0, cleaned_vendors: 0, rows: [] };
  }

  const emails = [...detected.keys()];
  const messagesResult = await supabase
    .from("outreach_messages")
    .select("id,vendor_id,recipient_email,status,subject,campaign_id,rfx_event_id,metadata")
    .eq("owner_email", user.owner_email)
    .in("recipient_email", emails)
    .order("updated_at", { ascending: false })
    .limit(1000);
  if (messagesResult.error) throw messagesResult.error;
  const messagesByEmail = new Map<string, Record<string, unknown>[]>();
  for (const row of messagesResult.data || []) {
    const email = cleanText(row.recipient_email)?.toLowerCase() || "";
    const bucket = messagesByEmail.get(email) || [];
    bucket.push(row);
    messagesByEmail.set(email, bucket);
  }

  const suppressionRows: Record<string, unknown>[] = [];
  const historyRows: Record<string, unknown>[] = [];
  let cleanedVendors = 0;
  for (const [email, notice] of detected) {
    const relatedMessages = messagesByEmail.get(email) || [];
    const primaryMessage = relatedMessages[0] || {};
    const bounceStatus = cleanText(notice.status) || "soft_bounce";
    const reason = cleanText(notice.reason) || "Delivery failure detected.";
    suppressionRows.push(withOwner({
      email,
      status: bounceStatus,
      reason,
      source: "gmail_bounce",
      outreach_message_id: primaryMessage.id || null,
      vendor_id: primaryMessage.vendor_id || null,
      last_seen_at: now,
      updated_at: now,
      resolved_at: null,
      resolved_by: null,
      replacement_email: null,
      metadata: {
        gmail_message_id: notice.gmail_message_id,
        gmail_thread_id: notice.gmail_thread_id,
        subject: notice.subject
      }
    }, user));

    if (bounceStatus === "hard_bounce") {
      cleanedVendors += (await quarantineVendorEmail(supabase, user, email, reason)).length;
    }

    for (const message of relatedMessages) {
      const nextStatus = bounceStatus === "hard_bounce" ? "bounced" : "failed";
      const update = await supabase
        .from("outreach_messages")
        .update({
          status: nextStatus,
          delivery_error: reason,
          bounce_status: bounceStatus,
          bounce_detected_at: now,
          updated_at: now,
          metadata: {
            ...objectRecord(message.metadata),
            bounce: {
              status: bounceStatus,
              reason,
              gmail_message_id: notice.gmail_message_id,
              detected_at: now
            }
          }
        })
        .eq("id", message.id)
        .eq("owner_email", user.owner_email);
      if (update.error) throw update.error;
      historyRows.push(withOwner({
        outreach_message_id: message.id,
        campaign_id: message.campaign_id,
        vendor_id: message.vendor_id,
        rfx_event_id: message.rfx_event_id,
        channel: "email",
        direction: "inbound",
        status: nextStatus,
        subject: cleanText(message.subject) || "Delivery failure",
        body_preview: reason,
        occurred_at: now,
        metadata: {
          source: "gmail_bounce_sync",
          email,
          bounce_status: bounceStatus,
          gmail_message_id: notice.gmail_message_id
        }
      }, user));
    }
  }

  for (const chunk of chunkValues(suppressionRows, 100)) {
    const result = await supabase
      .from("email_suppression_list")
      .upsert(chunk, { onConflict: "owner_email,email" })
      .select("email,status,reason,updated_at");
    if (result.error) throw result.error;
  }
  if (historyRows.length) {
    for (const chunk of chunkValues(historyRows, 200)) {
      const history = await supabase.from("contact_history").insert(chunk);
      if (history.error) throw history.error;
    }
  }

  await writeAuditLog(
    supabase,
    user,
    "gmail.bounces.sync",
    "email_suppression_list",
    null,
    `Synced ${detected.size} Gmail delivery failure email(s)`,
    { scanned, detected: detected.size, cleaned_vendors: cleanedVendors }
  );

  return {
    scanned,
    detected: detected.size,
    blocked: suppressionRows.filter((row) => row.status === "hard_bounce").length,
    cleaned_vendors: cleanedVendors,
    rows: suppressionRows.map((row) => ({ email: row.email, status: row.status, reason: row.reason }))
  };
}

async function googleChatAccessToken(supabase: RatewareSupabaseClient, user: { owner_email: string | null }) {
  const result = await supabase
    .from("google_chat_connections")
    .select("*")
    .eq("owner_email", user.owner_email)
    .eq("account_email", GOOGLE_CHAT_ALLOWED_ACCOUNT)
    .eq("status", "connected")
    .maybeSingle();
  if (result.error) throw result.error;
  const connection = result.data;
  if (!connection) throw new Error(`Connect ${GOOGLE_CHAT_ALLOWED_ACCOUNT} in Settings before using Google Chat.`);

  const expiresAt = connection.token_expires_at ? new Date(connection.token_expires_at).getTime() : 0;
  if (connection.access_token_encrypted && expiresAt > Date.now() + 120_000) {
    return await decryptGmailToken(connection.access_token_encrypted);
  }

  const clientId = Deno.env.get("GOOGLE_CLIENT_ID");
  const clientSecret = Deno.env.get("GOOGLE_CLIENT_SECRET");
  if (!clientId || !clientSecret) throw new Error("Google OAuth client is not configured.");
  const refreshToken = await decryptGmailToken(connection.refresh_token_encrypted);
  const tokenResponse = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      client_id: clientId,
      client_secret: clientSecret,
      refresh_token: refreshToken,
      grant_type: "refresh_token"
    })
  });
  const tokenData = await tokenResponse.json();
  if (!tokenResponse.ok || !tokenData.access_token) {
    const message = cleanText(tokenData.error_description) || cleanText(tokenData.error) || "Google Chat token refresh failed.";
    await supabase
      .from("google_chat_connections")
      .update({ status: "error", last_error: message, updated_at: new Date().toISOString() })
      .eq("owner_email", user.owner_email)
      .eq("account_email", GOOGLE_CHAT_ALLOWED_ACCOUNT);
    throw new Error(message);
  }

  const accessToken = String(tokenData.access_token);
  const expiresIn = Number(tokenData.expires_in) || 3600;
  const update = await supabase
    .from("google_chat_connections")
    .update({
      access_token_encrypted: await encryptGmailToken(accessToken),
      token_expires_at: new Date(Date.now() + expiresIn * 1000).toISOString(),
      last_error: null,
      updated_at: new Date().toISOString()
    })
    .eq("owner_email", user.owner_email)
    .eq("account_email", GOOGLE_CHAT_ALLOWED_ACCOUNT);
  if (update.error) throw update.error;
  return accessToken;
}

function normalizeGoogleChatSpaceName(value: unknown) {
  const text = cleanText(value);
  if (!text) return null;
  const directMatch = text.match(/^spaces\/([A-Za-z0-9_-]+)$/i);
  if (directMatch) return `spaces/${directMatch[1]}`;

  try {
    const url = new URL(text);
    const combined = `${url.pathname} ${url.hash} ${url.search}`;
    const urlMatch = combined.match(/(?:\/|#)(?:chat\/)?(?:space|room)\/([A-Za-z0-9_-]+)/i);
    if (urlMatch) return `spaces/${urlMatch[1]}`;
  } catch {
    // Not a URL; fall through to raw ID parsing.
  }

  const rawId = text.replace(/^space\s*[:=]\s*/i, "").trim();
  if (/^[A-Za-z0-9_-]{5,}$/.test(rawId) && !rawId.includes("/")) return `spaces/${rawId}`;
  return null;
}

function publicGoogleChatSpace(space: Record<string, unknown>, fallbackName: string | null = null) {
  const name = cleanText(space.name) || fallbackName;
  return {
    name,
    display_name: cleanText(space.displayName) || cleanText(space.spaceUri) || name,
    type: cleanText(space.spaceType),
    threaded: space.threaded,
    space_threading_state: cleanText(space.spaceThreadingState)
  };
}

async function getGoogleChatSpaceDetails(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  spaceReference: unknown
) {
  const spaceName = normalizeGoogleChatSpaceName(spaceReference);
  if (!spaceName) {
    throw new Error("Paste a valid Google Chat Space link or resource name like spaces/AAA...");
  }
  const accessToken = await googleChatAccessToken(supabase, user);
  const response = await fetch(`https://chat.googleapis.com/v1/${spaceName}`, {
    headers: { Authorization: `Bearer ${accessToken}` }
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) {
    const message = cleanText(payload?.error?.message) || `Google Chat space lookup failed (${response.status}).`;
    throw new Error(`${message} Confirm ${GOOGLE_CHAT_ALLOWED_ACCOUNT} is a member of that Space.`);
  }
  return publicGoogleChatSpace(payload, spaceName);
}

async function listGoogleChatSpaces(supabase: RatewareSupabaseClient, user: { owner_email: string | null }) {
  const connectionResult = await supabase
    .from("google_chat_connections")
    .select("default_space_name,default_space_display_name,status")
    .eq("owner_email", user.owner_email)
    .eq("account_email", GOOGLE_CHAT_ALLOWED_ACCOUNT)
    .eq("status", "connected")
    .maybeSingle();
  if (connectionResult.error) throw connectionResult.error;
  if (!connectionResult.data) return { connected: false, rows: [], default_space_name: null };

  const accessToken = await googleChatAccessToken(supabase, user);
  const rows: Record<string, unknown>[] = [];
  const seen = new Set<string>();
  let pageToken = "";
  for (let page = 0; page < 10; page += 1) {
    const url = new URL("https://chat.googleapis.com/v1/spaces");
    url.searchParams.set("pageSize", "100");
    if (pageToken) url.searchParams.set("pageToken", pageToken);
    const response = await fetch(url.toString(), {
      headers: { Authorization: `Bearer ${accessToken}` }
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      const message = cleanText(payload?.error?.message) || `Google Chat spaces lookup failed (${response.status}).`;
      throw new Error(message);
    }
    if (Array.isArray(payload.spaces)) {
      for (const space of payload.spaces) {
        const row = publicGoogleChatSpace(space);
        const name = cleanText(row.name);
        if (name && !seen.has(name)) {
          seen.add(name);
          rows.push(row);
        }
      }
    }
    pageToken = cleanText(payload.nextPageToken) || "";
    if (!pageToken) break;
  }
  return {
    connected: true,
    rows,
    default_space_name: connectionResult.data.default_space_name || null,
    default_space_display_name: connectionResult.data.default_space_display_name || null
  };
}

async function saveGoogleChatSettings(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  input: Record<string, unknown>
) {
  const spaceName = cleanText(input.default_space_name || input.space_name || input.manual_space_name || input.space_link);
  if (!spaceName) throw new Error("Select a Google Chat space or paste the Space link first.");
  const spaces = await listGoogleChatSpaces(supabase, user);
  const selected = (spaces.rows || []).find((space: Record<string, unknown>) => cleanText(space.name) === spaceName);
  const resolved = selected || await getGoogleChatSpaceDetails(supabase, user, spaceName);
  const result = await supabase
    .from("google_chat_connections")
    .update({
      default_space_name: resolved.name,
      default_space_display_name: resolved.display_name,
      last_error: null,
      updated_at: new Date().toISOString()
    })
    .eq("owner_email", user.owner_email)
    .eq("account_email", GOOGLE_CHAT_ALLOWED_ACCOUNT)
    .eq("status", "connected")
    .select("account_email,provider,status,scopes,token_expires_at,updated_at,last_error,default_space_name,default_space_display_name")
    .single();
  if (result.error) throw result.error;
  return publicGoogleChatConnection(result.data);
}

function messageInvitationIds(message: Record<string, unknown>) {
  const metadata = objectRecord(message.metadata);
  const ids = Array.isArray(metadata.rfx_lane_vendor_ids)
    ? metadata.rfx_lane_vendor_ids.map(String).filter(Boolean)
    : [];
  const directId = cleanText(message.rfx_lane_vendor_id);
  return [...new Set([directId, ...ids].filter(Boolean))];
}

const OUTREACH_SENDABLE_STATUSES = new Set(["drafted", "queued", "failed"]);

function outreachSendResult(
  stage: string,
  details: Record<string, unknown> = {}
) {
  return {
    stage,
    recorded_at: new Date().toISOString(),
    ...details
  };
}

async function gmailConnectionIdentity(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  senderEmail: string
) {
  const result = await supabase
    .from("gmail_mailbox_connections")
    .select("id,mailbox_email,provider,status")
    .eq("owner_email", user.owner_email)
    .eq("mailbox_email", senderEmail.toLowerCase())
    .maybeSingle();
  if (result.error) throw result.error;
  return (result.data || null) as Record<string, unknown> | null;
}

async function gmailApiGet(accessToken: string, path: string) {
  const response = await fetch(`https://gmail.googleapis.com/gmail/v1/users/me${path}`, {
    headers: { Authorization: `Bearer ${accessToken}` }
  });
  const data = await response.json().catch(() => ({})) as Record<string, unknown>;
  if (!response.ok) {
    const reason = cleanText(objectRecord(data.error).message) || `Gmail request failed (${response.status}).`;
    throw new Error(reason);
  }
  return data;
}

function gmailReplyCandidateFromThread(
  thread: Record<string, unknown>,
  vendorEmails: string[]
) {
  const emailSet = new Set(vendorEmails.map((email) => email.toLowerCase()));
  const messages = Array.isArray(thread.messages) ? thread.messages.map(objectRecord) : [];
  const carrierMessages = messages.filter((message) => emailSet.has(normalizeEmail(gmailPayloadHeader(message, "From")) || ""));
  const latest = carrierMessages.sort((left, right) => gmailMessageTimestamp(right) - gmailMessageTimestamp(left))[0];
  if (!latest) return null;
  const rfcMessageId = gmailPayloadHeader(latest, "Message-ID");
  const referenceParts = [gmailPayloadHeader(latest, "References"), rfcMessageId].filter(Boolean);
  return {
    reply_mode: "thread_reply",
    gmail_thread_id: cleanText(thread.id) || cleanText(latest.threadId),
    gmail_source_message_id: cleanText(latest.id),
    gmail_in_reply_to: rfcMessageId,
    gmail_references: [...new Set(referenceParts)].join(" "),
    source_subject: gmailPayloadHeader(latest, "Subject"),
    source_received_at: gmailMessageTimestamp(latest) ? new Date(gmailMessageTimestamp(latest)).toISOString() : null,
    recipient_email: normalizeEmail(gmailPayloadHeader(latest, "From")) || ""
  };
}

function gmailThreadMatchesRfx(thread: Record<string, unknown>, rfxId: string) {
  const key = cleanText(rfxId)?.toLowerCase();
  if (!key) return false;
  const messages = Array.isArray(thread.messages) ? thread.messages.map(objectRecord) : [];
  return messages.some((message) => gmailPayloadHeader(message, "Subject").toLowerCase().includes(key));
}

async function resolveBidRoomGmailReplyContext(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  event: Record<string, unknown>,
  vendor: Record<string, unknown>,
  recipientEmail: string
) {
  const vendorEmails = vendorContactEmailCandidates(vendor);
  const accessToken = await gmailAccessToken(supabase, user, GMAIL_ALLOWED_SENDER);
  const knownMessages = await supabase
    .from("outreach_messages")
    .select("id,provider_thread_id,provider_message_id,recipient_email,subject,sent_at,updated_at")
    .eq("owner_email", user.owner_email)
    .eq("rfx_event_id", event.id)
    .eq("vendor_id", vendor.id)
    .eq("channel", "email")
    .not("provider_thread_id", "is", null)
    .order("updated_at", { ascending: false })
    .limit(24);
  if (knownMessages.error) throw knownMessages.error;

  const knownCandidates: Record<string, unknown>[] = [];
  const checkedThreadIds = new Set<string>();
  for (const message of knownMessages.data || []) {
    const threadId = cleanText(message.provider_thread_id);
    if (!threadId || checkedThreadIds.has(threadId)) continue;
    checkedThreadIds.add(threadId);
    try {
      const thread = await gmailApiGet(accessToken, `/threads/${encodeURIComponent(threadId)}?format=metadata&metadataHeaders=From&metadataHeaders=Subject&metadataHeaders=Message-ID&metadataHeaders=References&metadataHeaders=Date`);
      const candidate = gmailReplyCandidateFromThread(thread, vendorEmails);
      if (candidate?.gmail_thread_id) knownCandidates.push(candidate);
    } catch (error) {
      // A deleted Gmail thread must not prevent a deliberate new email. Other
      // Gmail failures are detected again by the actual send operation.
      if (!/\b404\b/.test(safeOperationalError(error))) throw error;
    }
  }
  if (knownCandidates.length) {
    const latest = knownCandidates.sort((left, right) => Date.parse(String(right.source_received_at || 0)) - Date.parse(String(left.source_received_at || 0)))[0];
    return { ...latest, recipient_email: cleanText(latest.recipient_email) || recipientEmail };
  }

  const rfxId = cleanText(event.rfx_id);
  if (rfxId) {
    const searchedThreadIds = new Set<string>();
    const discovered: Record<string, unknown>[] = [];
    for (const email of vendorEmails) {
      const query = new URLSearchParams({ q: `from:${email} "${rfxId}"`, maxResults: "12" });
      const search = await gmailApiGet(accessToken, `/messages?${query.toString()}`);
      const messages = Array.isArray(search.messages) ? search.messages.map(objectRecord) : [];
      for (const message of messages) {
        const threadId = cleanText(message.threadId);
        if (!threadId || searchedThreadIds.has(threadId)) continue;
        searchedThreadIds.add(threadId);
        const thread = await gmailApiGet(accessToken, `/threads/${encodeURIComponent(threadId)}?format=metadata&metadataHeaders=From&metadataHeaders=Subject&metadataHeaders=Message-ID&metadataHeaders=References&metadataHeaders=Date`);
        if (!gmailThreadMatchesRfx(thread, rfxId)) continue;
        const candidate = gmailReplyCandidateFromThread(thread, vendorEmails);
        if (candidate?.gmail_thread_id) discovered.push(candidate);
      }
    }
    if (discovered.length) {
      const latest = discovered.sort((left, right) => Date.parse(String(right.source_received_at || 0)) - Date.parse(String(left.source_received_at || 0)))[0];
      return { ...latest, recipient_email: cleanText(latest.recipient_email) || recipientEmail };
    }
  }

  return {
    reply_mode: "new_email",
    gmail_thread_id: null,
    gmail_source_message_id: null,
    gmail_in_reply_to: null,
    gmail_references: null,
    source_subject: null,
    source_received_at: null,
    recipient_email: recipientEmail
  };
}

async function claimOutreachMessageForSend(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  message: Record<string, unknown>,
  trace: Record<string, unknown> = {}
) {
  const status = cleanText(message.status)?.toLowerCase() || "";
  if (!OUTREACH_SENDABLE_STATUSES.has(status)) return null;
  const attemptId = crypto.randomUUID();
  const startedAt = new Date().toISOString();
  const result = await supabase
    .from("outreach_messages")
    .update({
      ...trace,
      status: "sending",
      send_attempt_id: attemptId,
      send_started_at: startedAt,
      send_completed_at: null,
      delivery_error: null,
      provider_response_status: "sending",
      send_result: outreachSendResult("sending", {
        ...objectRecord(trace.send_result),
        attempt_id: attemptId,
        channel: cleanText(trace.channel || message.channel),
        provider: cleanText(trace.provider || message.provider)
      }),
      updated_at: startedAt
    })
    .eq("id", message.id)
    .eq("owner_email", user.owner_email)
    .eq("status", status)
    .select("*")
    .maybeSingle();
  if (result.error) throw result.error;
  return result.data ? { row: result.data as Record<string, unknown>, attemptId, startedAt } : null;
}

async function updateClaimedOutreachMessage(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  messageId: unknown,
  attemptId: string,
  patch: Record<string, unknown>
) {
  const result = await supabase
    .from("outreach_messages")
    .update({ ...patch, updated_at: new Date().toISOString() })
    .eq("id", messageId)
    .eq("owner_email", user.owner_email)
    .eq("status", "sending")
    .eq("send_attempt_id", attemptId)
    .select("*")
    .maybeSingle();
  if (result.error) throw result.error;
  return result.data as Record<string, unknown> | null;
}

async function markClaimedOutreachFailure(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  message: Record<string, unknown>,
  attemptId: string,
  reason: string,
  uncertain = false,
  extra: Record<string, unknown> = {}
) {
  const now = new Date().toISOString();
  const { send_result: extraSendResult, ...extraPatch } = extra;
  return await updateClaimedOutreachMessage(supabase, user, message.id, attemptId, {
    status: uncertain ? "delivery_unknown" : "failed",
    delivery_status: uncertain ? "delivery_unknown" : "failed",
    failed_at: uncertain ? null : now,
    send_completed_at: now,
    delivery_error: reason,
    provider_response_status: uncertain ? "delivery_unknown" : "failed",
    ...extraPatch,
    send_result: outreachSendResult("completed", {
      ...objectRecord(message.send_result),
      ...objectRecord(extraSendResult),
      attempt_id: attemptId,
      outcome: uncertain ? "delivery_unknown" : "failed",
      error: reason
    })
  });
}

async function writeOutreachSentHistory(
  supabase: RatewareSupabaseClient,
  row: Record<string, unknown>
) {
  const result = await supabase.from("contact_history").insert(row);
  if (result.error && String(result.error.code || "") !== "23505") throw result.error;
}

async function writeOutreachDeliveryIssueHistory(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null },
  message: Record<string, unknown>,
  {
    channel,
    status,
    reason,
    provider,
    connectionId = null,
    sender = null,
    extraMetadata = {}
  }: {
    channel: string;
    status: "failed" | "delivery_unknown";
    reason: string;
    provider: string;
    connectionId?: unknown;
    sender?: unknown;
    extraMetadata?: Record<string, unknown>;
  }
) {
  await writeOutreachSentHistory(supabase, withOwner({
    outreach_message_id: message.id,
    campaign_id: message.campaign_id,
    vendor_id: message.vendor_id,
    rfx_event_id: message.rfx_event_id,
    channel,
    direction: "outbound",
    status,
    subject: message.subject,
    body_preview: contactPreview(message.text_body || message.html_body || message.whatsapp_body || message.whatsapp_text),
    occurred_at: new Date().toISOString(),
    metadata: {
      provider,
      connection_id: cleanText(connectionId),
      sender: cleanText(sender),
      delivery_status: status,
      delivery_error: reason,
      outcome: status,
      source: "outreach_send_attempt",
      ...extraMetadata
    }
  }, user));
}

async function sendOutreachMessages(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null },
  input: Record<string, unknown>
) {
  const requestedProvider = cleanText(input.provider)?.toLowerCase() || "gmail";
  const requestedChannel = cleanText(input.channel)?.toLowerCase() || "email";
  if (requestedProvider !== "gmail" || !["email", "gmail", "gmail_only"].includes(requestedChannel)) {
    throw new Error("Gmail send only accepts email outreach drafts.");
  }
  const ids = normalizeBulkIds(input.ids, { label: "Outreach message ids", limit: BULK_SEND_LIMIT });
  if (!ids.length) return { sent: 0, failed: 0, rows: [], failures: [] };
  requireBulkConfirmation(input, {
    action: "send_outreach_messages",
    label: "Gmail bulk send",
    count: ids.length
  });

  const messagesResult = await supabase
    .from("outreach_messages")
    .select("*")
    .eq("owner_email", user.owner_email)
    .in("id", ids)
    .order("created_at", { ascending: true });
  if (messagesResult.error) throw messagesResult.error;

  const rowsById = new Map<string, Record<string, unknown>>();
  for (const message of messagesResult.data || []) {
    const id = cleanText(message.id);
    if (id) rowsById.set(id, message);
  }
  const messages: Record<string, unknown>[] = [];
  const failures: Record<string, unknown>[] = [];
  const skipped: Record<string, unknown>[] = [];
  for (const id of ids) {
    const message = rowsById.get(id);
    if (!message) {
      failures.push({ id, reason: "Message was not found in your workspace." });
      continue;
    }
    if (cleanText(message.channel) !== "email") {
      failures.push({ id, reason: `Message channel is ${cleanText(message.channel) || "unknown"}; expected email.` });
      continue;
    }
    messages.push(message);
  }
  if (!messages.length) {
    return {
      sent: 0,
      failed: failures.length,
      skipped: 0,
      skipped_rows: [],
      rows: [],
      failures
    };
  }
  const campaignIds = [...new Set(messages.map((message) => cleanText(message.campaign_id)).filter(Boolean))];
  const senderCandidates = new Set(messages.map((message) => cleanText(message.sender_email)?.toLowerCase()).filter(Boolean));
  if (senderCandidates.size > 1 && !cleanText(input.sender_email)) throw new Error("Bulk send has multiple sender accounts. Select one sender before sending.");
  const senderEmail = (cleanText(input.sender_email) || cleanText(messages[0].sender_email) || GMAIL_ALLOWED_SENDER).toLowerCase();
  if (senderEmail !== GMAIL_ALLOWED_SENDER) throw new Error(`Gmail sender must be ${GMAIL_ALLOWED_SENDER}.`);
  const suppressedEmails = await suppressedEmailSet(
    supabase,
    user,
    messages.map((message) => cleanText(message.recipient_email)).filter(Boolean) as string[]
  );
  const accessToken = await gmailAccessToken(supabase, user, senderEmail);
  const gmailConnection = await gmailConnectionIdentity(supabase, user, senderEmail);
  const gmailConnectionId = cleanText(gmailConnection?.id) || null;
  const gmailConnectionType = "gmail_oauth";
  const now = new Date().toISOString();
  const sentRows: Record<string, unknown>[] = [];
  let deliveryUnknown = 0;

  for (const message of messages) {
    const status = cleanText(message.status)?.toLowerCase();
    if (status && !["drafted", "queued", "failed"].includes(status)) {
      failures.push({ id: message.id, reason: `Message is ${status}.` });
      continue;
    }
    if (message.status === "sent" || message.status === "archived") {
      failures.push({ id: message.id, reason: `Message is ${message.status}.` });
      continue;
    }
    if (!cleanText(message.recipient_email)) {
      failures.push({ id: message.id, reason: "Missing recipient email." });
      await supabase
        .from("outreach_messages")
        .update({
          status: "failed",
          delivery_status: "failed",
          failed_at: now,
          delivery_error: "Missing recipient email.",
          provider: "gmail",
          gmail_connection_id: gmailConnectionId,
          sender_address: senderEmail,
          sender_connection_type: gmailConnectionType,
          provider_response_status: "validation_failed",
          send_result: outreachSendResult("completed", {
            channel: "email",
            provider: "gmail",
            outcome: "validation_failed",
            error: "Missing recipient email."
          }),
          updated_at: now
        })
        .eq("id", message.id)
        .eq("owner_email", user.owner_email);
      continue;
    }
    const recipientEmail = cleanText(message.recipient_email)?.toLowerCase() || "";
    if (suppressedEmails.has(recipientEmail)) {
      const reason = "Recipient email is blocked because a prior delivery failure was detected.";
      failures.push({ id: message.id, recipient_email: message.recipient_email, reason });
      await supabase
        .from("outreach_messages")
        .update({
          status: "bounced",
          delivery_status: "bounced",
          delivery_error: reason,
          bounce_status: "hard_bounce",
          provider: "gmail",
          gmail_connection_id: gmailConnectionId,
          sender_address: senderEmail,
          sender_connection_type: gmailConnectionType,
          provider_response_status: "suppressed",
          send_result: outreachSendResult("completed", {
            channel: "email",
            provider: "gmail",
            outcome: "suppressed",
            error: reason
          }),
          updated_at: now
        })
        .eq("id", message.id)
        .eq("owner_email", user.owner_email);
      continue;
    }

    let claim: Awaited<ReturnType<typeof claimOutreachMessageForSend>> = null;
    try {
      claim = await claimOutreachMessageForSend(supabase, user, message, {
        channel: "email",
        provider: "gmail",
        gmail_connection_id: gmailConnectionId,
        sender_email: senderEmail,
        sender_address: senderEmail,
        sender_connection_type: gmailConnectionType,
        send_result: {
          connection_id: gmailConnectionId,
          sender: senderEmail
        }
      });
    } catch (error) {
      failures.push({ id: message.id, recipient_email: message.recipient_email, reason: safeOperationalError(error) });
      continue;
    }
    if (!claim) {
      skipped.push({ id: message.id, reason: "Message was already claimed or completed by another request." });
      continue;
    }

    let providerAccepted = false;
    try {
      let response: Response;
      try {
        const gmailThreadId = cleanText(objectRecord(message.metadata).gmail_thread_id);
        response = await fetch("https://gmail.googleapis.com/gmail/v1/users/me/messages/send", {
          method: "POST",
          headers: {
            Authorization: `Bearer ${accessToken}`,
            "Content-Type": "application/json"
          },
          body: JSON.stringify({
            raw: gmailRawMessage(message, senderEmail),
            ...(gmailThreadId ? { threadId: gmailThreadId } : {})
          })
        });
      } catch (error) {
        const requestError = new Error(error instanceof Error ? error.message : "Gmail did not return a response.");
        (requestError as Error & { deliveryUncertain?: boolean }).deliveryUncertain = true;
        throw requestError;
      }
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        const reason = cleanText(data?.error?.message) || cleanText(data?.error_description) || `Gmail send failed (${response.status}).`;
        const responseError = new Error(reason);
        (responseError as Error & { deliveryUncertain?: boolean }).deliveryUncertain = response.status === 408 || response.status >= 500;
        throw responseError;
      }
      providerAccepted = true;

      const updateResult = await updateClaimedOutreachMessage(supabase, user, message.id, claim.attemptId, {
        status: "sent",
        delivery_status: "sent",
        sent_at: now,
        send_completed_at: now,
        last_contacted_at: now,
        sender_email: senderEmail,
        sender_connection_status: "connected",
        sender_address: senderEmail,
        sender_connection_type: gmailConnectionType,
        provider: "gmail",
        gmail_connection_id: gmailConnectionId,
        provider_message_id: cleanText(data.id),
        provider_thread_id: cleanText(data.threadId),
        provider_response_status: "accepted",
        delivery_error: null,
        delivered_by: GMAIL_ALLOWED_SENDER,
        send_result: outreachSendResult("completed", {
          attempt_id: claim.attemptId,
          channel: "email",
          provider: "gmail",
          outcome: "accepted",
          connection_id: gmailConnectionId,
          sender: senderEmail,
          provider_message_id: cleanText(data.id),
          provider_thread_id: cleanText(data.threadId)
        })
      });
      if (!updateResult) throw new Error("Gmail accepted the message, but its delivery claim could not be finalized.");
      sentRows.push(updateResult);

      try {
        await writeOutreachSentHistory(supabase, withOwner({
          gmail_connection_id: gmailConnectionId,
          outreach_message_id: message.id,
          campaign_id: message.campaign_id,
          vendor_id: message.vendor_id,
          rfx_event_id: message.rfx_event_id,
          channel: "email",
          direction: "outbound",
          status: "sent",
          subject: message.subject,
          body_preview: contactPreview(message.text_body || message.html_body),
          occurred_at: now,
          metadata: {
            sent_from: "gmail_api",
            provider: "gmail",
            gmail_connection_id: gmailConnectionId,
            sender_connection_type: gmailConnectionType,
            sender_email: senderEmail,
            provider_message_id: cleanText(data.id),
            gmail_thread_id: cleanText(data.threadId),
            result: "accepted",
            source: cleanText(objectRecord(message.metadata).source),
            ratebook_id: cleanText(objectRecord(message.metadata).ratebook_id),
            ratebook_share_id: cleanText(objectRecord(message.metadata).ratebook_share_id)
          }
        }, user));

        const invitationIds = messageInvitationIds(message);
        if (invitationIds.length) {
          const invitationUpdate = await supabase
            .from("rfx_lane_vendors")
            .update({ invitation_status: "invited", invited_at: now, updated_at: now })
            .in("id", invitationIds)
            .not("invitation_status", "in", "(quoted,bid_submitted,awarded,archived)");
          if (invitationUpdate.error) throw invitationUpdate.error;
        }
      } catch (error) {
        try {
          await writeAuditLog(supabase, user, "gmail.post_send_sync_failed", "outreach_messages", String(message.id), "Gmail accepted outreach, but follow-up synchronization failed", {
            provider_message_id: cleanText(data.id),
            error: safeOperationalError(error)
          });
        } catch (_) {
          // Provider acceptance is authoritative; diagnostics cannot make the message retryable.
        }
      }
    } catch (error) {
      const reason = safeOperationalError(error);
      const uncertain = providerAccepted || Boolean((error as Error & { deliveryUncertain?: boolean })?.deliveryUncertain);
      if (uncertain) deliveryUnknown += 1;
      failures.push({ id: message.id, recipient_email: message.recipient_email, reason, delivery_unknown: uncertain });
      try {
        await markClaimedOutreachFailure(supabase, user, message, claim.attemptId, reason, uncertain, {
          sender_email: senderEmail,
          sender_connection_status: "connected",
          sender_address: senderEmail,
          sender_connection_type: gmailConnectionType,
          provider: "gmail",
          gmail_connection_id: gmailConnectionId,
          send_result: {
            channel: "email",
            provider: "gmail",
            connection_id: gmailConnectionId,
            sender: senderEmail
          }
        });
        await writeOutreachDeliveryIssueHistory(supabase, user, message, {
          channel: "email",
          status: uncertain ? "delivery_unknown" : "failed",
          reason,
          provider: "gmail",
          connectionId: gmailConnectionId,
          sender: senderEmail,
          extraMetadata: {
            gmail_connection_id: gmailConnectionId,
            sender_connection_type: gmailConnectionType,
            delivery_unknown: uncertain
          }
        });
      } catch (_) {
        // The send claim remains locked if persistence is unavailable, preventing an unsafe retry.
      }
    }
  }

  const sentCampaignIds = [...new Set(sentRows.map((row) => cleanText(row.campaign_id)).filter(Boolean))];
  if (sentCampaignIds.length) {
    const campaignUpdate = await supabase
      .from("outreach_campaigns")
      .update({ status: "sent", sender_email: senderEmail, sender_connection_status: "connected", updated_at: now })
      .eq("owner_email", user.owner_email)
      .in("id", sentCampaignIds);
    if (campaignUpdate.error) {
      try {
        await writeAuditLog(supabase, user, "outreach.campaign_status_sync_failed", "outreach_campaigns", sentCampaignIds.join(","), "Messages were sent but campaign status synchronization failed", {
          error: safeOperationalError(campaignUpdate.error)
        });
      } catch (_) {
        // Message delivery must not be reported as failed after provider acceptance.
      }
    }
  }

  await tryWriteAuditLog(
    supabase,
    user,
    "outreach.gmail.bulk_send",
    "outreach_messages",
    campaignIds.join(",") || ids.join(","),
    `Processed ${ids.length} Gmail outreach message(s)`,
    {
      requested: ids.length,
      sent: sentRows.length,
      failed: failures.length,
      skipped: skipped.length,
      delivery_unknown: deliveryUnknown,
      sender_email: senderEmail,
      campaign_ids: campaignIds,
      campaign_count: campaignIds.length
    }
  );
  return { sent: sentRows.length, failed: failures.length, skipped: skipped.length, delivery_unknown: deliveryUnknown, rows: sentRows, failures, skipped_rows: skipped };
}

async function metaSendWhatsappTemplate(
  message: Record<string, unknown>,
  connection: Awaited<ReturnType<typeof activeWhatsappConnection>>
) {
  const to = normalizeWhatsappPhone(message.normalized_recipient_phone || message.recipient_phone);
  const language = cleanText(message.whatsapp_template_language) || "en";
  const templateName = whatsappCanonicalTemplateName(message.whatsapp_template_name, language);
  const metadata = objectRecord(message.metadata);
  const templateStatus = cleanText(metadata.whatsapp_template_status)
    ? whatsappMetaStatus(metadata.whatsapp_template_status)
    : templateName ? "NOT_SYNCED" : "NOT_PUBLISHED";
  const parameterRows = Array.isArray(metadata.whatsapp_template_parameters)
    ? metadata.whatsapp_template_parameters.filter((row) => row && typeof row === "object") as Record<string, unknown>[]
    : [];
  if (!to) throw new Error("Missing WhatsApp recipient phone.");
  if (!templateName) throw new Error("Publish this Outreach template to Meta and wait for approval before sending WhatsApp messages.");
  if (templateStatus !== "APPROVED") {
    const templateError = cleanText(metadata.whatsapp_template_error);
    if (templateError) throw new Error(templateError);
    if (whatsappMetaStatusNeedsApproval(templateStatus)) {
      throw new Error(`WhatsApp Meta notifier is ${whatsappMetaStatusLabel(templateStatus)}. Direct WhatsApp sends unlock after Meta approves it; Rateware will refresh status when you generate or send the queue again.`);
    }
    if (templateStatus === "LANGUAGE_MISMATCH") {
      throw new Error(`WhatsApp Meta notifier has no approved translation compatible with ${String(language).replace(/_/g, "-")}. Add or approve that language in Meta, then sync templates.`);
    }
    if (["NOT_SYNCED", "NOT_FOUND"].includes(templateStatus)) {
      throw new Error("WhatsApp Meta notifier has not been verified in this sender's current template catalog. Sync Meta templates or regenerate the queue before sending.");
    }
    throw new Error(`WhatsApp template is ${whatsappMetaStatusLabel(templateStatus)}. Sync Meta templates after it is approved.`);
  }
  const components = parameterRows.length
    ? [{
        type: "body",
        parameters: parameterRows.map((row) => ({
          type: "text",
          text: cleanText(row.value) || "-"
        }))
      }]
    : [];
  const languages = whatsappTemplateLanguageCandidates(language);
  let lastError: unknown = null;
  for (const languageCode of languages) {
    try {
      return await whatsappGraphFetch(connection, `${connection.phoneNumberId}/messages`, {
        method: "POST",
        body: JSON.stringify({
          messaging_product: "whatsapp",
          recipient_type: "individual",
          to,
          type: "template",
          template: {
            name: templateName,
            language: { code: languageCode },
            ...(components.length ? { components } : {})
          }
        })
      });
    } catch (error) {
      lastError = error;
      if (!isWhatsappTemplateTranslationError(error)) throw error;
    }
  }
  const detail = lastError instanceof Error ? lastError.message : String(lastError || "WhatsApp template send failed.");
  throw new Error(`Meta could not find template "${templateName}" for language(s) ${languages.join(", ")}. ${detail}`);
}

async function updateWhatsappMessageFailure(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  message: Record<string, unknown>,
  reason: string,
  now = new Date().toISOString(),
  connection: { row: Record<string, unknown> } | null = null
) {
  const connectionId = cleanText(connection?.row?.id || message.whatsapp_connection_id) || null;
  const connectionType = cleanText(connection?.row?.connection_mode) || "unresolved";
  const senderAddress = cleanText(connection?.row?.display_phone_number) || null;
  const metadata = {
    ...objectRecord(message.metadata),
    whatsapp_last_error: reason,
    whatsapp_last_error_at: now
  };
  await supabase
    .from("outreach_messages")
    .update({
      status: "failed",
      delivery_status: "failed",
      failed_at: now,
      delivery_error: reason,
      provider: "meta",
      // Keep the resolved Meta mapping on retriable failures. Without this, the
      // draft queue loses the template name/status that explains why Meta blocked it.
      whatsapp_connection_id: connectionId,
      whatsapp_template_name: cleanText(message.whatsapp_template_name) || null,
      whatsapp_template_language: cleanText(message.whatsapp_template_language) || null,
      sender_address: senderAddress,
      sender_connection_type: connectionType,
      provider_response_status: "failed",
      send_completed_at: now,
      send_result: outreachSendResult("completed", {
        channel: cleanText(message.channel) || "whatsapp",
        provider: "meta",
        outcome: "failed",
        connection_id: connectionId,
        sender: senderAddress,
        error: reason
      }),
      metadata,
      updated_at: now
    })
    .eq("id", message.id)
    .eq("owner_email", user.owner_email);
}

async function sendWhatsappOutreachMessages(
  supabase: RatewareSupabaseClient,
  user: RatewareUser,
  input: Record<string, unknown>
) {
  const ids = normalizeBulkIds(input.ids, { label: "WhatsApp message ids", limit: BULK_SEND_LIMIT });
  if (!ids.length) return { sent: 0, failed: 0, rows: [], failures: [] };
  requireBulkConfirmation(input, {
    action: "send_whatsapp_outreach_messages",
    label: "WhatsApp bulk send",
    count: ids.length
  });
  const messagesResult = await supabase
    .from("outreach_messages")
    .select("*, vendors(id,vendor_name,domain,whatsapp_do_not_contact,whatsapp_permission_basis)")
    .eq("owner_email", user.owner_email)
    .in("id", ids)
    .order("created_at", { ascending: true });
  if (messagesResult.error) throw messagesResult.error;
  const rowsById = new Map<string, Record<string, unknown>>();
  for (const message of messagesResult.data || []) {
    const id = cleanText(message.id);
    if (id) rowsById.set(id, message);
  }
  const messages: Record<string, unknown>[] = [];
  const failures: Record<string, unknown>[] = [];
  const skipped: Record<string, unknown>[] = [];
  for (const id of ids) {
    const message = rowsById.get(id);
    if (!message) {
      failures.push({ id, reason: "Message was not found in your workspace." });
      continue;
    }
    if (cleanText(message.channel) !== "whatsapp") {
      failures.push({ id, reason: `Message channel is ${cleanText(message.channel) || "unknown"}; expected WhatsApp.` });
      continue;
    }
    messages.push(message);
  }
  if (!messages.length) {
    return { sent: 0, failed: failures.length, skipped: 0, rows: [], skipped_rows: [], failures };
  }

  const connection = await validatedWhatsappConnection(supabase, user);

  const now = new Date().toISOString();
  const rows: Record<string, unknown>[] = [];
  let deliveryUnknown = 0;
  const notifierByTemplate = new Map<string, Record<string, unknown>>();
  for (const message of messages) {
    const vendor = typeof message.vendors === "object" && message.vendors ? message.vendors as Record<string, unknown> : {};
    const status = cleanText(message.status)?.toLowerCase();
    if (!["drafted", "queued", "failed"].includes(status || "")) {
      failures.push({ id: message.id, reason: `Message is ${status}.` });
      continue;
    }
    if (cleanBoolean(vendor.whatsapp_do_not_contact)) {
      const reason = "Vendor is marked do-not-contact for WhatsApp.";
      failures.push({ id: message.id, reason });
      await updateWhatsappMessageFailure(supabase, user, message, reason, now, connection);
      continue;
    }
    let resolvedMessage = message;
    try {
      const outreachTemplateId = cleanText(message.template_id);
      if (outreachTemplateId) {
        let notifier = notifierByTemplate.get(outreachTemplateId);
        if (!notifier) {
          const result = await publishOutreachTemplateToWhatsapp(supabase, user, { template_id: outreachTemplateId });
          notifier = result.row as Record<string, unknown>;
          notifierByTemplate.set(outreachTemplateId, notifier);
        }
        resolvedMessage = {
          ...message,
          whatsapp_template_name: cleanText(notifier.meta_template_name),
          whatsapp_template_language: cleanText(notifier.meta_template_language),
          metadata: {
            ...objectRecord(message.metadata),
            whatsapp_template_mapped: true,
            whatsapp_template_status: whatsappMetaStatus(notifier.meta_template_status),
            whatsapp_template_error: cleanText(notifier.last_error),
            whatsapp_template_auto_checked_at: now
          }
        };
      } else if (cleanText(objectRecord(message.metadata).whatsapp_template_source) === "bid_room_follow_up") {
        const followUp = await ensureBidRoomWhatsappFollowUpTemplate(supabase, user, {
          language: cleanText(message.whatsapp_template_language) || "en",
          vendor_name: cleanText(vendor.vendor_name || vendor.domain) || "Carrier",
          event_name: cleanText(objectRecord(message.metadata).event_name) || "RFx opportunity",
          question: cleanText(message.whatsapp_text || message.text_body),
          bid_link: cleanText(objectRecord(message.metadata).bid_link)
        });
        resolvedMessage = {
          ...message,
          whatsapp_connection_id: followUp.connection.row.id,
          whatsapp_template_name: followUp.name,
          whatsapp_template_language: followUp.language,
          metadata: {
            ...objectRecord(message.metadata),
            whatsapp_template_status: followUp.status,
            whatsapp_template_parameters: followUp.parameters,
            whatsapp_template_auto_checked_at: now
          }
        };
      }
    } catch (error) {
      const reason = safeOperationalError(error);
      failures.push({ id: message.id, reason });
      await updateWhatsappMessageFailure(supabase, user, resolvedMessage, reason, now, connection);
      continue;
    }

    let claim: Awaited<ReturnType<typeof claimOutreachMessageForSend>> = null;
    try {
      claim = await claimOutreachMessageForSend(supabase, user, resolvedMessage, {
        channel: "whatsapp",
        provider: "meta",
        whatsapp_connection_id: connection.row.id,
        sender_address: cleanText(connection.row.display_phone_number) || null,
        sender_connection_type: cleanText(connection.row.connection_mode) || "unresolved",
        send_result: {
          connection_id: connection.row.id,
          sender: cleanText(connection.row.display_phone_number) || null
        }
      });
    } catch (error) {
      failures.push({ id: message.id, reason: safeOperationalError(error) });
      continue;
    }
    if (!claim) {
      skipped.push({ id: message.id, reason: "Message was already claimed or completed by another request." });
      continue;
    }

    let providerAccepted = false;
    try {
      const data = await metaSendWhatsappTemplate(resolvedMessage, connection);
      providerAccepted = true;
      const providerMessageId = cleanText(data?.messages?.[0]?.id);
      const senderDisplayPhone = cleanText(connection.row.display_phone_number);
      const updateResult = await updateClaimedOutreachMessage(supabase, user, message.id, claim.attemptId, {
        status: "sent",
        delivery_status: "sent",
        sent_at: now,
        send_completed_at: now,
        last_contacted_at: now,
        provider: "meta",
        whatsapp_connection_id: connection.row.id,
        sender_address: senderDisplayPhone || null,
        sender_connection_type: cleanText(connection.row.connection_mode) || "unresolved",
        whatsapp_template_name: cleanText(resolvedMessage.whatsapp_template_name),
        whatsapp_template_language: cleanText(resolvedMessage.whatsapp_template_language),
        provider_message_id: providerMessageId,
        provider_response_status: "accepted",
        delivery_error: null,
        send_result: outreachSendResult("completed", {
          attempt_id: claim.attemptId,
          channel: "whatsapp",
          provider: "meta",
          outcome: "accepted",
          connection_id: connection.row.id,
          sender: senderDisplayPhone || null,
          provider_message_id: providerMessageId,
          template_name: cleanText(resolvedMessage.whatsapp_template_name),
          template_language: cleanText(resolvedMessage.whatsapp_template_language)
        }),
        metadata: {
          ...objectRecord(resolvedMessage.metadata),
          whatsapp_connection_id: connection.row.id,
          whatsapp_connection_mode: cleanText(connection.row.connection_mode),
          sender_display_phone: senderDisplayPhone
        }
      });
      if (!updateResult) throw new Error("Meta accepted the message, but its delivery claim could not be finalized.");
      rows.push(updateResult);

      try {
        await writeOutreachSentHistory(supabase, withOwner({
          whatsapp_connection_id: connection.row.id,
          outreach_message_id: message.id,
          campaign_id: message.campaign_id,
          vendor_id: message.vendor_id,
          rfx_event_id: message.rfx_event_id,
          channel: "whatsapp",
          direction: "outbound",
          status: "sent",
          subject: message.subject,
          body_preview: contactPreview(message.whatsapp_body || message.whatsapp_text || message.text_body),
          occurred_at: now,
          metadata: {
            provider: "meta",
            whatsapp_connection_id: connection.row.id,
            whatsapp_connection_mode: cleanText(connection.row.connection_mode),
            sender_connection_type: cleanText(connection.row.connection_mode),
            sender_display_phone: senderDisplayPhone,
            phone_number_id: maskedSecret(connection.phoneNumberId),
            provider_message_id: providerMessageId,
            template_name: resolvedMessage.whatsapp_template_name,
            template_language: resolvedMessage.whatsapp_template_language
          }
        }, user));
      } catch (error) {
        try {
          await writeAuditLog(supabase, user, "whatsapp.post_send_sync_failed", "outreach_messages", String(message.id), "Meta accepted outreach, but contact history synchronization failed", {
            provider_message_id: providerMessageId,
            error: safeOperationalError(error)
          });
        } catch (_) {
          // Provider acceptance is authoritative; diagnostics cannot make the message retryable.
        }
      }
    } catch (error) {
      const reason = safeOperationalError(error);
      const uncertain = providerAccepted || Boolean((error as Error & { deliveryUncertain?: boolean })?.deliveryUncertain);
      if (uncertain) deliveryUnknown += 1;
      failures.push({ id: message.id, reason, delivery_unknown: uncertain });
      try {
        await markClaimedOutreachFailure(supabase, user, resolvedMessage, claim.attemptId, reason, uncertain, {
          provider: "meta",
          whatsapp_connection_id: connection.row.id,
          sender_address: cleanText(connection.row.display_phone_number) || null,
          sender_connection_type: cleanText(connection.row.connection_mode) || "unresolved",
          whatsapp_template_name: cleanText(resolvedMessage.whatsapp_template_name) || null,
          whatsapp_template_language: cleanText(resolvedMessage.whatsapp_template_language) || null,
          metadata: {
            ...objectRecord(resolvedMessage.metadata),
            whatsapp_connection_id: connection.row.id,
            whatsapp_connection_mode: cleanText(connection.row.connection_mode),
            whatsapp_last_error: reason,
            whatsapp_last_error_at: now
          },
          send_result: {
            channel: "whatsapp",
            provider: "meta",
            connection_id: connection.row.id,
            sender: cleanText(connection.row.display_phone_number) || null,
            template_name: cleanText(resolvedMessage.whatsapp_template_name),
            template_language: cleanText(resolvedMessage.whatsapp_template_language)
          }
        });
        await writeOutreachDeliveryIssueHistory(supabase, user, resolvedMessage, {
          channel: "whatsapp",
          status: uncertain ? "delivery_unknown" : "failed",
          reason,
          provider: "meta",
          connectionId: connection.row.id,
          sender: cleanText(connection.row.display_phone_number) || null,
          extraMetadata: {
            whatsapp_connection_id: connection.row.id,
            sender_connection_type: cleanText(connection.row.connection_mode),
            whatsapp_template_name: cleanText(resolvedMessage.whatsapp_template_name),
            whatsapp_template_language: cleanText(resolvedMessage.whatsapp_template_language),
            delivery_unknown: uncertain
          }
        });
      } catch (_) {
        // The send claim remains locked if persistence is unavailable, preventing an unsafe retry.
      }
    }
  }
  await tryWriteAuditLog(
    supabase,
    user,
    "outreach.whatsapp.bulk_send",
    "outreach_messages",
    connection.row.id,
    `Processed ${ids.length} WhatsApp outreach message(s)`,
    {
      requested: ids.length,
      sent: rows.length,
      failed: failures.length,
      skipped: skipped.length,
      delivery_unknown: deliveryUnknown,
      whatsapp_connection_id: connection.row.id,
      sender_address: cleanText(connection.row.display_phone_number) || null
    }
  );
  return { sent: rows.length, failed: failures.length, skipped: skipped.length, delivery_unknown: deliveryUnknown, rows, failures, skipped_rows: skipped };
}

async function ensureBidRoomCarrierFollowUpCampaign(
  supabase: RatewareSupabaseClient,
  user: RatewareUser,
  event: Record<string, unknown>
) {
  const key = `bid-room-carrier-follow-up:${event.id}`;
  const existing = await supabase
    .from("outreach_campaigns")
    .select("*")
    .eq("owner_email", user.owner_email)
    .eq("idempotency_key", key)
    .maybeSingle();
  if (existing.error) throw existing.error;
  if (existing.data) return existing.data as Record<string, unknown>;

  const created = await supabase
    .from("outreach_campaigns")
    .insert(withOwner({
      rfx_event_id: event.id,
      name: `${cleanText(event.rfx_id) || "RFx"} | Carrier follow-up`,
      channel: "multi",
      status: "generated",
      sender_email: GMAIL_ALLOWED_SENDER,
      sender_label: "Rateware Procurement",
      sender_connection_status: "draft_only",
      idempotency_key: key,
      notes: "Targeted carrier questions created from the Bid Room communication workspace."
    }, user))
    .select("*")
    .single();
  if (!created.error) return created.data as Record<string, unknown>;
  if (String(created.error.code || "") !== "23505") throw created.error;

  const concurrent = await supabase
    .from("outreach_campaigns")
    .select("*")
    .eq("owner_email", user.owner_email)
    .eq("idempotency_key", key)
    .single();
  if (concurrent.error) throw concurrent.error;
  return concurrent.data as Record<string, unknown>;
}

async function mirrorBidRoomCarrierDelivery(
  supabase: RatewareSupabaseClient,
  user: RatewareUser,
  event: Record<string, unknown>,
  invitation: Record<string, unknown>,
  payload: Record<string, unknown>
) {
  const vendor = relationRecord(invitation.vendors);
  const lane = relationRecord(invitation.rfx_lanes);
  const channel = cleanText(payload.channel) || "email";
  const result = objectRecord(payload.result);
  const sent = Number(result.sent || 0) > 0;
  const deliveryUnknown = Number(result.delivery_unknown || 0) > 0;
  const failure = Array.isArray(result.failures)
    ? cleanText(objectRecord(result.failures[0]).reason)
    : "";
  const outcome = sent
    ? `${channel === "whatsapp" ? "WhatsApp" : "Email"} sent to ${cleanText(payload.recipient) || "carrier"}.`
    : deliveryUnknown
      ? `${channel === "whatsapp" ? "WhatsApp" : "Email"} delivery is unknown. Review the Delivery Queue before retrying.`
      : `${channel === "whatsapp" ? "WhatsApp" : "Email"} was not sent${failure ? `: ${failure}` : "."}`;
  const thread = await findOrCreateBidRoomChatThread(supabase, user, event, {
    thread_type: "carrier_private",
    vendor_id: invitation.vendor_id,
    rfx_lane_id: invitation.rfx_lane_id,
    title: `${cleanText(event.rfx_id) || "RFx"} | Private: ${cleanText(vendor.vendor_name || vendor.domain) || "Carrier"}`
  });
  const message = withOwner({
    thread_id: thread.id,
    rfx_event_id: event.id,
    rfx_lane_id: invitation.rfx_lane_id,
    vendor_id: invitation.vendor_id,
    sender_role: "procurement",
    sender_name: user.owner_email || "Procurement",
    sender_email: user.owner_email,
    body: `${outcome}\n\n${cleanText(payload.body)}`,
    google_chat_sync_status: "pending",
    metadata: {
      source: "bid_room_external_outreach",
      outreach_message_id: payload.outreach_message_id || null,
      channel,
      delivery_status: sent ? "sent" : deliveryUnknown ? "delivery_unknown" : "failed",
      recipient: cleanText(payload.recipient),
      rfx_lane_id: lane.id || invitation.rfx_lane_id || null,
      request_key: cleanText(payload.request_key)
    }
  }, user);
  const inserted = await supabase
    .from("bid_room_chat_messages")
    .insert(message)
    .select("*, vendors(vendor_name,domain)")
    .single();
  if (inserted.error) throw inserted.error;
  await supabase.from("bid_room_chat_threads").update({
    updated_at: new Date().toISOString(),
    communication_status: "open",
    needs_reply: sent || deliveryUnknown,
    read_status: "read",
    last_read_at: new Date().toISOString(),
    resolved_at: null,
    resolved_by: null
  }).eq("id", thread.id);
  const sync = await syncBidRoomMessageToGoogleChat(supabase, thread, inserted.data, event);
  return {
    thread,
    message: { ...inserted.data, google_chat_sync_status: sync.status },
    google_chat_configured: sync.status !== "not_configured" || Boolean(GOOGLE_CHAT_WEBHOOK_URL)
  };
}

function existingBidRoomCarrierEmailReply(message: Record<string, unknown>, reused = true) {
  const metadata = objectRecord(message.metadata);
  const status = cleanText(message.status)?.toLowerCase() || "drafted";
  return {
    reused,
    outreach_message: message,
    result: {
      sent: status === "sent" ? 1 : 0,
      failed: ["failed", "bounced"].includes(status) ? 1 : 0,
      delivery_unknown: status === "delivery_unknown" ? 1 : 0,
      failures: ["failed", "bounced"].includes(status)
        ? [{ id: message.id, reason: cleanText(message.delivery_error) || `Email is ${status}.` }]
        : []
    },
    email_context: {
      reply_mode: cleanText(metadata.gmail_reply_mode) || "new_email",
      gmail_thread_id: cleanText(metadata.gmail_thread_id) || null,
      gmail_source_message_id: cleanText(metadata.gmail_source_message_id) || null,
      source_subject: cleanText(metadata.gmail_source_subject) || null,
      source_received_at: cleanText(metadata.gmail_source_received_at) || null
    }
  };
}

async function sendBidRoomCarrierMessage(
  supabase: RatewareSupabaseClient,
  user: RatewareUser,
  input: Record<string, unknown>
) {
  const body = cleanText(input.body || input.message);
  const requestKey = cleanText(input.idempotency_key || input.request_key);
  if (!body) throw new Error("Message body is required.");
  if (body.length > 600) throw new Error("Keep a direct carrier question under 600 characters.");
  if (!requestKey) throw new Error("A message request key is required to prevent duplicate sends.");
  requireBulkConfirmation(input, {
    action: "send_bid_room_carrier_message",
    label: "Carrier message send",
    count: 1
  });

  const event = await requireOwnedRfxEvent(supabase, user, input.rfx_event_id || input.event_id);
  const invitation = await requireOwnedRfxLaneVendor(supabase, user, input.rfx_lane_vendor_id || input.invitation_id);
  if (cleanText(invitation.rfx_event_id) !== cleanText(event.id)) {
    throw new Error("That carrier invitation does not belong to the selected RFx.");
  }
  if (cleanText(input.rfx_lane_id || input.lane_id) && cleanText(input.rfx_lane_id || input.lane_id) !== cleanText(invitation.rfx_lane_id)) {
    throw new Error("That carrier invitation does not belong to the selected lane.");
  }

  const previous = await supabase
    .from("outreach_messages")
    .select("*")
    .eq("owner_email", user.owner_email)
    .contains("metadata", { bid_room_request_key: requestKey })
    .maybeSingle();
  if (previous.error) throw previous.error;
  if (previous.data) {
    return existingBidRoomCarrierEmailReply(previous.data);
  }

  const vendorResult = await supabase
    .from("vendors")
    .select("id,vendor_name,legal_name,domain,primary_email,secondary_emails,contact_name")
    .eq("id", invitation.vendor_id)
    .maybeSingle();
  if (vendorResult.error) throw vendorResult.error;
  const vendor = relationRecord(vendorResult.data);
  if (!vendor.id) throw new Error("Carrier CRM profile was not found for this invitation.");

  const lane = relationRecord(invitation.rfx_lanes);
  const appOrigin = cleanText(input.app_origin) || Deno.env.get("RATEWARE_APP_URL") || "https://rateware.vercel.app";
  const eventLaneRows = await fetchAllRfxLaneRows(supabase, cleanText(event.id) || "", "*");
  const routeBookRows = outreachEventLaneRows(
    eventLaneRows,
    [invitation]
  );
  const bidLink = `${appOrigin.replace(/\/$/, "")}/rfx-bid.html?token=${encodeURIComponent(cleanText(invitation.invitation_token) || "")}${routeBookRows.length > 1 ? "&view=book" : ""}`;
  const route = [cleanText(lane.origin), cleanText(lane.destination)].filter(Boolean).join(" -> ") || "this RFx";
  const vendorName = cleanText(vendor.vendor_name || vendor.legal_name || vendor.domain) || "Carrier";
  const campaign = await ensureBidRoomCarrierFollowUpCampaign(supabase, user, event);
  const now = new Date().toISOString();
  const suppressed = await suppressedEmailSet(supabase, user, vendorContactEmailCandidates(vendor));
  const sendableEmail = firstSendableVendorEmail(vendor, suppressed);
  if (!sendableEmail) {
    throw new Error("This carrier has no sendable email. Add or replace a verified contact in Carrier CRM.");
  }
  const emailContext = await resolveBidRoomGmailReplyContext(supabase, user, event, vendor, sendableEmail);
  const profileLinks = await vendorProfileLinksForInvitations(
    supabase,
    user,
    [invitation],
    appOrigin,
    { rfx_event_id: event.id, source: "bid_room_targeted_follow_up" }
  );
  const profileLink = profileLinks.get(cleanText(vendor.id) || "") || "";
  const language = bidRoomFollowUpLanguage(body, event, emailContext.source_subject);
  const routeBookText = outreachLaneRowsText(routeBookRows, language);
  const routeBookHtml = outreachLaneTableHtml(routeBookRows, language);
  const laneSummaryHtml = bidRoomFollowUpLaneSummaryHtml(invitation, language);
  const contactName = cleanText(vendor.contact_name || vendor.vendor_name || vendor.legal_name || "team");
  const greeting = language === "es" ? `Hola ${contactName},` : `Hello ${contactName},`;
  const originalReference = cleanText(emailContext.source_subject);
  const questionLabel = language === "es" ? "Pregunta sobre esta ruta" : "Question about this lane";
  const routeSummaryLabel = language === "es" ? "Resumen de la ruta consultada" : "Selected lane summary";
  const bidLinkLabel = language === "es" ? "Abrir Private Bid Room" : "Open Private Bid Room";
  const profileLinkLabel = language === "es" ? "Actualizar perfil de carrier" : "Update carrier profile";
  const routeBookLabel = language === "es"
    ? "Para referencia: libro de rutas original"
    : "For reference: original RFx route book";
  const followUpIntro = language === "es"
    ? "Dando seguimiento a la invitacion original de este RFx, te hacemos una pregunta puntual sobre la ruta indicada abajo."
    : "Following up on the original invitation for this RFx, we have one focused question about the lane below.";
  const originalSubjectLine = originalReference
    ? (language === "es" ? `Asunto original: ${originalReference}` : `Original subject: ${originalReference}`)
    : "";
  const safeQuestionHtml = escapeHtmlText(body).replace(/\r?\n/g, "<br>");
  const textLane = [
    `${language === "es" ? "Ruta" : "Lane"}: ${route}`,
    `${language === "es" ? "Equipo" : "Equipment"}: ${[lane.equipment, lane.trailer, lane.config].map(cleanText).filter(Boolean).join(" / ") || "-"}`,
    `${language === "es" ? "Operacion" : "Operation"}: ${cleanText(lane.operation) || "-"}`,
    `${language === "es" ? "Servicio" : "Service"}: ${cleanText(lane.service) || "-"}`,
    `${language === "es" ? "Volumen semanal" : "Weekly volume"}: ${cleanText(lane.weekly_volume) || "-"}`
  ].join("\n");
  const textBody = [
    greeting,
    "",
    followUpIntro,
    originalSubjectLine,
    "",
    `${questionLabel}:`,
    body,
    "",
    `${routeSummaryLabel}:`,
    textLane,
    "",
    `${bidLinkLabel}: ${bidLink}`,
    `${profileLinkLabel}: ${profileLink}`,
    "",
    routeBookLabel,
    routeBookText,
    "",
    marksmanSignatureText(language)
  ].filter((line) => line !== "").join("\n");
  const htmlBody = `
    <div style="font-family:Arial,sans-serif;color:#1f2937;font-size:14px;line-height:1.45">
      <p>${escapeHtmlText(greeting)}</p>
      <p>${escapeHtmlText(followUpIntro)}</p>
      ${originalReference ? `<p style="font-size:12px;color:#64748b"><strong>${language === "es" ? "Asunto original" : "Original subject"}:</strong> ${escapeHtmlText(originalReference)}</p>` : ""}
      <div style="border:1px solid #cbd5e1;border-left:4px solid #3157d5;border-radius:4px;padding:10px 12px;margin:14px 0;background:#f8fafc">
        <p style="margin:0 0 6px"><strong>${escapeHtmlText(questionLabel)}</strong></p>
        <p style="margin:0">${safeQuestionHtml}</p>
      </div>
      <p style="margin:14px 0 6px"><strong>${escapeHtmlText(routeSummaryLabel)}</strong></p>
      ${laneSummaryHtml}
      <p style="margin:14px 0">
        <a href="${escapeHtmlText(bidLink)}" style="display:inline-block;background:#3157d5;color:#fff;text-decoration:none;border-radius:4px;padding:9px 13px;margin-right:8px">${escapeHtmlText(bidLinkLabel)}</a>
        ${profileLink ? `<a href="${escapeHtmlText(profileLink)}" style="display:inline-block;border:1px solid #3157d5;color:#3157d5;text-decoration:none;border-radius:4px;padding:8px 12px">${escapeHtmlText(profileLinkLabel)}</a>` : ""}
      </p>
      <div style="border:1px solid #e3b341;border-radius:5px;padding:12px;margin-top:18px;background:#fffdf4">
        <p style="margin:0 0 8px"><strong>${escapeHtmlText(routeBookLabel)}</strong></p>
        ${originalReference ? `<p style="margin:0 0 10px;font-size:12px;color:#64748b"><strong>${language === "es" ? "Asunto original" : "Original subject"}:</strong> ${escapeHtmlText(originalReference)}</p>` : ""}
        ${routeBookHtml}
      </div>
      ${marksmanSignatureHtml(language)}
    </div>
  `;
  const commonMetadata = {
    source: "bid_room_carrier_ask",
    bid_room_request_key: requestKey,
    bid_link: bidLink,
    event_name: cleanText(event.name || event.rfx_id) || "RFx opportunity",
    rfx_id: cleanText(event.rfx_id),
    vendor_name: vendorName,
    vendor_domain: cleanText(vendor.domain),
    lane_route: route,
    profile_link: profileLink,
    route_book_lane_count: routeBookRows.length,
    route_book_signature: outreachLaneTableSignature(routeBookRows),
    follow_up_language: language,
    original_source_subject: emailContext.source_subject,
    created_from: "bid_room_carrier_communications",
    created_at: now
  };
  const recipient = cleanText(emailContext.recipient_email) || sendableEmail;
  if (suppressed.has(recipient.toLowerCase())) {
    throw new Error("The most recent Gmail thread uses an email blocked after a delivery failure. Update the carrier contact before replying.");
  }
  const subject = emailContext.reply_mode === "thread_reply"
    ? gmailReplySubject(emailContext.source_subject, `${cleanText(event.rfx_id) || "RFx"} | Question about ${route}`)
    : `${cleanText(event.rfx_id) || "RFx"} | Question about ${route}`;
  const messageRow = withOwner({
    campaign_id: campaign.id,
    rfx_event_id: event.id,
    rfx_lane_id: invitation.rfx_lane_id,
    rfx_lane_vendor_id: invitation.id,
    vendor_id: vendor.id,
    channel: "email",
    recipient_email: recipient,
    contact_key: `ask:${requestKey}`,
    subject,
    text_body: textBody,
    html_body: htmlBody,
    sender_email: GMAIL_ALLOWED_SENDER,
    sender_label: "Rateware Procurement",
    sender_connection_status: "draft_only",
    provider: "gmail",
    provider_response_status: "drafted",
    status: "drafted",
    metadata: {
      ...commonMetadata,
      gmail_reply_mode: emailContext.reply_mode,
      gmail_thread_id: emailContext.gmail_thread_id,
      gmail_source_message_id: emailContext.gmail_source_message_id,
      gmail_in_reply_to: emailContext.gmail_in_reply_to,
      gmail_references: emailContext.gmail_references,
      gmail_source_subject: emailContext.source_subject,
      gmail_source_received_at: emailContext.source_received_at
    }
  }, user);

  const created = await supabase.from("outreach_messages").insert(messageRow).select("*").single();
  if (created.error) {
    if (String(created.error.code || "") === "23505") {
      const duplicate = await supabase
        .from("outreach_messages")
        .select("*")
        .eq("owner_email", user.owner_email)
        .contains("metadata", { bid_room_request_key: requestKey })
        .maybeSingle();
      if (duplicate.error) throw duplicate.error;
      if (duplicate.data) return existingBidRoomCarrierEmailReply(duplicate.data);
    }
    throw created.error;
  }

  const sendInput = {
    ids: [created.data.id],
    provider: "gmail",
    channel: "email",
    sender_email: GMAIL_ALLOWED_SENDER,
    confirmed: true,
    confirmation_action: "send_outreach_messages"
  };
  let result: Record<string, unknown>;
  try {
    result = await sendOutreachMessages(supabase, user, sendInput);
  } catch (error) {
    const reason = safeOperationalError(error);
    result = { sent: 0, failed: 1, skipped: 0, delivery_unknown: false, failures: [{ id: created.data.id, reason }] };
    const failureUpdate = await supabase
      .from("outreach_messages")
      .update({
        status: "failed",
        delivery_status: "failed",
        delivery_error: reason,
        failed_at: now,
        provider_response_status: "connection_or_provider_error",
        updated_at: now,
        metadata: {
          ...objectRecord(messageRow.metadata),
          direct_delivery_error: reason,
          direct_delivery_error_at: now
        }
      })
      .eq("id", created.data.id)
      .eq("owner_email", user.owner_email);
    if (failureUpdate.error) throw failureUpdate.error;
  }
  const latest = await supabase
    .from("outreach_messages")
    .select("*")
    .eq("id", created.data.id)
    .eq("owner_email", user.owner_email)
    .single();
  if (latest.error) throw latest.error;
  await tryWriteAuditLog(
    supabase,
    user,
    "bid_room.carrier_question.send",
    "outreach_messages",
    created.data.id,
    `Sent targeted Gmail carrier reply for ${cleanText(event.rfx_id) || event.id}`,
    { rfx_event_id: event.id, rfx_lane_vendor_id: invitation.id, vendor_id: vendor.id, channel: "email", request_key: requestKey, reply_mode: emailContext.reply_mode }
  );
  return {
    reused: false,
    outreach_message: latest.data,
    result,
    email_context: emailContext
  };
}

async function sendWhatsappGroupOutreachMessages(
  supabase: RatewareSupabaseClient,
  user: RatewareUser,
  input: Record<string, unknown>
) {
  const ids = normalizeBulkIds(input.ids, { label: "WhatsApp group message ids", limit: BULK_SEND_LIMIT });
  if (!ids.length) return { sent: 0, failed: 0, rows: [], failures: [] };
  requireBulkConfirmation(input, {
    action: "send_whatsapp_group_outreach_messages",
    label: "WhatsApp group bulk send",
    count: ids.length
  });
  await tryWriteAuditLog(
    supabase,
    user,
    "outreach.whatsapp_group.bulk_send",
    "outreach_messages",
    ids.slice(0, 50).join(","),
    `Blocked automated send for ${ids.length} WhatsApp group message(s)`,
    {
      requested: ids.length,
      sent: 0,
      blocked: true,
      manual_only: true,
      groups_enabled: WHATSAPP_GROUPS_ENABLED
    }
  );
  throw new Error("WhatsApp groups are manual-only. Open the group, copy the message, then mark the draft as manually sent.");
}

async function markWhatsappGroupMessageManuallySent(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null },
  input: Record<string, unknown>
) {
  const ids = normalizeBulkIds(input.ids, { label: "WhatsApp group message ids", limit: BULK_SELECTED_ID_LIMIT });
  if (!ids.length) return { updated: 0, rows: [] };
  requireBulkConfirmation(input, {
    action: "mark_whatsapp_group_message_manually_sent",
    label: "WhatsApp group manual send",
    count: ids.length
  });
  const now = new Date().toISOString();
  const result = await supabase
    .from("outreach_messages")
    .update({
      status: "manual_sent",
      delivery_status: "manual_sent",
      manual_sent_at: now,
      manual_sent_by: user.owner_email,
      sent_at: now,
      last_contacted_at: now,
      provider: "meta",
      sender_connection_type: "manual_group",
      provider_response_status: "manual_sent",
      send_result: outreachSendResult("completed", {
        channel: "whatsapp_group",
        provider: "meta",
        outcome: "manual_sent",
        sender: user.owner_email
      }),
      updated_at: now
    })
    .eq("owner_email", user.owner_email)
    .eq("channel", "whatsapp_group")
    .in("id", ids)
    .select("*");
  if (result.error) throw result.error;
  const historyRows = (result.data || []).map((message) => withOwner({
    outreach_message_id: message.id,
    campaign_id: message.campaign_id,
    vendor_id: message.vendor_id,
    rfx_event_id: message.rfx_event_id,
    channel: "whatsapp_group",
    direction: "outbound",
    status: "manual_sent",
    subject: message.subject,
    body_preview: contactPreview(message.whatsapp_body || message.whatsapp_text || message.text_body),
    occurred_at: now,
    metadata: {
      marked_from: "manual_whatsapp_group",
      manual_sent_by: user.owner_email,
      provider: message.provider || "meta",
      whatsapp_connection_id: message.whatsapp_connection_id || null,
      sender_address: message.sender_address || null,
      sender_connection_type: message.sender_connection_type || "manual_group",
      result: objectRecord(message.send_result),
      group_url: objectRecord(message.metadata).group_url || message.whatsapp_url
    }
  }, user));
  if (historyRows.length) {
    const history = await supabase.from("contact_history").insert(historyRows);
    if (history.error) throw history.error;
  }
  await tryWriteAuditLog(
    supabase,
    user,
    "outreach.whatsapp_group.manual_send",
    "outreach_messages",
    ids.slice(0, 50).join(","),
    `Marked ${result.data?.length || 0} WhatsApp group message(s) as manually sent`,
    { requested: ids.length, updated: result.data?.length || 0 }
  );
  return { updated: result.data?.length || 0, rows: result.data || [] };
}

function onboardingDefinition(summary: Record<string, unknown>, profile: Record<string, unknown>, organization: Record<string, unknown>, manual: Map<string, Record<string, unknown>>) {
  const definitions = [
    {
      key: "profile",
      label: "Complete user profile",
      detail: "Name, role, timezone, and contact data are configured.",
      done: Boolean(profile.full_name && profile.job_title)
    },
    {
      key: "organization",
      label: "Set organization profile",
      detail: "Workspace name, industry, website, and billing contact are set.",
      done: Boolean(organization.org_name && organization.billing_email)
    },
    {
      key: "vendors",
      label: "Load vendor base",
      detail: "Sourcing or procurement carriers exist in the workspace.",
      done: Number(summary.vendors || 0) > 0
    },
    {
      key: "rfx",
      label: "Create first RFx event",
      detail: "Spot book or RFx lane book has been created.",
      done: Number(summary.rfx_events || 0) > 0
    },
    {
      key: "outreach",
      label: "Generate carrier outreach",
      detail: "At least one Gmail or WhatsApp draft has been generated.",
      done: Number(summary.outreach_messages || 0) > 0
    },
    {
      key: "uploads",
      label: "Upload source evidence",
      detail: "Quotes, PDFs, images, emails, or spreadsheets are preserved.",
      done: Number(summary.raw_uploads || 0) > 0
    },
    {
      key: "rateware",
      label: "Approve first Rateware row",
      detail: "Human-approved rows are available in the final rate book.",
      done: Number(summary.approved_rows || 0) > 0
    },
    {
      key: "settings_reviewed",
      label: "Review SaaS controls",
      detail: "Confirm full access mode, audit visibility, and next role plan.",
      done: Boolean(manual.get("settings_reviewed")?.completed)
    }
  ];

  return definitions.map((item) => {
    const manualRow = manual.get(item.key);
    const completed = Boolean(item.done || manualRow?.completed);
    return {
      ...item,
      completed,
      completed_at: manualRow?.completed_at || (completed && item.done ? new Date().toISOString() : null),
      manual: Boolean(manualRow?.completed)
    };
  });
}

type ObservabilityEvent = {
  id: string;
  at: string | null;
  source: "rateware_api" | "gmail" | "google_chat" | "whatsapp" | "bid_room";
  severity: "error" | "warning" | "info";
  incident_state: "active" | "historical";
  title: string;
  detail: string;
  status: string | null;
  entity_type: string | null;
  entity_id: string | null;
  action: string | null;
  next_action: string;
  metadata?: Record<string, unknown>;
};

function observabilityEvent(input: Partial<ObservabilityEvent> & Pick<ObservabilityEvent, "source" | "severity" | "title">): ObservabilityEvent {
  return {
    id: cleanText(input.id) || crypto.randomUUID(),
    at: cleanText(input.at) || new Date().toISOString(),
    source: input.source,
    severity: input.severity,
    incident_state: input.incident_state === "historical" ? "historical" : "active",
    title: cleanText(input.title) || "Operational event",
    detail: cleanText(input.detail) || "",
    status: cleanText(input.status),
    entity_type: cleanText(input.entity_type),
    entity_id: cleanText(input.entity_id),
    action: cleanText(input.action),
    next_action: cleanText(input.next_action) || "Retry the action. If it repeats, review the integration setup.",
    metadata: objectRecord(input.metadata || {})
  };
}

async function safeObservabilityQuery(
  events: ObservabilityEvent[],
  source: ObservabilityEvent["source"],
  label: string,
  nextAction: string,
  query: () => PromiseLike<{ data?: unknown[] | null; error?: { message?: string } | null }>
) {
  try {
    const result = await query();
    if (result.error) {
      events.push(observabilityEvent({
        source,
        severity: "error",
        title: `${label} could not load`,
        detail: cleanText(result.error.message) || "Rateware could not read this operational log.",
        entity_type: "observability_query",
        action: "observability.query_failed",
        next_action: nextAction
      }));
      return [];
    }
    return Array.isArray(result.data) ? result.data as Record<string, unknown>[] : [];
  } catch (error) {
    events.push(observabilityEvent({
      source,
      severity: "error",
      title: `${label} could not load`,
      detail: safeOperationalError(error),
      entity_type: "observability_query",
      action: "observability.query_failed",
      next_action: nextAction
    }));
    return [];
  }
}

function auditSource(row: Record<string, unknown>): ObservabilityEvent["source"] {
  const action = cleanText(row.action) || "";
  const entityType = cleanText(row.entity_type) || "";
  if (action.startsWith("gmail.") || entityType.includes("gmail")) return "gmail";
  if (action.startsWith("google_chat.") || entityType.includes("google_chat")) return "google_chat";
  if (action.startsWith("whatsapp.") || entityType.includes("whatsapp")) return "whatsapp";
  if (action.startsWith("bid_room.") || action.startsWith("rfx.") || action.startsWith("outreach_queue.") || entityType.includes("rfx") || entityType.includes("outreach_queue")) return "bid_room";
  return "rateware_api";
}

function auditSeverity(row: Record<string, unknown>): ObservabilityEvent["severity"] {
  const text = `${cleanText(row.action) || ""} ${cleanText(row.summary) || ""}`.toLowerCase();
  if (text.includes("error") || text.includes("failed") || text.includes("could not")) return "error";
  if (text.includes("disconnect") || text.includes("archive") || text.includes("delete") || text.includes("retry")) return "warning";
  return "info";
}

function observabilityAuditErrorDetail(metadataValue: unknown) {
  const metadata = objectRecord(metadataValue);
  const causeChain = Array.isArray(metadata.cause_chain) ? metadata.cause_chain : [];
  const cause = causeChain.find((value) => cleanText(value) && cleanText(value) !== cleanText(metadata.error));
  const diagnostic = [
    metadata.error,
    cause,
    metadata.details,
    metadata.hint
  ]
    .map((value) => safeOperationalValue(value, 700))
    .filter((value, index, values): value is string => Boolean(value) && values.indexOf(value) === index)
    .join(" | ");
  const context = [
    metadata.code ? `Code ${safeOperationalValue(metadata.code, 80)}` : "",
    metadata.stage ? `Stage ${safeOperationalValue(metadata.stage, 120)}` : "",
    metadata.incident_id ? `Incident ${safeOperationalValue(metadata.incident_id, 80)}` : ""
  ].filter(Boolean).join(" | ");
  return [diagnostic, context].filter(Boolean).join(" | ");
}

function observabilitySummary(events: ObservabilityEvent[]) {
  const sources: ObservabilityEvent["source"][] = ["rateware_api", "gmail", "google_chat", "whatsapp", "bid_room"];
  const bySource = Object.fromEntries(sources.map((source) => [source, { total: 0, error: 0, warning: 0, info: 0 }]));
  const bySeverity = { error: 0, warning: 0, info: 0 };
  const activeEvents = events.filter((event) => event.incident_state === "active");
  for (const event of activeEvents) {
    bySeverity[event.severity] += 1;
    const sourceBucket = bySource[event.source] || { total: 0, error: 0, warning: 0, info: 0 };
    sourceBucket[event.severity] += 1;
    if (event.severity !== "info") sourceBucket.total += 1;
    bySource[event.source] = sourceBucket;
  }
  return {
    total_logs: events.length,
    total_incidents: activeEvents.filter((event) => event.severity !== "info").length,
    total_history: events.filter((event) => event.incident_state === "historical").length,
    by_source: bySource,
    by_severity: bySeverity
  };
}

async function buildObservabilityEvents(
  supabase: RatewareSupabaseClient,
  user: RatewareUser,
  input: Record<string, unknown> = {}
) {
  const limit = Math.min(Math.max(Number(input.limit) || 150, 20), 300);
  const events: ObservabilityEvent[] = [];
  const apiNextAction = "Retry. If this repeats, check the Rateware API deployment and Supabase logs.";
  const gmailNextAction = "Open Settings > Integrations, confirm Gmail is connected, then retry the send queue.";
  const chatNextAction = "Open Settings > Integrations, confirm Google Chat and Space, then retry Chat sync.";
  const whatsappNextAction = "Open Settings > Integrations, test WhatsApp Business, sync Meta templates, then retry the WhatsApp queue.";
  const bidRoomNextAction = "Open Bid Room, inspect the event thread, then retry or resolve the communication item.";

  const auditRows = await safeObservabilityQuery(events, "rateware_api", "Rateware API audit log", apiNextAction, () =>
    supabase
      .from("saas_audit_log")
      .select("id,created_at,actor_email,action,entity_type,entity_id,summary,metadata")
      .eq("owner_email", user.owner_email)
      .order("created_at", { ascending: false })
      .limit(80)
  );

  for (const row of auditRows) {
    const action = cleanText(row.action) || "";
    if (!action.includes("error") && !action.startsWith("gmail.") && !action.startsWith("google_chat.") && !action.startsWith("whatsapp.") && !action.startsWith("bid_room.") && !action.startsWith("rfx.") && !action.startsWith("outreach_queue.")) continue;
    const source = auditSource(row);
    const auditMetadata = objectRecord(row.metadata);
    events.push(observabilityEvent({
      id: `audit-${row.id}`,
      at: cleanText(row.created_at),
      source,
      severity: auditSeverity(row),
      incident_state: "historical",
      title: cleanText(row.summary) || cleanText(row.action) || "Workspace activity",
      detail: action.endsWith(".error")
        ? observabilityAuditErrorDetail(auditMetadata)
        : [row.actor_email, row.entity_type, row.entity_id].filter(Boolean).join(" / "),
      status: cleanText(row.action),
      entity_type: cleanText(row.entity_type),
      entity_id: cleanText(row.entity_id),
      action,
      next_action: source === "gmail" ? gmailNextAction : source === "google_chat" ? chatNextAction : source === "whatsapp" ? whatsappNextAction : source === "bid_room" ? bidRoomNextAction : apiNextAction,
      metadata: auditMetadata
    }));
  }

  const gmailRows = await safeObservabilityQuery(events, "gmail", "Gmail connection status", gmailNextAction, () =>
    supabase
      .from("gmail_mailbox_connections")
      .select("id,updated_at,mailbox_email,status,token_expires_at,last_error,metadata")
      .eq("owner_email", user.owner_email)
      .eq("mailbox_email", GMAIL_ALLOWED_SENDER)
      .limit(1)
  );
  for (const row of gmailRows) {
    const status = cleanText(row.status) || "not_connected";
    const expiresAt = cleanText(row.token_expires_at);
    const expired = Boolean(expiresAt && new Date(expiresAt).getTime() < Date.now());
    if (status === "connected" && !row.last_error && !expired) continue;
    events.push(observabilityEvent({
      id: `gmail-connection-${row.id || GMAIL_ALLOWED_SENDER}`,
      at: cleanText(row.updated_at),
      source: "gmail",
      severity: status === "error" || row.last_error || expired ? "error" : "warning",
      title: status === "connected" && expired ? "Gmail token needs refresh" : `Gmail sender is ${status.replace(/_/g, " ")}`,
      detail: cleanText(row.last_error) || `Sender: ${GMAIL_ALLOWED_SENDER}`,
      status,
      entity_type: "gmail_mailbox_connections",
      entity_id: cleanText(row.mailbox_email),
      action: "gmail.connection_status",
      next_action: gmailNextAction,
      metadata: objectRecord(row.metadata)
    }));
  }

  const outreachRows = await safeObservabilityQuery(events, "gmail", "Gmail delivery queue", gmailNextAction, () =>
    supabase
      .from("outreach_messages")
      .select("id,created_at,updated_at,status,channel,recipient_email,normalized_recipient_phone,subject,delivery_error,sender_email,sender_connection_status,rfx_event_id,campaign_id,metadata")
      .eq("owner_email", user.owner_email)
      .order("updated_at", { ascending: false })
      .limit(120)
  );
  for (const row of outreachRows) {
    const status = cleanText(row.status);
    if (status !== "failed" && !row.delivery_error) continue;
    const channel = cleanText(row.channel) || "email";
    const source = channel.startsWith("whatsapp") ? "whatsapp" : "gmail";
    events.push(observabilityEvent({
      id: `outreach-${row.id}`,
      at: cleanText(row.updated_at || row.created_at),
      source,
      severity: "error",
      title: `${source === "whatsapp" ? "WhatsApp" : "Email"} invitation failed for ${cleanText(row.recipient_email || row.normalized_recipient_phone) || "carrier"}`,
      detail: cleanText(row.delivery_error) || cleanText(row.subject) || "Outbound invitation did not complete.",
      status,
      entity_type: "outreach_messages",
      entity_id: cleanText(row.id),
      action: source === "whatsapp" ? "whatsapp.delivery_failed" : "gmail.delivery_failed",
      next_action: source === "whatsapp" ? whatsappNextAction : gmailNextAction,
      metadata: {
        campaign_id: row.campaign_id,
        rfx_event_id: row.rfx_event_id,
        sender_email: row.sender_email,
        sender_connection_status: row.sender_connection_status,
        ...(objectRecord(row.metadata))
      }
    }));
  }

  const whatsappConnectionRows = await safeObservabilityQuery(events, "whatsapp", "WhatsApp Business connection status", whatsappNextAction, () => {
    let query = supabase
      .from("whatsapp_business_connections")
      .select("id,updated_at,status,phone_number_id,display_phone_number,waba_id,templates_last_synced_at,webhook_verified_at,last_error,metadata")
      .eq("provider", "meta")
      .order("updated_at", { ascending: false })
      .limit(1);
    query = scopeWhatsappConnectionQuery(query, user);
    return query;
  });
  for (const row of whatsappConnectionRows) {
    const status = cleanText(row.status) || "not_configured";
    const missingTemplates = status === "connected" && !row.templates_last_synced_at;
    const missingWebhook = status === "connected" && !row.webhook_verified_at;
    if (status === "connected" && !row.last_error && !missingTemplates && !missingWebhook) continue;
    events.push(observabilityEvent({
      id: `whatsapp-connection-${row.id || "meta"}`,
      at: cleanText(row.updated_at),
      source: "whatsapp",
      severity: status === "error" || row.last_error ? "error" : "warning",
      title: status === "connected"
        ? missingTemplates ? "WhatsApp templates need sync" : "WhatsApp webhook is not verified"
        : `WhatsApp Business is ${status.replace(/_/g, " ")}`,
      detail: cleanText(row.last_error) || cleanText(row.display_phone_number || row.phone_number_id || row.waba_id) || "Meta WhatsApp sender is not ready.",
      status,
      entity_type: "whatsapp_business_connections",
      entity_id: cleanText(row.id),
      action: "whatsapp.connection_status",
      next_action: whatsappNextAction,
      metadata: objectRecord(row.metadata)
    }));
  }

  const chatConnectionRows = await safeObservabilityQuery(events, "google_chat", "Google Chat connection status", chatNextAction, () =>
    supabase
      .from("google_chat_connections")
      .select("id,updated_at,account_email,status,token_expires_at,default_space_name,default_space_display_name,last_error,metadata")
      .eq("owner_email", user.owner_email)
      .eq("account_email", GOOGLE_CHAT_ALLOWED_ACCOUNT)
      .limit(1)
  );
  for (const row of chatConnectionRows) {
    const status = cleanText(row.status) || "not_connected";
    const expiresAt = cleanText(row.token_expires_at);
    const expired = Boolean(expiresAt && new Date(expiresAt).getTime() < Date.now());
    const missingSpace = status === "connected" && !cleanText(row.default_space_name);
    if (status === "connected" && !row.last_error && !expired && !missingSpace) continue;
    events.push(observabilityEvent({
      id: `google-chat-connection-${row.id || GOOGLE_CHAT_ALLOWED_ACCOUNT}`,
      at: cleanText(row.updated_at),
      source: "google_chat",
      severity: status === "error" || row.last_error || expired ? "error" : "warning",
      title: missingSpace ? "Google Chat Space is not selected" : `Google Chat is ${status.replace(/_/g, " ")}`,
      detail: cleanText(row.last_error) || cleanText(row.default_space_display_name || row.default_space_name) || `Account: ${GOOGLE_CHAT_ALLOWED_ACCOUNT}`,
      status,
      entity_type: "google_chat_connections",
      entity_id: cleanText(row.account_email),
      action: "google_chat.connection_status",
      next_action: chatNextAction,
      metadata: objectRecord(row.metadata)
    }));
  }

  const chatMessageRows = await safeObservabilityQuery(events, "google_chat", "Google Chat message sync", chatNextAction, () =>
    supabase
      .from("bid_room_chat_messages")
      .select("id,created_at,thread_id,rfx_event_id,sender_role,sender_name,sender_email,body,google_chat_sync_status,google_chat_message_name,metadata")
      .eq("owner_email", user.owner_email)
      .in("google_chat_sync_status", ["error", "pending"])
      .order("created_at", { ascending: false })
      .limit(120)
  );
  for (const row of chatMessageRows) {
    const status = cleanText(row.google_chat_sync_status) || "pending";
    events.push(observabilityEvent({
      id: `chat-message-${row.id}`,
      at: cleanText(row.created_at),
      source: "google_chat",
      severity: status === "error" ? "error" : "warning",
      title: `Google Chat message sync is ${status}`,
      detail: cleanText(row.body)?.slice(0, 180) || "Bid Room message has not mirrored correctly.",
      status,
      entity_type: "bid_room_chat_messages",
      entity_id: cleanText(row.id),
      action: "google_chat.message_sync",
      next_action: chatNextAction,
      metadata: {
        thread_id: row.thread_id,
        rfx_event_id: row.rfx_event_id,
        google_chat_message_name: row.google_chat_message_name,
        sender_role: row.sender_role,
        sender_email: row.sender_email,
        sender_name: row.sender_name,
        ...(objectRecord(row.metadata))
      }
    }));
  }

  const chatThreadRows = await safeObservabilityQuery(events, "bid_room", "Bid Room communication queue", bidRoomNextAction, () =>
    supabase
      .from("bid_room_chat_threads")
      .select("id,updated_at,rfx_event_id,rfx_lane_id,vendor_id,thread_type,title,communication_status,needs_reply,read_status,google_chat_sync_status,metadata")
      .eq("owner_email", user.owner_email)
      .neq("status", "archived")
      .order("updated_at", { ascending: false })
      .limit(120)
  );
  for (const row of chatThreadRows) {
    const syncStatus = cleanText(row.google_chat_sync_status) || "not_configured";
    const communicationStatus = cleanText(row.communication_status) || "open";
    const isResolved = communicationStatus === "resolved";
    const needsReply = !isResolved && (
      row.needs_reply === true || cleanText(row.read_status) === "unread" || communicationStatus === "needs_reply"
    );
    if (syncStatus !== "error" && syncStatus !== "pending" && !needsReply) continue;
    events.push(observabilityEvent({
      id: `bid-room-thread-${row.id}`,
      at: cleanText(row.updated_at),
      source: "bid_room",
      severity: syncStatus === "error" ? "error" : "warning",
      title: needsReply ? `Bid Room thread needs reply: ${cleanText(row.title) || cleanText(row.thread_type) || "thread"}` : `Bid Room thread sync is ${syncStatus}`,
      detail: [row.thread_type, row.communication_status, row.read_status].filter(Boolean).join(" / "),
      status: needsReply ? "needs_reply" : syncStatus,
      entity_type: "bid_room_chat_threads",
      entity_id: cleanText(row.id),
      action: needsReply ? "bid_room.thread_needs_reply" : "bid_room.thread_sync",
      next_action: bidRoomNextAction,
      metadata: {
        rfx_event_id: row.rfx_event_id,
        rfx_lane_id: row.rfx_lane_id,
        vendor_id: row.vendor_id,
        ...(objectRecord(row.metadata))
      }
    }));
  }

  events.sort((a, b) => new Date(b.at || 0).getTime() - new Date(a.at || 0).getTime());
  return {
    summary: observabilitySummary(events),
    events: events.slice(0, limit)
  };
}

async function buildSaasSettings(supabase: RatewareSupabaseClient, user: RatewareUser) {
  const [profile, organization, checklistResult, auditResult, uploads, vendors, pending, approved, rfxEvents, outreachMessages, gmailConnections, googleChatConnections, whatsappConnections] = await Promise.all([
    ensureSaasProfile(supabase, user),
    ensureOrganization(supabase, user),
    supabase.from("onboarding_checklist").select("*").eq("owner_email", user.owner_email),
    supabase.from("saas_audit_log").select("*").eq("owner_email", user.owner_email).order("created_at", { ascending: false }).limit(80),
    supabase.from("raw_uploads").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).neq("status", "archived"),
    supabase.from("vendors").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email),
    supabase.from("rate_staging").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("status", "pending_review"),
    supabase.from("rate_staging").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("status", "approved"),
    supabase.from("rfx_events").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).neq("status", "archived"),
    supabase.from("outreach_messages").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).neq("status", "archived"),
    listGmailConnections(supabase, user),
    listGoogleChatConnections(supabase, user),
    listWhatsappConnections(supabase, user)
  ]);

  for (const result of [checklistResult, auditResult, uploads, vendors, pending, approved, rfxEvents, outreachMessages]) {
    if (result.error) throw result.error;
  }

  const summary = {
    raw_uploads: uploads.count || 0,
    vendors: vendors.count || 0,
    pending_review: pending.count || 0,
    approved_rows: approved.count || 0,
    rfx_events: rfxEvents.count || 0,
    outreach_messages: outreachMessages.count || 0
  };
  const manual = new Map((checklistResult.data || []).map((row) => [row.task_key, row]));
  const onboarding = onboardingDefinition(summary, profile, organization, manual);
  return {
    profile,
    organization,
    access: {
      mode: "full_access",
      label: "Full access enabled",
      detail: "All authenticated users can use every Rateware module. Roles can be added later without blocking the current MVP."
    },
    summary,
    onboarding,
    audit: auditResult.data || [],
    gmail: gmailConnections,
    google_chat: googleChatConnections,
    whatsapp: whatsappConnections
  };
}

function buildRowKeys(row: Record<string, unknown>) {
  const routeParts = [
    row.origin,
    row.destination,
    row.equipment,
    row.trailer,
    row.config,
    row.operation,
    row.service,
    row.driver,
    row.mx_border_crossing_point && row.us_border_crossing_point
      ? `${row.mx_border_crossing_point}/${row.us_border_crossing_point}`
      : row.mx_border_crossing_point || row.us_border_crossing_point
  ].filter(Boolean);
  const routeKey = routeParts.join(" ");
  const rfxKey = [row.rfx_id, row.row_id].filter(Boolean).join("-");

  return {
    route_key: routeKey || null,
    rfx_key: rfxKey || null,
    business_key: [rfxKey, routeKey].filter(Boolean).join(" ") || null
  };
}

function normalizeCatalogValues(row: Record<string, unknown>, catalog: Map<string, Map<string, Record<string, unknown>>>) {
  const patch: Record<string, unknown> = {};
  const fields: Array<[string, string, string[]]> = [
    ["equipment", "normalized_equipment", ["equipment"]],
    ["config", "normalized_config", ["config"]],
    ["operation", "normalized_operation", ["operation"]],
    ["service", "normalized_service", ["service"]],
    ["driver", "normalized_driver", ["driver"]]
  ];

  let matchCount = 0;
  for (const [field, normalizedField, categories] of fields) {
    const match = catalogMatch(catalog, categories, row[field]);
    if (!match?.normalized_value) {
      patch[normalizedField] = null;
      continue;
    }
    patch[normalizedField] = cleanText(match.normalized_value);
    patch[field] = cleanText(match.normalized_value);
    matchCount += 1;
  }

  const trailerMatch = catalogMatch(catalog, ["trailer"], row.trailer);
  if (trailerMatch?.normalized_value) {
    patch.normalized_trailer = trailerWithFlags(trailerMatch.normalized_value, row.hazmat, row.temperature_controlled);
    patch.trailer = patch.normalized_trailer;
    matchCount += 1;
  } else if (row.trailer || row.hazmat || row.temperature_controlled) {
    patch.trailer = trailerWithFlags(row.trailer, row.hazmat, row.temperature_controlled);
    patch.normalized_trailer = patch.trailer;
  }

  return { patch, matchCount };
}

function normalizeLocations(row: Record<string, unknown>, locationIndex: Map<string, Record<string, unknown>[]>) {
  const preserveOriginManual = cleanBoolean(row.origin_match_manual) && (row.origin_zip_prefix || row.origin_state || row.origin_market || row.origin_region || row.origin_country);
  const preserveDestinationManual = cleanBoolean(row.destination_match_manual) && (row.destination_zip_prefix || row.destination_state || row.destination_market || row.destination_region || row.destination_country);
  const originResolution = locationMatch(locationIndex, row.origin || row.normalized_origin);
  const destinationResolution = locationMatch(locationIndex, row.destination || row.normalized_destination);
  const originLocation = preserveOriginManual ? null : originResolution?.location || null;
  const destinationLocation = preserveDestinationManual ? null : destinationResolution?.location || null;
  const originPatch = preserveOriginManual
    ? { origin_match_source: row.origin_match_source || "manual", origin_match_confidence: row.origin_match_confidence || 100, origin_match_manual: true }
    : { ...applyLocation(row, "origin", originLocation), ...locationMatchMeta("origin", originResolution) };
  const destinationPatch = preserveDestinationManual
    ? { destination_match_source: row.destination_match_source || "manual", destination_match_confidence: row.destination_match_confidence || 100, destination_match_manual: true }
    : { ...applyLocation(row, "destination", destinationLocation), ...locationMatchMeta("destination", destinationResolution) };
  const merged = { ...row, ...originPatch, ...destinationPatch };

  return {
    patch: {
      ...originPatch,
      ...destinationPatch,
      origin_match_reason: preserveOriginManual ? row.origin_match_reason || "manual match preserved" : originResolution?.reason || null,
      destination_match_reason: preserveDestinationManual ? row.destination_match_reason || "manual match preserved" : destinationResolution?.reason || null,
      origin_location_candidates: preserveOriginManual ? row.origin_location_candidates || [] : originResolution?.candidates || [],
      destination_location_candidates: preserveDestinationManual ? row.destination_location_candidates || [] : destinationResolution?.candidates || [],
      location_match_status: isLocationResolved(merged, "origin") && isLocationResolved(merged, "destination")
        ? "matched"
        : isLocationResolved(merged, "origin") || isLocationResolved(merged, "destination")
          ? "partial"
          : "unmatched"
    },
    originLocation: preserveOriginManual ? row : originLocation,
    destinationLocation: preserveDestinationManual ? row : destinationLocation
  };
}

function applyMileage(row: Record<string, unknown>, patch: Record<string, unknown>, mileage: Map<string, Record<string, unknown>>) {
  const normalized = { ...row, ...patch };
  const routeCandidates = [
    [normalized.normalized_origin || normalized.origin, normalized.normalized_destination || normalized.destination, normalized.normalized_equipment || normalized.equipment, normalized.normalized_trailer || normalized.trailer, normalized.normalized_config || normalized.config, normalized.normalized_operation || normalized.operation, normalized.normalized_service || normalized.service, normalized.normalized_driver || normalized.driver],
    [normalized.normalized_origin || normalized.origin, normalized.normalized_destination || normalized.destination, normalized.normalized_equipment || normalized.equipment],
    [normalized.normalized_origin || normalized.origin, normalized.normalized_destination || normalized.destination],
    [normalized.origin_market, normalized.destination_market, normalized.normalized_equipment || normalized.equipment],
    [normalized.origin_market, normalized.destination_market],
    [row.route_key]
  ].map((parts) => catalogKey(Array.isArray(parts) ? parts.filter(Boolean).join(" ") : parts));

  const lane = routeCandidates.map((candidate) => mileage.get(candidate)).find(Boolean);
  if (!lane) return {};

  const mileagePatch: Record<string, unknown> = {
    calculated_miles: lane.miles ? Number(lane.miles) : null,
    calculated_km: lane.km ? Number(lane.km) : null,
    mileage_source: cleanText(lane.source || "catalog")
  };
  if (!row.us_miles && lane.miles) mileagePatch.us_miles = String(lane.miles);
  return mileagePatch;
}

function normalizeRowWithCurrentCatalog(row: Record<string, unknown>, catalog: Map<string, Map<string, Record<string, unknown>>>, locationIndex: Map<string, Record<string, unknown>[]>, mileage: Map<string, Record<string, unknown>>) {
  const categoryResult = normalizeCatalogValues(row, catalog);
  const locationResult = normalizeLocations({ ...row, ...categoryResult.patch }, locationIndex);
  const patch: Record<string, unknown> = {
    ...categoryResult.patch,
    ...locationResult.patch
  };

  Object.assign(patch, applyMileage(row, patch, mileage));
  Object.assign(patch, buildRowKeys({ ...row, ...patch }));

  const locationMatchCount = [locationResult.originLocation, locationResult.destinationLocation].filter(Boolean).length;
  const matchCount = categoryResult.matchCount + locationMatchCount;
  patch.catalog_match_status = matchCount >= 5 ? "matched" : matchCount >= 2 ? "partial" : "unmatched";
  return patch;
}

const US_STATE_CODES = new Set([
  "AL", "AK", "AZ", "AR", "CA", "CO", "CT", "DE", "FL", "GA", "HI", "IA", "ID", "IL", "IN", "KS", "KY", "LA", "MA", "MD", "ME", "MI", "MN", "MO", "MS", "MT", "NC", "ND", "NE", "NH", "NJ", "NM", "NV", "NY", "OH", "OK", "OR", "PA", "RI", "SC", "SD", "TN", "TX", "UT", "VA", "VT", "WA", "WI", "WV", "WY", "DC"
]);

function stateToken(value: unknown) {
  const text = String(value || "").toUpperCase();
  const direct = text.match(/\b[A-Z]{2}\b/)?.[0] || null;
  return direct || null;
}

function locationParts(value: unknown, fallbackState: unknown = null, fallbackCountry: unknown = null) {
  const text = cleanText(value);
  if (!text) return null;
  const profile = locationTextProfile([value, fallbackState].filter(Boolean).join(" "));
  if (profile.explicitMx) return null;
  const parts = text.split(",").map((part) => part.trim()).filter(Boolean);
  const state = stateToken(fallbackState) || stateToken(parts.slice(1).join(" "));
  const city = parts[0]?.replace(/\b[A-Z]{2}\b/g, "").trim();
  const fallbackText = cleanText(fallbackCountry)?.toUpperCase();
  const fallback = fallbackText === "USA"
    ? "US"
    : fallbackText === "CAN" || fallbackText === "CANADA"
      ? "CA"
      : fallbackText === "MEX" || fallbackText === "MEXICO"
        ? "MX"
        : fallbackText;
  if (fallback === "MX") return null;
  const country = fallback || (state && LOCATION_US_STATES.has(state) ? "US" : state && LOCATION_CA_PROVINCES.has(state) ? "CA" : null);
  if (!city || !state || !country) return null;
  if (!["US", "CA"].includes(country)) return null;
  return { city, state, country };
}

async function lookupPostalPrefix(value: unknown, fallbackState: unknown = null, fallbackCountry: unknown = null) {
  const parsed = locationParts(value, fallbackState, fallbackCountry);
  if (!parsed || !["US", "CA"].includes(parsed.country)) return null;

  const countryPath = parsed.country.toLowerCase();
  const url = `https://api.zippopotam.us/${countryPath}/${encodeURIComponent(parsed.state)}/${encodeURIComponent(parsed.city)}`;

  try {
    const response = await fetch(url);
    if (!response.ok) return null;
    const payload = await response.json();
    const place = Array.isArray(payload.places) ? payload.places[0] : null;
    const postalCode = cleanText(place?.["post code"]);
    if (!postalCode) return null;
    return {
      zip_prefix: postalCode.slice(0, parsed.country === "US" ? 3 : 3).toUpperCase(),
      city: cleanText(place?.["place name"]) || parsed.city,
      state: cleanText(place?.["state abbreviation"]) || parsed.state,
      country: parsed.country,
      source: "zippopotam.us"
    };
  } catch {
    return null;
  }
}

function patchLookupLocation(prefix: "origin" | "destination", lookup: Record<string, unknown> | null, locationIndex: Map<string, Record<string, unknown>[]>) {
  if (!lookup) return {};
  const catalogResolution = locationMatch(locationIndex, lookup.zip_prefix, lookup.country);
  const catalogLocation = catalogResolution?.location || null;
  const patch: Record<string, unknown> = {
    [`${prefix}_zip_prefix`]: lookup.zip_prefix,
    [`${prefix}_city`]: lookup.city,
    [`${prefix}_state`]: lookup.state,
    [`${prefix}_country`]: lookup.country,
    [`${prefix}_match_reason`]: `external ZIP lookup via ${lookup.source}`,
    [`${prefix}_match_source`]: "external_zip_lookup",
    [`${prefix}_match_confidence`]: catalogResolution?.score || 70,
    [`${prefix}_match_manual`]: false,
    [`${prefix}_location_candidates`]: catalogResolution?.candidates || []
  };

  if (catalogLocation) {
    Object.assign(patch, applyLocation({}, prefix, catalogLocation));
    patch[`${prefix}_match_reason`] = `external ZIP lookup, then ${catalogResolution?.reason || "catalog match"}`;
    patch[`${prefix}_match_source`] = "external_zip_lookup";
    patch[`${prefix}_match_confidence`] = Math.max(70, Number(catalogResolution?.score || 0));
  }
  return patch;
}

async function enrichMissingLocationZips(
  supabase: RatewareSupabaseClient,
  ownerEmail: string | null,
  ids: string[],
  status: string | null = null
) {
  if (!ids.length) throw new Error("At least one rate row id is required.");
  const scopedOwnerEmail = cleanText(ownerEmail)?.toLowerCase();
  if (!scopedOwnerEmail) throw new Error("Workspace owner is required for rate normalization.");

  let rowQuery = supabase.from("rate_staging").select("*").eq("owner_email", scopedOwnerEmail).in("id", ids).limit(250);
  if (status) rowQuery = rowQuery.eq("status", status);

  const [rowsResult, locations] = await Promise.all([
    rowQuery,
    fetchAllLocationCatalogRows(supabase, { activeOnly: true })
  ]);

  if (rowsResult.error) throw rowsResult.error;

  const locationIndex = buildLocationIndex(locations);
  const updatedRows = [];
  let enriched = 0;

  for (const row of rowsResult.data || []) {
    const patch: Record<string, unknown> = {};
    if (!row.origin_zip_prefix) {
      const lookup = await lookupPostalPrefix(row.origin || row.normalized_origin, row.origin_state, row.origin_country);
      const lookupPatch = patchLookupLocation("origin", lookup, locationIndex);
      if (Object.keys(lookupPatch).length) enriched += 1;
      Object.assign(patch, lookupPatch);
    }
    if (!row.destination_zip_prefix) {
      const lookup = await lookupPostalPrefix(row.destination || row.normalized_destination, row.destination_state, row.destination_country);
      const lookupPatch = patchLookupLocation("destination", lookup, locationIndex);
      if (Object.keys(lookupPatch).length) enriched += 1;
      Object.assign(patch, lookupPatch);
    }

    if (!Object.keys(patch).length) continue;
    const merged = { ...row, ...patch };
    patch.location_match_status = isLocationResolved(merged, "origin") && isLocationResolved(merged, "destination")
      ? "matched"
      : isLocationResolved(merged, "origin") || isLocationResolved(merged, "destination")
        ? "partial"
        : "unmatched";
    Object.assign(patch, buildRowKeys({ ...row, ...patch }));

    const result = await supabase
      .from("rate_staging")
      .update(patch)
      .eq("id", row.id)
      .eq("owner_email", scopedOwnerEmail)
      .select("*, vendors(vendor_name, domain)")
      .single();
    if (result.error) throw result.error;
    updatedRows.push(result.data);
  }

  return { rows: updatedRows, enriched };
}

async function fetchVendorRowsForRateMatching(supabase: RatewareSupabaseClient, user: { owner_email: string | null }) {
  return await fetchVendorReferenceRows(supabase, user, 50000);
}

async function attachUploadVendorHints(
  supabase: RatewareSupabaseClient,
  rows: Record<string, unknown>[],
  ownerEmail: string | null
) {
  const scopedOwnerEmail = cleanText(ownerEmail)?.toLowerCase();
  if (!scopedOwnerEmail) throw new Error("Workspace owner is required for upload vendor hints.");
  const uploadIds = [...new Set(rows.map((row) => cleanText(row.raw_upload_id)).filter(Boolean) as string[])];
  if (!uploadIds.length) return rows;

  const uploads: Record<string, unknown>[] = [];
  for (const chunk of chunkValues(uploadIds, 500)) {
    const result = await supabase
      .from("raw_uploads")
      .select("id,original_filename,vendor_id,vendor_hint,vendor_match_source")
      .eq("owner_email", scopedOwnerEmail)
      .in("id", chunk);
    if (result.error) throw result.error;
    uploads.push(...((result.data || []) as Record<string, unknown>[]));
  }

  const byId = new Map(uploads.map((upload) => [cleanText(upload.id), upload]));
  return rows.map((row) => ({
    ...row,
    raw_upload: byId.get(cleanText(row.raw_upload_id)) || null
  }));
}

function rateVendorReferenceCandidates(row: Record<string, unknown>) {
  const upload = typeof row.raw_upload === "object" && row.raw_upload ? row.raw_upload as Record<string, unknown> : {};
  return [
    ...vendorReferenceCandidatesFromText(row.vendor_domain),
    ...vendorReferenceCandidatesFromText(row.vendor_reference),
    ...vendorReferenceCandidatesFromText(row.vendor_email),
    ...vendorReferenceCandidatesFromText(row.vendor_name),
    ...vendorReferenceCandidatesFromText(row.legal_name || row.vendor_legal_name),
    ...vendorReferenceCandidatesFromText(row.commercial_name || row.vendor_commercial_name || row.trade_name),
    ...vendorReferenceCandidatesFromText(row.dba_name || row.vendor_dba_name),
    ...vendorReferenceCandidatesFromText(upload.vendor_hint),
    ...vendorReferenceCandidatesFromText(upload.original_filename)
  ]
    .filter(Boolean)
    .filter((reference) => !isGenericEmailDomain(domainFromVendorReference(reference)))
    .filter((reference) => !isInternalRatewareDomain(reference)) as string[];
}

function rawRateVendorReferenceCandidates(row: Record<string, unknown>) {
  const upload = typeof row.raw_upload === "object" && row.raw_upload ? row.raw_upload as Record<string, unknown> : {};
  return [
    cleanText(row.vendor_domain),
    cleanText(row.vendor_reference),
    cleanText(row.vendor_email),
    cleanText(row.vendor_name),
    cleanText(row.legal_name || row.vendor_legal_name),
    cleanText(row.commercial_name || row.vendor_commercial_name || row.trade_name),
    cleanText(row.dba_name || row.vendor_dba_name),
    cleanText(upload.vendor_hint),
    cleanText(upload.original_filename)
  ].filter(Boolean) as string[];
}

function rawUploadVendorReferenceCandidates(upload: Record<string, unknown>) {
  return [
    ...vendorReferenceCandidatesFromText(upload.vendor_hint),
    ...vendorReferenceCandidatesFromText(upload.original_filename)
  ]
    .filter(Boolean)
    .filter((reference) => !isGenericEmailDomain(domainFromVendorReference(reference)))
    .filter((reference) => !isInternalRatewareDomain(reference)) as string[];
}

function plannedVendorPatchForRawUpload(upload: Record<string, unknown>, vendors: Record<string, unknown>[]) {
  if (cleanText(upload.vendor_id)) return null;

  for (const reference of rawUploadVendorReferenceCandidates(upload)) {
    const match = resolveVendorReferenceFromRows(vendors, reference);
    if (!match) continue;
    const fallbackDomain = domainFromVendorReference(reference);
    return {
      vendor_id: match.vendor.id,
      vendor_hint: cleanText(upload.vendor_hint) || normalizeDomain(match.vendor.domain) || match.domain || fallbackDomain || cleanText(match.vendor.vendor_name),
      vendor_match_source: "auto"
    };
  }

  return null;
}

function vendorMatchErrorReason(rawReferences: string[], usableReferences: string[]) {
  if (!rawReferences.length) return "Missing vendor reference. Add vendor domain, vendor name, or legal name.";
  if (!usableReferences.length) {
    const rawText = rawReferences.join(" ");
    if (rawReferences.some((reference) => isInternalRatewareDomain(reference))) return "Internal Marksman/Rateware domain cannot be used as carrier evidence.";
    if (rawReferences.some((reference) => isGenericEmailDomain(domainFromVendorReference(reference)))) return "Generic email domain needs vendor legal name or commercial name.";
    if (!domainFromVendorReference(rawText) && !businessNameKey(rawText)) return "Vendor reference is not usable. Add carrier domain, legal name, or commercial name.";
    return "Vendor reference could not be normalized.";
  }
  return "No vendor record matched the detected domain/name. Correct vendor domain/name or add the vendor to Carrier CRM.";
}

function vendorMatchErrorRow(row: Record<string, unknown>, reason: string, reference: string | null = null) {
  const upload = typeof row.raw_upload === "object" && row.raw_upload ? row.raw_upload as Record<string, unknown> : {};
  const detectedReference = reference || rateVendorReferenceCandidates(row)[0] || rawRateVendorReferenceCandidates(row)[0] || "";
  return {
    rate_row_id: cleanText(row.id),
    shipment_id: cleanText(row.row_id),
    raw_upload_id: cleanText(row.raw_upload_id),
    source_file: cleanText(upload.original_filename),
    rfx_id: cleanText(row.rfx_id),
    quote_date: cleanText(row.quote_date),
    origin: cleanText(row.origin || row.normalized_origin),
    destination: cleanText(row.destination || row.normalized_destination),
    current_vendor_domain: cleanText(row.vendor_domain),
    detected_vendor_reference: detectedReference,
    error_reason: reason,
    corrected_vendor_domain: "",
    corrected_vendor_name: "",
    corrected_legal_name: ""
  };
}

function planRawUploadVendorMatches(uploads: Record<string, unknown>[], vendors: Record<string, unknown>[], seenUploadIds = new Set<string>()) {
  const groups = new Map<string, { patch: Record<string, unknown>; ids: string[] }>();
  let candidates = 0;
  let matchable = 0;

  for (const upload of uploads) {
    const id = cleanText(upload.id);
    if (!id || seenUploadIds.has(id)) continue;
    seenUploadIds.add(id);
    const references = rawUploadVendorReferenceCandidates(upload);
    if (!references.length && !cleanText(upload.vendor_id)) continue;
    candidates += 1;

    const patch = plannedVendorPatchForRawUpload(upload, vendors);
    if (!patch?.vendor_id) continue;
    matchable += 1;

    const groupKey = `${patch.vendor_id}::${patch.vendor_hint}`;
    const group = groups.get(groupKey) || { patch, ids: [] as string[] };
    group.ids.push(id);
    groups.set(groupKey, group);
  }

  return { candidates, matchable, groups };
}

async function applyPlannedRawUploadVendorMatches(
  supabase: RatewareSupabaseClient,
  plan: ReturnType<typeof planRawUploadVendorMatches>,
  ownerEmail: string | null
) {
  const scopedOwnerEmail = cleanText(ownerEmail)?.toLowerCase();
  if (!scopedOwnerEmail) throw new Error("Workspace owner is required for upload vendor matching.");
  let updated = 0;
  const rows: Record<string, unknown>[] = [];

  for (const group of plan.groups.values()) {
    for (const chunk of chunkValues(group.ids, 500)) {
      const result = await supabase
        .from("raw_uploads")
        .update(group.patch)
        .eq("owner_email", scopedOwnerEmail)
        .in("id", chunk)
        .is("vendor_id", null)
        .select("id,vendor_id,vendor_hint,vendor_match_source");
      if (result.error) throw result.error;
      updated += result.data?.length || 0;
      if (rows.length < 100) rows.push(...((result.data || []) as Record<string, unknown>[]).slice(0, 100 - rows.length));
    }
  }

  return { updated, rows };
}

function plannedVendorPatchForRateRow(row: Record<string, unknown>, vendors: Record<string, unknown>[]) {
  const vendorsById = vendorById(vendors);
  const upload = typeof row.raw_upload === "object" && row.raw_upload ? row.raw_upload as Record<string, unknown> : {};
  const linkedVendor = vendorsById.get(cleanText(row.vendor_id) || "") || vendorsById.get(cleanText(upload.vendor_id) || "");
  if (linkedVendor) {
    return {
      vendor_id: linkedVendor.id,
      vendor_domain: normalizeDomain(linkedVendor.domain) || domainFromVendorReference(linkedVendor.primary_email) || domainFromVendorReference(row.vendor_domain)
    };
  }

  for (const reference of rateVendorReferenceCandidates(row)) {
    const match = resolveVendorReferenceFromRows(vendors, reference);
    if (!match) continue;
    const fallbackDomain = domainFromVendorReference(reference);
    return {
      vendor_id: match.vendor.id,
      vendor_domain: normalizeDomain(match.vendor.domain) || match.domain || fallbackDomain || reference
    };
  }

  return null;
}

function planRateVendorMatches(rows: Record<string, unknown>[], vendors: Record<string, unknown>[], options: { collectErrors?: number } = {}) {
  const groups = new Map<string, { patch: Record<string, unknown>; ids: string[] }>();
  let candidates = 0;
  let matchable = 0;
  const unmatchedErrors: Record<string, unknown>[] = [];
  const errorLimit = Math.max(0, Number(options.collectErrors || 0) || 0);

  for (const row of rows) {
    const id = cleanText(row.id);
    if (!id) continue;
    const rawReferences = rawRateVendorReferenceCandidates(row);
    const references = rateVendorReferenceCandidates(row);
    const hasUploadVendor = Boolean(cleanText((row.raw_upload as Record<string, unknown> | undefined)?.vendor_id));
    const hasCurrentVendor = Boolean(cleanText(row.vendor_id));
    if (!hasCurrentVendor && !hasUploadVendor && !references.length) {
      if (errorLimit && unmatchedErrors.length < errorLimit) {
        unmatchedErrors.push(vendorMatchErrorRow(row, vendorMatchErrorReason(rawReferences, references)));
      }
      continue;
    }
    candidates += 1;

    const patch = plannedVendorPatchForRateRow(row, vendors);
    if (!patch?.vendor_id) {
      if (errorLimit && unmatchedErrors.length < errorLimit && !hasCurrentVendor && !hasUploadVendor) {
        unmatchedErrors.push(vendorMatchErrorRow(row, vendorMatchErrorReason(rawReferences, references), references[0]));
      }
      continue;
    }
    const currentVendorId = cleanText(row.vendor_id);
    const currentDomain = normalizeDomain(row.vendor_domain);
    if (currentVendorId === cleanText(patch.vendor_id) && currentDomain === normalizeDomain(patch.vendor_domain)) continue;
    matchable += 1;

    const groupKey = `${patch.vendor_id}::${patch.vendor_domain}`;
    const group = groups.get(groupKey) || { patch, ids: [] as string[] };
    group.ids.push(id);
    groups.set(groupKey, group);
  }

  return { candidates, matchable, groups, unmatched_errors: unmatchedErrors, unmatched_errors_truncated: errorLimit > 0 && unmatchedErrors.length >= errorLimit };
}

async function applyPlannedRateVendorMatches(
  supabase: RatewareSupabaseClient,
  plan: ReturnType<typeof planRateVendorMatches>,
  ownerEmail: string | null
) {
  const scopedOwnerEmail = cleanText(ownerEmail)?.toLowerCase();
  if (!scopedOwnerEmail) throw new Error("Workspace owner is required for rate vendor matching.");
  const rows: Record<string, unknown>[] = [];
  let updated = 0;

  for (const group of plan.groups.values()) {
    for (const chunk of chunkValues(group.ids, 500)) {
      const result = await supabase
        .from("rate_staging")
        .update(group.patch)
        .eq("owner_email", scopedOwnerEmail)
        .in("id", chunk)
        .select("id,status,vendor_id,vendor_domain");
      if (result.error) throw result.error;
      updated += result.data?.length || 0;
      if (rows.length < 100) rows.push(...((result.data || []) as Record<string, unknown>[]).slice(0, 100 - rows.length));
    }
  }

  return { updated, rows };
}

async function matchRateVendorRows(supabase: RatewareSupabaseClient, user: { owner_email: string | null }, ids: string[], status: string | null = null) {
  if (!ids.length) throw new Error("At least one rate row id is required.");

  const selectedRows = await fetchRateRowsForIds(
    supabase,
    ids,
    "id,row_id,vendor_id,vendor_domain,status,raw_upload_id,rfx_id,quote_date,origin,destination,normalized_origin,normalized_destination",
    user.owner_email
  );
  const scopedRows = status ? selectedRows.filter((row) => cleanText(row.status) === status) : selectedRows;

  const vendors = await fetchVendorRowsForRateMatching(supabase, user);
  const rows = await attachUploadVendorHints(supabase, scopedRows, user.owner_email);
  const uploads = rows.map((row) => row.raw_upload).filter((upload) => upload && typeof upload === "object") as Record<string, unknown>[];
  const uploadPlan = planRawUploadVendorMatches(uploads, vendors);
  const uploadApplied = await applyPlannedRawUploadVendorMatches(supabase, uploadPlan, user.owner_email);
  const plan = planRateVendorMatches(rows, vendors, { collectErrors: 1000 });
  const applied = await applyPlannedRateVendorMatches(supabase, plan, user.owner_email);
  return {
    ...applied,
    candidates: plan.candidates,
    matchable: plan.matchable,
    unmatched_errors: plan.unmatched_errors,
    unmatched_errors_truncated: plan.unmatched_errors_truncated,
    upload_candidates: uploadPlan.candidates,
    upload_matchable: uploadPlan.matchable,
    upload_updated: uploadApplied.updated
  };
}

async function matchRateVendorRowsByFilter(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  filters: Record<string, unknown>,
  options: { dryRun?: boolean; maxRows?: number } = {}
) {
  const maxRows = Math.min(Math.max(Number(options.maxRows) || 100000, 1), 100000);
  const vendors = await fetchVendorRowsForRateMatching(supabase, user);
  const pageSize = 5000;
  let candidates = 0;
  let matchable = 0;
  let updated = 0;
  let uploadCandidates = 0;
  let uploadMatchable = 0;
  let uploadUpdated = 0;
  const sampleRows: Record<string, unknown>[] = [];
  const unmatchedErrors: Record<string, unknown>[] = [];
  let unmatchedErrorsTruncated = false;
  const filtered = await collectRateRowIdsByFilter(supabase, filters, {
    maxRows,
    pageSize,
    ownerEmail: user.owner_email
  });
  const ids = filtered.ids;
  const seenUploadIds = new Set<string>();

  for (const chunk of chunkValues(ids, pageSize)) {
    const rawRows = await fetchRateRowsForIds(
      supabase,
      chunk,
      "id,row_id,vendor_id,vendor_domain,status,raw_upload_id,rfx_id,quote_date,origin,destination,normalized_origin,normalized_destination",
      user.owner_email
    );
    const rows = await attachUploadVendorHints(supabase, rawRows as Record<string, unknown>[], user.owner_email);
    const uploads = rows.map((row) => row.raw_upload).filter((upload) => upload && typeof upload === "object") as Record<string, unknown>[];
    const uploadPlan = planRawUploadVendorMatches(uploads, vendors, seenUploadIds);
    uploadCandidates += uploadPlan.candidates;
    uploadMatchable += uploadPlan.matchable;
    const remainingErrorSlots = Math.max(0, 5000 - unmatchedErrors.length);
    if (remainingErrorSlots === 0) unmatchedErrorsTruncated = true;
    const plan = planRateVendorMatches(rows as Record<string, unknown>[], vendors, { collectErrors: remainingErrorSlots });
    candidates += plan.candidates;
    matchable += plan.matchable;
    unmatchedErrors.push(...(plan.unmatched_errors || []));
    unmatchedErrorsTruncated = unmatchedErrorsTruncated || Boolean(plan.unmatched_errors_truncated);

    if (!options.dryRun) {
      const uploadApplied = await applyPlannedRawUploadVendorMatches(supabase, uploadPlan, user.owner_email);
      uploadUpdated += uploadApplied.updated;
      const applied = await applyPlannedRateVendorMatches(supabase, plan, user.owner_email);
      updated += applied.updated;
      if (sampleRows.length < 100) sampleRows.push(...applied.rows.slice(0, 100 - sampleRows.length));
    }
  }

  if (options.dryRun) {
    return {
      matched: filtered.database_count || ids.length,
      scanned: ids.length,
      candidates,
      matchable,
      upload_candidates: uploadCandidates,
      upload_matchable: uploadMatchable,
      upload_updated: 0,
      unmatched_errors: unmatchedErrors,
      unmatched_errors_truncated: unmatchedErrorsTruncated,
      updated: 0,
      rows: [],
      database_count: filtered.database_count || ids.length,
      hard_limit_reached: filtered.hard_limit_reached,
      remaining: Math.max(0, (filtered.database_count || ids.length) - ids.length),
      completed: ids.length >= (filtered.database_count || ids.length),
      max_rows: maxRows
    };
  }

  return {
    matched: filtered.database_count || ids.length,
    scanned: ids.length,
    candidates,
    matchable,
    upload_candidates: uploadCandidates,
    upload_matchable: uploadMatchable,
    upload_updated: uploadUpdated,
    unmatched_errors: unmatchedErrors,
    unmatched_errors_truncated: unmatchedErrorsTruncated,
    updated,
    rows: sampleRows,
    database_count: filtered.database_count || ids.length,
    hard_limit_reached: filtered.hard_limit_reached,
    remaining: Math.max(0, (filtered.database_count || ids.length) - ids.length),
    completed: ids.length >= (filtered.database_count || ids.length),
    max_rows: maxRows
  };
}

async function renormalizeRateRows(
  supabase: RatewareSupabaseClient,
  ownerEmail: string | null,
  ids: string[],
  status: string | null = null
) {
  if (!ids.length) throw new Error("At least one rate row id is required.");
  const scopedOwnerEmail = cleanText(ownerEmail)?.toLowerCase();
  if (!scopedOwnerEmail) throw new Error("Workspace owner is required for rate normalization.");

  let rowQuery = supabase.from("rate_staging").select("*").eq("owner_email", scopedOwnerEmail).in("id", ids).limit(500);
  if (status) rowQuery = rowQuery.eq("status", status);

  const [rowsResult, catalogItems] = await Promise.all([
    rowQuery,
    fetchAllManagedCatalogRows(supabase, null)
  ]);

  if (rowsResult.error) throw rowsResult.error;

  const scopedRows = (rowsResult.data || []).map((row) => ({ mapped: row }));
  const [locations, mileageRows] = await Promise.all([
    fetchScopedTemplateLocations(supabase, scopedRows),
    fetchScopedTemplateMileage(supabase, scopedRows)
  ]);

  const catalog = buildCatalogIndex(catalogItems);
  const locationIndex = buildLocationIndex(locations);
  const mileage = new Map(mileageRows.map((lane) => [catalogKey(lane.route_key), lane]));

  const updatedRows = [];
  for (const row of rowsResult.data || []) {
    const patch = normalizeRowWithCurrentCatalog(row, catalog, locationIndex, mileage);
    const result = await supabase
      .from("rate_staging")
      .update(patch)
      .eq("id", row.id)
      .eq("owner_email", scopedOwnerEmail)
      .select("*, vendors(vendor_name, domain)")
      .single();
    if (result.error) throw result.error;
    updatedRows.push(result.data);
  }

  return updatedRows;
}

async function saveRatewareLocationAlias(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  body: Record<string, unknown>
) {
  const alias = cleanText(body.alias);
  const targetLocationId = cleanText(body.target_location_id);
  if (!alias) throw new Error("Alias text is required.");
  if (!targetLocationId) throw new Error("A target catalog location is required.");

  const targetResult = await supabase
    .from("rateware_locations")
    .select("*")
    .eq("id", targetLocationId)
    .eq("active", true)
    .single();
  if (targetResult.error) throw targetResult.error;

  const target = targetResult.data || {};
  const country = ["US", "CA", "MX", "UNKNOWN"].includes(String(target.country || "").toUpperCase())
    ? String(target.country || "").toUpperCase()
    : "UNKNOWN";
  const locationKey = catalogKey([
    alias,
    country,
    target.state_code || target.state_name,
    target.market || target.region
  ].filter(Boolean).join(" "));

  const aliasRow = {
    source: "rateware_manual_catalog",
    country,
    location_key: locationKey,
    raw_value: alias,
    zip_prefix: cleanText(target.zip_prefix),
    city: cleanText(target.city || target.metro_city || alias),
    state_code: cleanText(target.state_code),
    state_name: cleanText(target.state_name),
    metro_city: cleanText(target.metro_city || target.city || alias),
    market: cleanText(target.market),
    region: cleanText(target.region),
    metadata: {
      reason: "user_saved_alias",
      owner_email: user.owner_email,
      target_location_id: target.id,
      target_raw_value: target.raw_value,
      target_source: target.source
    },
    active: true,
    updated_at: new Date().toISOString()
  };

  const result = await supabase
    .from("rateware_locations")
    .upsert(aliasRow, { onConflict: "source,location_key" })
    .select("id,source,raw_value,zip_prefix,metro_city,city,state_code,state_name,country,market,region")
    .single();
  if (result.error) throw result.error;

  await writeAuditLog(supabase, user, "catalog.location_alias", "rateware_locations", String(result.data.id), `Saved location alias "${alias}"`, {
    target_location_id: targetLocationId,
    country,
    market: aliasRow.market,
    region: aliasRow.region
  });

  return { location: locationOptionPayload(result.data) };
}

function normalizeLocationCatalogInput(input: Record<string, unknown>, user: { owner_email: string | null }) {
  const countryInput = cleanText(input.country)?.toUpperCase() || "UNKNOWN";
  const country = ["US", "CA", "MX", "UNKNOWN"].includes(countryInput) ? countryInput : "UNKNOWN";
  const zipPrefix = cleanText(input.zip_prefix || input.zipPrefix);
  const rawValue = cleanText(input.raw_value || input.rawValue || input.value)
    || [cleanText(input.city || input.metro_city), cleanText(input.state_code || input.state_name), zipPrefix].filter(Boolean).join(", ");
  if (!rawValue) throw new Error("Location value is required.");

  const stateCode = cleanText(input.state_code || input.stateCode)?.toUpperCase() || null;
  const stateName = cleanText(input.state_name || input.stateName);
  const city = cleanText(input.city || input.metro_city || input.metroCity || rawValue);
  const metroCity = cleanText(input.metro_city || input.metroCity || city || rawValue);
  const market = cleanText(input.market);
  const region = cleanText(input.region);
  const locationKey = catalogKey([
    rawValue,
    zipPrefix,
    stateCode || stateName,
    country
  ].filter(Boolean).join(" "));

  return {
    row: {
      source: "rateware_manual_catalog",
      country,
      location_key: locationKey,
      raw_value: rawValue,
      zip_prefix: zipPrefix,
      city,
      state_code: stateCode,
      state_name: stateName,
      metro_city: metroCity,
      market,
      region,
      metadata: {
        owner_email: user.owner_email,
        owner_user_id: (user as Record<string, unknown>).owner_user_id || null,
        note: cleanText(input.note),
        created_from: "admin_catalogs"
      },
      active: true,
      updated_at: new Date().toISOString()
    },
    summary: {
      raw_value: rawValue,
      country,
      zip_prefix: zipPrefix,
      state_code: stateCode,
      market,
      region
    }
  };
}

function normalizeOperationalCatalogImportRow(input: Record<string, unknown>, user: { owner_email: string | null }, context: Record<string, unknown> = {}) {
  const category = cleanText(input.category);
  const rawValue = cleanText(input.raw_value || input.rawValue || input.value);
  const normalizedValue = cleanText(input.normalized_value || input.normalizedValue || rawValue);
  if (!category || !MANAGED_CATALOG_CATEGORIES.has(category)) throw new Error("invalid category");
  if (!rawValue || !normalizedValue) throw new Error("missing value");
  const code = cleanText(input.code) || catalogCode(normalizedValue);
  return {
    source: "rateware_manual_catalog",
    category,
    raw_value: rawValue,
    normalized_value: normalizedValue,
    code,
    metadata: {
      owner_email: user.owner_email,
      owner_user_id: (user as Record<string, unknown>).owner_user_id || null,
      note: cleanText(input.note),
      import_file_name: cleanText(context.file_name),
      import_sheet_name: cleanText(context.sheet_name),
      created_from: "admin_catalog_import"
    },
    active: true,
    updated_at: new Date().toISOString()
  };
}

async function bulkImportCatalogValues(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  body: Record<string, unknown>
) {
  const importType = cleanText(body.import_type || body.importType) || "locations";
  const rows = Array.isArray(body.rows) ? body.rows.slice(0, 5000) : [];
  if (!rows.length) throw new Error("No catalog rows were provided.");
  const context = {
    file_name: cleanText(body.file_name || body.fileName),
    sheet_name: cleanText(body.sheet_name || body.sheetName)
  };
  const warnings: string[] = [];
  const normalizedRows: Record<string, unknown>[] = [];
  let skipped = 0;

  for (const [index, item] of rows.entries()) {
    const input = item && typeof item === "object" ? item as Record<string, unknown> : {};
    try {
      if (importType === "operational") {
        normalizedRows.push(normalizeOperationalCatalogImportRow(input, user, context));
      } else if (importType === "locations") {
        const normalized = normalizeLocationCatalogInput({ ...input, ...context }, user);
        const locationRow = normalized.row as Record<string, unknown>;
        locationRow.metadata = {
          ...objectRecord(locationRow.metadata),
          import_file_name: context.file_name,
          import_sheet_name: context.sheet_name,
          created_from: "admin_catalog_import"
        };
        normalizedRows.push(locationRow);
      } else {
        throw new Error("invalid catalog import type");
      }
    } catch (error) {
      skipped += 1;
      if (warnings.length < 20) warnings.push(`Row ${index + 1}: ${error instanceof Error ? error.message : "invalid row"}.`);
    }
  }

  if (!normalizedRows.length) {
    throw new Error(warnings[0] || "No usable catalog rows were found.");
  }

  let imported = 0;
  const table = importType === "operational" ? "rateware_catalog_items" : "rateware_locations";
  const conflict = importType === "operational" ? "source,category,raw_value,normalized_value" : "source,location_key";
  for (const batch of chunkValues(normalizedRows, 500)) {
    const result = await supabase
      .from(table)
      .upsert(batch, { onConflict: conflict })
      .select("id");
    if (result.error) throw result.error;
    imported += result.data?.length || 0;
  }

  await writeAuditLog(
    supabase,
    user,
    importType === "operational" ? "catalog.values.bulk_import" : "catalog.locations.bulk_import",
    table,
    null,
    `Imported ${imported} ${importType === "operational" ? "catalog value" : "location catalog"} row(s)`,
    { imported, skipped, file_name: context.file_name, sheet_name: context.sheet_name }
  );

  return { imported, skipped, warnings };
}

const RFX_PROCESS_STATUSES = new Set([
  "draft",
  "rfi_sent",
  "rfi_in_progress",
  "rfi_submitted",
  "demand_review",
  "rfx_design",
  "bid_room_open",
  "bid_room_closed",
  "bid_evaluation",
  "awarded",
  "implementation_ready",
  "archived"
]);

const RFX_PROCESS_OPPORTUNITY_TYPES = new Set([
  "benchmark",
  "new_provider",
  "capacity_addition",
  "dedicated",
  "spot",
  "contract",
  "backup"
]);

const RFX_PROCESS_SEGMENTS = new Set(["expedited", "time_critical", "crossborder", "local", "regional", "national"]);

function normalizeRfxProcessSegments(value: unknown) {
  const raw = Array.isArray(value) ? value : String(value || "").split(/[,|]/);
  return Array.from(new Set(raw
    .map((item) => cleanText(item)?.toLowerCase().replace(/[\s-]+/g, "_"))
    .filter((item): item is string => Boolean(item && RFX_PROCESS_SEGMENTS.has(item)))));
}

function normalizeRfxProjectInput(input: Record<string, unknown>) {
  const opportunityType = cleanText(input.opportunity_type || input.opportunityType)?.toLowerCase() || "spot";
  const status = cleanText(input.status)?.toLowerCase() || "draft";
  const title = cleanText(input.title || input.name);
  if (!title) throw new Error("RFx Project title is required.");
  const customerEmail = cleanText(input.customer_contact_email || input.customerContactEmail)?.toLowerCase();
  if (customerEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail)) throw new Error("Customer contact email is invalid.");
  return {
    title,
    customer_id: cleanText(input.customer_id || input.customerId),
    customer_name: cleanText(input.customer_name || input.customerName || input.customer),
    customer_contact_name: cleanText(input.customer_contact_name || input.customerContactName),
    customer_contact_email: customerEmail || null,
    opportunity_type: RFX_PROCESS_OPPORTUNITY_TYPES.has(opportunityType) ? opportunityType : "spot",
    operating_segments: normalizeRfxProcessSegments(input.operating_segments || input.operatingSegments),
    status: RFX_PROCESS_STATUSES.has(status) ? status : "draft",
    target_start_date: cleanDate(input.target_start_date || input.targetStartDate),
    due_date: cleanDate(input.due_date || input.dueDate),
    notes: cleanText(input.notes),
    linked_rfx_event_id: cleanText(input.linked_rfx_event_id || input.linkedRfxEventId),
    updated_at: new Date().toISOString()
  };
}

function normalizeRfxProjectPatch(input: Record<string, unknown>) {
  const patch: Record<string, unknown> = {};
  if (input.title !== undefined || input.name !== undefined) patch.title = cleanText(input.title || input.name);
  if (input.customer_id !== undefined || input.customerId !== undefined) patch.customer_id = cleanText(input.customer_id || input.customerId);
  if (input.customer_name !== undefined || input.customerName !== undefined || input.customer !== undefined) patch.customer_name = cleanText(input.customer_name || input.customerName || input.customer);
  if (input.customer_contact_name !== undefined || input.customerContactName !== undefined) patch.customer_contact_name = cleanText(input.customer_contact_name || input.customerContactName);
  if (input.customer_contact_email !== undefined || input.customerContactEmail !== undefined) {
    const email = cleanText(input.customer_contact_email || input.customerContactEmail)?.toLowerCase();
    if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error("Customer contact email is invalid.");
    patch.customer_contact_email = email || null;
  }
  if (input.opportunity_type !== undefined || input.opportunityType !== undefined) {
    const type = cleanText(input.opportunity_type || input.opportunityType)?.toLowerCase();
    if (type && RFX_PROCESS_OPPORTUNITY_TYPES.has(type)) patch.opportunity_type = type;
  }
  if (input.operating_segments !== undefined || input.operatingSegments !== undefined) patch.operating_segments = normalizeRfxProcessSegments(input.operating_segments || input.operatingSegments);
  if (input.status !== undefined) {
    const status = cleanText(input.status)?.toLowerCase();
    if (status && RFX_PROCESS_STATUSES.has(status)) patch.status = status;
  }
  if (input.target_start_date !== undefined || input.targetStartDate !== undefined) patch.target_start_date = cleanDate(input.target_start_date || input.targetStartDate);
  if (input.due_date !== undefined || input.dueDate !== undefined) patch.due_date = cleanDate(input.due_date || input.dueDate);
  if (input.notes !== undefined) patch.notes = cleanText(input.notes);
  if (input.linked_rfx_event_id !== undefined || input.linkedRfxEventId !== undefined) patch.linked_rfx_event_id = cleanText(input.linked_rfx_event_id || input.linkedRfxEventId);
  patch.updated_at = new Date().toISOString();
  return patch;
}

async function requireOwnedRfxProcessProject(supabase: RatewareSupabaseClient, user: { owner_email: string | null }, projectId: unknown) {
  const id = cleanText(projectId);
  if (!id) throw new Error("RFx Project id is required.");
  const result = await supabase
    .from("rfx_projects")
    .select("*")
    .eq("id", id)
    .eq("owner_email", user.owner_email)
    .single();
  if (result.error) throw result.error;
  return result.data as Record<string, unknown>;
}

async function writeRfxProcessAudit(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null },
  projectId: unknown,
  action: string,
  entityType: string,
  entityId: unknown,
  summary: string,
  metadata: Record<string, unknown> = {}
) {
  const row = withOwner({
    project_id: cleanText(projectId),
    actor_email: user.owner_email,
    action,
    entity_type: entityType,
    entity_id: cleanText(entityId),
    summary,
    metadata
  }, user);
  const result = await supabase.from("rfx_process_audit").insert(row);
  if (result.error) throw result.error;
  await writeAuditLog(supabase, user, action, entityType, entityId, summary, { ...metadata, rfx_project_id: cleanText(projectId) });
}

async function hashRfxMagicToken(token: string) {
  const hash = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(token));
  return Array.from(new Uint8Array(hash)).map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

async function hashRatebookCarrierAccessToken(token: string) {
  const hash = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(token));
  return Array.from(new Uint8Array(hash)).map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

async function hashVendorProfileRequestToken(token: string) {
  const hash = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(token));
  return Array.from(new Uint8Array(hash)).map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

async function hashRatebookSourceSnapshot(snapshot: string) {
  const hash = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(snapshot));
  return Array.from(new Uint8Array(hash)).map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

function ratebookCarrierAccessToken() {
  return `${crypto.randomUUID().replaceAll("-", "")}${crypto.randomUUID().replaceAll("-", "")}`;
}

function rfxMagicToken() {
  return `${randomToken()}${randomToken()}`;
}

function rfxProjectPublicLink(token: string, appOrigin: unknown) {
  const origin = cleanText(appOrigin) || "https://rateware.vercel.app";
  return `${origin.replace(/\/$/, "")}/customer-rfi.html?token=${encodeURIComponent(token)}`;
}

function rfxRequiredLaneIssues(lane: Record<string, unknown>) {
  const issues: string[] = [];
  if (!cleanText(lane.origin_location || lane.origin_text || lane.origin || lane.origin_id || lane.origin_name || lane.origin_city)) issues.push("origin_missing");
  if (!cleanText(lane.destination_location || lane.destination_text || lane.destination || lane.destination_id || lane.destination_name || lane.destination_city)) issues.push("destination_missing");
  if (!cleanText(lane.truck_type || lane.equipment_type || lane.equipment || lane.trailer_requirements || lane.trailer)) issues.push("equipment_missing");
  if (cleanNumber(lane.weekly_volume) === null && cleanNumber(lane.monthly_volume) === null && cleanNumber(lane.last_annual_volume) === null && cleanNumber(lane.annual_volume) === null) issues.push("volume_missing");
  return issues;
}

function completenessScoreFromIssues(requiredCount: number, issueCount: number) {
  if (!requiredCount) return 100;
  return Math.max(0, Math.min(100, Math.round((requiredCount - issueCount) / requiredCount * 100)));
}

async function rfxProcessReadiness(supabase: RatewareSupabaseClient, projectId: unknown) {
  const submissionResult = await supabase
    .from("rfx_rfi_submissions")
    .select("*")
    .eq("project_id", projectId)
    .maybeSingle();
  if (submissionResult.error) throw submissionResult.error;

  const snapshotResult = await supabase
    .from("rfx_demand_snapshots")
    .select("*, rfx_demand_lanes(*)")
    .eq("project_id", projectId)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (snapshotResult.error) throw snapshotResult.error;

  const packageResult = await supabase
    .from("rfx_packages")
    .select("*")
    .eq("project_id", projectId)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (packageResult.error) throw packageResult.error;

  return {
    submission: submissionResult.data as Record<string, unknown> | null,
    snapshot: snapshotResult.data as Record<string, unknown> | null,
    package: packageResult.data as Record<string, unknown> | null
  };
}

async function validateRfxProjectStatusChange(supabase: RatewareSupabaseClient, projectId: unknown, status: unknown) {
  const nextStatus = cleanText(status);
  if (!nextStatus) return;
  const readiness = await rfxProcessReadiness(supabase, projectId);
  if (["demand_review", "rfx_design", "bid_room_open", "bid_evaluation", "awarded", "implementation_ready"].includes(nextStatus)) {
    if (readiness.submission?.status !== "submitted") throw new Error("RFx Project cannot move forward until the Customer RFI is submitted.");
  }
  if (["rfx_design", "bid_room_open", "bid_evaluation", "awarded", "implementation_ready"].includes(nextStatus)) {
    const lanes = Array.isArray(readiness.snapshot?.rfx_demand_lanes) ? readiness.snapshot?.rfx_demand_lanes as Record<string, unknown>[] : [];
    const hasIssues = lanes.some((lane) => Array.isArray(lane.validation_issues) && lane.validation_issues.length);
    if (!readiness.snapshot || !lanes.length) throw new Error("Create a reviewed Demand Snapshot before RFx Design.");
    if (hasIssues) throw new Error("Resolve incomplete demand lanes before RFx Design.");
  }
  if (["bid_room_open", "bid_evaluation", "awarded", "implementation_ready"].includes(nextStatus)) {
    if (!readiness.package?.linked_rfx_event_id) throw new Error("Launch an RFx Package to Bid Room before marking the project as bid_room_open.");
  }
}

function rfxPackageWeights(input: Record<string, unknown>) {
  return {
    price_weight: cleanNumber(input.price_weight) ?? 40,
    capacity_weight: cleanNumber(input.capacity_weight) ?? 25,
    service_weight: cleanNumber(input.service_weight) ?? 20,
    compliance_weight: cleanNumber(input.compliance_weight) ?? 10,
    risk_weight: cleanNumber(input.risk_weight) ?? 5
  };
}

const RFX_PACKAGE_RUBRICS = [
  { key: "logistics_model", label: "Logistics model", es_label: "Modelo logistico" },
  { key: "operation_criteria", label: "Operation criteria", es_label: "Criterios de operacion" },
  { key: "business_rules", label: "Business rules", es_label: "Reglas de negocio" },
  { key: "service_specifications", label: "Service specifications", es_label: "Especificaciones de servicio" },
  { key: "carrier_requirements", label: "Required carrier profile", es_label: "Perfil requerido del carrier" },
  { key: "other_notes", label: "Other notes", es_label: "Otras notas" }
];

function firstCleanText(...values: unknown[]) {
  for (const value of values) {
    const text = cleanText(value);
    if (text) return text;
  }
  return "";
}

function safeRfxSegmentSlug(value: string) {
  return value
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 120);
}

function rfxSegmentKeyForDemandLane(lane: Record<string, unknown>) {
  const payload = objectRecord(lane.normalized_payload);
  const label = [
    firstCleanText(lane.operating_segment, payload.operating_segment, lane.operation_type, payload.operation),
    firstCleanText(lane.service_type, payload.service),
    firstCleanText(lane.equipment_type, payload.equipment),
    firstCleanText(lane.trailer_requirements, payload.trailer)
  ].filter(Boolean).join(" / ");
  return safeRfxSegmentSlug(label) || "general";
}

function rfxSegmentNameForDemandLane(lane: Record<string, unknown>) {
  const payload = objectRecord(lane.normalized_payload);
  return [
    firstCleanText(lane.operating_segment, payload.operating_segment, lane.operation_type, payload.operation),
    firstCleanText(lane.service_type, payload.service),
    firstCleanText(lane.equipment_type, payload.equipment),
    firstCleanText(lane.trailer_requirements, payload.trailer)
  ].filter(Boolean).join(" / ") || "General RFx segment";
}

function rfxDemandLaneDetail(lane: Record<string, unknown>, field: string) {
  const payload = objectRecord(lane.normalized_payload);
  const aliasMap: Record<string, string[]> = {
    logistics_model: ["logistic_model", "modelo_logistico", "shipment_model", "operating_model"],
    operation_criteria: ["operational_criteria", "criterios_de_operacion", "criteria"],
    business_rules: ["reglas_de_negocio", "commercial_rules", "rules"],
    service_specifications: ["service_specs", "service_requirements", "especificaciones_de_servicio"],
    carrier_requirements: ["required_carrier_profile", "carrier_profile", "perfil_requerido", "carrier_requirements_notes"],
    other_notes: ["otras_notas", "additional_notes", "lane_notes"]
  };
  const aliases = aliasMap[field] || [];
  const candidates = [
    payload[field],
    ...aliases.map((alias) => payload[alias]),
    lane[field],
    ...aliases.map((alias) => lane[alias])
  ];
  if (field === "logistics_model") {
    candidates.push([
      firstCleanText(lane.operating_segment, lane.operation_type),
      firstCleanText(lane.service_type),
      firstCleanText(lane.currency) ? `Currency ${firstCleanText(lane.currency)}` : ""
    ].filter(Boolean).join(" | "));
  }
  if (field === "service_specifications") {
    candidates.push([
      firstCleanText(lane.equipment_type),
      firstCleanText(lane.trailer_requirements),
      firstCleanText(lane.frequency),
      cleanNumber(lane.weekly_volume) !== null ? `${cleanNumber(lane.weekly_volume)} / wk` : ""
    ].filter(Boolean).join(" | "));
  }
  if (field === "other_notes") candidates.push(lane.internal_notes);
  return firstCleanText(...candidates);
}

function rfxChecklistForSegment(segment: Record<string, unknown>) {
  return RFX_PACKAGE_RUBRICS.map((rubric) => ({
    key: rubric.key,
    label: rubric.label,
    es_label: rubric.es_label,
    required: rubric.key !== "other_notes",
    detail: cleanText(segment[rubric.key])
  }));
}

function buildRfxPackageSegments(
  packageId: unknown,
  lanes: Record<string, unknown>[],
  user: { owner_user_id: string | null; owner_email: string | null }
) {
  const groups = new Map<string, Record<string, unknown>[]>();
  for (const lane of lanes) {
    const key = rfxSegmentKeyForDemandLane(lane);
    const bucket = groups.get(key) || [];
    bucket.push(lane);
    groups.set(key, bucket);
  }
  return [...groups.entries()].map(([segmentKey, segmentLanes], index) => {
    const firstLane = segmentLanes[0] || {};
    const segment: Record<string, unknown> = withOwner({
      package_id: cleanText(packageId),
      segment_key: segmentKey,
      segment_name: rfxSegmentNameForDemandLane(firstLane),
      operation: firstCleanText(firstLane.operation_type, objectRecord(firstLane.normalized_payload).operation),
      service: firstCleanText(firstLane.service_type, objectRecord(firstLane.normalized_payload).service),
      equipment: firstCleanText(firstLane.equipment_type, objectRecord(firstLane.normalized_payload).equipment),
      trailer: firstCleanText(firstLane.trailer_requirements, objectRecord(firstLane.normalized_payload).trailer),
      lane_count: segmentLanes.length,
      lane_ids: segmentLanes.map((lane) => cleanText(lane.id || lane.lane_key)).filter(Boolean),
      logistics_model: firstCleanText(...segmentLanes.map((lane) => rfxDemandLaneDetail(lane, "logistics_model"))),
      operation_criteria: firstCleanText(...segmentLanes.map((lane) => rfxDemandLaneDetail(lane, "operation_criteria"))),
      business_rules: firstCleanText(...segmentLanes.map((lane) => rfxDemandLaneDetail(lane, "business_rules"))),
      service_specifications: firstCleanText(...segmentLanes.map((lane) => rfxDemandLaneDetail(lane, "service_specifications"))),
      carrier_requirements: firstCleanText(...segmentLanes.map((lane) => rfxDemandLaneDetail(lane, "carrier_requirements"))),
      other_notes: firstCleanText(...segmentLanes.map((lane) => rfxDemandLaneDetail(lane, "other_notes"))),
      sort_order: index + 1
    }, user);
    segment.checklist = rfxChecklistForSegment(segment);
    return segment;
  });
}

function rfxMasterPackagePayload(pack: Record<string, unknown>, project: Record<string, unknown>, segments: Record<string, unknown>[], laneCount: number) {
  return {
    mode: "master_package",
    package_id: pack.id,
    package_name: pack.name,
    project_id: project.id,
    project_title: project.title,
    customer: project.customer_name,
    strategy: pack.sourcing_strategy,
    pricing_structure: pack.pricing_structure,
    lane_count: laneCount,
    segment_count: segments.length,
    requires_carrier_confirmation: true,
    rubrics: RFX_PACKAGE_RUBRICS,
    segments: segments.map((segment) => ({
      segment_key: segment.segment_key,
      segment_name: segment.segment_name,
      operation: segment.operation,
      service: segment.service,
      equipment: segment.equipment,
      trailer: segment.trailer,
      lane_count: segment.lane_count,
      lane_ids: segment.lane_ids,
      logistics_model: segment.logistics_model,
      operation_criteria: segment.operation_criteria,
      business_rules: segment.business_rules,
      service_specifications: segment.service_specifications,
      carrier_requirements: segment.carrier_requirements,
      other_notes: segment.other_notes,
      checklist: Array.isArray(segment.checklist) ? segment.checklist : rfxChecklistForSegment(segment)
    }))
  };
}

async function resolveShipperForRfxCustomer(
  supabase: RatewareSupabaseClient,
  user: RatewareUser,
  input: Record<string, unknown>,
  event: Record<string, unknown> = {}
) {
  const requestedId = cleanText(input.customer_id || input.customerId || input.shipper_id || input.shipperId);
  if (requestedId && UUID_PATTERN.test(requestedId)) {
    return await requireOwnedShipper(supabase, user, requestedId);
  }

  const customer = firstCleanText(input.customer, input.customer_name, input.shipper, input.account, event.customer);
  const term = safeShipperSearch(customer);
  if (!term) return null;

  const result = await supabase
    .from("shippers")
    .select("id,shipper_name,legal_name,domain,primary_contact_email,status")
    .eq("owner_email", user.owner_email)
    .neq("status", "archived")
    .or(`shipper_name.ilike.%${term}%,legal_name.ilike.%${term}%,domain.ilike.%${term}%,primary_contact_email.ilike.%${term}%`)
    .limit(25);
  if (result.error) throw result.error;

  const rows = (result.data || []) as Record<string, unknown>[];
  const needle = catalogKey(customer);
  return rows.find((row) => [row.shipper_name, row.legal_name, row.domain, row.primary_contact_email]
    .some((value) => catalogKey(value) === needle))
    || rows.find((row) => [row.shipper_name, row.legal_name, row.domain, row.primary_contact_email]
      .some((value) => {
        const candidate = catalogKey(value);
        return candidate && (candidate.includes(needle) || needle.includes(candidate));
      }))
    || null;
}

function rfxEventMatchesShipper(event: Record<string, unknown>, shipper: Record<string, unknown>) {
  const shipperId = cleanText(shipper.id);
  if (shipperId && cleanText(event.customer_id) === shipperId) return true;
  const shipperKeys = [
    shipper.shipper_name,
    shipper.legal_name,
    shipper.domain,
    shipper.website
  ].map(catalogKey).filter(Boolean);
  if (!shipperKeys.length) return false;
  const eventKeys = [
    catalogKey(event.customer),
    catalogKey(event.name)
  ].filter(Boolean);
  return eventKeys.some((eventKey) => shipperKeys.some((shipperKey) =>
    eventKey === shipperKey || eventKey.includes(shipperKey) || shipperKey.includes(eventKey)
  ));
}

async function linkRfxProjectToShipper(
  supabase: RatewareSupabaseClient,
  user: RatewareUser,
  project: Record<string, unknown>,
  event: Record<string, unknown>,
  input: Record<string, unknown> = {}
) {
  let shipper = cleanText(project.customer_id) && UUID_PATTERN.test(cleanText(project.customer_id)!)
    ? await requireOwnedShipper(supabase, user, project.customer_id).catch(() => null)
    : null;
  if (!shipper) shipper = await resolveShipperForRfxCustomer(supabase, user, input, event);
  if (!shipper) return { project, shipper: null };
  const shipperId = cleanText(shipper.id);
  if (!shipperId) return { project, shipper };
  let linkedProject = project;
  if (cleanText(project.customer_id) !== shipperId) {
    const updateProject = await supabase
      .from("rfx_projects")
      .update({
        customer_id: shipperId,
        customer_name: firstCleanText(shipper.shipper_name, shipper.legal_name, project.customer_name, event.customer),
        customer_contact_email: cleanText(shipper.primary_contact_email)?.toLowerCase() || cleanText(project.customer_contact_email) || null,
        updated_at: new Date().toISOString()
      })
      .eq("id", project.id)
      .eq("owner_email", user.owner_email)
      .select()
      .single();
    if (updateProject.error) throw updateProject.error;
    linkedProject = updateProject.data as Record<string, unknown>;
  }
  const eventId = cleanText(event.id);
  if (eventId && UUID_PATTERN.test(eventId) && cleanText(event.customer_id) !== shipperId) {
    const updateEvent = await supabase.from("rfx_events")
      .update({ customer_id: shipperId, updated_at: new Date().toISOString() })
      .eq("id", eventId)
      .eq("owner_email", user.owner_email)
      .select("id")
      .single();
    if (updateEvent.error) throw updateEvent.error;
  }
  return { project: linkedProject, shipper };
}

async function findBidRoomEventsForShipper(
  supabase: RatewareSupabaseClient,
  user: RatewareUser,
  shipper: Record<string, unknown>,
  linkedProjectIds: string[]
) {
  const selectColumns = "id,rfx_id,name,customer,customer_id,status,due_date,event_type,bid_visibility_mode,source_rfx_process_project_id,source_rfx_package_id,source_rfx_package_name,notes,updated_at,created_at";
  const eventRows = await fetchAllOwnedRfxEvents(supabase, user.owner_email, selectColumns, { includeArchived: true });
  const linkedProjectSet = new Set(linkedProjectIds);
  return eventRows
    .filter((event) => linkedProjectSet.has(cleanText(event.source_rfx_process_project_id) || "") || rfxEventMatchesShipper(event, shipper))
    .sort((left, right) => (cleanText(right.updated_at) || cleanText(right.created_at) || "").localeCompare(cleanText(left.updated_at) || cleanText(left.created_at) || ""));
}

function emptyRatebookSyncSummary() {
  return {
    attempted: 0,
    synchronized: 0,
    failed: [] as { event_id: string | null; error: string | null }[],
    rows: [] as Record<string, unknown>[]
  };
}

async function syncBidRoomEventsForRatebookScope(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null; organization_id?: string | null },
  input: Record<string, unknown>
) {
  if (cleanText(input.package_id || input.rfx_package_id)) return emptyRatebookSyncSummary();
  const requestedSourceType = cleanText(input.source_type)?.toLowerCase();
  if (requestedSourceType && !["bid_room", "spot"].includes(requestedSourceType)) return emptyRatebookSyncSummary();
  const requestedProjectId = cleanText(input.project_id);
  const requestedShipperId = cleanText(input.shipper_id);
  if (requestedProjectId && !UUID_PATTERN.test(requestedProjectId)) return emptyRatebookSyncSummary();
  const scopedUser = { ...user, organization_id: user.organization_id || null };
  const selectColumns = "id,rfx_id,name,customer,customer_id,status,due_date,event_type,bid_visibility_mode,source_rfx_process_project_id,source_rfx_package_id,source_rfx_package_name,notes,updated_at,created_at";
  let events = await fetchAllOwnedRfxEvents(supabase, user.owner_email, selectColumns, { includeArchived: true });
  if (requestedProjectId) {
    events = events.filter((event) => cleanText(event.source_rfx_process_project_id) === requestedProjectId);
  }
  if (requestedShipperId && UUID_PATTERN.test(requestedShipperId)) {
    const shipper = await requireOwnedShipper(supabase, scopedUser, requestedShipperId);
    const linkedProjects = await fetchAllRfxProjectIdsForShipper(supabase, user.owner_email, requestedShipperId);
    const linkedProjectIds = new Set(linkedProjects.map((project) => cleanText(project.id)).filter(Boolean));
    events = events.filter((event) =>
      linkedProjectIds.has(cleanText(event.source_rfx_process_project_id) || "") || rfxEventMatchesShipper(event, shipper)
    );
  }
  const eligibleEvents = events.filter((event) => {
    const eventType = cleanText(event.event_type)?.toLowerCase();
    if (requestedSourceType === "spot" && eventType !== "spot") return false;
    if (requestedSourceType === "bid_room" && eventType === "spot") return false;
    return true;
  });
  const outcomes = await mapWithConcurrency(eligibleEvents, RATEBOOK_SYNC_CONCURRENCY, async (event) => {
    try {
      return {
        event_id: cleanText(event.id),
        synced: await ensureRatebookForBidRoomEvent(
          supabase,
          scopedUser,
          event,
          requestedShipperId && UUID_PATTERN.test(requestedShipperId) ? { customer_id: requestedShipperId } : {}
        ),
        error: null as string | null
      };
    } catch (error) {
      return {
        event_id: cleanText(event.id),
        synced: null,
        error: safeOperationalError(error) || "Ratebook synchronization failed for this Bid Room event."
      };
    }
  });
  const failed = outcomes
    .filter((outcome) => outcome.error)
    .map((outcome) => ({ event_id: outcome.event_id, error: outcome.error }));
  return {
    attempted: eligibleEvents.length,
    synchronized: outcomes.filter((outcome) => outcome.synced).length,
    failed,
    rows: outcomes.reduce<Record<string, unknown>[]>((rows, outcome) => {
      if (outcome.synced) rows.push(outcome.synced as Record<string, unknown>);
      return rows;
    }, [])
  };
}

function rfxProjectStatusForEvent(event: Record<string, unknown>) {
  const status = cleanText(event.status)?.toLowerCase();
  if (status === "archived") return "archived";
  if (status === "closed" || status === "awarded") return "bid_room_closed";
  if (status === "open") return "bid_room_open";
  return "draft";
}

function rfxOpportunityTypeForEvent(event: Record<string, unknown>) {
  return cleanText(event.event_type)?.toLowerCase() === "spot" ? "spot" : "contract";
}

function ratebookSourceTypeForEvent(event: Record<string, unknown>) {
  return cleanText(event.event_type)?.toLowerCase() === "spot" ? "spot" : "bid_room";
}

async function ensureBidRoomEventProject(
  supabase: RatewareSupabaseClient,
  user: RatewareUser,
  event: Record<string, unknown>,
  input: Record<string, unknown> = {}
) {
  const eventId = cleanText(event.id);
  if (!eventId) throw new Error("RFx event id is required.");

  const sourceProjectId = cleanText(event.source_rfx_process_project_id);
  if (sourceProjectId && UUID_PATTERN.test(sourceProjectId)) {
    const project = await requireOwnedRfxProcessProject(supabase, user, sourceProjectId);
    const linked = await linkRfxProjectToShipper(supabase, user, project, event, input);
    return { event, project: linked.project, shipper: linked.shipper };
  }

  const existingProjectResult = await supabase
    .from("rfx_projects")
    .select("*")
    .eq("owner_email", user.owner_email)
    .eq("linked_rfx_event_id", eventId)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (existingProjectResult.error) throw existingProjectResult.error;
  if (existingProjectResult.data) {
    const project = existingProjectResult.data as Record<string, unknown>;
    const updateEvent = await supabase
      .from("rfx_events")
      .update({ source_rfx_process_project_id: project.id, updated_at: new Date().toISOString() })
      .eq("id", eventId)
      .eq("owner_email", user.owner_email)
      .select()
      .single();
    if (updateEvent.error) throw updateEvent.error;
    const linked = await linkRfxProjectToShipper(supabase, user, project, updateEvent.data as Record<string, unknown>, input);
    return { event: updateEvent.data as Record<string, unknown>, project: linked.project, shipper: linked.shipper };
  }

  const shipper = await resolveShipperForRfxCustomer(supabase, user, input, event);
  const projectRow = withOwner({
    title: firstCleanText(event.name, event.rfx_id, "Bid Room event") || "Bid Room event",
    customer_id: cleanText(shipper?.id) || null,
    customer_name: firstCleanText(shipper?.shipper_name, shipper?.legal_name, event.customer),
    customer_contact_email: cleanText(shipper?.primary_contact_email)?.toLowerCase() || null,
    opportunity_type: rfxOpportunityTypeForEvent(event),
    operating_segments: [],
    status: rfxProjectStatusForEvent(event),
    due_date: cleanDate(event.due_date),
    notes: firstCleanText(event.notes, `Auto-created from Bid Room event ${firstCleanText(event.rfx_id, event.name, event.id)}.`),
    linked_rfx_event_id: eventId,
    updated_at: new Date().toISOString()
  }, user);
  const projectInsert = await supabase.from("rfx_projects").insert(projectRow).select().single();
  if (projectInsert.error) throw projectInsert.error;
  const updateEvent = await supabase
    .from("rfx_events")
    .update({ source_rfx_process_project_id: projectInsert.data.id, customer_id: cleanText(shipper?.id) || null, updated_at: new Date().toISOString() })
    .eq("id", eventId)
    .eq("owner_email", user.owner_email)
    .select()
    .single();
  if (updateEvent.error) throw updateEvent.error;

  await writeRfxProcessAudit(
    supabase,
    user,
    projectInsert.data.id,
    "bid_room_project_created",
    "rfx_events",
    eventId,
    `Created Ratebook capture workspace for Bid Room event ${firstCleanText(event.rfx_id, event.name, event.id)}.`,
    { shipper_id: cleanText(shipper?.id), source: "bid_room_event" }
  );

  return { event: updateEvent.data as Record<string, unknown>, project: projectInsert.data as Record<string, unknown>, shipper };
}

function bidRoomDemandLaneRow(
  lane: Record<string, unknown>,
  event: Record<string, unknown>,
  project: Record<string, unknown>,
  snapshotId: unknown,
  user: { owner_user_id: string | null; owner_email: string | null },
  index = 0
) {
  const annualVolume = cleanNumber(lane.annual_volume);
  const weeklyVolume = cleanNumber(lane.weekly_volume);
  const laneKey = firstCleanText(lane.lane_number, lane.id, `L${index + 1}`) || `L${index + 1}`;
  const normalizedPayload = {
    ...lane,
    source: "bid_room_event",
    source_rfx_event_id: cleanText(event.id),
    source_rfx_lane_id: cleanText(lane.id),
    event_rfx_id: cleanText(event.rfx_id),
    event_name: cleanText(event.name),
    event_customer: cleanText(event.customer),
    event_type: cleanText(event.event_type),
    source_rfx_process_project_id: cleanText(project.id)
  };
  const row = withOwner({
    snapshot_id: cleanText(snapshotId),
    project_id: cleanText(project.id),
    source_rfi_lane_id: null,
    lane_key: laneKey,
    origin: firstCleanText(lane.origin, [lane.origin_city, lane.origin_state].filter(Boolean).join(", ")),
    origin_city: cleanText(lane.origin_city),
    origin_state: cleanText(lane.origin_state),
    origin_country: cleanText(lane.origin_country),
    origin_postal_code: firstCleanText(lane.origin_postal_code, objectRecord(lane.normalized_payload).origin_postal_code),
    destination: firstCleanText(lane.destination, [lane.destination_city, lane.destination_state].filter(Boolean).join(", ")),
    destination_city: cleanText(lane.destination_city),
    destination_state: cleanText(lane.destination_state),
    destination_country: cleanText(lane.destination_country),
    destination_postal_code: firstCleanText(lane.destination_postal_code, objectRecord(lane.normalized_payload).destination_postal_code),
    operating_segment: firstCleanText(lane.rfx_segment_name, lane.operation, lane.service),
    operation_type: cleanText(lane.operation),
    service_type: cleanText(lane.service),
    equipment_type: cleanText(lane.equipment),
    trailer_requirements: cleanText(lane.trailer),
    weekly_volume: weeklyVolume,
    monthly_volume: weeklyVolume === null ? (annualVolume === null ? null : annualVolume / 12) : weeklyVolume * 4.33,
    frequency: cleanText(lane.frequency),
    currency: cleanText(lane.currency)?.toUpperCase() || "USD",
    target_rate: cleanNumber(lane.target_rate),
    current_rate: null,
    internal_notes: firstCleanText(lane.notes, lane.other_notes),
    validation_issues: [],
    normalized_payload: normalizedPayload,
    updated_at: new Date().toISOString()
  }, user);
  const issues = rfxRequiredLaneIssues(row).map((issue) => ({ issue }));
  row.validation_issues = issues;
  return row;
}

async function fetchAllBidRoomDemandLanes(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  snapshotId: unknown,
  projectId: unknown
) {
  const rows: Record<string, unknown>[] = [];
  for (let offset = 0; offset < RFX_EVENT_CHILD_MAX_ROWS; offset += RFX_EVENT_CHILD_PAGE_SIZE) {
    const result = await supabase
      .from("rfx_demand_lanes")
      .select("*")
      .eq("owner_email", user.owner_email)
      .eq("snapshot_id", snapshotId)
      .eq("project_id", projectId)
      .order("id", { ascending: true })
      .range(offset, offset + RFX_EVENT_CHILD_PAGE_SIZE - 1);
    if (result.error) throw new Error(`RFx demand lane load failed: ${result.error.message}`);
    const page = (result.data || []) as Record<string, unknown>[];
    rows.push(...page);
    if (page.length < RFX_EVENT_CHILD_PAGE_SIZE) return rows;
  }
  throw new Error(`RFx demand lane load exceeded ${RFX_EVENT_CHILD_MAX_ROWS} rows for one Bid Room event.`);
}

async function upsertBidRoomDemandLanes(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null },
  event: Record<string, unknown>,
  project: Record<string, unknown>,
  snapshotId: unknown,
  lanes: Record<string, unknown>[]
) {
  const existingRows = await fetchAllBidRoomDemandLanes(supabase, user, snapshotId, project.id);
  const existingBySourceLaneId = new Map<string, Record<string, unknown>>();
  existingRows.forEach((row) => {
    const sourceLaneId = cleanText(objectRecord(row.normalized_payload).source_rfx_lane_id);
    if (sourceLaneId) existingBySourceLaneId.set(sourceLaneId, row);
  });

  const demandRows: Record<string, unknown>[] = [];
  for (const [index, lane] of lanes.entries()) {
    const row = bidRoomDemandLaneRow(lane, event, project, snapshotId, user, index);
    const existing = existingBySourceLaneId.get(cleanText(lane.id) || "");
    if (existing) {
      const update = await supabase
        .from("rfx_demand_lanes")
        .update(row)
        .eq("id", existing.id)
        .eq("owner_email", user.owner_email)
        .select()
        .single();
      if (update.error) throw update.error;
      demandRows.push(update.data as Record<string, unknown>);
    } else {
      const insert = await supabase.from("rfx_demand_lanes").insert(row).select().single();
      if (insert.error) throw insert.error;
      demandRows.push(insert.data as Record<string, unknown>);
    }
  }
  return demandRows;
}

async function updateLinkedDemandLanesFromBidRoom(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null },
  event: Record<string, unknown>,
  project: Record<string, unknown>,
  lanes: Record<string, unknown>[]
) {
  const updatedIds: string[] = [];
  for (const [index, lane] of lanes.entries()) {
    const demandLaneId = cleanText(lane.source_rfx_demand_lane_id);
    if (!demandLaneId || !UUID_PATTERN.test(demandLaneId)) continue;
    const row = bidRoomDemandLaneRow(lane, event, project, cleanText(objectRecord(lane.rfx_demand_lanes).snapshot_id), user, index);
    const { snapshot_id: _snapshotId, project_id: _projectId, source_rfi_lane_id: _sourceRfiLaneId, ...patch } = row as Record<string, unknown>;
    const update = await supabase
      .from("rfx_demand_lanes")
      .update(patch)
      .eq("id", demandLaneId)
      .eq("project_id", project.id)
      .eq("owner_email", user.owner_email)
      .select("id");
    if (update.error) throw update.error;
    if (update.data?.length) updatedIds.push(demandLaneId);
  }
  return updatedIds;
}

async function ensureRatebookForBidRoomEvent(
  supabase: RatewareSupabaseClient,
  user: RatewareUser,
  eventOrId: Record<string, unknown> | string,
  input: Record<string, unknown> = {}
) {
  const baseEvent = typeof eventOrId === "string"
    ? await requireOwnedRfxEvent(supabase, user, eventOrId)
    : eventOrId;
  const context = await ensureBidRoomEventProject(supabase, user, baseEvent, input);
  let event = context.event;
  const project = context.project;
  const shipperContext = context.shipper ? {
    shipper_id: cleanText(context.shipper.id) || null,
    shipper_name: firstCleanText(context.shipper.shipper_name, context.shipper.legal_name) || null,
    opportunity_name: null
  } : undefined;

  const lanes = await fetchAllRfxLaneRows(supabase, cleanText(event.id) || "", "*");
  if (!lanes.length) return { event, project, ratebook: null, lanes: 0, package: null };

  const sourcePackageId = cleanText(event.source_rfx_package_id);
  if (sourcePackageId && UUID_PATTERN.test(sourcePackageId)) {
    const initialPackageContext = await getOwnedRatebookPackage(supabase, user, sourcePackageId);
    await updateLinkedDemandLanesFromBidRoom(supabase, user, event, initialPackageContext.project, lanes);
    const unlinkedLanes = lanes.filter((lane) => !cleanText(lane.source_rfx_demand_lane_id));
    if (unlinkedLanes.length) {
      const extraDemandRows = await upsertBidRoomDemandLanes(
        supabase,
        user,
        event,
        initialPackageContext.project,
        initialPackageContext.pack.demand_snapshot_id,
        unlinkedLanes
      );
      const existingPackageLanes = await fetchAllRatebookPackageRows(
        supabase,
        "rfx_package_lanes",
        [cleanText(initialPackageContext.pack.id) || ""],
        "id,demand_lane_id"
      );
      const existingDemandIds = new Set(existingPackageLanes.map((row) => cleanText(row.demand_lane_id)).filter(Boolean));
      const missingPackageLanes = extraDemandRows
        .filter((row) => !existingDemandIds.has(cleanText(row.id)))
        .map((row) => withOwner({ package_id: initialPackageContext.pack.id, demand_lane_id: row.id, lot_name: cleanText(event.name || event.rfx_id) }, user));
      for (const batch of chunkValues(missingPackageLanes, 500)) {
        const insert = await supabase.from("rfx_package_lanes").insert(batch).select("id");
        if (insert.error) throw insert.error;
      }
      const extraDemandBySourceLaneId = new Map(extraDemandRows.map((row) => [cleanText(objectRecord(row.normalized_payload).source_rfx_lane_id), row]));
      for (const lane of unlinkedLanes) {
        const demand = extraDemandBySourceLaneId.get(cleanText(lane.id));
        if (!demand) continue;
        const updateLane = await supabase
          .from("rfx_lanes")
          .update({ source_rfx_demand_lane_id: demand.id, updated_at: new Date().toISOString() })
          .eq("id", lane.id)
          .eq("rfx_event_id", event.id);
        if (updateLane.error) throw updateLane.error;
      }
      const segmentRows = buildRfxPackageSegments(initialPackageContext.pack.id, [...initialPackageContext.package_lanes.map((row) => objectRecord(row.rfx_demand_lanes)), ...extraDemandRows], user);
      for (const batch of chunkValues(segmentRows, 250)) {
        const segmentInsert = await supabase.from("rfx_package_segments").upsert(batch, { onConflict: "package_id,segment_key" }).select("id");
        if (segmentInsert.error) throw segmentInsert.error;
      }
    }
    const packageContext = await getOwnedRatebookPackage(supabase, user, sourcePackageId);
    const demandRows = packageContext.package_lanes.map((row) => objectRecord(row.rfx_demand_lanes)).filter((row) => cleanText(row.id));
    const segmentRows = buildRfxPackageSegments(packageContext.pack.id, demandRows, user);
    for (const batch of chunkValues(segmentRows, 250)) {
      const segmentInsert = await supabase.from("rfx_package_segments").upsert(batch, { onConflict: "package_id,segment_key" }).select("id");
      if (segmentInsert.error) throw segmentInsert.error;
    }
  const packageProjectId = cleanText(packageContext.project.id) || "";
  const shipperContexts = await getRatebookShipperContexts(supabase, user, [packageProjectId]);
    const ratebook = await upsertRatebookForPackage(supabase, user, {
      ...packageContext,
      package_segments: segmentRows,
      shipper: shipperContexts.get(packageProjectId) || shipperContext
    });
    return { event, project: packageContext.project, ratebook, lanes: packageContext.package_lanes.length, package: packageContext.pack };
  }

  const snapshotResult = await supabase
    .from("rfx_demand_snapshots")
    .select("*")
    .eq("owner_email", user.owner_email)
    .eq("project_id", project.id)
    .eq("metadata->>source_rfx_event_id", cleanText(event.id))
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (snapshotResult.error) throw snapshotResult.error;

  let snapshot = snapshotResult.data as Record<string, unknown> | null;
  if (!snapshot) {
    const insertSnapshot = await supabase.from("rfx_demand_snapshots").insert(withOwner({
      project_id: project.id,
      name: `${firstCleanText(event.name, event.rfx_id, "Bid Room")} route capture`,
      status: "draft",
      completeness_score: 100,
      validation_issues: [],
      frozen_rfi_snapshot: { source: "bid_room_event", rfx_event_id: event.id, rfx_id: event.rfx_id },
      metadata: {
        source: "bid_room_event",
        source_rfx_event_id: cleanText(event.id),
        event_type: cleanText(event.event_type)
      }
    }, user)).select().single();
    if (insertSnapshot.error) throw insertSnapshot.error;
    snapshot = insertSnapshot.data as Record<string, unknown>;
  }

  const demandRows = await upsertBidRoomDemandLanes(supabase, user, event, project, snapshot.id, lanes);
  const issueCount = demandRows.reduce((sum, row) => sum + (Array.isArray(row.validation_issues) ? row.validation_issues.length : 0), 0);
  const snapshotUpdate = await supabase
    .from("rfx_demand_snapshots")
    .update({
      completeness_score: completenessScoreFromIssues(Math.max(demandRows.length * 5, 1), issueCount),
      validation_issues: demandRows.flatMap((row) => Array.isArray(row.validation_issues) ? row.validation_issues : []).slice(0, 100),
      updated_at: new Date().toISOString()
    })
    .eq("id", snapshot.id)
    .eq("owner_email", user.owner_email);
  if (snapshotUpdate.error) throw snapshotUpdate.error;

  let packageResult = await supabase
    .from("rfx_packages")
    .select("*")
    .eq("owner_email", user.owner_email)
    .eq("project_id", project.id)
    .eq("linked_rfx_event_id", event.id)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (packageResult.error) throw packageResult.error;
  let pack = packageResult.data as Record<string, unknown> | null;
  const packageStatus = cleanText(event.status)?.toLowerCase() === "archived"
    ? "archived"
    : cleanText(event.status)?.toLowerCase() === "open"
      ? "launched"
      : "draft";
  if (!pack) {
    const insertPackage = await supabase.from("rfx_packages").insert(withOwner({
      project_id: project.id,
      demand_snapshot_id: snapshot.id,
      linked_rfx_event_id: event.id,
      name: `${firstCleanText(event.name, event.rfx_id, "Bid Room")} Ratebook package`,
      status: packageStatus,
      sourcing_strategy: cleanText(event.bid_visibility_mode) === "open_leaderboard" ? "open_bid" : "closed_bid",
      pricing_structure: "all_in",
      bid_due_at: cleanTimestamp(event.due_date ? `${event.due_date}T23:59:59Z` : null),
      bid_validity_days: null,
      notes: `Auto-synced from Bid Room event ${firstCleanText(event.rfx_id, event.name, event.id)}.`
    }, user)).select().single();
    if (insertPackage.error) throw insertPackage.error;
    pack = insertPackage.data as Record<string, unknown>;
  } else {
    const updatePackage = await supabase
      .from("rfx_packages")
      .update({
        demand_snapshot_id: snapshot.id,
        status: packageStatus,
        bid_due_at: cleanTimestamp(event.due_date ? `${event.due_date}T23:59:59Z` : null),
        updated_at: new Date().toISOString()
      })
      .eq("id", pack.id)
      .eq("owner_email", user.owner_email)
      .select()
      .single();
    if (updatePackage.error) throw updatePackage.error;
    pack = updatePackage.data as Record<string, unknown>;
  }

  const existingPackageLanes = await fetchAllRatebookPackageRows(
    supabase,
    "rfx_package_lanes",
    [cleanText(pack.id) || ""],
    "id,demand_lane_id"
  );
  const existingDemandIds = new Set(existingPackageLanes.map((row) => cleanText(row.demand_lane_id)).filter(Boolean));
  const missingPackageLanes = demandRows
    .filter((row) => !existingDemandIds.has(cleanText(row.id)))
    .map((row) => withOwner({ package_id: pack!.id, demand_lane_id: row.id, lot_name: cleanText(event.name || event.rfx_id) }, user));
  for (const batch of chunkValues(missingPackageLanes, 500)) {
    const insert = await supabase.from("rfx_package_lanes").insert(batch).select("id");
    if (insert.error) throw insert.error;
  }

  const demandBySourceLaneId = new Map(demandRows.map((row) => [cleanText(objectRecord(row.normalized_payload).source_rfx_lane_id), row]));
  for (const lane of lanes) {
    const demand = demandBySourceLaneId.get(cleanText(lane.id));
    if (!demand || cleanText(lane.source_rfx_demand_lane_id) === cleanText(demand.id)) continue;
    const updateLane = await supabase
      .from("rfx_lanes")
      .update({ source_rfx_demand_lane_id: demand.id, updated_at: new Date().toISOString() })
      .eq("id", lane.id)
      .eq("rfx_event_id", event.id);
    if (updateLane.error) throw updateLane.error;
  }

  const segmentRows = buildRfxPackageSegments(pack.id, demandRows, user);
  for (const batch of chunkValues(segmentRows, 250)) {
    const insert = await supabase.from("rfx_package_segments").upsert(batch, { onConflict: "package_id,segment_key" }).select("id");
    if (insert.error) throw insert.error;
  }

  const eventUpdate = await supabase
    .from("rfx_events")
    .update({
      source_rfx_process_project_id: project.id,
      source_rfx_package_id: pack.id,
      source_rfx_package_name: cleanText(pack.name),
      updated_at: new Date().toISOString()
    })
    .eq("id", event.id)
    .eq("owner_email", user.owner_email)
    .select()
    .single();
  if (eventUpdate.error) throw eventUpdate.error;
  event = eventUpdate.data as Record<string, unknown>;

  const projectUpdate = await supabase
    .from("rfx_projects")
    .update({ status: rfxProjectStatusForEvent(event), linked_rfx_event_id: event.id, updated_at: new Date().toISOString() })
    .eq("id", project.id)
    .eq("owner_email", user.owner_email);
  if (projectUpdate.error) throw projectUpdate.error;

  const ratebook = await upsertRatebookForPackage(supabase, user, {
    pack: { ...pack, source_type: ratebookSourceTypeForEvent(event) },
    project,
    package_lanes: demandRows.map((demand) => ({
      package_id: pack!.id,
      demand_lane_id: demand.id,
      rfx_demand_lanes: demand
    })),
    package_segments: segmentRows,
    shipper: shipperContext
  });
  await writeRfxProcessAudit(
    supabase,
    user,
    project.id,
    "bid_room_ratebook_synced",
    "rfx_ratebooks",
    ratebook.id,
    `Synced ${demandRows.length} Bid Room route(s) into Ratebook ${cleanText(ratebook.name) || ratebook.id}.`,
    { rfx_event_id: cleanText(event.id), rfx_package_id: cleanText(pack.id), source_type: ratebookSourceTypeForEvent(event) }
  );

  return { event, project, ratebook, lanes: demandRows.length, package: pack };
}

async function listRfxProcessProjects(supabase: RatewareSupabaseClient, user: { owner_email: string | null }, input: Record<string, unknown>) {
  const limit = Math.min(Math.max(Number(input.limit) || 100, 1), 250);
  const offset = Math.max(Number(input.offset) || 0, 0);
  let query = supabase
    .from("rfx_projects")
    .select("*", { count: "exact" })
    .eq("owner_email", user.owner_email)
    .neq("status", "archived")
    .order("updated_at", { ascending: false })
    .range(offset, offset + limit - 1);
  if (input.status) query = query.eq("status", cleanText(input.status));
  if (input.search) {
    const term = String(input.search).trim();
    if (term) query = query.or(`title.ilike.%${term}%,customer_name.ilike.%${term}%,customer_contact_email.ilike.%${term}%`);
  }
  const result = await query;
  if (result.error) throw result.error;
  const projectIds = (result.data || []).map((row) => row.id);
  const [lanesResult, packageResult, auditResult, eventResult] = projectIds.length
    ? await Promise.all([
        supabase.from("rfx_rfi_lanes").select("project_id,id").in("project_id", projectIds),
        supabase.from("rfx_packages").select("project_id,id,status,linked_rfx_event_id").in("project_id", projectIds),
        supabase.from("rfx_process_audit").select("project_id,id").in("project_id", projectIds),
        supabase.from("rfx_events").select("id,rfx_id,status,due_date,source_rfx_process_project_id,updated_at,created_at")
          .eq("owner_email", user.owner_email)
          .in("source_rfx_process_project_id", projectIds)
          .neq("status", "archived")
          .order("updated_at", { ascending: false })
          .limit(Math.min(projectIds.length * 5, 250))
      ])
    : [{ data: [], error: null }, { data: [], error: null }, { data: [], error: null }, { data: [], error: null }];
  if (lanesResult.error) throw lanesResult.error;
  if (packageResult.error) throw packageResult.error;
  if (auditResult.error) throw auditResult.error;
  if (eventResult.error && eventResult.error.code !== "42P01") throw eventResult.error;
  const laneCounts = new Map<string, number>();
  const packageCounts = new Map<string, number>();
  const auditCounts = new Map<string, number>();
  const rfiStatuses = new Map<string, string>();
  const eventsByProject = new Map<string, Record<string, unknown>>();
  const packageEventIds = new Map<string, string>();
  for (const row of lanesResult.data || []) laneCounts.set(row.project_id, (laneCounts.get(row.project_id) || 0) + 1);
  for (const row of packageResult.data || []) {
    packageCounts.set(row.project_id, (packageCounts.get(row.project_id) || 0) + 1);
    const linkedEventId = cleanText(row.linked_rfx_event_id);
    if (!packageEventIds.get(row.project_id) && linkedEventId) packageEventIds.set(row.project_id, linkedEventId);
  }
  for (const row of auditResult.data || []) auditCounts.set(row.project_id, (auditCounts.get(row.project_id) || 0) + 1);
  const submissions = projectIds.length
    ? await supabase.from("rfx_rfi_submissions").select("project_id,status").in("project_id", projectIds)
    : { data: [], error: null };
  if (submissions.error && submissions.error.code !== "42P01") throw submissions.error;
  for (const row of submissions.data || []) rfiStatuses.set(row.project_id, cleanText(row.status) || "draft");
  for (const row of eventResult.data || []) {
    const projectId = cleanText(row.source_rfx_process_project_id);
    if (projectId && !eventsByProject.has(projectId)) eventsByProject.set(projectId, row as Record<string, unknown>);
  }
  return {
    rows: (result.data || []).map((row) => ({
      ...row,
      lane_count: laneCounts.get(row.id) || 0,
      package_count: packageCounts.get(row.id) || 0,
      audit_count: auditCounts.get(row.id) || 0,
      rfi_status: rfiStatuses.get(row.id) || "not started",
      bid_room_event_id: eventsByProject.get(row.id)?.id || packageEventIds.get(row.id) || row.linked_rfx_event_id || null,
      bid_room_rfx_id: eventsByProject.get(row.id)?.rfx_id || null,
      bid_room_status: eventsByProject.get(row.id)?.status || (packageEventIds.get(row.id) ? "linked" : null),
      bid_room_due_date: eventsByProject.get(row.id)?.due_date || null
    })),
    total: result.count || 0,
    limit,
    offset
  };
}

function internalRfxSegment(value: unknown) {
  const key = (cleanText(value) || "").toLowerCase().replace(/[^a-z0-9]+/g, "_");
  const aliases: Record<string, string> = {
    crossborder_ftl: "crossborder",
    local_ftl: "local",
    regional_ftl: "regional",
    national_ftl: "national",
    expedited_ground: "expedited",
    time_critical_ground: "time_critical",
    port_drayage_us: "local",
    port_drayage_mx: "local"
  };
  const normalized = aliases[key] || key;
  return ["expedited", "time_critical", "crossborder", "local", "regional", "national"].includes(normalized) ? normalized : null;
}

function internalRfxOperation(value: unknown) {
  const key = (cleanText(value) || "").toLowerCase().replace(/[^a-z0-9]+/g, "_");
  const aliases: Record<string, string> = {
    d2d_export: "crossborder",
    d2d_import: "crossborder",
    mx_northbound: "crossborder",
    mx_southbound: "crossborder",
    intra_mex: "mx_domestic",
    mx_domestic: "mx_domestic",
    us_domestic: "us_domestic"
  };
  const normalized = aliases[key] || key;
  return ["mx_domestic", "us_domestic", "crossborder", "local", "regional", "national"].includes(normalized) ? normalized : null;
}

function internalRfxService(value: unknown) {
  const key = (cleanText(value) || "").toLowerCase().replace(/[^a-z0-9]+/g, "_");
  const aliases: Record<string, string> = { time_critical_ground: "time_critical", expedited_ground: "expedited" };
  const normalized = aliases[key] || key;
  return ["standard", "expedited", "time_critical", "dedicated", "spot", "recurring"].includes(normalized) ? normalized : null;
}

async function saveRfxProcessRfi(supabase: RatewareSupabaseClient, user: { owner_user_id: string | null; owner_email: string | null }, input: Record<string, unknown>) {
  const project = await requireOwnedRfxProcessProject(supabase, user, input.project_id || input.id);
  const rfi = objectRecord(input.rfi);
  const existing = await supabase.from("rfx_rfi_submissions").select("*").eq("project_id", project.id).maybeSingle();
  if (existing.error) throw existing.error;
  const now = new Date().toISOString();
  const lanes = Array.isArray(rfi.lanes) ? rfi.lanes.map((row) => objectRecord(row)).filter((row) => Object.values(row).some((value) => cleanText(value))) : [];
  const segmentValues = (Array.isArray(rfi.operating_segments) ? rfi.operating_segments : [])
    .map((item) => cleanText(objectRecord(item).value || objectRecord(item).segment || item))
    .filter(Boolean)
    .map((value) => ({ value }));
  const lanePayloads = lanes.map((lane, index) => {
    const issueCodes = rfxRequiredLaneIssues(lane);
    const rawPayload = { ...objectRecord(lane.raw_payload), ...lane };
    return {
      lane_id: cleanText(lane.lane_id) || `L${index + 1}`,
      origin_text: firstCleanText(lane.origin_text, lane.origin, lane.origin_location),
      destination_text: firstCleanText(lane.destination_text, lane.destination, lane.destination_location),
      operating_segment: internalRfxSegment(lane.operating_segment),
      operation_type: internalRfxOperation(lane.operation_type),
      service_type: internalRfxService(lane.service_type),
      origin_name: firstCleanText(lane.origin_name, lane.origin_location, lane.origin_text),
      origin_address: cleanText(lane.origin_address),
      origin_city: cleanText(lane.origin_city),
      origin_state: cleanText(lane.origin_state),
      origin_country: cleanText(lane.origin_country),
      origin_postal_code: cleanText(lane.origin_postal_code),
      origin_contact_name: cleanText(lane.origin_shipper || lane.origin_contact_name),
      origin_contact_phone: cleanText(lane.origin_contact_phone),
      origin_contact_email: cleanText(lane.origin_contact_email),
      origin_hours: cleanText(lane.origin_service_window || lane.origin_hours),
      origin_handling_type: cleanText(lane.origin_load_type || lane.origin_handling_type),
      origin_appointment_required: lane.origin_appointment_required === true,
      origin_average_time_hours: cleanNumber(lane.origin_average_time_hours),
      origin_site_restrictions: cleanText(lane.origin_site_restrictions),
      destination_name: firstCleanText(lane.destination_name, lane.destination_location, lane.destination_text),
      destination_address: cleanText(lane.destination_address),
      destination_city: cleanText(lane.destination_city),
      destination_state: cleanText(lane.destination_state),
      destination_country: cleanText(lane.destination_country),
      destination_postal_code: cleanText(lane.destination_postal_code),
      destination_contact_name: cleanText(lane.destination_consignee || lane.destination_contact_name),
      destination_contact_phone: cleanText(lane.destination_contact_phone),
      destination_contact_email: cleanText(lane.destination_contact_email),
      destination_hours: cleanText(lane.destination_service_window || lane.destination_hours),
      destination_handling_type: cleanText(lane.destination_unload_type || lane.destination_handling_type),
      destination_appointment_required: lane.destination_appointment_required === true,
      destination_average_time_hours: cleanNumber(lane.destination_average_time_hours),
      destination_site_restrictions: cleanText(lane.destination_site_restrictions),
      equipment_type: firstCleanText(lane.equipment_type, lane.truck_type),
      trailer_requirements: cleanText(lane.trailer_requirements),
      config: cleanText(lane.config),
      commodity: cleanText(lane.commodity || lane.product),
      hazmat: lane.hazmat === true,
      temperature_controlled: lane.temperature_controlled === true,
      cargo_value: cleanNumber(lane.cargo_value),
      cargo_value_currency: cleanText(lane.cargo_value_currency),
      weight: cleanNumber(lane.weight),
      pallets: cleanNumber(lane.pallets),
      dimensions: cleanText(lane.average_cubic_meters || lane.dimensions),
      weekly_volume: cleanNumber(lane.weekly_volume),
      monthly_volume: cleanNumber(lane.monthly_volume),
      annual_volume: cleanNumber(lane.last_annual_volume || lane.annual_volume),
      frequency: cleanText(lane.frequency),
      pickup_lead_time_hours: cleanNumber(lane.pickup_lead_time_hours || lane.positioning_lead_time),
      expected_transit_time_hours: cleanNumber(lane.expected_transit_time_hours),
      transit_days: cleanNumber(lane.transit_days),
      target_rate: cleanNumber(lane.target_rate),
      current_rate: cleanNumber(lane.current_rate),
      currency: cleanText(lane.currency) || "USD",
      seasonality_notes: cleanText(lane.seasonality_notes),
      special_requirements: cleanText(lane.special_requirements || lane.service_specifications),
      logistics_model: cleanText(lane.logistics_model),
      operation_criteria: cleanText(lane.operation_criteria),
      business_rules: cleanText(lane.business_rules),
      service_specifications: cleanText(lane.service_specifications),
      carrier_requirements: cleanText(lane.carrier_requirements),
      other_notes: cleanText(lane.other_notes),
      attachment_links: cleanText(lane.attachment_links),
      notes: cleanText(lane.notes),
      raw_payload: rawPayload,
      validation_issues: issueCodes.map((issue) => ({ issue })),
      completeness_score: completenessScoreFromIssues(4, issueCodes.length)
    };
  });
  const issueCount = lanePayloads.reduce((sum, lane) => sum + lane.validation_issues.length, 0);
  // Internal procurement edits do not invalidate the customer's submitted RFI.
  // Keeping the submitted state lets the existing Demand Snapshot workflow continue.
  const submissionStatus = cleanText(existing.data?.status) || "draft";
  const submissionRow = withOwner({
    project_id: project.id,
    magic_link_id: existing.data?.magic_link_id || null,
    status: submissionStatus,
    account_overview: objectRecord(rfi.account_overview),
    operating_segments: segmentValues,
    segment_checklists: Array.isArray(rfi.segment_checklists) ? rfi.segment_checklists : (existing.data?.segment_checklists || []),
    logistics_models: objectRecord(rfi.logistics_models || existing.data?.logistics_models),
    operational_criteria: objectRecord(rfi.operational_criteria || existing.data?.operational_criteria),
    business_rules: objectRecord(rfi.business_rules || existing.data?.business_rules),
    service_requirements: objectRecord(rfi.service_requirements || existing.data?.service_requirements),
    carrier_requirements: objectRecord(rfi.carrier_requirements || existing.data?.carrier_requirements),
    crossborder_details: objectRecord(rfi.crossborder_details || existing.data?.crossborder_details),
    notes_exceptions: objectRecord(rfi.notes_exceptions || existing.data?.notes_exceptions),
    attachments: Array.isArray(rfi.attachments) ? rfi.attachments : (existing.data?.attachments || []),
    response: existing.data?.response || {},
    frozen_snapshot: existing.data?.frozen_snapshot || {},
    completeness_score: completenessScoreFromIssues(Math.max(lanePayloads.length * 4, 1), issueCount),
    submitted_at: existing.data?.submitted_at || null,
    reopened_at: existing.data?.reopened_at || null,
    updated_at: now
  }, user);
  const submissionResult = existing.data?.id
    ? await supabase.from("rfx_rfi_submissions").update(submissionRow).eq("id", existing.data.id).select().single()
    : await supabase.from("rfx_rfi_submissions").insert(submissionRow).select().single();
  if (submissionResult.error) throw submissionResult.error;
  const submissionId = submissionResult.data.id;
  const deletes = await Promise.all([
    supabase.from("rfx_rfi_lanes").delete().eq("project_id", project.id).eq("submission_id", submissionId),
    supabase.from("rfx_rfi_origins").delete().eq("project_id", project.id).eq("submission_id", submissionId),
    supabase.from("rfx_rfi_destinations").delete().eq("project_id", project.id).eq("submission_id", submissionId)
  ]);
  for (const result of deletes) if (result.error) throw result.error;
  const originRows = lanePayloads.map((lane, index) => withOwner({ project_id: project.id, submission_id: submissionId, origin_key: lane.lane_id || `O${index + 1}`, name: lane.origin_text }, user));
  const destinationRows = lanePayloads.map((lane, index) => withOwner({ project_id: project.id, submission_id: submissionId, destination_key: lane.lane_id || `D${index + 1}`, name: lane.destination_text }, user));
  const origins = originRows.length ? await supabase.from("rfx_rfi_origins").insert(originRows).select("id,origin_key") : { data: [], error: null };
  const destinations = destinationRows.length ? await supabase.from("rfx_rfi_destinations").insert(destinationRows).select("id,destination_key") : { data: [], error: null };
  if (origins.error) throw origins.error;
  if (destinations.error) throw destinations.error;
  const originIds = new Map((origins.data || []).map((row) => [cleanText(row.origin_key), row.id]));
  const destinationIds = new Map((destinations.data || []).map((row) => [cleanText(row.destination_key), row.id]));
  const laneRows = lanePayloads.map((lane) => withOwner({
    ...lane,
    project_id: project.id,
    submission_id: submissionId,
    origin_id: originIds.get(lane.lane_id) || null,
    destination_id: destinationIds.get(lane.lane_id) || null
  }, user));
  if (laneRows.length) {
    const insert = await supabase.from("rfx_rfi_lanes").insert(laneRows);
    if (insert.error) throw insert.error;
  }
  const currentProjectStatus = cleanText(project.status) || "draft";
  const nextProjectStatus = ["draft", "rfi_sent", "rfi_in_progress", "rfi_submitted"].includes(currentProjectStatus) ? "rfi_in_progress" : currentProjectStatus;
  await supabase.from("rfx_projects").update({ status: nextProjectStatus, updated_at: now }).eq("id", project.id).eq("owner_email", user.owner_email);
  await writeRfxProcessAudit(supabase, user, project.id, "rfi_updated_in_procurement_design", "rfx_rfi_submissions", submissionId, `Updated Customer RFI in Procurement Design`, { lanes: laneRows.length, issue_count: issueCount });
  return { saved: true, row: submissionResult.data, lanes: laneRows.length, validation_issues: issueCount, completeness_score: submissionResult.data.completeness_score };
}

async function getRfxProcessProjectDetail(supabase: RatewareSupabaseClient, user: { owner_email: string | null }, projectId: unknown, appOrigin?: unknown) {
  const project = await requireOwnedRfxProcessProject(supabase, user, projectId);
  const [
    magicLinks,
    submission,
    origins,
    destinations,
    lanes,
    businessRules,
    serviceRequirements,
    carrierRequirements,
    crossborderDetails,
    attachments,
    exceptionNotes,
    snapshots,
    packages,
    awards,
    audit
  ] = await Promise.all([
    supabase.from("rfx_rfi_magic_links").select("id,status,expires_at,revoked_at,last_viewed_at,submitted_at,created_at,token_encrypted").eq("project_id", project.id).order("created_at", { ascending: false }).limit(10),
    supabase.from("rfx_rfi_submissions").select("*").eq("project_id", project.id).maybeSingle(),
    supabase.from("rfx_rfi_origins").select("*").eq("project_id", project.id).order("created_at", { ascending: true }),
    supabase.from("rfx_rfi_destinations").select("*").eq("project_id", project.id).order("created_at", { ascending: true }),
    supabase.from("rfx_rfi_lanes").select("*").eq("project_id", project.id).order("created_at", { ascending: true }),
    supabase.from("rfx_rfi_business_rules").select("*").eq("project_id", project.id).order("created_at", { ascending: true }),
    supabase.from("rfx_rfi_service_requirements").select("*").eq("project_id", project.id).order("created_at", { ascending: true }),
    supabase.from("rfx_rfi_carrier_requirements").select("*").eq("project_id", project.id).order("created_at", { ascending: true }),
    supabase.from("rfx_rfi_crossborder_details").select("*").eq("project_id", project.id).order("created_at", { ascending: true }),
    supabase.from("rfx_rfi_attachments").select("*").eq("project_id", project.id).order("created_at", { ascending: true }),
    supabase.from("rfx_rfi_exception_notes").select("*").eq("project_id", project.id).order("created_at", { ascending: true }),
    supabase.from("rfx_demand_snapshots").select("*, rfx_demand_lanes(*)").eq("project_id", project.id).order("created_at", { ascending: false }),
    supabase.from("rfx_packages").select("*, rfx_package_lanes(*), rfx_package_segments(*)").eq("project_id", project.id).order("created_at", { ascending: false }),
    supabase.from("rfx_award_packages").select("*, rfx_award_package_lanes(*)").eq("project_id", project.id).order("created_at", { ascending: false }),
    supabase.from("rfx_process_audit").select("*").eq("project_id", project.id).order("created_at", { ascending: false }).limit(100)
  ]);
  for (const result of [magicLinks, submission, origins, destinations, lanes, businessRules, serviceRequirements, carrierRequirements, crossborderDetails, attachments, exceptionNotes, snapshots, packages, awards, audit]) {
    if (result.error) throw result.error;
  }
  const visibleMagicLinks = await Promise.all((magicLinks.data || []).map(async (link) => {
    let linkUrl: string | null = null;
    if (cleanText(link.token_encrypted)) {
      try {
        const token = await decryptRfxMagicLinkToken(link.token_encrypted);
        if (token) linkUrl = rfxProjectPublicLink(token, appOrigin);
      } catch (error) {
        console.error("Could not recover Customer RFI link token", error);
      }
    }
    const { token_encrypted: _tokenEncrypted, ...safeLink } = link;
    return { ...safeLink, link: linkUrl, recoverable: Boolean(linkUrl) };
  }));
  return {
    project,
    magic_links: visibleMagicLinks,
    rfi_submission: submission.data || null,
    origins: origins.data || [],
    destinations: destinations.data || [],
    lanes: lanes.data || [],
    business_rules: businessRules.data || [],
    service_requirements: serviceRequirements.data || [],
    carrier_requirements: carrierRequirements.data || [],
    crossborder_details: crossborderDetails.data || [],
    attachments: attachments.data || [],
    exception_notes: exceptionNotes.data || [],
    demand_snapshots: snapshots.data || [],
    packages: packages.data || [],
    award_packages: awards.data || [],
    audit: audit.data || []
  };
}

async function createRfxRfiMagicLink(supabase: RatewareSupabaseClient, user: { owner_user_id: string | null; owner_email: string | null }, input: Record<string, unknown>) {
  const project = await requireOwnedRfxProcessProject(supabase, user, input.project_id || input.id);
  const now = new Date().toISOString();
  const existing = await supabase
    .from("rfx_rfi_magic_links")
    .select("id,status,expires_at,created_at,token_encrypted")
    .eq("project_id", project.id)
    .eq("status", "active")
    .gt("expires_at", now)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (existing.error) throw existing.error;
  if (existing.data) {
    const recoveredToken = await decryptRfxMagicLinkToken(existing.data.token_encrypted);
    return {
      reused: true,
      row: { id: existing.data.id, status: existing.data.status, expires_at: existing.data.expires_at, created_at: existing.data.created_at },
      link: recoveredToken ? rfxProjectPublicLink(recoveredToken, input.app_origin || input.appOrigin) : null,
      recoverable: Boolean(recoveredToken),
      message: recoveredToken
        ? "The active Customer RFI link is still valid."
        : "This legacy Customer RFI link cannot be displayed because its original token was not retained. Revoke it once to issue a fixed, copyable link."
    };
  }
  const token = rfxMagicToken();
  const tokenHash = await hashRfxMagicToken(token);
  const days = Math.min(Math.max(Number(input.expires_in_days || input.expiresInDays) || 14, 1), 90);
  const row = withOwner({
    project_id: project.id,
    token_hash: tokenHash,
    token_encrypted: await encryptRfxMagicLinkToken(token),
    expires_at: new Date(Date.now() + days * 24 * 60 * 60 * 1000).toISOString(),
    metadata: {
      customer_email: project.customer_contact_email || null,
      generated_from: "rfx_process"
    }
  }, user);
  const result = await supabase.from("rfx_rfi_magic_links").insert(row).select("id,status,expires_at,created_at").single();
  if (result.error) throw result.error;
  await supabase
    .from("rfx_projects")
    .update({ status: "rfi_sent", updated_at: new Date().toISOString() })
    .eq("id", project.id)
    .eq("owner_email", user.owner_email);
  const link = rfxProjectPublicLink(token, input.app_origin || input.appOrigin);
  await writeRfxProcessAudit(supabase, user, project.id, "rfi_magic_link_sent", "rfx_rfi_magic_links", result.data.id, `Generated Customer RFI magic link for ${project.title}`, { expires_at: result.data.expires_at });
  return { row: result.data, token, link };
}

async function createRfxDemandSnapshot(supabase: RatewareSupabaseClient, user: { owner_user_id: string | null; owner_email: string | null }, input: Record<string, unknown>) {
  const project = await requireOwnedRfxProcessProject(supabase, user, input.project_id || input.id);
  const submissionResult = await supabase
    .from("rfx_rfi_submissions")
    .select("*")
    .eq("project_id", project.id)
    .eq("status", "submitted")
    .maybeSingle();
  if (submissionResult.error) throw submissionResult.error;
  const submission = submissionResult.data as Record<string, unknown> | null;
  if (!submission) throw new Error("Customer RFI must be submitted before creating a Demand Snapshot.");

  const lanesResult = await supabase
    .from("rfx_rfi_lanes")
    .select("*, rfx_rfi_origins(*), rfx_rfi_destinations(*)")
    .eq("project_id", project.id)
    .order("created_at", { ascending: true });
  if (lanesResult.error) throw lanesResult.error;
  const lanes = (lanesResult.data || []) as Record<string, unknown>[];
  if (!lanes.length) throw new Error("No RFI lanes were found to normalize.");
  const laneIssues = lanes.flatMap((lane) => rfxRequiredLaneIssues(lane));
  const completeness = completenessScoreFromIssues(Math.max(lanes.length * 5, 1), laneIssues.length);
  const snapshotRow = withOwner({
    project_id: project.id,
    rfi_submission_id: submission.id,
    name: cleanText(input.name) || `Demand Snapshot ${new Date().toISOString().slice(0, 10)}`,
    status: cleanOptionalBoolean(input.locked) === true ? "locked" : "draft",
    completeness_score: completeness,
    validation_issues: laneIssues.map((issue) => ({ issue })),
    frozen_rfi_snapshot: submission.frozen_snapshot || submission.response || {},
    metadata: { created_from: "submitted_customer_rfi" }
  }, user);
  const snapshotInsert = await supabase.from("rfx_demand_snapshots").insert(snapshotRow).select().single();
  if (snapshotInsert.error) throw snapshotInsert.error;

  const demandRows = lanes.map((lane, index) => {
    const origin = objectRecord(lane.rfx_rfi_origins);
    const destination = objectRecord(lane.rfx_rfi_destinations);
    const payload = objectRecord(lane.raw_payload);
    const normalizedPayload = {
      ...lane,
      ...payload,
      rfi_submission_segment_checklists: submission.segment_checklists || []
    };
    const issues = rfxRequiredLaneIssues(lane).map((issue) => ({ issue }));
    return withOwner({
      snapshot_id: snapshotInsert.data.id,
      project_id: project.id,
      source_rfi_lane_id: lane.id,
      lane_key: cleanText(lane.lane_id) || `L${index + 1}`,
      origin: firstCleanText(payload.origin_location, payload.origin_text, lane.origin_text, lane.origin_name, origin.name, [lane.origin_city || origin.city, lane.origin_state || origin.state].filter(Boolean).join(", ")),
      origin_city: firstCleanText(payload.origin_city, lane.origin_city, origin.city, String(payload.origin_location || "").split(",")[0]),
      origin_state: firstCleanText(payload.origin_state, lane.origin_state, origin.state),
      origin_country: firstCleanText(payload.origin_country, lane.origin_country, origin.country),
      origin_postal_code: firstCleanText(payload.origin_postal_code, lane.origin_postal_code, origin.postal_code),
      destination: firstCleanText(payload.destination_location, payload.destination_text, lane.destination_text, lane.destination_name, destination.name, [lane.destination_city || destination.city, lane.destination_state || destination.state].filter(Boolean).join(", ")),
      destination_city: firstCleanText(payload.destination_city, lane.destination_city, destination.city, String(payload.destination_location || "").split(",")[0]),
      destination_state: firstCleanText(payload.destination_state, lane.destination_state, destination.state),
      destination_country: firstCleanText(payload.destination_country, lane.destination_country, destination.country),
      destination_postal_code: firstCleanText(payload.destination_postal_code, lane.destination_postal_code, destination.postal_code),
      operating_segment: firstCleanText(payload.operating_segment, lane.operating_segment),
      operation_type: firstCleanText(payload.operation_type, lane.operation_type),
      service_type: firstCleanText(payload.service_type, lane.service_type),
      equipment_type: firstCleanText(payload.truck_type, lane.equipment_type),
      trailer_requirements: firstCleanText(payload.trailer_requirements, lane.trailer_requirements, payload.equipment_type),
      weekly_volume: cleanNumber(lane.weekly_volume),
      monthly_volume: cleanNumber(lane.monthly_volume) ?? (cleanNumber(payload.last_annual_volume || lane.annual_volume) === null ? null : Number(payload.last_annual_volume || lane.annual_volume) / 12),
      frequency: firstCleanText(payload.frequency, payload.scheduling_type, lane.frequency),
      currency: cleanText(lane.currency),
      target_rate: cleanNumber(lane.target_rate),
      current_rate: cleanNumber(lane.current_rate),
      internal_notes: firstCleanText(lane.notes, payload.notes, payload.service_specifications, lane.other_notes, payload.other_notes),
      validation_issues: issues,
      normalized_payload: normalizedPayload
    }, user);
  });
  for (const batch of chunkValues(demandRows, 500)) {
    const insert = await supabase.from("rfx_demand_lanes").insert(batch).select("id");
    if (insert.error) throw insert.error;
  }
  await supabase
    .from("rfx_projects")
    .update({ status: "demand_review", updated_at: new Date().toISOString() })
    .eq("id", project.id)
    .eq("owner_email", user.owner_email);
  await writeRfxProcessAudit(supabase, user, project.id, "demand_snapshot_created", "rfx_demand_snapshots", snapshotInsert.data.id, `Created Demand Snapshot with ${demandRows.length} lane(s)`, { completeness_score: completeness, issue_count: laneIssues.length });
  return { row: snapshotInsert.data, lanes: demandRows.length, validation_issues: laneIssues };
}

async function createRfxProcessPackage(supabase: RatewareSupabaseClient, user: { owner_user_id: string | null; owner_email: string | null }, input: Record<string, unknown>) {
  const project = await requireOwnedRfxProcessProject(supabase, user, input.project_id || input.id);
  const snapshotId = cleanText(input.demand_snapshot_id || input.snapshot_id);
  if (!snapshotId) throw new Error("Demand Snapshot id is required.");
  const snapshotResult = await supabase
    .from("rfx_demand_snapshots")
    .select("*, rfx_demand_lanes(*)")
    .eq("id", snapshotId)
    .eq("project_id", project.id)
    .single();
  if (snapshotResult.error) throw snapshotResult.error;
  const lanes = Array.isArray(snapshotResult.data.rfx_demand_lanes) ? snapshotResult.data.rfx_demand_lanes as Record<string, unknown>[] : [];
  if (!lanes.length) throw new Error("Demand Snapshot has no lanes.");
  const hasIssues = lanes.some((lane) => Array.isArray(lane.validation_issues) && lane.validation_issues.length);
  if (hasIssues) throw new Error("Resolve Demand Snapshot validation issues before creating an RFx Package.");
  const strategy = cleanText(input.sourcing_strategy || input.sourcingStrategy)?.toLowerCase() || "closed_bid";
  const pricing = cleanText(input.pricing_structure || input.pricingStructure)?.toLowerCase() || "all_in";
  const weights = rfxPackageWeights(input);
  const packageRow = withOwner({
    project_id: project.id,
    demand_snapshot_id: snapshotId,
    name: cleanText(input.name) || `${project.title} sourcing package`,
    status: cleanOptionalBoolean(input.locked) === true ? "locked" : "draft",
    sourcing_strategy: ["open_bid", "closed_bid", "semi_controlled", "direct_award", "csa_contract", "dedicated_capacity"].includes(strategy) ? strategy : "closed_bid",
    pricing_structure: ["all_in", "linehaul_plus_fuel", "linehaul_plus_accessorials", "detailed_breakdown"].includes(pricing) ? pricing : "all_in",
    ...weights,
    carrier_eligibility_rules: objectRecord(input.carrier_eligibility_rules || input.carrierEligibilityRules),
    accessorial_template: objectRecord(input.accessorial_template || input.accessorialTemplate),
    rate_guidance: objectRecord(input.rate_guidance || input.rateGuidance),
    bid_due_at: cleanTimestamp(input.bid_due_at || input.bidDueAt),
    bid_validity_days: cleanNumber(input.bid_validity_days || input.bidValidityDays),
    locked_at: cleanOptionalBoolean(input.locked) === true ? new Date().toISOString() : null,
    notes: cleanText(input.notes)
  }, user);
  const packageInsert = await supabase.from("rfx_packages").insert(packageRow).select().single();
  if (packageInsert.error) throw packageInsert.error;
  const laneIds = normalizeBulkIds(input.demand_lane_ids || input.lane_ids || lanes.map((lane) => lane.id), { label: "Demand lane ids", limit: 1000 });
  const laneRows = lanes
    .filter((lane) => laneIds.includes(String(lane.id)))
    .map((lane) => withOwner({ package_id: packageInsert.data.id, demand_lane_id: lane.id, lot_name: cleanText(input.lot_name || input.lotName) }, user));
  for (const batch of chunkValues(laneRows, 500)) {
    const insert = await supabase.from("rfx_package_lanes").insert(batch).select("id");
    if (insert.error) throw insert.error;
  }
  const selectedLanes = lanes.filter((lane) => laneIds.includes(String(lane.id)));
  const segmentRows = buildRfxPackageSegments(packageInsert.data.id, selectedLanes, user);
  for (const batch of chunkValues(segmentRows, 250)) {
    const insert = await supabase.from("rfx_package_segments").upsert(batch, { onConflict: "package_id,segment_key" }).select("id");
    if (insert.error) throw insert.error;
  }
  await supabase
    .from("rfx_projects")
    .update({ status: "rfx_design", updated_at: new Date().toISOString() })
    .eq("id", project.id)
    .eq("owner_email", user.owner_email);
  const projectId = cleanText(project.id) || "";
  const shipperContexts = await getRatebookShipperContexts(supabase, user, [projectId]);
  const ratebook = await upsertRatebookForPackage(supabase, user, {
    pack: packageInsert.data as Record<string, unknown>,
    project,
    package_lanes: laneRows,
    package_segments: segmentRows,
    shipper: shipperContexts.get(projectId)
  });
  await writeRfxProcessAudit(supabase, user, project.id, "rfx_package_created", "rfx_packages", packageInsert.data.id, `Created RFx sourcing package with ${laneRows.length} lane(s) and ${segmentRows.length} segment(s)`, { weights, sourcing_strategy: packageRow.sourcing_strategy, segments: segmentRows.length });
  return { row: { ...packageInsert.data, rfx_package_segments: segmentRows }, ratebook, lanes: laneRows.length, segments: segmentRows.length };
}

async function launchRfxProcessPackageToBidRoom(supabase: RatewareSupabaseClient, user: { owner_user_id: string | null; owner_email: string | null }, input: Record<string, unknown>) {
  const packageId = cleanText(input.package_id || input.id);
  if (!packageId) throw new Error("RFx Package id is required.");
  const packageResult = await supabase
    .from("rfx_packages")
    .select("*, rfx_projects(*), rfx_package_lanes(*, rfx_demand_lanes(*)), rfx_package_segments(*)")
    .eq("id", packageId)
    .eq("owner_email", user.owner_email)
    .single();
  if (packageResult.error) throw packageResult.error;
  const pack = packageResult.data as Record<string, unknown>;
  if (pack.linked_rfx_event_id) return { launched: false, rfx_event_id: pack.linked_rfx_event_id, message: "RFx Package is already linked to a Bid Room." };
  const project = objectRecord(pack.rfx_projects);
  const packageLanes = Array.isArray(pack.rfx_package_lanes) ? pack.rfx_package_lanes as Record<string, unknown>[] : [];
  if (!packageLanes.length) throw new Error("RFx Package has no lanes to launch.");
  const demandLanes = packageLanes.map((packageLane) => objectRecord(packageLane.rfx_demand_lanes)).filter((lane) => cleanText(lane.id));
  let segmentRows = Array.isArray(pack.rfx_package_segments) ? pack.rfx_package_segments as Record<string, unknown>[] : [];
  if (!segmentRows.length) {
    segmentRows = buildRfxPackageSegments(pack.id, demandLanes, user);
    for (const batch of chunkValues(segmentRows, 250)) {
      const insert = await supabase.from("rfx_package_segments").upsert(batch, { onConflict: "package_id,segment_key" }).select("id");
      if (insert.error) throw insert.error;
    }
  }
  const segmentByKey = new Map(segmentRows.map((segment) => [cleanText(segment.segment_key), segment]));

  const rfxId = cleanText(input.rfx_id || input.rfxId) || `RFx-${new Date().toISOString().slice(5, 10).replace("-", "")}-${String(project.title || "Project").replace(/[^a-z0-9]+/gi, "").slice(0, 8)}`;
  const eventRow = withOwner({
    ...normalizeRfxEvent({
      rfx_id: rfxId,
      name: cleanText(input.name) || project.title || pack.name,
      customer: project.customer_name,
      event_type: "rfx",
      status: cleanText(input.open_now || input.status) === "open" || cleanOptionalBoolean(input.open_now) === true ? "open" : "draft",
      due_date: input.due_date || pack.bid_due_at || project.due_date,
      notes: `Launched from RFx Process package ${pack.name || pack.id}. Target buy rates remain internal in RFx Package guidance.`
    }),
    source_rfx_process_project_id: project.id,
    source_rfx_package_id: pack.id,
    source_rfx_package_name: cleanText(pack.name),
    rfx_master_package: rfxMasterPackagePayload(pack, project, segmentRows, packageLanes.length)
  }, user);
  const eventInsert = await supabase.from("rfx_events").insert(eventRow).select().single();
  if (eventInsert.error) throw eventInsert.error;

  const laneRows = packageLanes.map((packageLane, index) => {
    const lane = objectRecord(packageLane.rfx_demand_lanes);
    const segmentKey = rfxSegmentKeyForDemandLane(lane);
    const segment = objectRecord(segmentByKey.get(segmentKey));
    return {
      rfx_event_id: eventInsert.data.id,
      source_rfx_demand_lane_id: cleanText(lane.id),
      lane_number: index + 1,
      origin: cleanText(lane.origin),
      origin_city: cleanText(lane.origin_city),
      origin_state: cleanText(lane.origin_state),
      origin_country: cleanText(lane.origin_country),
      origin_market: cleanText(objectRecord(lane.normalized_payload).origin_market),
      origin_region: cleanText(objectRecord(lane.normalized_payload).origin_region),
      destination: cleanText(lane.destination),
      destination_city: cleanText(lane.destination_city),
      destination_state: cleanText(lane.destination_state),
      destination_country: cleanText(lane.destination_country),
      destination_market: cleanText(objectRecord(lane.normalized_payload).destination_market),
      destination_region: cleanText(objectRecord(lane.normalized_payload).destination_region),
      equipment: cleanText(lane.equipment_type),
      trailer: cleanText(lane.trailer_requirements),
      config: cleanText(objectRecord(lane.normalized_payload).config),
      operation: cleanText(lane.operation_type),
      service: cleanText(lane.service_type),
      rfx_segment_key: segmentKey,
      rfx_segment_name: cleanText(segment.segment_name) || rfxSegmentNameForDemandLane(lane),
      weekly_volume: cleanNumber(lane.weekly_volume),
      annual_volume: cleanNumber(lane.monthly_volume) === null ? null : Number(lane.monthly_volume) * 12,
      target_rate: null,
      currency: cleanText(lane.currency) || "USD",
      logistics_model: firstCleanText(rfxDemandLaneDetail(lane, "logistics_model"), segment.logistics_model),
      operation_criteria: firstCleanText(rfxDemandLaneDetail(lane, "operation_criteria"), segment.operation_criteria),
      business_rules: firstCleanText(rfxDemandLaneDetail(lane, "business_rules"), segment.business_rules),
      service_specifications: firstCleanText(rfxDemandLaneDetail(lane, "service_specifications"), segment.service_specifications),
      carrier_requirements: firstCleanText(rfxDemandLaneDetail(lane, "carrier_requirements"), segment.carrier_requirements),
      other_notes: firstCleanText(rfxDemandLaneDetail(lane, "other_notes"), segment.other_notes),
      notes: cleanText(lane.internal_notes)
    };
  });
  for (const batch of chunkValues(laneRows, 500)) {
    const insert = await supabase.from("rfx_lanes").insert(batch).select("id");
    if (insert.error) throw insert.error;
  }
  await Promise.all([
    supabase.from("rfx_packages").update({ linked_rfx_event_id: eventInsert.data.id, status: "launched", updated_at: new Date().toISOString() }).eq("id", pack.id),
    supabase.from("rfx_projects").update({ linked_rfx_event_id: eventInsert.data.id, status: "bid_room_open", updated_at: new Date().toISOString() }).eq("id", project.id)
  ]);
  const projectId = cleanText(project.id);
  if (!projectId) throw new Error("The RFx project is missing its identifier.");
  const shipperContexts = await getRatebookShipperContexts(supabase, user, [projectId]);
  const ratebook = await upsertRatebookForPackage(supabase, user, {
    pack: { ...pack, linked_rfx_event_id: eventInsert.data.id, status: "launched" },
    project,
    package_lanes: packageLanes,
    package_segments: segmentRows,
    shipper: shipperContexts.get(projectId)
  });
  await writeRfxProcessAudit(supabase, user, project.id, "bid_room_launched", "rfx_events", eventInsert.data.id, `Launched Bid Room from RFx Package ${pack.name || ""}`.trim(), { package_id: pack.id, lanes: laneRows.length, segments: segmentRows.length });
  return { launched: true, rfx_event_id: eventInsert.data.id, row: eventInsert.data, ratebook, lanes: laneRows.length, segments: segmentRows.length };
}

function ratebookOrigin(input: Record<string, unknown>) {
  return (cleanUrl(input.app_origin || input.appOrigin || input.origin) || Deno.env.get("RATEWARE_PUBLIC_APP_URL") || "https://rateware.vercel.app").replace(/\/$/, "");
}

function ratebookStatusForPackage(pack: Record<string, unknown>) {
  if (cleanText(pack.status)?.toLowerCase() === "archived") return "archived";
  if (cleanText(pack.linked_rfx_event_id)) return "shared";
  if (cleanText(pack.status)?.toLowerCase() === "locked") return "ready";
  return "draft";
}

const RATEBOOK_SOURCE_TYPES = new Set(["rfi", "rfx", "spot", "bid_room"]);
const RATEBOOK_LIFECYCLE_STATUSES = new Set(["draft", "published", "superseded", "archived"]);

function ratebookSourceType(project: Record<string, unknown>, pack: Record<string, unknown>) {
  const metadata = objectRecord(project.metadata);
  const source = cleanText(pack.source_type || project.source_type || metadata.source_type || metadata.source)?.toLowerCase();
  if (source === "bid" || source === "bidroom" || source === "bid_room") return "bid_room";
  if (source && RATEBOOK_SOURCE_TYPES.has(source)) return source;
  const linkedEventId = cleanText(pack.linked_rfx_event_id);
  const projectStatus = cleanText(project.status)?.toLowerCase() || "";
  if (linkedEventId && (projectStatus.includes("bid_room") || projectStatus.includes("bid"))) return "bid_room";
  return "rfx";
}

function ratebookLifecycleStatus(value: unknown, fallback = "draft") {
  const normalized = cleanText(value)?.toLowerCase();
  return normalized && RATEBOOK_LIFECYCLE_STATUSES.has(normalized) ? normalized : fallback;
}

function ratebookLegacyStatus(lifecycle: string, pack: Record<string, unknown>, existingStatus?: unknown) {
  if (lifecycle === "archived" || lifecycle === "superseded") return "archived";
  if (lifecycle === "draft") return "draft";
  if (cleanText(existingStatus)?.toLowerCase() === "shared" || cleanText(pack.linked_rfx_event_id)) return "shared";
  return "ready";
}

function ratebookSourceFingerprint(project: Record<string, unknown>, pack: Record<string, unknown>, sourceType: string) {
  return `${sourceType}:${cleanText(project.id) || "project"}:${cleanText(pack.id) || "package"}`;
}

function ratebookSourceSnapshot(
  project: Record<string, unknown>,
  pack: Record<string, unknown>,
  packageLanes: Record<string, unknown>[],
  packageSegments: Record<string, unknown>[] = []
) {
  const lanes = packageLanes.map((packageLane) => {
    const demand = objectRecord(packageLane.rfx_demand_lanes);
    return {
      id: cleanText(packageLane.id),
      demand_id: cleanText(demand.id || packageLane.demand_lane_id),
      lane_key: cleanText(demand.lane_key),
      origin: firstCleanText(demand.origin, [demand.origin_city, demand.origin_state].filter(Boolean).join(", ")),
      destination: firstCleanText(demand.destination, [demand.destination_city, demand.destination_state].filter(Boolean).join(", ")),
      origin_zip: cleanText(demand.origin_zip),
      destination_zip: cleanText(demand.destination_zip),
      equipment: cleanText(demand.equipment_type),
      trailer: cleanText(demand.trailer_requirements),
      config: cleanText(demand.configuration_type),
      operation: cleanText(demand.operation_type),
      service: cleanText(demand.service_type),
      weekly_volume: cleanText(demand.weekly_volume),
      frequency: cleanText(demand.frequency),
      target_rate: cleanText(demand.target_rate),
      currency: cleanText(demand.currency),
      segment_key: firstCleanText(demand.rfx_segment_key, demand.operating_segment)
    };
  }).sort((left, right) => `${left.lane_key}|${left.id}`.localeCompare(`${right.lane_key}|${right.id}`));
  const segments = packageSegments.map((segment) => ({
    id: cleanText(segment.id),
    key: cleanText(segment.segment_key),
    name: firstCleanText(segment.segment_name, segment.name),
    operation: cleanText(segment.operation),
    service: cleanText(segment.service),
    equipment: cleanText(segment.equipment),
    trailer: cleanText(segment.trailer),
    checklist: Array.isArray(segment.checklist) ? segment.checklist : []
  })).sort((left, right) => `${left.key}|${left.id}`.localeCompare(`${right.key}|${right.id}`));
  return JSON.stringify({
    project: {
      id: cleanText(project.id), title: cleanText(project.title), customer_name: cleanText(project.customer_name),
      status: cleanText(project.status), due_date: cleanText(project.due_date)
    },
    package: {
      id: cleanText(pack.id), name: cleanText(pack.name), status: cleanText(pack.status),
      bid_due_at: cleanText(pack.bid_due_at), valid_from: cleanText(pack.valid_from), valid_until: cleanText(pack.valid_until)
    },
    lanes,
    segments
  });
}

function ratebookSourceFreshness(ratebook: Record<string, unknown>, currentSnapshotHash: string) {
  const storedSnapshotHash = cleanText(ratebook.source_snapshot_hash);
  if (!storedSnapshotHash) return "unknown";
  return storedSnapshotHash === currentSnapshotHash ? "current" : "outdated";
}

type RatebookShipperContext = {
  shipper_id: string | null;
  shipper_name: string | null;
  opportunity_name: string | null;
};

async function getRatebookShipperContexts(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  projectIds: string[]
) {
  const ids = Array.from(new Set(projectIds.map((id) => cleanText(id)).filter((id): id is string => Boolean(id))));
  const contexts = new Map<string | null, RatebookShipperContext>();
  if (!ids.length) return contexts;
  const [opportunitiesResult, projectsResult] = await Promise.all([
    supabase.from("shipper_opportunities")
      .select("rfx_project_id,shipper_id,opportunity_name")
      .eq("owner_email", user.owner_email)
      .in("rfx_project_id", ids),
    supabase.from("rfx_projects")
      .select("id,customer_id,customer_name,title")
      .eq("owner_email", user.owner_email)
      .in("id", ids)
  ]);
  if (opportunitiesResult.error) throw opportunitiesResult.error;
  if (projectsResult.error) throw projectsResult.error;
  const opportunities = (opportunitiesResult.data || []) as Record<string, unknown>[];
  const projects = (projectsResult.data || []) as Record<string, unknown>[];
  const shipperIds = Array.from(new Set([
    ...opportunities.map((row) => cleanText(row.shipper_id)),
    ...projects.map((row) => cleanText(row.customer_id))
  ].filter((id): id is string => Boolean(id))));
  const shipperById = new Map<string, Record<string, unknown>>();
  if (shipperIds.length) {
    const shippersResult = await supabase.from("shippers")
      .select("id,shipper_name,legal_name")
      .eq("owner_email", user.owner_email)
      .in("id", shipperIds);
    if (shippersResult.error) throw shippersResult.error;
    ((shippersResult.data || []) as Record<string, unknown>[]).forEach((shipper) => {
      const shipperId = cleanText(shipper.id);
      if (shipperId) shipperById.set(shipperId, shipper);
    });
  }
  opportunities.forEach((opportunity) => {
    const projectId = cleanText(opportunity.rfx_project_id);
    if (!projectId) return;
    const shipperId = cleanText(opportunity.shipper_id);
    const shipper = shipperId ? shipperById.get(shipperId) || {} : {};
    contexts.set(projectId, {
      shipper_id: shipperId,
      shipper_name: firstCleanText(shipper.shipper_name, shipper.legal_name) || null,
      opportunity_name: cleanText(opportunity.opportunity_name) || null
    });
  });
  projects.forEach((project) => {
    const projectId = cleanText(project.id);
    if (!projectId || contexts.has(projectId)) return;
    const shipperId = cleanText(project.customer_id);
    const shipper = shipperId ? shipperById.get(shipperId) || {} : {};
    contexts.set(projectId, {
      shipper_id: shipperId,
      shipper_name: firstCleanText(shipper.shipper_name, shipper.legal_name, project.customer_name) || null,
      opportunity_name: cleanText(project.title) || null
    });
  });
  return contexts;
}

async function getOwnedRatebookPackage(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  packageId: unknown
) {
  const id = cleanText(packageId);
  if (!id || !UUID_PATTERN.test(id)) throw new Error("A valid RFx Package id is required.");
  const packResult = await supabase.from("rfx_packages").select("*")
    .eq("id", id).eq("owner_email", user.owner_email).single();
  if (packResult.error) throw packResult.error;
  const pack = packResult.data as Record<string, unknown>;
  const [projectResult, packageLanes, packageSegments] = await Promise.all([
    supabase.from("rfx_projects").select("*")
      .eq("id", pack.project_id).eq("owner_email", user.owner_email).single(),
    fetchAllRatebookPackageRows(supabase, "rfx_package_lanes", [id], "*, rfx_demand_lanes(*)"),
    fetchAllRatebookPackageRows(supabase, "rfx_package_segments", [id], "*")
  ]);
  if (projectResult.error) throw projectResult.error;
  return {
    pack,
    project: projectResult.data as Record<string, unknown>,
    package_lanes: packageLanes.sort((left, right) => {
      const created = String(left.created_at || "").localeCompare(String(right.created_at || ""));
      return created || String(left.id || "").localeCompare(String(right.id || ""));
    }),
    package_segments: packageSegments.sort((left, right) => {
      const sortOrder = Number(left.sort_order || 0) - Number(right.sort_order || 0);
      return sortOrder || String(left.id || "").localeCompare(String(right.id || ""));
    })
  };
}

async function upsertRatebookForPackage(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null; organization_id?: string | null },
  packageContext: {
    pack: Record<string, unknown>;
    project: Record<string, unknown>;
    package_lanes: Record<string, unknown>[];
    package_segments?: Record<string, unknown>[];
    shipper?: RatebookShipperContext;
  }
) {
  const { pack, project, package_lanes: packageLanes, package_segments: packageSegments = [] } = packageContext;
  const sourceType = ratebookSourceType(project, pack);
  const sourceFingerprint = ratebookSourceFingerprint(project, pack, sourceType);
  const sourceSnapshotHash = await hashRatebookSourceSnapshot(ratebookSourceSnapshot(project, pack, packageLanes, packageSegments));
  const structuralRow: Record<string, unknown> = {
    ...withOwner({
      project_id: project.id,
      rfx_package_id: pack.id,
      rfx_event_id: cleanText(pack.linked_rfx_event_id) || null,
      name: firstCleanText(pack.name, project.title, "RFx Ratebook") || "RFx Ratebook",
      lane_count: packageLanes.length,
      shipper_id: packageContext.shipper?.shipper_id || null,
      shipper_name: packageContext.shipper?.shipper_name || cleanText(project.customer_name) || null,
      source_type: sourceType,
      source_reference: firstCleanText(packageContext.shipper?.opportunity_name, project.title, project.customer_name),
      source_fingerprint: sourceFingerprint,
      source_snapshot_hash: sourceSnapshotHash,
      metadata: {
        source: sourceType === "spot" || sourceType === "bid_room" ? "bid_room_event" : "rfx_process_package",
        source_type: sourceType,
        project_title: cleanText(project.title),
        customer_name: cleanText(project.customer_name),
        shipper_opportunity: packageContext.shipper?.opportunity_name || null,
        bid_due_at: cleanText(pack.bid_due_at)
      },
      updated_at: new Date().toISOString()
    }, user),
    organization_id: user.organization_id || null
  };
  const existingResult = await supabase.from("rfx_ratebooks").select("*")
    .eq("owner_email", user.owner_email).eq("rfx_package_id", pack.id)
    .order("version_number", { ascending: false }).limit(1).maybeSingle();
  if (existingResult.error) throw existingResult.error;
  const existing = existingResult.data as Record<string, unknown> | null;
  const existingLifecycle = ratebookLifecycleStatus(existing?.lifecycle_status);
  if (existing && existingLifecycle === "published") {
    const freshness = ratebookSourceFreshness(existing, sourceSnapshotHash);
    const now = new Date().toISOString();
    const publishedPatch = freshness === "unknown"
      ? {
        source_snapshot_hash: sourceSnapshotHash,
        metadata: { ...objectRecord(existing.metadata), source_snapshot_seeded_at: now },
        updated_at: now
      }
      : freshness === "outdated"
        ? {
          source_changed_at: existing.source_changed_at || now,
          metadata: { ...objectRecord(existing.metadata), source_change_detected_at: now, current_source_snapshot_hash: sourceSnapshotHash },
          updated_at: now
        }
        : null;
    if (!publishedPatch) return { ...existing, source_freshness: "current" };
    const preserved = await supabase.from("rfx_ratebooks").update(publishedPatch)
      .eq("id", existing.id).eq("owner_email", user.owner_email).select().single();
    if (preserved.error) throw preserved.error;
    return { ...(preserved.data as Record<string, unknown>), source_freshness: freshness === "unknown" ? "current" : "outdated" };
  }
  if (existing && (existingLifecycle === "archived" || existingLifecycle === "superseded")) {
    return existing;
  }
  const result = existing
    ? await supabase.from("rfx_ratebooks").update({
      ...structuralRow,
      source_changed_at: null,
      metadata: { ...objectRecord(existing.metadata), ...objectRecord(structuralRow.metadata) },
      status: ratebookLegacyStatus(existingLifecycle, pack, existing.status)
    }).eq("id", existing.id).eq("owner_email", user.owner_email).select().single()
    : await supabase.from("rfx_ratebooks").insert({
      ...structuralRow,
      status: ratebookStatusForPackage(pack),
      lifecycle_status: "draft",
      version_number: 1
    }).select().single();
  if (result.error) throw result.error;
  const ratebook = result.data as Record<string, unknown>;
  await syncRatebookSegments(supabase, user, ratebook, packageContext);
  return ratebook;
}

function fallbackRatebookSegments(packageLanes: Record<string, unknown>[]) {
  const grouped = new Map<string, Record<string, unknown>[]>();
  packageLanes.forEach((packageLane) => {
    const demand = objectRecord(packageLane.rfx_demand_lanes);
    const key = cleanText(demand.rfx_segment_key) || cleanText(demand.operating_segment) || "all_routes";
    const rows = grouped.get(key) || [];
    rows.push(packageLane);
    grouped.set(key, rows);
  });
  return Array.from(grouped.entries()).map(([segmentKey, rows], index) => {
    const firstDemand = objectRecord(rows[0]?.rfx_demand_lanes);
    return {
      id: null,
      segment_key: segmentKey,
      segment_name: firstCleanText(firstDemand.rfx_segment_name, firstDemand.operating_segment, "All routes") || "All routes",
      operation: cleanText(firstDemand.operation_type),
      service: cleanText(firstDemand.service_type),
      equipment: cleanText(firstDemand.equipment_type),
      trailer: cleanText(firstDemand.trailer_requirements),
      lane_count: rows.length,
      sort_order: index + 1
    };
  });
}

async function syncRatebookSegments(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null; organization_id?: string | null },
  ratebook: Record<string, unknown>,
  packageContext: { pack: Record<string, unknown>; project: Record<string, unknown>; package_lanes: Record<string, unknown>[]; package_segments?: Record<string, unknown>[] }
) {
  const sourceType = ratebookSourceType(packageContext.project, packageContext.pack);
  const segments = packageContext.package_segments?.length
    ? packageContext.package_segments
    : fallbackRatebookSegments(packageContext.package_lanes);
  if (!segments.length) return [];
  const now = new Date().toISOString();
  const rows: Record<string, unknown>[] = segments.map((segment, index) => {
    const segmentRow = objectRecord(segment);
    return {
    ...withOwner({
      ratebook_id: ratebook.id,
      source_package_segment_id: cleanText(segmentRow.id) || null,
      segment_key: cleanText(segmentRow.segment_key) || `segment_${index + 1}`,
      segment_name: firstCleanText(segmentRow.segment_name, segmentRow.name, "Operating segment") || "Operating segment",
      source_type: sourceType,
      operation: cleanText(segmentRow.operation),
      service: cleanText(segmentRow.service),
      equipment: cleanText(segmentRow.equipment),
      trailer: cleanText(segmentRow.trailer),
      lane_count: Number(segmentRow.lane_count || 0),
      valid_from: cleanText(ratebook.valid_from) || null,
      valid_until: cleanText(ratebook.valid_until) || null,
      metadata: {
        checklist_count: Array.isArray(segmentRow.checklist) ? segmentRow.checklist.length : 0,
        source_package_id: packageContext.pack.id,
        sort_order: Number(segmentRow.sort_order || index + 1)
      },
      updated_at: now
    }, user),
    organization_id: user.organization_id || null
    };
  });
  const existingResult = await supabase.from("rfx_ratebook_segments")
    .select("id,segment_key")
    .eq("ratebook_id", ratebook.id)
    .eq("owner_email", user.owner_email);
  if (existingResult.error) throw existingResult.error;
  const activeSegmentKeys = new Set(rows.map((row) => cleanText(row.segment_key)).filter((key): key is string => Boolean(key)));
  const staleSegmentIds = ((existingResult.data || []) as Record<string, unknown>[])
    .filter((segment) => {
      const segmentKey = cleanText(segment.segment_key);
      return !segmentKey || !activeSegmentKeys.has(segmentKey);
    })
    .map((segment) => cleanText(segment.id))
    .filter((id): id is string => Boolean(id));
  for (const batch of chunkValues(staleSegmentIds, 500)) {
    const staleDelete = await supabase.from("rfx_ratebook_segments")
      .delete()
      .eq("ratebook_id", ratebook.id)
      .eq("owner_email", user.owner_email)
      .in("id", batch);
    if (staleDelete.error) throw staleDelete.error;
  }
  const result = await supabase.from("rfx_ratebook_segments")
    .upsert(rows, { onConflict: "ratebook_id,segment_key" }).select("id,segment_key");
  if (result.error) throw result.error;
  return result.data || [];
}

async function requireOwnedRatebook(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  ratebookId: unknown
) {
  const id = cleanText(ratebookId);
  if (!id || !UUID_PATTERN.test(id)) throw new Error("A valid Ratebook id is required.");
  const result = await supabase.from("rfx_ratebooks").select("*")
    .eq("id", id).eq("owner_email", user.owner_email).single();
  if (result.error) throw result.error;
  return result.data as Record<string, unknown>;
}

async function listRatebooks(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null; organization_id?: string | null },
  input: Record<string, unknown>
) {
  const requestedPackageId = cleanText(input.package_id || input.rfx_package_id);
  const requestedProjectId = cleanText(input.project_id);
  const requestedShipperId = cleanText(input.shipper_id);
  const requestedSourceType = cleanText(input.source_type)?.toLowerCase();
  const requestedSegmentKey = cleanText(input.segment_key)?.toLowerCase();
  if (requestedPackageId && !UUID_PATTERN.test(requestedPackageId)) throw new Error("A valid RFx Package id is required.");
  if (requestedProjectId && !UUID_PATTERN.test(requestedProjectId)) throw new Error("A valid RFx Project id is required.");
  if (requestedShipperId && !UUID_PATTERN.test(requestedShipperId)) throw new Error("A valid Shipper id is required.");
  let bidRoomSync = emptyRatebookSyncSummary();
  if (input.skip_bid_room_sync !== true) {
    bidRoomSync = await syncBidRoomEventsForRatebookScope(supabase, user, input);
  }
  let packs: Record<string, unknown>[];
  let ownedRatebooksForScope: Record<string, unknown>[] | null = null;
  if (requestedShipperId) {
    const [linkedProjects, directlyLinkedRatebooks] = await Promise.all([
      fetchAllRfxProjectIdsForShipper(supabase, user.owner_email, requestedShipperId),
      fetchOwnedRfxRatebooksForShipper(supabase, user.owner_email, requestedShipperId)
    ]);
    const linkedProjectIds = linkedProjects.map((project) => cleanText(project.id)).filter((id): id is string => Boolean(id));
    const directlyLinkedPackageIds = directlyLinkedRatebooks
      .map((ratebook) => cleanText(ratebook.rfx_package_id))
      .filter((id): id is string => Boolean(id));
    packs = await fetchOwnedRfxPackagesForScope(
      supabase,
      user.owner_email,
      linkedProjectIds,
      directlyLinkedPackageIds
    );
    const linkedRatebooks = await fetchOwnedRfxRatebooksByPackageIds(
      supabase,
      user.owner_email,
      packs.map((pack) => cleanText(pack.id)).filter((id): id is string => Boolean(id))
    );
    const ratebookById = new Map<string, Record<string, unknown>>();
    [...directlyLinkedRatebooks, ...linkedRatebooks].forEach((ratebook) => {
      const ratebookId = cleanText(ratebook.id);
      if (ratebookId) ratebookById.set(ratebookId, ratebook);
    });
    ownedRatebooksForScope = Array.from(ratebookById.values());
  } else {
    packs = await fetchAllOwnedRfxPackages(supabase, user.owner_email);
  }
  if (requestedPackageId) packs = packs.filter((pack) => cleanText(pack.id) === requestedPackageId);
  if (requestedProjectId) packs = packs.filter((pack) => cleanText(pack.project_id) === requestedProjectId);
  if (!packs.length) return {
    rows: [],
    loaded: 0,
    total: 0,
    route_rows: input.include_routes === true ? [] : undefined,
    route_total: input.include_routes === true ? 0 : undefined,
    facets: { shippers: [], sources: [], segments: [] },
    sync: bidRoomSync
  };
  const projectIds = Array.from(new Set(packs.map((pack) => cleanText(pack.project_id)).filter((id): id is string => Boolean(id))));
  const packageIds = packs.map((pack) => cleanText(pack.id)).filter((id): id is string => Boolean(id));
  const [projectBatches, packageLaneRows, packageSegmentRows] = await Promise.all([
    mapWithConcurrency(chunkValues(projectIds, RATEBOOK_PACKAGE_QUERY_CHUNK_SIZE), RATEBOOK_SYNC_CONCURRENCY, async (projectIdChunk) => {
      const result = await supabase.from("rfx_projects").select("*").eq("owner_email", user.owner_email).in("id", projectIdChunk);
      if (result.error) throw result.error;
      return (result.data || []) as Record<string, unknown>[];
    }),
    fetchAllRatebookPackageRows(supabase, "rfx_package_lanes", packageIds, "package_id,id,demand_lane_id,rfx_demand_lanes(*)"),
    fetchAllRatebookPackageRows(supabase, "rfx_package_segments", packageIds, "*")
  ]);
  const projectRows = projectBatches.flat();
  const projectById = new Map<string, Record<string, unknown>>();
  projectRows.forEach((project) => {
    const projectId = cleanText(project.id);
    if (projectId) projectById.set(projectId, project);
  });
  const shipperContexts = await getRatebookShipperContexts(supabase, user, projectIds);
  const laneCountByPackage = new Map<string, number>();
  const lanesByPackage = new Map<string, Record<string, unknown>[]>();
  packageLaneRows.forEach((row) => {
    const key = cleanText(row.package_id);
    if (!key) return;
    laneCountByPackage.set(key, (laneCountByPackage.get(key) || 0) + 1);
    const lanes = lanesByPackage.get(key) || [];
    lanes.push(row);
    lanesByPackage.set(key, lanes);
  });
  const segmentsByPackage = new Map<string, Record<string, unknown>[]>();
  packageSegmentRows.forEach((segment) => {
    const key = cleanText(segment.package_id);
    if (!key) return;
    const rows = segmentsByPackage.get(key) || [];
    rows.push(segment);
    segmentsByPackage.set(key, rows);
  });
  const materializationOutcomes = input.skip_materialization === true ? [] : await mapWithConcurrency(packs, RATEBOOK_SYNC_CONCURRENCY, async (pack) => {
    const projectId = cleanText(pack.project_id);
    const packageId = cleanText(pack.id);
    if (!projectId || !packageId) return { package_id: packageId, ratebook: null as Record<string, unknown> | null, error: null as string | null };
    const project = projectById.get(projectId);
    if (!project) return { package_id: packageId, ratebook: null as Record<string, unknown> | null, error: "Ratebook source project is unavailable." };
    try {
      return {
        package_id: packageId,
        ratebook: await upsertRatebookForPackage(supabase, user, {
          pack,
          project,
          package_lanes: lanesByPackage.get(packageId) || [],
          package_segments: segmentsByPackage.get(packageId) || [],
          shipper: shipperContexts.get(cleanText(project.id))
        }),
        error: null as string | null
      };
    } catch (error) {
      return {
        package_id: packageId,
        ratebook: null as Record<string, unknown> | null,
        error: safeOperationalError(error) || "Ratebook materialization failed for this package."
      };
    }
  });
  const materializedRatebooks = materializationOutcomes
    .map((outcome) => outcome.ratebook)
    .filter((ratebook): ratebook is Record<string, unknown> => Boolean(ratebook));
  const packageIdSet = new Set(packageIds);
  const persistedRatebooks = (ownedRatebooksForScope || await fetchAllOwnedRfxRatebooks(supabase, user.owner_email))
    .filter((ratebook) => packageIdSet.has(cleanText(ratebook.rfx_package_id) || ""));
  const ratebookById = new Map<string, Record<string, unknown>>();
  // A read immediately after materialization can be temporarily incomplete. Keep the
  // just-materialized rows and let the persisted canonical row win when available.
  [...materializedRatebooks, ...persistedRatebooks].forEach((ratebook) => {
    const ratebookId = cleanText(ratebook.id);
    if (ratebookId) ratebookById.set(ratebookId, ratebook);
  });
  const ratebooks = Array.from(ratebookById.values());
  const ratebookIds = ratebooks.map((row) => cleanText(row.id)).filter((id): id is string => Boolean(id));
  const shareRows = await fetchAllRatebookShares(supabase, ratebookIds);
  const shareCountByRatebook = new Map<string, number>();
  shareRows.forEach((share) => {
    const key = cleanText(share.ratebook_id);
    if (!key) return;
    shareCountByRatebook.set(key, (shareCountByRatebook.get(key) || 0) + 1);
  });
  const search = cleanText(input.search)?.toLowerCase();
  const requestedStatus = cleanText(input.lifecycle_status || input.status)?.toLowerCase();
  const allRows: Record<string, unknown>[] = ratebooks.map((ratebook) => {
    const pack = packs.find((item) => cleanText(item.id) === cleanText(ratebook.rfx_package_id)) || {};
    const project = projectById.get(mapLookupKey(ratebook.project_id)) || {};
    const segments = (segmentsByPackage.get(mapLookupKey(pack.id)) || []).map((segment) => ({
      id: segment.id,
      segment_key: cleanText(segment.segment_key),
      segment_name: cleanText(segment.segment_name),
      operation: cleanText(segment.operation),
      service: cleanText(segment.service),
      equipment: cleanText(segment.equipment),
      lane_count: Number(segment.lane_count || 0)
    }));
    return {
      ...ratebook,
      lane_count: Number(ratebook.lane_count || 0),
      shared_carrier_count: shareCountByRatebook.get(mapLookupKey(ratebook.id)) || 0,
      segments,
      segment_count: segments.length,
      project: {
        id: project.id,
        title: project.title,
        customer_name: project.customer_name,
        due_date: project.due_date,
        status: project.status
      },
      package: {
        id: pack.id,
        name: pack.name,
        status: pack.status,
        bid_due_at: pack.bid_due_at,
        linked_rfx_event_id: pack.linked_rfx_event_id
      }
    };
  });
  const facetCounts = {
    shippers: new Map<string, { value: string; label: string; count: number }>(),
    sources: new Map<string, { value: string; label: string; count: number }>(),
    segments: new Map<string, { value: string; label: string; count: number }>()
  };
  allRows.forEach((row) => {
    const project = objectRecord(row.project);
    const shipperId = cleanText(row.shipper_id);
    const shipperLabel = firstCleanText(row.shipper_name, project.customer_name, project.title, "Unassigned shipper") || "Unassigned shipper";
    const shipperKey = shipperId || "__unassigned__";
    const shipperFacet = facetCounts.shippers.get(shipperKey) || { value: shipperId || "__unassigned__", label: shipperLabel, count: 0 };
    shipperFacet.count += 1;
    facetCounts.shippers.set(shipperKey, shipperFacet);

    const sourceValue = cleanText(row.source_type)?.toLowerCase() || "rfx";
    const sourceFacet = facetCounts.sources.get(sourceValue) || { value: sourceValue, label: sourceValue, count: 0 };
    sourceFacet.count += 1;
    facetCounts.sources.set(sourceValue, sourceFacet);

    (Array.isArray(row.segments) ? row.segments as Record<string, unknown>[] : []).forEach((segment) => {
      const segmentValue = cleanText(segment.segment_key)?.toLowerCase();
      if (!segmentValue) return;
      const segmentLabel = firstCleanText(segment.segment_name, segment.segment_key) || segmentValue;
      const segmentFacet = facetCounts.segments.get(segmentValue) || { value: segmentValue, label: segmentLabel, count: 0 };
      segmentFacet.count += 1;
      facetCounts.segments.set(segmentValue, segmentFacet);
    });
  });
  const facets = {
    shippers: Array.from(facetCounts.shippers.values()).sort((left, right) => left.label.localeCompare(right.label)),
    sources: Array.from(facetCounts.sources.values()).sort((left, right) => left.label.localeCompare(right.label)),
    segments: Array.from(facetCounts.segments.values()).sort((left, right) => left.label.localeCompare(right.label))
  };
  const laneSearchTextByPackage = new Map<string, string>();
  lanesByPackage.forEach((lanes, packageId) => {
    const content = lanes.map((packageLane) => {
      const demand = objectRecord(packageLane.rfx_demand_lanes);
      const normalized = objectRecord(demand.normalized_payload);
      return [
        demand.lane_key,
        demand.origin,
        demand.origin_city,
        demand.origin_state,
        demand.origin_country,
        demand.origin_postal_code,
        normalized.origin_market,
        normalized.origin_region,
        demand.destination,
        demand.destination_city,
        demand.destination_state,
        demand.destination_country,
        demand.destination_postal_code,
        normalized.destination_market,
        normalized.destination_region,
        demand.equipment_type,
        demand.trailer_requirements,
        demand.operation_type,
        demand.service_type,
        demand.currency
      ].map(cleanText).filter(Boolean).join(" ");
    }).join(" ").toLowerCase();
    laneSearchTextByPackage.set(packageId, content);
  });
  const rows = allRows.filter((row) => {
    if (requestedStatus && requestedStatus !== ratebookLifecycleStatus(row.lifecycle_status, cleanText(row.status)?.toLowerCase() || "draft")) return false;
    if (requestedShipperId === "__unassigned__" && cleanText(row.shipper_id)) return false;
    if (requestedShipperId && requestedShipperId !== "__unassigned__" && cleanText(row.shipper_id) !== requestedShipperId) return false;
    if (requestedSourceType && cleanText(row.source_type)?.toLowerCase() !== requestedSourceType) return false;
    if (requestedSegmentKey && !(Array.isArray(row.segments) ? row.segments : []).some((segment) => cleanText(segment.segment_key)?.toLowerCase() === requestedSegmentKey)) return false;
    if (!search) return true;
    const project = objectRecord(row.project);
    const pack = objectRecord(row.package);
    const packageId = cleanText(row.rfx_package_id) || "";
    return [row.name, row.shipper_name, row.source_type, project.title, project.customer_name, pack.name, laneSearchTextByPackage.get(packageId)]
      .map(cleanText).filter(Boolean).join(" ").toLowerCase().includes(search);
  });
  const materializationFailed = materializationOutcomes
    .filter((outcome) => outcome.error)
    .map((outcome) => ({ package_id: outcome.package_id, error: outcome.error }));
  const routeExport = input.include_routes === true
    ? await buildRatebookRouteExportRows(supabase, user, rows, input)
    : null;
  return {
    rows,
    loaded: rows.length,
    total: allRows.length,
    ...(routeExport ? { route_rows: routeExport.rows, route_total: routeExport.total } : {}),
    facets,
    sync: {
      ...bidRoomSync,
      materialization_attempted: materializationOutcomes.length,
      materialization_succeeded: materializedRatebooks.length,
      materialization_failed: materializationFailed
    }
  };
}

async function buildRatebookRouteExportRows(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null; organization_id?: string | null },
  ratebooks: Record<string, unknown>[],
  input: Record<string, unknown>
) {
  const packageIds = Array.from(new Set(ratebooks.map((row) => cleanText(row.rfx_package_id)).filter((id): id is string => Boolean(id))));
  if (!packageIds.length) {
    return { rows: [], total: 0, filters: input };
  }

  const eventIds = Array.from(new Set(ratebooks.map((row) => {
    const pack = objectRecord(row.package);
    return cleanText(row.rfx_event_id || pack.linked_rfx_event_id);
  }).filter((id): id is string => Boolean(id))));
  const requestedSegmentKey = cleanText(input.segment_key)?.toLowerCase();
  const [packageLaneRows, eventBatches, eventLaneRows, participantRows] = await Promise.all([
    fetchAllRatebookPackageRows(supabase, "rfx_package_lanes", packageIds, "package_id,id,demand_lane_id,rfx_demand_lanes(*)"),
    mapWithConcurrency(chunkValues(eventIds, RATEBOOK_PACKAGE_QUERY_CHUNK_SIZE), RATEBOOK_SYNC_CONCURRENCY, async (eventIdChunk) => {
      const result = await supabase
        .from("rfx_events")
        .select("id,rfx_id,name,customer,status,due_date")
        .eq("owner_email", user.owner_email)
        .in("id", eventIdChunk);
      if (result.error) throw result.error;
      return (result.data || []) as Record<string, unknown>[];
    }),
    fetchAllRfxEventRows(supabase, "rfx_lanes", eventIds, "*"),
    fetchAllRfxEventRows(supabase, "rfx_lane_vendors", eventIds, "id,rfx_lane_id,vendor_id,invitation_status,bid_rate,currency,weekly_capacity")
  ]);
  const eventRows = eventBatches.flat();

  const ratebookByPackage = new Map<string, Record<string, unknown>>();
  ratebooks.forEach((ratebook) => {
    const packageId = cleanText(ratebook.rfx_package_id);
    if (packageId) ratebookByPackage.set(packageId, ratebook);
  });
  const eventById = new Map<string, Record<string, unknown>>();
  eventRows.forEach((event) => {
    const eventId = cleanText(event.id);
    if (eventId) eventById.set(eventId, event);
  });
  const eventLaneByDemandId = new Map<string, Record<string, unknown>>();
  eventLaneRows.forEach((lane) => {
    const demandId = cleanText(lane.source_rfx_demand_lane_id);
    if (demandId) eventLaneByDemandId.set(demandId, lane);
  });
  const participantsByLaneId = new Map<string, Record<string, unknown>[]>();
  participantRows.forEach((participant) => {
    const key = cleanText(participant.rfx_lane_id);
    if (!key) return;
    const rows = participantsByLaneId.get(key) || [];
    rows.push(participant);
    participantsByLaneId.set(key, rows);
  });

  const rows = packageLaneRows.flatMap((packageLane, index) => {
    const ratebook = ratebookByPackage.get(mapLookupKey(packageLane.package_id));
    if (!ratebook) return [];
    const route = ratebookRouteSummary(packageLane, index, eventLaneByDemandId, participantsByLaneId);
    if (requestedSegmentKey && cleanText(route.segment_key)?.toLowerCase() !== requestedSegmentKey) return [];
    const demand = objectRecord(packageLane.rfx_demand_lanes);
    const eventLane = eventLaneByDemandId.get(mapLookupKey(demand.id)) || {};
    const normalized = objectRecord(demand.normalized_payload);
    const project = objectRecord(ratebook.project);
    const pack = objectRecord(ratebook.package);
    const eventId = cleanText(ratebook.rfx_event_id || pack.linked_rfx_event_id);
    const event = eventById.get(mapLookupKey(eventId)) || {};
    return [{
      ratebook_id: cleanText(ratebook.id),
      ratebook_name: firstCleanText(ratebook.name, pack.name, "Ratebook") || "Ratebook",
      lifecycle_status: ratebookLifecycleStatus(ratebook.lifecycle_status, cleanText(ratebook.status)?.toLowerCase() || "draft"),
      version_number: Number(ratebook.version_number || 1),
      shipper_id: cleanText(ratebook.shipper_id),
      shipper_name: firstCleanText(ratebook.shipper_name, project.customer_name, event.customer, "Unassigned shipper") || "Unassigned shipper",
      source_type: cleanText(ratebook.source_type) || "rfx",
      project_id: cleanText(ratebook.project_id),
      project_name: firstCleanText(project.title, project.customer_name),
      package_id: cleanText(ratebook.rfx_package_id),
      package_name: firstCleanText(pack.name, ratebook.name),
      event_id: eventId,
      event_name: firstCleanText(event.name, pack.name),
      rfx_id: cleanText(event.rfx_id),
      transaction_id: cleanText(route.transaction_id),
      route_status: cleanText(route.status),
      package_lane_id: cleanText(route.package_lane_id),
      source_demand_lane_id: cleanText(route.source_demand_lane_id),
      source_rfi_lane_id: cleanText(route.source_rfi_lane_id),
      segment_key: cleanText(route.segment_key),
      segment_name: cleanText(route.segment_name),
      origin: firstCleanText(route.origin, demand.origin, eventLane.origin),
      origin_city: firstCleanText(demand.origin_city, normalized.origin_city, eventLane.origin_city),
      origin_state: firstCleanText(demand.origin_state, normalized.origin_state, eventLane.origin_state),
      origin_country: firstCleanText(demand.origin_country, normalized.origin_country, eventLane.origin_country),
      origin_postal_code: firstCleanText(demand.origin_postal_code, demand.origin_zip, normalized.origin_postal_code, normalized.origin_zip, normalized.origin_zip_prefix),
      origin_market: firstCleanText(normalized.origin_market, eventLane.origin_market),
      origin_region: firstCleanText(normalized.origin_region, eventLane.origin_region),
      destination: firstCleanText(route.destination, demand.destination, eventLane.destination),
      destination_city: firstCleanText(demand.destination_city, normalized.destination_city, eventLane.destination_city),
      destination_state: firstCleanText(demand.destination_state, normalized.destination_state, eventLane.destination_state),
      destination_country: firstCleanText(demand.destination_country, normalized.destination_country, eventLane.destination_country),
      destination_postal_code: firstCleanText(demand.destination_postal_code, demand.destination_zip, normalized.destination_postal_code, normalized.destination_zip, normalized.destination_zip_prefix),
      destination_market: firstCleanText(normalized.destination_market, eventLane.destination_market),
      destination_region: firstCleanText(normalized.destination_region, eventLane.destination_region),
      equipment: firstCleanText(route.equipment, demand.equipment_type, eventLane.equipment),
      trailer: firstCleanText(route.trailer, demand.trailer_requirements, eventLane.trailer),
      configuration: firstCleanText(demand.configuration_type, eventLane.config),
      operation: firstCleanText(route.operation, demand.operation_type, eventLane.operation),
      service: firstCleanText(route.service, demand.service_type, eventLane.service),
      weekly_volume: cleanNumber(demand.weekly_volume) ?? cleanNumber(eventLane.weekly_volume),
      monthly_volume: cleanNumber(demand.monthly_volume),
      frequency: firstCleanText(route.frequency, demand.frequency),
      target_rate: cleanNumber(demand.target_rate) ?? cleanNumber(eventLane.target_rate),
      currency: firstCleanText(route.currency, demand.currency, eventLane.currency) || "USD",
      carrier_count: Number(route.carrier_count || 0),
      bid_count: Number(route.bid_count || 0),
      updated_at: firstCleanText(demand.updated_at, packageLane.updated_at, ratebook.updated_at)
    }];
  });

  return {
    rows,
    total: rows.length,
    ratebook_count: ratebooks.length,
    filters: {
      search: cleanText(input.search),
      status: cleanText(input.status || input.lifecycle_status),
      shipper_id: cleanText(input.shipper_id),
      source_type: cleanText(input.source_type),
      segment_key: cleanText(input.segment_key),
      project_id: cleanText(input.project_id)
    }
  };
}

async function exportRatebookRoutes(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null; organization_id?: string | null },
  input: Record<string, unknown>
) {
  const listed = await listRatebooks(supabase, user, { ...input, include_routes: false });
  return await buildRatebookRouteExportRows(
    supabase,
    user,
    (listed.rows || []) as Record<string, unknown>[],
    input
  );
}

async function materializeRatebooksForProjects(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null; organization_id?: string | null },
  projectIds: string[]
) {
  const ids = Array.from(new Set(projectIds.map((id) => cleanText(id)).filter((id): id is string => Boolean(id))));
  if (!ids.length) return { rows: [] as Record<string, unknown>[], failed: [] as Record<string, unknown>[] };
  const [projectBatches, ownerPackages] = await Promise.all([
    mapWithConcurrency(chunkValues(ids, RATEBOOK_PACKAGE_QUERY_CHUNK_SIZE), RATEBOOK_SYNC_CONCURRENCY, async (projectIdChunk) => {
      const result = await supabase.from("rfx_projects").select("*")
        .eq("owner_email", user.owner_email).in("id", projectIdChunk);
      if (result.error) throw result.error;
      return (result.data || []) as Record<string, unknown>[];
    }),
    fetchAllOwnedRfxPackages(supabase, user.owner_email)
  ]);
  const projects = projectBatches.flat();
  const projectIdSet = new Set(ids);
  const packs = ownerPackages.filter((pack) => projectIdSet.has(cleanText(pack.project_id) || ""));
  if (!packs.length) return { rows: [] as Record<string, unknown>[], failed: [] as Record<string, unknown>[] };
  const packageIds = packs.map((pack) => cleanText(pack.id)).filter((id): id is string => Boolean(id));
  const [packageLaneRows, packageSegmentRows] = await Promise.all([
    fetchAllRatebookPackageRows(supabase, "rfx_package_lanes", packageIds, "package_id,id,demand_lane_id,rfx_demand_lanes(*)"),
    fetchAllRatebookPackageRows(supabase, "rfx_package_segments", packageIds, "*")
  ]);
  const projectById = new Map<string, Record<string, unknown>>();
  projects.forEach((project) => {
    const projectId = cleanText(project.id);
    if (projectId) projectById.set(projectId, project);
  });
  const shipperContexts = await getRatebookShipperContexts(supabase, user, ids);
  const laneCountByPackage = new Map<string, number>();
  const lanesByPackage = new Map<string, Record<string, unknown>[]>();
  packageLaneRows.forEach((row) => {
    const key = cleanText(row.package_id);
    if (!key) return;
    laneCountByPackage.set(key, (laneCountByPackage.get(key) || 0) + 1);
    const lanes = lanesByPackage.get(key) || [];
    lanes.push(row);
    lanesByPackage.set(key, lanes);
  });
  const segmentsByPackage = new Map<string, Record<string, unknown>[]>();
  packageSegmentRows.forEach((segment) => {
    const key = cleanText(segment.package_id);
    if (!key) return;
    const rows = segmentsByPackage.get(key) || [];
    rows.push(segment);
    segmentsByPackage.set(key, rows);
  });
  const outcomes: Array<{ row: Record<string, unknown> | null; failed: Record<string, unknown> | null }> = await mapWithConcurrency(packs, RATEBOOK_SYNC_CONCURRENCY, async (pack) => {
    const projectId = cleanText(pack.project_id);
    const packageId = cleanText(pack.id);
    if (!projectId || !packageId) return { row: null, failed: null };
    const project = projectById.get(projectId);
    if (!project) {
      return {
        row: null,
        failed: {
          package_id: packageId,
          package_name: cleanText(pack.name) || "Untitled RFx package",
          project_id: projectId,
          error: "The RFx project is no longer available for this account."
        }
      };
    }
    try {
      const ratebook = await upsertRatebookForPackage(supabase, user, {
        pack,
        project,
        package_lanes: lanesByPackage.get(packageId) || [],
        package_segments: segmentsByPackage.get(packageId) || [],
        shipper: shipperContexts.get(projectId)
      });
      const row: Record<string, unknown> = {
        ...ratebook,
        lane_count: laneCountByPackage.get(packageId) || 0,
        project: {
          id: project.id,
          title: project.title,
          customer_name: project.customer_name,
          due_date: project.due_date,
          status: project.status
        },
        package: {
          id: pack.id,
          name: pack.name,
          status: pack.status,
          bid_due_at: pack.bid_due_at,
          linked_rfx_event_id: pack.linked_rfx_event_id
        }
      };
      return {
        row,
        failed: null
      };
    } catch (error) {
      return {
        row: null,
        failed: {
          package_id: packageId,
          package_name: cleanText(pack.name) || "Untitled RFx package",
          project_id: projectId,
          error: safeOperationalError(error)
        }
      };
    }
  });
  const rows: Record<string, unknown>[] = [];
  const failed: Record<string, unknown>[] = [];
  outcomes.forEach((outcome) => {
    if (outcome.row) rows.push(outcome.row);
    if (outcome.failed) failed.push(outcome.failed);
  });
  return { rows, failed };
}

function ratebookRouteSummary(
  packageLane: Record<string, unknown>,
  index: number,
  eventLaneByDemandId: Map<string, Record<string, unknown>>,
  participantsByLaneId: Map<string, Record<string, unknown>[]>
) {
  const demand = objectRecord(packageLane.rfx_demand_lanes);
  const eventLane = eventLaneByDemandId.get(mapLookupKey(demand.id)) || {};
  const laneId = cleanText(eventLane.id) || cleanText(demand.id);
  const participants = participantsByLaneId.get(mapLookupKey(eventLane.id)) || [];
  const hasBid = participants.some((participant) => cleanText(participant.invitation_status) === "bid_submitted" || cleanNumber(participant.bid_rate) !== null);
  return {
    id: laneId,
    package_lane_id: cleanText(packageLane.id),
    source_demand_lane_id: cleanText(demand.id),
    source_rfi_lane_id: cleanText(demand.source_rfi_lane_id),
    transaction_id: cleanText(demand.lane_key) || `L${index + 1}`,
    origin: firstCleanText(demand.origin, [demand.origin_city, demand.origin_state].filter(Boolean).join(", ")),
    destination: firstCleanText(demand.destination, [demand.destination_city, demand.destination_state].filter(Boolean).join(", ")),
    equipment: firstCleanText(demand.equipment_type, eventLane.equipment),
    trailer: firstCleanText(demand.trailer_requirements, eventLane.trailer),
    operation: firstCleanText(demand.operation_type, eventLane.operation),
    service: firstCleanText(demand.service_type, eventLane.service),
    weekly_volume: cleanNumber(demand.weekly_volume),
    frequency: cleanText(demand.frequency),
    currency: firstCleanText(demand.currency, eventLane.currency) || "USD",
    segment_key: cleanText(demand.rfx_segment_key) || cleanText(demand.operating_segment) || "all_routes",
    segment_name: firstCleanText(demand.rfx_segment_name, demand.operating_segment, "All routes") || "All routes",
    rfx_lane_id: cleanText(eventLane.id),
    carrier_count: participants.length,
    bid_count: participants.filter((participant) => cleanText(participant.invitation_status) === "bid_submitted" || cleanNumber(participant.bid_rate) !== null).length,
    status: hasBid ? "quoted" : participants.length ? "shared" : "ready"
  };
}

function evaluateRatebookReadiness(packageLanes: Record<string, unknown>[]) {
  const issues: Record<string, unknown>[] = [];
  if (!packageLanes.length) {
    issues.push({ type: "missing_routes", message: "Add at least one route before publishing this Ratebook." });
  }
  packageLanes.forEach((packageLane, index) => {
    const demand = objectRecord(packageLane.rfx_demand_lanes);
    const missing = [
      ["origin", firstCleanText(demand.origin, demand.origin_city)],
      ["destination", firstCleanText(demand.destination, demand.destination_city)],
      ["equipment", demand.equipment_type],
      ["operation", demand.operation_type],
      ["service", demand.service_type],
      ["currency", demand.currency]
    ].filter(([, value]) => !cleanText(value)).map(([key]) => key);
    if (missing.length) {
      issues.push({
        type: "incomplete_route",
        transaction_id: cleanText(demand.lane_key) || `L${index + 1}`,
        source_demand_lane_id: cleanText(demand.id),
        missing
      });
    }
  });
  return { ready: !issues.length, route_count: packageLanes.length, issues };
}

async function createRatebookRevision(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null; organization_id?: string | null },
  input: Record<string, unknown>
) {
  const previousRatebook = await requireOwnedRatebook(supabase, user, input.ratebook_id || input.id);
  if (ratebookLifecycleStatus(previousRatebook.lifecycle_status) !== "published") {
    throw new Error("Only a published Ratebook can create a revision.");
  }
  const context = await getOwnedRatebookPackage(supabase, user, previousRatebook.rfx_package_id);
  const projectId = cleanText(context.project.id);
  if (!projectId) throw new Error("The RFx project is missing its identifier.");
  const shipperContexts = await getRatebookShipperContexts(supabase, user, [projectId]);
  const sourceType = ratebookSourceType(context.project, context.pack);
  const sourceFingerprint = ratebookSourceFingerprint(context.project, context.pack, sourceType);
  const sourceSnapshotHash = await hashRatebookSourceSnapshot(ratebookSourceSnapshot(
    context.project, context.pack, context.package_lanes, context.package_segments
  ));
  const existingDraftResult = await supabase.from("rfx_ratebooks").select("*")
    .eq("owner_email", user.owner_email).eq("rfx_package_id", context.pack.id)
    .eq("lifecycle_status", "draft").eq("source_snapshot_hash", sourceSnapshotHash)
    .order("version_number", { ascending: false }).limit(1).maybeSingle();
  if (existingDraftResult.error) throw existingDraftResult.error;
  if (existingDraftResult.data) {
    return { ratebook: existingDraftResult.data, reused_existing_draft: true };
  }
  const versionsResult = await supabase.from("rfx_ratebooks").select("version_number")
    .eq("owner_email", user.owner_email).eq("rfx_package_id", context.pack.id)
    .order("version_number", { ascending: false }).limit(1).maybeSingle();
  if (versionsResult.error) throw versionsResult.error;
  const nextVersion = Number(versionsResult.data?.version_number || previousRatebook.version_number || 1) + 1;
  const shipper = shipperContexts.get(projectId);
  const now = new Date().toISOString();
  const insert = await supabase.from("rfx_ratebooks").insert({
    ...withOwner({
      parent_ratebook_id: previousRatebook.id,
      project_id: context.project.id,
      rfx_package_id: context.pack.id,
      rfx_event_id: cleanText(context.pack.linked_rfx_event_id) || null,
      name: firstCleanText(context.pack.name, context.project.title, "RFx Ratebook") || "RFx Ratebook",
      lane_count: context.package_lanes.length,
      shipper_id: shipper?.shipper_id || cleanText(previousRatebook.shipper_id) || null,
      shipper_name: shipper?.shipper_name || cleanText(previousRatebook.shipper_name) || cleanText(context.project.customer_name) || null,
      source_type: sourceType,
      source_reference: firstCleanText(shipper?.opportunity_name, context.project.title, context.project.customer_name),
      source_fingerprint: sourceFingerprint,
      source_snapshot_hash: sourceSnapshotHash,
      status: "draft",
      lifecycle_status: "draft",
      version_number: nextVersion,
      valid_from: previousRatebook.valid_from || null,
      valid_until: previousRatebook.valid_until || null,
      metadata: {
        ...objectRecord(previousRatebook.metadata),
        source: "rfx_process_package",
        source_type: sourceType,
        revision_of_ratebook_id: previousRatebook.id,
        revision_created_at: now,
        project_title: cleanText(context.project.title),
        customer_name: cleanText(context.project.customer_name),
        shipper_opportunity: shipper?.opportunity_name || null,
        bid_due_at: cleanText(context.pack.bid_due_at)
      },
      updated_at: now
    }, user),
    organization_id: user.organization_id || null
  }).select().single();
  if (insert.error) throw insert.error;
  const ratebook = insert.data as Record<string, unknown>;
  await syncRatebookSegments(supabase, user, ratebook, context);
  await writeRfxProcessAudit(supabase, user, context.project.id, "ratebook_revision_created", "rfx_ratebooks", ratebook.id,
    `Created Ratebook v${nextVersion} from published v${Number(previousRatebook.version_number || 1)}.`, {
      rfx_package_id: context.pack.id,
      parent_ratebook_id: previousRatebook.id,
      source_snapshot_hash: sourceSnapshotHash
    });
  return { ratebook, reused_existing_draft: false };
}

async function getRatebookAudit(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  input: Record<string, unknown>
) {
  const ratebook = await requireOwnedRatebook(supabase, user, input.ratebook_id || input.id);
  const context = await getOwnedRatebookPackage(supabase, user, ratebook.rfx_package_id);
  const currentSourceSnapshotHash = await hashRatebookSourceSnapshot(ratebookSourceSnapshot(
    context.project, context.pack, context.package_lanes, context.package_segments
  ));
  const readiness = evaluateRatebookReadiness(context.package_lanes);
  const segmentsResult = await supabase.from("rfx_ratebook_segments").select("*")
    .eq("ratebook_id", ratebook.id).eq("owner_email", user.owner_email).order("created_at", { ascending: true });
  if (segmentsResult.error) throw segmentsResult.error;
  return {
    ratebook_id: ratebook.id,
    lifecycle_status: ratebookLifecycleStatus(ratebook.lifecycle_status),
    source: {
      type: cleanText(ratebook.source_type) || "rfx",
      fingerprint: cleanText(ratebook.source_fingerprint),
      project_id: cleanText(ratebook.project_id),
      rfx_package_id: cleanText(ratebook.rfx_package_id),
      shipper_id: cleanText(ratebook.shipper_id),
      shipper_name: cleanText(ratebook.shipper_name),
      freshness: ratebookSourceFreshness(ratebook, currentSourceSnapshotHash),
      changed_at: ratebook.source_changed_at || null
    },
    version: Number(ratebook.version_number || 1),
    validity: { valid_from: ratebook.valid_from || null, valid_until: ratebook.valid_until || null },
    readiness,
    segments: segmentsResult.data || []
  };
}

async function getRatebookHealth(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
) {
  const ratebooks = (await fetchAllOwnedRfxRatebooks(supabase, user.owner_email))
    .filter((ratebook) => ["draft", "published"].includes(cleanText(ratebook.lifecycle_status)?.toLowerCase() || ""));
  if (!ratebooks.length) {
    return {
      generated_at: new Date().toISOString(),
      summary: { active_ratebooks: 0, priority_issues: 0, expiring: 0, routes_without_offers: 0, offers_to_review: 0 },
      rows: [],
      queue: []
    };
  }

  const ratebookIds = ratebooks.map((row) => cleanText(row.id)).filter((id): id is string => Boolean(id));
  const packageIds = ratebooks.map((row) => cleanText(row.rfx_package_id)).filter((id): id is string => Boolean(id));
  const [packageLaneRows, shareRows, quoteRows, reviewRows, campaigns] = await Promise.all([
    fetchAllRatebookPackageRows(supabase, "rfx_package_lanes", packageIds, "id,package_id"),
    fetchAllRatebookShares(supabase, ratebookIds, {
      activeOnly: false,
      columns: "id,ratebook_id,status,access_count,last_accessed_at,last_viewed_at,last_quote_at"
    }),
    fetchAllRatebookRowsByRatebookIds(supabase, user.owner_email, "rfx_ratebook_carrier_quotes", ratebookIds, "id,ratebook_id,package_lane_id,status,updated_at", { status: "submitted" }),
    fetchAllRatebookRowsByRatebookIds(supabase, user.owner_email, "rfx_ratebook_quote_reviews", ratebookIds, "quote_id,ratebook_id,package_lane_id,decision"),
    fetchAllRatebookRowsByRatebookIds(supabase, user.owner_email, "outreach_campaigns", ratebookIds, "id,ratebook_id")
  ]);
  const campaignIds = campaigns.map((row) => cleanText(row.id)).filter((id): id is string => Boolean(id));
  const messageRows = await fetchAllOutreachMessagesByCampaignIds(supabase, user.owner_email, campaignIds);

  const packageToRatebook = new Map(ratebooks.map((row) => [cleanText(row.rfx_package_id), cleanText(row.id)]));
  const campaignToRatebook = new Map(campaigns.map((row) => [cleanText(row.id), cleanText(row.ratebook_id)]));
  const counter = () => new Map<string, number>();
  const increment = (map: Map<string, number>, id: string) => map.set(id, (map.get(id) || 0) + 1);
  const laneCountByRatebook = counter();
  const shareCountByRatebook = counter();
  const accessedByRatebook = counter();
  const quotedLaneIdsByRatebook = new Map<string, Set<string>>();
  const reviewPendingByRatebook = counter();
  const firstPendingRouteByRatebook = new Map<string, string>();
  const failedDeliveryByRatebook = counter();
  const reviewByQuoteId = new Map<string, Record<string, unknown>>();

  reviewRows.forEach((review) => {
    const quoteId = cleanText(review.quote_id);
    if (quoteId) reviewByQuoteId.set(quoteId, review);
  });
  packageLaneRows.forEach((lane) => {
    const ratebookId = packageToRatebook.get(cleanText(lane.package_id));
    if (ratebookId) increment(laneCountByRatebook, ratebookId);
  });
  shareRows.forEach((share) => {
    const ratebookId = cleanText(share.ratebook_id);
    if (!ratebookId || cleanText(share.status)?.toLowerCase() !== "active") return;
    increment(shareCountByRatebook, ratebookId);
    if (Number(share.access_count || 0) > 0 || cleanText(share.last_accessed_at || share.last_viewed_at)) increment(accessedByRatebook, ratebookId);
  });
  quoteRows.forEach((quote) => {
    const ratebookId = cleanText(quote.ratebook_id);
    const packageLaneId = cleanText(quote.package_lane_id);
    if (!ratebookId || !packageLaneId) return;
    const quotedLaneIds = quotedLaneIdsByRatebook.get(ratebookId) || new Set<string>();
    quotedLaneIds.add(packageLaneId);
    quotedLaneIdsByRatebook.set(ratebookId, quotedLaneIds);
    const review = reviewByQuoteId.get(mapLookupKey(quote.id));
    if (!review || cleanText(review.decision)?.toLowerCase() === "pending") {
      increment(reviewPendingByRatebook, ratebookId);
      if (!firstPendingRouteByRatebook.has(ratebookId)) firstPendingRouteByRatebook.set(ratebookId, packageLaneId);
    }
  });
  messageRows.forEach((message) => {
    if (!["failed", "bounced"].includes(cleanText(message.status)?.toLowerCase() || "")) return;
    const ratebookId = campaignToRatebook.get(cleanText(message.campaign_id));
    if (ratebookId) increment(failedDeliveryByRatebook, ratebookId);
  });

  const now = Date.now();
  const expiringThreshold = now + (30 * 24 * 60 * 60 * 1000);
  const priorityOrder: Record<string, number> = { high: 0, medium: 1, low: 2 };
  const queue: Record<string, unknown>[] = [];
  const rows = ratebooks.map((ratebook) => {
    const id = mapLookupKey(ratebook.id);
    const lifecycle = ratebookLifecycleStatus(ratebook.lifecycle_status, cleanText(ratebook.status)?.toLowerCase() || "draft");
    const laneCount = laneCountByRatebook.get(id) || Number(ratebook.lane_count || 0);
    const quotedLaneCount = quotedLaneIdsByRatebook.get(id)?.size || 0;
    const routesWithoutOffers = Math.max(0, laneCount - quotedLaneCount);
    const shares = shareCountByRatebook.get(id) || 0;
    const accesses = accessedByRatebook.get(id) || 0;
    const pendingReviews = reviewPendingByRatebook.get(id) || 0;
    const failedDelivery = failedDeliveryByRatebook.get(id) || 0;
    const validUntil = cleanText(ratebook.valid_until);
    const validUntilTime = validUntil ? new Date(validUntil).getTime() : Number.NaN;
    const expired = lifecycle === "published" && Number.isFinite(validUntilTime) && validUntilTime < now;
    const expiring = lifecycle === "published" && Number.isFinite(validUntilTime) && validUntilTime >= now && validUntilTime <= expiringThreshold;
    const sourceOutdated = lifecycle === "published" && Boolean(cleanText(ratebook.source_changed_at));
    const carrierAccessPending = lifecycle === "published" && shares > 0 && accesses === 0;
    const name = firstCleanText(ratebook.name, ratebook.shipper_name, "Ratebook") || "Ratebook";
    const context = { ratebook_id: id, ratebook_name: name, shipper_name: cleanText(ratebook.shipper_name), version_number: Number(ratebook.version_number || 1) };
    if (sourceOutdated) queue.push({ ...context, priority: "high", type: "source_outdated", title: "Source changed after publish", detail: "Create a controlled revision before using newer RFx/RFI data.", action: "revision" });
    if (expired) queue.push({ ...context, priority: "high", type: "expired", title: "Ratebook validity expired", detail: "Confirm validity and create a revision or archive this release.", action: "audit" });
    if (failedDelivery) queue.push({ ...context, priority: "high", type: "delivery_failed", title: `${failedDelivery} carrier delivery failure${failedDelivery === 1 ? "" : "s"}`, detail: "Open carrier distribution to replace failed delivery with a new controlled invitation.", action: "share" });
    if (pendingReviews) queue.push({ ...context, priority: "medium", type: "offers_to_review", title: `${pendingReviews} submitted offer${pendingReviews === 1 ? "" : "s"} need review`, detail: "Review or shortlist carrier offers without awarding a Rateware rate.", action: "review", package_lane_id: firstPendingRouteByRatebook.get(id) || null });
    if (lifecycle === "published" && routesWithoutOffers && shares > 0) queue.push({ ...context, priority: "medium", type: "coverage_gap", title: `${routesWithoutOffers} route${routesWithoutOffers === 1 ? "" : "s"} without offers`, detail: "Share the Ratebook with additional carriers or follow up on the existing private links.", action: "share" });
    if (carrierAccessPending) queue.push({ ...context, priority: "low", type: "carrier_access_pending", title: `${shares} carrier link${shares === 1 ? "" : "s"} not opened`, detail: "Carrier access has not been used yet. Review delivery timing before following up.", action: "share" });
    return {
      ...context,
      lifecycle_status: lifecycle,
      valid_until: validUntil || null,
      source_outdated: sourceOutdated,
      expired,
      expiring,
      lane_count: laneCount,
      routes_without_offers: routesWithoutOffers,
      active_shares: shares,
      accessed_shares: accesses,
      offers_to_review: pendingReviews,
      delivery_failed: failedDelivery
    };
  });
  queue.sort((left, right) => (priorityOrder[cleanText(left.priority) || "low"] || 9) - (priorityOrder[cleanText(right.priority) || "low"] || 9));
  return {
    generated_at: new Date().toISOString(),
    summary: {
      active_ratebooks: rows.filter((row) => row.lifecycle_status === "published").length,
      priority_issues: queue.filter((item) => cleanText(item.priority) === "high").length,
      expiring: rows.filter((row) => row.expiring || row.expired).length,
      routes_without_offers: rows.reduce((total, row) => total + Number(row.routes_without_offers || 0), 0),
      offers_to_review: rows.reduce((total, row) => total + Number(row.offers_to_review || 0), 0)
    },
    rows,
    queue: queue.slice(0, 50)
  };
}

async function updateRatebookLifecycle(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null },
  input: Record<string, unknown>,
  lifecycle: "published" | "archived" | "superseded"
) {
  const ratebook = await requireOwnedRatebook(supabase, user, input.ratebook_id || input.id);
  const context = await getOwnedRatebookPackage(supabase, user, ratebook.rfx_package_id);
  const readiness = evaluateRatebookReadiness(context.package_lanes);
  if (lifecycle === "published" && !readiness.ready) {
    throw new Error(`Ratebook cannot publish until ${readiness.issues.length} route issue(s) are resolved.`);
  }
  const now = new Date().toISOString();
  const patch: Record<string, unknown> = {
    lifecycle_status: lifecycle,
    status: ratebookLegacyStatus(lifecycle, context.pack, ratebook.status),
    updated_at: now
  };
  if (lifecycle === "published") patch.published_at = ratebook.published_at || now;
  if (lifecycle === "archived") patch.archived_at = now;
  if (lifecycle === "superseded") patch.superseded_at = now;
  const update = await supabase.from("rfx_ratebooks").update(patch)
    .eq("id", ratebook.id).eq("owner_email", user.owner_email).select().single();
  if (update.error) throw update.error;
  let supersededRatebookIds: string[] = [];
  if (lifecycle === "published") {
    const previousPublished = await supabase.from("rfx_ratebooks").select("id")
      .eq("owner_email", user.owner_email).eq("rfx_package_id", ratebook.rfx_package_id)
      .eq("lifecycle_status", "published").neq("id", ratebook.id);
    if (previousPublished.error) throw previousPublished.error;
    supersededRatebookIds = ((previousPublished.data || []) as Record<string, unknown>[]).map((row) => cleanText(row.id)).filter((id): id is string => Boolean(id));
    if (supersededRatebookIds.length) {
      const supersede = await supabase.from("rfx_ratebooks").update({
        lifecycle_status: "superseded",
        status: "archived",
        superseded_at: now,
        updated_at: now
      }).eq("owner_email", user.owner_email).in("id", supersededRatebookIds);
      if (supersede.error) throw supersede.error;
      const revokeShares = await supabase.from("rfx_ratebook_shares").update({ status: "revoked", updated_at: now })
        .eq("owner_email", user.owner_email).in("ratebook_id", supersededRatebookIds).eq("status", "active");
      if (revokeShares.error) throw revokeShares.error;
    }
  }
  if (lifecycle === "archived") {
    const shares = await supabase.from("rfx_ratebook_shares").update({ status: "archived", updated_at: now })
      .eq("ratebook_id", ratebook.id).eq("owner_email", user.owner_email).eq("status", "active");
    if (shares.error) throw shares.error;
  }
  await writeRfxProcessAudit(supabase, user, context.project.id, `ratebook_${lifecycle}`, "rfx_ratebooks", ratebook.id,
    `${lifecycle === "published" ? "Published" : lifecycle === "archived" ? "Archived" : "Superseded"} Ratebook ${cleanText(ratebook.name) || ratebook.id}.`, {
      rfx_package_id: context.pack.id,
      route_count: readiness.route_count,
      source_type: cleanText(ratebook.source_type) || "rfx",
      superseded_ratebook_count: supersededRatebookIds.length
    });
  return { ratebook: update.data, readiness };
}

async function getRatebook(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  input: Record<string, unknown>
) {
  const ratebook = await requireOwnedRatebook(supabase, user, input.ratebook_id || input.id);
  const context = await getOwnedRatebookPackage(supabase, user, ratebook.rfx_package_id);
  const currentSourceSnapshotHash = await hashRatebookSourceSnapshot(ratebookSourceSnapshot(
    context.project, context.pack, context.package_lanes, context.package_segments
  ));
  const eventId = cleanText(ratebook.rfx_event_id || context.pack.linked_rfx_event_id);
  const ratebookId = cleanText(ratebook.id) || "";
  const [eventResult, eventLanes, participantRows, shareRows, segmentRows, ratebookQuoteRows, quoteReviewRows, campaignRows] = await Promise.all([
    eventId ? supabase.from("rfx_events").select("*").eq("id", eventId).eq("owner_email", user.owner_email).maybeSingle() : { data: null, error: null },
    eventId ? fetchAllRfxLaneRows(supabase, eventId, "*") : [],
    eventId ? fetchAllRfxLaneVendorRows(supabase, eventId, "id,rfx_event_id,rfx_lane_id,vendor_id,invitation_status,invitation_token,invitation_token_encrypted,invited_at,viewed_at,responded_at,bid_rate,weekly_capacity,currency") : [],
    fetchAllRatebookShares(supabase, [ratebookId], {
      activeOnly: false,
      columns: "*, vendors(id,vendor_name,domain,primary_email)"
    }),
    fetchAllRatebookRowsByRatebookIds(supabase, user.owner_email, "rfx_ratebook_segments", [ratebookId], "*"),
    fetchAllRatebookRowsByRatebookIds(
      supabase,
      user.owner_email,
      "rfx_ratebook_carrier_quotes",
      [ratebookId],
      "package_lane_id,status,all_in_rate,currency,updated_at",
      { status: "submitted" }
    ),
    fetchAllRatebookRowsByRatebookIds(supabase, user.owner_email, "rfx_ratebook_quote_reviews", [ratebookId], "package_lane_id,decision"),
    fetchAllRatebookRowsByRatebookIds(supabase, user.owner_email, "outreach_campaigns", [ratebookId], "id,ratebook_id,name,status,channel,created_at,updated_at")
  ]);
  if (eventResult.error) throw eventResult.error;
  const eventLaneByDemandId = new Map<string, Record<string, unknown>>();
  eventLanes.forEach((lane) => {
    const demandId = cleanText(lane.source_rfx_demand_lane_id);
    if (demandId) eventLaneByDemandId.set(demandId, lane);
  });
  const participants = await hydrateRfxInvitationTokens(supabase, participantRows);
  const participantsByLaneId = new Map<string, Record<string, unknown>[]>();
  participants.forEach((participant) => {
    const key = cleanText(participant.rfx_lane_id);
    if (!key) return;
    const rows = participantsByLaneId.get(key) || [];
    rows.push(participant);
    participantsByLaneId.set(key, rows);
  });
  const ratebookQuoteCounts = new Map<string, number>();
  ratebookQuoteRows.forEach((quote) => {
    const key = cleanText(quote.package_lane_id);
    if (key) ratebookQuoteCounts.set(key, (ratebookQuoteCounts.get(key) || 0) + 1);
  });
  const shortlistedRatebookQuotes = new Map<string, number>();
  quoteReviewRows.forEach((review) => {
    if (cleanText(review.decision) !== "shortlisted") return;
    const key = cleanText(review.package_lane_id);
    if (key) shortlistedRatebookQuotes.set(key, (shortlistedRatebookQuotes.get(key) || 0) + 1);
  });
  const routes = context.package_lanes.map((packageLane, index) => {
    const route = ratebookRouteSummary(packageLane, index, eventLaneByDemandId, participantsByLaneId);
    const ratebookQuoteCount = ratebookQuoteCounts.get(mapLookupKey(route.package_lane_id)) || 0;
    const shortlistedQuoteCount = shortlistedRatebookQuotes.get(mapLookupKey(route.package_lane_id)) || 0;
    return {
      ...route,
      ratebook_quote_count: ratebookQuoteCount,
      shortlisted_quote_count: shortlistedQuoteCount,
      live_bid_count: Number(route.bid_count || 0),
      carrier_response_count: Number(route.bid_count || 0) + ratebookQuoteCount,
      bid_count: Number(route.bid_count || 0) + ratebookQuoteCount,
      status: ratebookQuoteCount ? "quoted" : route.status
    };
  });
  const safeShares = shareRows.map((share) => {
    const { access_token_hash: _accessTokenHash, ...safeShare } = share;
    return safeShare;
  });
  const campaigns = campaignRows.sort((left, right) => String(right.created_at || "").localeCompare(String(left.created_at || "")));
  const campaignIds = campaigns.map((campaign) => cleanText(campaign.id)).filter(Boolean) as string[];
  const messages = campaignIds.length
    ? await fetchAllOutreachMessagesByCampaignIds(
      supabase,
      user.owner_email,
      campaignIds,
      "id,campaign_id,ratebook_share_id,vendor_id,channel,status,recipient_email,sent_at,last_contacted_at,delivery_error,created_at,updated_at"
    )
    : [];
  messages.sort((left, right) => String(right.updated_at || "").localeCompare(String(left.updated_at || "")));
  const messageCount = (statuses: string[]) => messages.filter((message) => statuses.includes(cleanText(message.status)?.toLowerCase() || "")).length;
  const accessed = safeShares.filter((share) => cleanText(share.last_accessed_at || share.last_viewed_at) || Number(share.access_count || 0) > 0).length;
  const quoted = safeShares.filter((share) => cleanText(share.last_quote_at)).length;
  return {
    ratebook: {
      ...ratebook,
      source_freshness: ratebookSourceFreshness(ratebook, currentSourceSnapshotHash),
      shared_carrier_count: shareRows.filter((share) => cleanText(share.status) === "active").length
    },
    project: context.project,
    package: context.pack,
    event: eventResult.data || null,
    routes,
    shares: safeShares,
    segments: segmentRows.sort((left, right) => String(left.created_at || "").localeCompare(String(right.created_at || ""))),
    distribution: {
      campaigns,
      messages,
      summary: {
        drafts: messageCount(["drafted", "queued"]),
        sent: messageCount(["sent", "replied"]),
        failed: messageCount(["failed", "bounced"]),
        accessed,
        quoted
      }
    },
    readiness: evaluateRatebookReadiness(context.package_lanes)
  };
}

async function getRatebookRouteQuotes(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  input: Record<string, unknown>
) {
  const ratebook = await requireOwnedRatebook(supabase, user, input.ratebook_id || input.id);
  const packageLaneId = cleanText(input.package_lane_id);
  if (!packageLaneId || !UUID_PATTERN.test(packageLaneId)) throw new Error("A valid Ratebook route is required.");
  const packageLaneResult = await supabase.from("rfx_package_lanes").select("id,demand_lane_id,rfx_demand_lanes(*)")
    .eq("id", packageLaneId).eq("package_id", ratebook.rfx_package_id).maybeSingle();
  if (packageLaneResult.error) throw packageLaneResult.error;
  if (!packageLaneResult.data) throw new Error("This route is not part of the selected Ratebook.");
  const [quotesResult, reviewsResult] = await Promise.all([
    supabase.from("rfx_ratebook_carrier_quotes")
      .select("id,vendor_id,package_lane_id,status,all_in_rate,currency,weekly_capacity,transit_days,valid_until,quote_reference,notes,revision_number,updated_at")
      .eq("ratebook_id", ratebook.id).eq("package_lane_id", packageLaneId).eq("status", "submitted")
      .order("all_in_rate", { ascending: true }).order("updated_at", { ascending: false }),
    supabase.from("rfx_ratebook_quote_reviews")
      .select("quote_id,decision,decision_note,decided_at,decided_by_email,updated_at")
      .eq("ratebook_id", ratebook.id).eq("package_lane_id", packageLaneId)
  ]);
  if (quotesResult.error) throw quotesResult.error;
  if (reviewsResult.error) throw reviewsResult.error;
  const quotes = (quotesResult.data || []) as Record<string, unknown>[];
  const vendorIds = quotes.map((quote) => cleanText(quote.vendor_id)).filter(Boolean) as string[];
  const vendorsResult = vendorIds.length
    ? await supabase.from("vendors").select("id,vendor_name,domain,primary_email").eq("owner_email", user.owner_email).in("id", vendorIds)
    : { data: [], error: null };
  if (vendorsResult.error) throw vendorsResult.error;
  const vendorsById = new Map<string, Record<string, unknown>>();
  ((vendorsResult.data || []) as Record<string, unknown>[]).forEach((vendor) => {
    const vendorId = cleanText(vendor.id);
    if (vendorId) vendorsById.set(vendorId, vendor);
  });
  const reviewsByQuoteId = new Map<string, Record<string, unknown>>();
  ((reviewsResult.data || []) as Record<string, unknown>[]).forEach((review) => {
    const quoteId = cleanText(review.quote_id);
    if (quoteId) reviewsByQuoteId.set(quoteId, review);
  });
  const demandLane = objectRecord(packageLaneResult.data.rfx_demand_lanes);
  return {
    ratebook_id: ratebook.id,
    route: {
      package_lane_id: packageLaneId,
      transaction_id: cleanText(demandLane.lane_key) || packageLaneId,
      origin: firstCleanText(demandLane.origin, [demandLane.origin_city, demandLane.origin_state].filter(Boolean).join(", ")),
      destination: firstCleanText(demandLane.destination, [demandLane.destination_city, demandLane.destination_state].filter(Boolean).join(", ")),
      currency: cleanText(demandLane.currency)
    },
    quotes: quotes.map((quote) => ({
      ...quote,
      vendor: vendorsById.get(mapLookupKey(quote.vendor_id)) || null,
      review: reviewsByQuoteId.get(mapLookupKey(quote.id)) || { decision: "pending" }
    }))
  };
}

async function updateRatebookQuoteReview(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null; organization_id?: string | null },
  input: Record<string, unknown>
) {
  const ratebook = await requireOwnedRatebook(supabase, user, input.ratebook_id || input.id);
  const quoteId = cleanText(input.quote_id);
  if (!quoteId || !UUID_PATTERN.test(quoteId)) throw new Error("A valid carrier offer is required.");
  const decision = cleanText(input.decision)?.toLowerCase() || "pending";
  if (!["pending", "shortlisted", "not_selected"].includes(decision)) {
    throw new Error("Choose pending, shortlisted, or not selected for this carrier offer.");
  }
  const decisionNote = cleanText(input.decision_note || input.note);
  if (decisionNote && decisionNote.length > 4000) throw new Error("Review note must be 4,000 characters or less.");
  const quoteResult = await supabase.from("rfx_ratebook_carrier_quotes")
    .select("id,ratebook_id,package_lane_id,vendor_id,status")
    .eq("id", quoteId).eq("ratebook_id", ratebook.id).maybeSingle();
  if (quoteResult.error) throw quoteResult.error;
  const quote = quoteResult.data as Record<string, unknown> | null;
  if (!quote || cleanText(quote.status) !== "submitted") {
    throw new Error("This carrier offer is no longer available for Ratebook review.");
  }
  const now = new Date().toISOString();
  const reviewRow = {
    ...withOwner({
      ratebook_id: ratebook.id,
      package_lane_id: quote.package_lane_id,
      quote_id: quote.id,
      vendor_id: quote.vendor_id,
      decision,
      decision_note: decisionNote || null,
      decided_at: decision === "pending" ? null : now,
      decided_by_email: decision === "pending" ? null : user.owner_email,
      metadata: { source: "ratebook_quote_review", decision_updated_at: now },
      updated_at: now
    }, user),
    organization_id: user.organization_id || null
  };
  const result = await supabase.from("rfx_ratebook_quote_reviews")
    .upsert(reviewRow, { onConflict: "quote_id" }).select().single();
  if (result.error) throw result.error;
  const context = await getOwnedRatebookPackage(supabase, user, ratebook.rfx_package_id);
  await writeRfxProcessAudit(supabase, user, context.project.id, `ratebook_quote_${decision}`, "rfx_ratebook_carrier_quotes", quote.id,
    `${decision === "shortlisted" ? "Shortlisted" : decision === "not_selected" ? "Marked not selected" : "Reset review for"} a carrier Ratebook offer.`, {
      ratebook_id: ratebook.id,
      package_lane_id: quote.package_lane_id,
      vendor_id: quote.vendor_id,
      decision
    });
  return { review: result.data };
}

async function getRatebookRouteDetail(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  input: Record<string, unknown>
) {
  const ratebook = await requireOwnedRatebook(supabase, user, input.ratebook_id);
  const sourceDemandLaneId = cleanText(input.source_demand_lane_id || input.demand_lane_id);
  if (!sourceDemandLaneId || !UUID_PATTERN.test(sourceDemandLaneId)) throw new Error("A valid Ratebook route is required.");
  const packageLaneResult = await supabase.from("rfx_package_lanes").select("id")
    .eq("package_id", ratebook.rfx_package_id).eq("demand_lane_id", sourceDemandLaneId).maybeSingle();
  if (packageLaneResult.error) throw packageLaneResult.error;
  if (!packageLaneResult.data) throw new Error("This route is not part of the selected Ratebook.");
  const laneResult = await supabase.from("rfx_demand_lanes").select("*")
    .eq("id", sourceDemandLaneId).eq("project_id", ratebook.project_id).eq("owner_email", user.owner_email).single();
  if (laneResult.error) throw laneResult.error;
  const lane = laneResult.data as Record<string, unknown>;
  const rfiLaneId = cleanText(lane.source_rfi_lane_id);
  const rfiResult = rfiLaneId
    ? await supabase.from("rfx_rfi_lanes").select("*").eq("id", rfiLaneId).eq("project_id", ratebook.project_id).eq("owner_email", user.owner_email).maybeSingle()
    : { data: null, error: null };
  if (rfiResult.error) throw rfiResult.error;
  const detail = {
    logistics_model: rfxDemandLaneDetail(lane, "logistics_model"),
    operation_criteria: rfxDemandLaneDetail(lane, "operation_criteria"),
    business_rules: rfxDemandLaneDetail(lane, "business_rules"),
    service_specifications: rfxDemandLaneDetail(lane, "service_specifications"),
    carrier_requirements: rfxDemandLaneDetail(lane, "carrier_requirements"),
    other_notes: rfxDemandLaneDetail(lane, "other_notes")
  };
  return { ratebook_id: ratebook.id, demand_lane: lane, rfi_lane: rfiResult.data || null, detail };
}

async function listRatebookCarriers(
  supabase: RatewareSupabaseClient,
  user: { owner_email: string | null },
  input: Record<string, unknown>
) {
  await requireOwnedRatebook(supabase, user, input.ratebook_id);
  const search = safeShipperSearch(input.search);
  const limit = Math.min(Math.max(Number(input.limit) || 1000, 1), 1000);
  const offset = Math.max(Number(input.offset) || 0, 0);
  let query = supabase.from("vendors")
    .select("id,vendor_name,domain,primary_email,whatsapp_phone,preferred_channel,base_stage,status,tags,coverage_notes", { count: "exact" })
    .eq("owner_email", user.owner_email)
    .or("base_stage.is.null,base_stage.neq.archived");
  if (search) query = query.or(vendorSearchClauses(search).join(","));
  const result = await query.order("vendor_name", { ascending: true }).range(offset, offset + limit - 1);
  if (result.error) throw result.error;
  const rows = (result.data || []) as Record<string, unknown>[];
  const total = Number(result.count ?? rows.length);
  return {
    rows,
    total,
    offset,
    limit,
    has_more: offset + rows.length < total
  };
}

async function shareRatebookWithCarriers(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null; organization_id?: string | null },
  input: Record<string, unknown>
) {
  const ratebook = await requireOwnedRatebook(supabase, user, input.ratebook_id);
  if (ratebookLifecycleStatus(ratebook.lifecycle_status) !== "published") {
    throw new Error("Publish this Ratebook before distributing private carrier links.");
  }
  const vendorIds = normalizeBulkIds(input.vendor_ids || input.vendorIds, { label: "Carrier ids", limit: 1000 });
  if (!vendorIds.length) throw new Error("Select at least one Carrier CRM record to share this Ratebook.");
  const context = await getOwnedRatebookPackage(supabase, user, ratebook.rfx_package_id);
  if (!context.package_lanes.length) throw new Error("This Ratebook has no routes to share.");
  const vendorsResult = await supabase.from("vendors")
    .select("id,vendor_name,domain,primary_email")
    .eq("owner_email", user.owner_email)
    .in("id", vendorIds);
  if (vendorsResult.error) throw vendorsResult.error;
  const vendors = (vendorsResult.data || []) as Record<string, unknown>[];
  if (vendors.length !== vendorIds.length) throw new Error("One or more selected Carrier CRM records are no longer available.");
  const now = new Date().toISOString();
  const generatedLinks = await Promise.all(vendors.map(async (vendor) => {
    const token = ratebookCarrierAccessToken();
    return {
      vendor,
      token,
      row: {
      ...withOwner({
        ratebook_id: ratebook.id,
        vendor_id: vendor.id,
        primary_rfx_lane_vendor_id: null,
        status: "active",
        access_token_hash: await hashRatebookCarrierAccessToken(token),
        access_token_last4: token.slice(-4),
        access_granted_at: now,
        access_revoked_at: null,
        metadata: { shared_at: now, shared_from: "ratebook", delivery_mode: "private_ratebook_link" },
        updated_at: now
      }, user),
      organization_id: user.organization_id || null
      }
    };
  }));
  const shareRows = generatedLinks.map((link) => link.row);
  const shares = await supabase.from("rfx_ratebook_shares")
    .upsert(shareRows, { onConflict: "ratebook_id,vendor_id" }).select("id,vendor_id,status,access_token_last4,access_granted_at");
  if (shares.error) throw shares.error;
  const activeSharesResult = await supabase.from("rfx_ratebook_shares").select("id")
    .eq("ratebook_id", ratebook.id).eq("status", "active");
  if (activeSharesResult.error) throw activeSharesResult.error;
  const bookUpdate = await supabase.from("rfx_ratebooks").update({
    status: "shared",
    shared_carrier_count: (activeSharesResult.data || []).length,
    updated_at: now
  }).eq("id", ratebook.id).eq("owner_email", user.owner_email).select().single();
  if (bookUpdate.error) throw bookUpdate.error;
  const appOrigin = ratebookOrigin(input);
  const sharesByVendorId = new Map(((shares.data || []) as Record<string, unknown>[]).map((share) => [cleanText(share.vendor_id), share]));
  const magic_links = generatedLinks.map(({ vendor, token }) => {
    const share = sharesByVendorId.get(cleanText(vendor.id)) || {};
    return {
      share_id: cleanText(share.id),
      vendor_id: vendor.id,
      vendor_name: vendor.vendor_name,
      email: vendor.primary_email,
      access_token_created: true,
      url: `${appOrigin}/ratebook-carrier.html?token=${encodeURIComponent(token)}`
    };
  });
  await writeRfxProcessAudit(supabase, user, context.project.id, "ratebook_shared", "rfx_ratebooks", ratebook.id,
    `Shared Ratebook ${cleanText(ratebook.name) || ratebook.id} with ${vendors.length} carrier(s).`, {
      rfx_package_id: context.pack.id,
      carrier_count: vendors.length,
      route_count: context.package_lanes.length,
      delivery_mode: "private_ratebook_link"
    });
  return {
    ratebook: bookUpdate.data,
    carriers_shared: vendors.length,
    carrier_links_rotated: generatedLinks.length,
    magic_links
  };
}

function ratebookDistributionCopy(ratebook: Record<string, unknown>, link: Record<string, unknown>) {
  const ratebookName = cleanText(ratebook.name) || "Ratebook";
  const carrierName = cleanText(link.vendor_name) || "Carrier";
  const privateUrl = cleanText(link.url);
  const subject = `Ratebook invitation | ${ratebookName}`;
  const textBody = [
    `Hello ${carrierName},`,
    "",
    `You have been invited to review and quote the asynchronous Ratebook: ${ratebookName}.`,
    "This private link is assigned to your Carrier CRM profile. You can review the route book and submit or update offers at any time while the Ratebook remains active.",
    "",
    `Open your private Ratebook: ${privateUrl}`,
    "",
    "Thank you,",
    "Rateware Procurement"
  ].join("\n");
  return {
    subject,
    text_body: textBody,
    html_body: `<p>Hello ${escapeHtmlText(carrierName)},</p><p>You have been invited to review and quote the asynchronous <strong>${escapeHtmlText(ratebookName)}</strong> Ratebook.</p><p>This private link is assigned to your Carrier CRM profile. You can review the route book and submit or update offers while the Ratebook remains active.</p><p><a href="${escapeHtmlText(privateUrl)}">Open your private Ratebook</a></p><p>Thank you,<br>Rateware Procurement</p>`
  };
}

async function queueRatebookDistribution(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null; organization_id?: string | null },
  input: Record<string, unknown>
) {
  const ratebook = await requireOwnedRatebook(supabase, user, input.ratebook_id || input.id);
  if (ratebookLifecycleStatus(ratebook.lifecycle_status) !== "published") {
    throw new Error("Publish this Ratebook before creating its delivery queue.");
  }
  const shared = await shareRatebookWithCarriers(supabase, user, { ...input, ratebook_id: ratebook.id });
  const magicLinks = Array.isArray(shared.magic_links) ? shared.magic_links as Record<string, unknown>[] : [];
  const deliverableLinks = magicLinks.filter((link) => cleanText(link.share_id) && cleanText(link.email));
  if (!deliverableLinks.length) {
    return { ...shared, campaign: null, message_ids: [], queued: 0, skipped_missing_email: magicLinks.length };
  }
  const existingCampaignResult = await supabase.from("outreach_campaigns")
    .select("id,name,status")
    .eq("owner_email", user.owner_email)
    .eq("ratebook_id", ratebook.id)
    .neq("status", "archived")
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (existingCampaignResult.error) throw existingCampaignResult.error;
  const now = new Date().toISOString();
  let campaign = existingCampaignResult.data as Record<string, unknown> | null;
  if (!campaign) {
    const campaignResult = await supabase.from("outreach_campaigns").insert(withOwner({
      rfx_event_id: ratebook.rfx_event_id || null,
      ratebook_id: ratebook.id,
      name: `Ratebook delivery | ${cleanText(ratebook.name) || ratebook.id}`,
      channel: "email",
      status: "generated",
      notes: "Controlled Ratebook distribution. Each message is tied to one private carrier share.",
      sender_email: GMAIL_ALLOWED_SENDER,
      sender_label: "Rateware Procurement",
      sender_connection_status: "draft_only"
    }, user)).select("id,name,status").single();
    if (campaignResult.error) throw campaignResult.error;
    campaign = campaignResult.data as Record<string, unknown>;
  }
  const campaignId = cleanText(campaign.id);
  const shareIds = deliverableLinks.map((link) => cleanText(link.share_id)).filter(Boolean) as string[];
  const pendingResult = await supabase.from("outreach_messages")
    .select("id,ratebook_share_id,status")
    .eq("owner_email", user.owner_email)
    .eq("campaign_id", campaignId)
    .eq("channel", "email")
    .in("ratebook_share_id", shareIds)
    .in("status", ["drafted", "queued", "failed"]);
  if (pendingResult.error) throw pendingResult.error;
  const existingByShareId = new Map(((pendingResult.data || []) as Record<string, unknown>[]).map((row) => [cleanText(row.ratebook_share_id), row]));
  const messageRows = deliverableLinks.map((link) => {
    const existing = existingByShareId.get(cleanText(link.share_id));
    const copy = ratebookDistributionCopy(ratebook, link);
    return withOwner({
      ...(existing ? { id: existing.id } : {}),
      campaign_id: campaignId,
      rfx_event_id: ratebook.rfx_event_id || null,
      vendor_id: link.vendor_id,
      ratebook_share_id: link.share_id,
      channel: "email",
      recipient_email: cleanText(link.email)?.toLowerCase(),
      subject: copy.subject,
      html_body: copy.html_body,
      text_body: copy.text_body,
      status: "drafted",
      sender_email: GMAIL_ALLOWED_SENDER,
      sender_label: "Rateware Procurement",
      sender_connection_status: "draft_only",
      delivery_error: null,
      metadata: {
        source: "ratebook_distribution",
        ratebook_id: ratebook.id,
        ratebook_share_id: link.share_id,
        ratebook_version: Number(ratebook.version_number) || 1,
        private_ratebook_url: cleanText(link.url),
        regenerated_at: now
      },
      updated_at: now
    }, user);
  });
  const messagesResult = await supabase.from("outreach_messages").upsert(messageRows).select("id,ratebook_share_id,recipient_email,status");
  if (messagesResult.error) throw messagesResult.error;
  const campaignUpdate = await supabase.from("outreach_campaigns")
    .update({ status: "generated", updated_at: now })
    .eq("id", campaignId).eq("owner_email", user.owner_email);
  if (campaignUpdate.error) throw campaignUpdate.error;
  const context = await getOwnedRatebookPackage(supabase, user, ratebook.rfx_package_id);
  await writeRfxProcessAudit(supabase, user, context.project.id, "ratebook_distribution_queued", "outreach_campaigns", campaignId,
    `Generated ${messageRows.length} controlled Ratebook delivery draft(s).`, {
      ratebook_id: ratebook.id,
      campaign_id: campaignId,
      carrier_count: messageRows.length,
      skipped_missing_email: magicLinks.length - deliverableLinks.length
    });
  return {
    ...shared,
    campaign,
    message_ids: (messagesResult.data || []).map((row: Record<string, unknown>) => row.id),
    queued: messageRows.length,
    skipped_missing_email: magicLinks.length - deliverableLinks.length
  };
}

async function sendRatebookDistribution(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null; organization_id?: string | null },
  input: Record<string, unknown>
) {
  const ratebook = await requireOwnedRatebook(supabase, user, input.ratebook_id || input.id);
  const messageIds = normalizeBulkIds(input.ids, { label: "Ratebook delivery message ids", limit: BULK_SEND_LIMIT });
  if (!messageIds.length) throw new Error("Select at least one Ratebook email draft to send.");
  const messagesResult = await supabase.from("outreach_messages")
    .select("id,campaign_id,ratebook_share_id,channel")
    .eq("owner_email", user.owner_email)
    .in("id", messageIds);
  if (messagesResult.error) throw messagesResult.error;
  const messages = (messagesResult.data || []) as Record<string, unknown>[];
  if (messages.length !== messageIds.length || messages.some((message) => cleanText(message.channel) !== "email" || !cleanText(message.ratebook_share_id))) {
    throw new Error("Every selected row must be an email draft created for this Ratebook.");
  }
  const campaignIds = [...new Set(messages.map((message) => cleanText(message.campaign_id)).filter(Boolean))];
  const campaignResult = await supabase.from("outreach_campaigns")
    .select("id,ratebook_id")
    .eq("owner_email", user.owner_email)
    .eq("ratebook_id", ratebook.id)
    .in("id", campaignIds);
  if (campaignResult.error) throw campaignResult.error;
  if ((campaignResult.data || []).length !== campaignIds.length) {
    throw new Error("Ratebook delivery drafts must belong to the selected Ratebook campaign.");
  }
  const result = await sendOutreachMessages(supabase, user, {
    ...input,
    ids: messageIds,
    confirmation_action: "send_outreach_messages"
  });
  const context = await getOwnedRatebookPackage(supabase, user, ratebook.rfx_package_id);
  await writeRfxProcessAudit(supabase, user, context.project.id, "ratebook_distribution_sent", "rfx_ratebooks", ratebook.id,
    `Sent ${Number(result.sent) || 0} Ratebook delivery email(s).`, {
      campaign_ids: campaignIds,
      sent: result.sent,
      failed: result.failed
    });
  return result;
}

async function syncShipperOpportunityFromImplementationReadyAward(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null },
  projectId: unknown,
  awardId: unknown
) {
  const projectRef = cleanText(projectId);
  if (!projectRef) return null;
  const result = await supabase.from("shipper_opportunities")
    .update({
      stage: "won",
      probability: 100,
      next_action: "Begin award implementation and commercial onboarding.",
      updated_at: new Date().toISOString()
    })
    .eq("owner_email", user.owner_email)
    .eq("rfx_project_id", projectRef)
    .not("stage", "in", '("lost","archived")')
    .select("id,shipper_id,opportunity_name,stage,probability,rfx_project_id")
    .maybeSingle();
  if (result.error) throw result.error;
  if (!result.data) return null;
  await writeAuditLog(
    supabase,
    user,
    "shipper_opportunity_won_from_rfx_award",
    "shipper_opportunity",
    result.data.id,
    `Marked shipper opportunity ${cleanText(result.data.opportunity_name) || result.data.id} as won from an implementation-ready RFx award.`,
    { rfx_project_id: projectRef, rfx_award_package_id: cleanText(awardId) }
  );
  return result.data as Record<string, unknown>;
}

async function createRfxAwardPackage(supabase: RatewareSupabaseClient, user: { owner_user_id: string | null; owner_email: string | null }, input: Record<string, unknown>) {
  const project = await requireOwnedRfxProcessProject(supabase, user, input.project_id || input.id);
  const scenarioType = cleanText(input.scenario_type || input.scenarioType)?.toLowerCase() || "best_value";
  const status = cleanText(input.status)?.toLowerCase() || "draft";
  const awardRow = withOwner({
    project_id: project.id,
    rfx_package_id: cleanText(input.rfx_package_id || input.package_id),
    linked_rfx_event_id: cleanText(input.linked_rfx_event_id || project.linked_rfx_event_id),
    scenario_name: cleanText(input.scenario_name || input.name) || "Primary award scenario",
    scenario_type: ["cheapest", "best_value", "primary_backup", "capacity_split", "incumbent_comparison"].includes(scenarioType) ? scenarioType : "best_value",
    status: ["draft", "approved", "implementation_ready", "archived"].includes(status) ? status : "draft",
    evaluation_summary: objectRecord(input.evaluation_summary || input.evaluationSummary),
    implementation_checklist: objectRecord(input.implementation_checklist || input.implementationChecklist),
    approved_at: ["approved", "implementation_ready"].includes(status) ? new Date().toISOString() : null,
    notes: cleanText(input.notes)
  }, user);
  const awardInsert = await supabase.from("rfx_award_packages").insert(awardRow).select().single();
  if (awardInsert.error) throw awardInsert.error;
  const lines = Array.isArray(input.lines) ? input.lines : [];
  const lineRows = lines.slice(0, 1000).map((line: Record<string, unknown>) => withOwner({
    award_package_id: awardInsert.data.id,
    lane_id: cleanText(line.lane_id || line.laneId),
    awarded_carrier_id: cleanText(line.awarded_carrier_id || line.awardedCarrierId),
    backup_carrier_id: cleanText(line.backup_carrier_id || line.backupCarrierId),
    awarded_rate: cleanNumber(line.awarded_rate || line.awardedRate),
    currency: cleanText(line.currency),
    awarded_capacity: cleanNumber(line.awarded_capacity || line.awardedCapacity),
    service_requirements: objectRecord(line.service_requirements || line.serviceRequirements),
    accessorials: objectRecord(line.accessorials),
    accepted_exceptions: Array.isArray(line.accepted_exceptions) ? line.accepted_exceptions : [],
    implementation_notes: cleanText(line.implementation_notes || line.implementationNotes),
    status: cleanText(line.status) || "draft"
  }, user));
  for (const batch of chunkValues(lineRows, 500)) {
    const insert = await supabase.from("rfx_award_package_lanes").insert(batch).select("id");
    if (insert.error) throw insert.error;
  }
  let shipperOpportunity: Record<string, unknown> | null = null;
  if (awardRow.status === "implementation_ready") {
    const projectUpdate = await supabase.from("rfx_projects")
      .update({ status: "implementation_ready", updated_at: new Date().toISOString() })
      .eq("id", project.id)
      .eq("owner_email", user.owner_email);
    if (projectUpdate.error) throw projectUpdate.error;
    shipperOpportunity = await syncShipperOpportunityFromImplementationReadyAward(supabase, user, project.id, awardInsert.data.id);
  }
  await writeRfxProcessAudit(supabase, user, project.id, "award_scenario_created", "rfx_award_packages", awardInsert.data.id, `Created RFx Award Package ${awardInsert.data.scenario_name}`, {
    scenario_type: awardInsert.data.scenario_type,
    lines: lineRows.length,
    shipper_opportunity_id: shipperOpportunity?.id || null
  });
  return { row: awardInsert.data, lines: lineRows.length, shipper_opportunity: shipperOpportunity };
}

async function markRfxAwardPackageImplementationReady(
  supabase: RatewareSupabaseClient,
  user: { owner_user_id: string | null; owner_email: string | null },
  input: Record<string, unknown>
) {
  const awardId = cleanText(input.award_package_id || input.id);
  if (!awardId || !UUID_PATTERN.test(awardId)) throw new Error("A valid RFx Award Package id is required.");
  const awardResult = await supabase.from("rfx_award_packages").select("*")
    .eq("owner_email", user.owner_email)
    .eq("id", awardId)
    .single();
  if (awardResult.error) throw awardResult.error;
  const award = awardResult.data as Record<string, unknown>;
  if (cleanText(award.status)?.toLowerCase() === "archived") {
    throw new Error("Archived award packages cannot be marked implementation ready.");
  }
  const project = await requireOwnedRfxProcessProject(supabase, user, award.project_id);
  await validateRfxProjectStatusChange(supabase, project.id, "implementation_ready");
  const now = new Date().toISOString();
  const awardUpdate = await supabase.from("rfx_award_packages")
    .update({
      status: "implementation_ready",
      approved_at: cleanText(award.approved_at) || now,
      updated_at: now
    })
    .eq("owner_email", user.owner_email)
    .eq("id", awardId)
    .select()
    .single();
  if (awardUpdate.error) throw awardUpdate.error;
  const projectUpdate = await supabase.from("rfx_projects")
    .update({ status: "implementation_ready", updated_at: now })
    .eq("owner_email", user.owner_email)
    .eq("id", project.id);
  if (projectUpdate.error) throw projectUpdate.error;
  const shipperOpportunity = await syncShipperOpportunityFromImplementationReadyAward(supabase, user, project.id, awardId);
  await writeRfxProcessAudit(
    supabase,
    user,
    project.id,
    "award_package_implementation_ready",
    "rfx_award_packages",
    awardId,
    `Marked RFx Award Package ${cleanText(awardUpdate.data.scenario_name) || awardId} implementation ready.`,
    { shipper_opportunity_id: shipperOpportunity?.id || null }
  );
  return { row: awardUpdate.data, project_id: project.id, shipper_opportunity: shipperOpportunity };
}

Deno.serve(async (request) => {
  const requestStartedAt = performance.now();
  const jsonResponse = (body: unknown, status = 200) => baseJsonResponse(body, status, request);
  if (request.method === "OPTIONS") return new Response("ok", { headers: corsHeaders(request) });

  let auditSupabase: RatewareSupabaseClient | null = null;
  let auditUser: RatewareUser | null = null;
  let body: Record<string, unknown> = {};

  try {
    const supabase = getClient();
    auditSupabase = supabase;
    const authenticationStartedAt = performance.now();
    const user = await resolveWorkspaceUser(
      supabase,
      workspaceUserContext(await requireKindeUser(request)),
      { persistIdentity: false }
    );
    const authenticationCompletedAt = performance.now();
    auditUser = user;
    body = await request.json();
    const bodyParsedAt = performance.now();

    const growthAction = typeof body.action === "string" ? body.action : "";
    if (isGrowthAction(growthAction)) {
      return jsonResponse(await handleGrowthAction(supabase, user, body));
    }

    if (body.action === "list_rfx_process_projects") {
      return jsonResponse(await listRfxProcessProjects(supabase, user, body));
    }

    if (body.action === "create_rfx_process_project") {
      const row = withOwner(normalizeRfxProjectInput(objectRecord(body.project || body)), user);
      const result = await supabase.from("rfx_projects").insert(row).select().single();
      if (result.error) throw result.error;
      await writeRfxProcessAudit(
        supabase,
        user,
        result.data.id,
        "rfx_project_created",
        "rfx_projects",
        result.data.id,
        `Created RFx Project ${result.data.title}`,
        { status: result.data.status, opportunity_type: result.data.opportunity_type }
      );
      return jsonResponse({ row: result.data });
    }

    if (body.action === "get_rfx_process_project") {
      return jsonResponse(await getRfxProcessProjectDetail(supabase, user, body.project_id || body.id, body.app_origin || body.appOrigin));
    }

    if (body.action === "update_rfx_process_project") {
      const project = await requireOwnedRfxProcessProject(supabase, user, body.project_id || body.id);
      const patch = normalizeRfxProjectPatch(objectRecord(body.patch || body.project || body));
      if (patch.status) await validateRfxProjectStatusChange(supabase, project.id, patch.status);
      const result = await supabase
        .from("rfx_projects")
        .update(patch)
        .eq("id", project.id)
        .eq("owner_email", user.owner_email)
        .select()
        .single();
      if (result.error) throw result.error;
      await writeRfxProcessAudit(
        supabase,
        user,
        project.id,
        "rfx_project_updated",
        "rfx_projects",
        project.id,
        `Updated RFx Project ${result.data.title}`,
        { changed_fields: Object.keys(patch), status: result.data.status }
      );
      return jsonResponse({ row: result.data });
    }

    if (body.action === "save_rfx_process_rfi") {
      return jsonResponse(await saveRfxProcessRfi(supabase, user, body));
    }

    if (body.action === "create_rfx_rfi_magic_link") {
      return jsonResponse(await createRfxRfiMagicLink(supabase, user, body));
    }

    if (body.action === "revoke_rfx_rfi_magic_link") {
      const linkId = cleanText(body.link_id || body.id);
      if (!linkId) return jsonResponse({ error: "RFI magic link id is required." }, 400);
      const linkResult = await supabase
        .from("rfx_rfi_magic_links")
        .select("id,project_id,rfx_projects!inner(id,title,owner_email)")
        .eq("id", linkId)
        .eq("rfx_projects.owner_email", user.owner_email)
        .single();
      if (linkResult.error) throw linkResult.error;
      const result = await supabase
        .from("rfx_rfi_magic_links")
        .update({ status: "revoked", revoked_at: new Date().toISOString(), updated_at: new Date().toISOString() })
        .eq("id", linkId)
        .select("id,project_id,status,revoked_at,expires_at")
        .single();
      if (result.error) throw result.error;
      await writeRfxProcessAudit(
        supabase,
        user,
        result.data.project_id,
        "rfi_magic_link_revoked",
        "rfx_rfi_magic_links",
        result.data.id,
        "Revoked Customer RFI magic link",
        {}
      );
      return jsonResponse({ row: result.data });
    }

    if (body.action === "reopen_rfx_rfi") {
      const project = await requireOwnedRfxProcessProject(supabase, user, body.project_id || body.id);
      const result = await supabase
        .from("rfx_rfi_submissions")
        .update({ status: "reopened", reopened_at: new Date().toISOString(), updated_at: new Date().toISOString() })
        .eq("project_id", project.id)
        .select()
        .single();
      if (result.error) throw result.error;
      await supabase
        .from("rfx_projects")
        .update({ status: "rfi_in_progress", updated_at: new Date().toISOString() })
        .eq("id", project.id)
        .eq("owner_email", user.owner_email);
      await writeRfxProcessAudit(
        supabase,
        user,
        project.id,
        "rfi_reopened",
        "rfx_rfi_submissions",
        result.data.id,
        "Reopened submitted Customer RFI for customer edits",
        {}
      );
      return jsonResponse({ row: result.data });
    }

    if (body.action === "create_rfx_demand_snapshot") {
      return jsonResponse(await createRfxDemandSnapshot(supabase, user, body));
    }

    if (body.action === "create_rfx_package") {
      return jsonResponse(await createRfxProcessPackage(supabase, user, body));
    }

    if (body.action === "launch_rfx_package_to_bid_room") {
      return jsonResponse(await launchRfxProcessPackageToBidRoom(supabase, user, body));
    }

    if (body.action === "list_ratebooks") {
      return jsonResponse(await listRatebooks(supabase, user, body));
    }

    if (body.action === "export_ratebook_routes") {
      return jsonResponse(await exportRatebookRoutes(supabase, user, body));
    }

    if (body.action === "get_ratebook") {
      return jsonResponse(await getRatebook(supabase, user, body));
    }

    if (body.action === "get_ratebook_route_detail") {
      return jsonResponse(await getRatebookRouteDetail(supabase, user, body));
    }

    if (body.action === "get_ratebook_route_quotes") {
      return jsonResponse(await getRatebookRouteQuotes(supabase, user, body));
    }

    if (body.action === "update_ratebook_quote_review") {
      return jsonResponse(await updateRatebookQuoteReview(supabase, user, body));
    }

    if (body.action === "list_ratebook_carriers") {
      return jsonResponse(await listRatebookCarriers(supabase, user, body));
    }

    if (body.action === "share_ratebook_with_carriers") {
      return jsonResponse(await shareRatebookWithCarriers(supabase, user, body));
    }

    if (body.action === "queue_ratebook_distribution") {
      return jsonResponse(await queueRatebookDistribution(supabase, user, body));
    }

    if (body.action === "send_ratebook_distribution") {
      return jsonResponse(await sendRatebookDistribution(supabase, user, body));
    }

    if (body.action === "get_ratebook_audit") {
      return jsonResponse(await getRatebookAudit(supabase, user, body));
    }

    if (body.action === "get_ratebook_health") {
      return jsonResponse(await getRatebookHealth(supabase, user));
    }

    if (body.action === "create_ratebook_revision") {
      return jsonResponse(await createRatebookRevision(supabase, user, body));
    }

    if (body.action === "publish_ratebook") {
      return jsonResponse(await updateRatebookLifecycle(supabase, user, body, "published"));
    }

    if (body.action === "archive_ratebook") {
      requireBulkConfirmation(body, {
        action: "archive_ratebook",
        label: "Ratebook archive",
        count: 1
      });
      return jsonResponse(await updateRatebookLifecycle(supabase, user, body, "archived"));
    }

    if (body.action === "supersede_ratebook") {
      return jsonResponse(await updateRatebookLifecycle(supabase, user, body, "superseded"));
    }

    if (body.action === "create_rfx_award_package") {
      return jsonResponse(await createRfxAwardPackage(supabase, user, body));
    }

    if (body.action === "mark_rfx_award_package_implementation_ready") {
      return jsonResponse(await markRfxAwardPackageImplementationReady(supabase, user, body));
    }

    if (body.action === "shipper_crm_summary") {
      const scopedCount = (configure: (query: any) => any = (query) => query) => configure(
        supabase.from("shippers").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email)
      );
      const [total, active, prospects, missingContact, opportunities] = await Promise.all([
        scopedCount((query) => query.neq("status", "archived")),
        scopedCount((query) => query.eq("status", "active")),
        scopedCount((query) => query.eq("status", "prospect")),
        scopedCount((query) => query.neq("status", "archived").is("primary_contact_email", null)),
        supabase.from("shipper_opportunities").select("id", { count: "exact", head: true })
          .eq("owner_email", user.owner_email).not("stage", "in", '("won","lost","archived")')
      ]);
      for (const result of [total, active, prospects, missingContact, opportunities]) {
        if (result.error) throw result.error;
      }
      return jsonResponse({
        total: total.count || 0,
        active: active.count || 0,
        prospects: prospects.count || 0,
        missing_contact: missingContact.count || 0,
        open_opportunities: opportunities.count || 0
      });
    }

    if (body.action === "list_shippers") {
      const offset = Math.max(Number(body.offset) || 0, 0);
      const limit = Math.min(Math.max(Number(body.limit) || 100, 1), 250);
      const search = safeShipperSearch(body.search);
      let query = supabase
        .from("shippers")
        .select("id,shipper_name,legal_name,domain,website,logo_url,industry,status,relationship_stage,segment,revenue_tier,account_owner_email,primary_contact_name,primary_contact_email,primary_contact_phone,headquarters_city,headquarters_state,headquarters_country,tags,notes,source,created_at,updated_at,shipper_account_actions(title,status,priority,due_date,created_at)", { count: "exact" })
        .eq("owner_email", user.owner_email)
        .order(cleanText(body.sort_by) === "shipper_name" ? "shipper_name" : "updated_at", { ascending: cleanText(body.sort_direction)?.toLowerCase() === "asc" })
        .range(offset, offset + limit - 1);
      const status = cleanText(body.status)?.toLowerCase();
      const relationshipStage = cleanText(body.relationship_stage)?.toLowerCase();
      const segment = cleanText(body.segment);
      if (status && status !== "all") query = query.eq("status", status);
      else query = query.neq("status", "archived");
      if (relationshipStage && relationshipStage !== "all") query = query.eq("relationship_stage", relationshipStage);
      if (segment && segment.toLowerCase() !== "all") query = query.eq("segment", segment);
      query = query.in("shipper_account_actions.status", ["open", "in_progress"]);
      if (search) {
        query = query.or([
          `shipper_name.ilike.%${search}%`,
          `legal_name.ilike.%${search}%`,
          `domain.ilike.%${search}%`,
          `industry.ilike.%${search}%`,
          `primary_contact_name.ilike.%${search}%`,
          `primary_contact_email.ilike.%${search}%`,
          `headquarters_city.ilike.%${search}%`,
          `headquarters_state.ilike.%${search}%`,
          `notes.ilike.%${search}%`
        ].join(","));
      }
      const result = await query;
      if (result.error) throw result.error;
      const shippers = (result.data || []) as Record<string, unknown>[];
      const today = new Date().toISOString().slice(0, 10);
      const rows = shippers.map((shipper) => {
        const actions = (Array.isArray(shipper.shipper_account_actions)
          ? shipper.shipper_account_actions as Record<string, unknown>[]
          : [])
          .slice()
          .sort((left, right) => {
            const dueComparison = (cleanText(left.due_date) || "9999-12-31")
              .localeCompare(cleanText(right.due_date) || "9999-12-31");
            return dueComparison || (cleanText(left.created_at) || "").localeCompare(cleanText(right.created_at) || "");
          });
        const nextAction = actions[0] || null;
        const dueActionCount = actions.filter((action) => {
          const dueDate = cleanText(action.due_date);
          return Boolean(dueDate && dueDate <= today);
        }).length;
        const { shipper_account_actions: _actions, ...shipperRow } = shipper;
        return {
          ...shipperRow,
          open_action_count: actions.length,
          due_action_count: dueActionCount,
          next_action: cleanText(nextAction?.title),
          next_due_date: cleanText(nextAction?.due_date),
          next_action_priority: cleanText(nextAction?.priority)
        };
      });
      return jsonResponse({ rows, total: result.count || 0, limit, offset });
    }

    if (body.action === "list_shipper_duplicates") {
      const batchSize = 1000;
      const scanLimit = 5000;
      const rows: Record<string, unknown>[] = [];
      let offset = 0;
      let truncated = false;
      while (rows.length < scanLimit) {
        const result = await supabase
          .from("shippers")
          .select("id,shipper_name,legal_name,domain,website,status,relationship_stage,primary_contact_name,primary_contact_email,primary_contact_phone,headquarters_city,headquarters_state,headquarters_country,tags,source,updated_at")
          .eq("owner_email", user.owner_email)
          .neq("status", "archived")
          .order("shipper_name", { ascending: true })
          .range(offset, offset + batchSize - 1);
        if (result.error) throw result.error;
        const batch = (result.data || []) as Record<string, unknown>[];
        rows.push(...batch);
        if (batch.length < batchSize) break;
        offset += batchSize;
        if (rows.length >= scanLimit) truncated = true;
      }
      return jsonResponse({ groups: buildShipperDuplicateCandidates(rows), scanned: rows.length, truncated });
    }

    if (body.action === "merge_shipper_accounts") {
      if (body.confirmed !== true) return jsonResponse({ error: "Confirm the duplicate consolidation before saving." }, 400);
      const primaryId = cleanText(body.primary_shipper_id);
      const duplicateId = cleanText(body.duplicate_shipper_id);
      if (!primaryId || !duplicateId) return jsonResponse({ error: "Choose both accounts before consolidating." }, 400);
      if (primaryId === duplicateId) return jsonResponse({ error: "Choose two different shipper accounts." }, 400);

      const [primary, duplicate] = await Promise.all([
        requireOwnedShipper(supabase, user, primaryId),
        requireOwnedShipper(supabase, user, duplicateId)
      ]);
      if (cleanText(primary.status)?.toLowerCase() === "archived") return jsonResponse({ error: "The account of record is archived." }, 400);
      if (cleanText(duplicate.status)?.toLowerCase() === "archived") return jsonResponse({ error: "The duplicate account is already archived." }, 400);

      const now = new Date().toISOString();
      const firstValue = (...values: unknown[]) => values.map(cleanText).find(Boolean) || null;
      const primaryMetadata = objectRecord(primary.metadata);
      const mergedFromShipperIds = primaryMetadata.merged_from_shipper_ids;
      const existingMergedFrom = Array.isArray(mergedFromShipperIds)
        ? mergedFromShipperIds.map(String)
        : [];
      const mergedMetadata = {
        ...objectRecord(duplicate.metadata),
        ...objectRecord(primary.metadata),
        merged_from_shipper_ids: Array.from(new Set([...existingMergedFrom, duplicateId])),
        merged_at: now,
        merged_by: user.owner_email
      };
      const primaryPatch = normalizeShipper({
        legal_name: firstValue(primary.legal_name, duplicate.legal_name),
        domain: firstValue(primary.domain, duplicate.domain),
        website: firstValue(primary.website, duplicate.website),
        logo_url: firstValue(primary.logo_url, duplicate.logo_url),
        industry: firstValue(primary.industry, duplicate.industry),
        segment: firstValue(primary.segment, duplicate.segment),
        revenue_tier: firstValue(primary.revenue_tier, duplicate.revenue_tier),
        account_owner_email: firstValue(primary.account_owner_email, duplicate.account_owner_email),
        primary_contact_name: firstValue(primary.primary_contact_name, duplicate.primary_contact_name),
        primary_contact_email: firstValue(primary.primary_contact_email, duplicate.primary_contact_email),
        primary_contact_phone: firstValue(primary.primary_contact_phone, duplicate.primary_contact_phone),
        headquarters_city: firstValue(primary.headquarters_city, duplicate.headquarters_city),
        headquarters_state: firstValue(primary.headquarters_state, duplicate.headquarters_state),
        headquarters_country: firstValue(primary.headquarters_country, duplicate.headquarters_country),
        tags: Array.from(new Set([...normalizeTags(primary.tags), ...normalizeTags(duplicate.tags)])),
        notes: [cleanText(primary.notes), cleanText(duplicate.notes)].filter((value, index, values) => value && values.indexOf(value) === index).join("\n\n") || null,
        metadata: mergedMetadata
      }, true);
      const primaryBackup = Object.fromEntries(
        Object.keys(primaryPatch).filter((key) => key !== "updated_at").map((key) => [key, primary[key]])
      );
      const moved: Record<string, string[]> = {};
      let primaryUpdated = false;
      try {
        for (const [entity, config] of Object.entries(SHIPPER_CHILD_CONFIG)) {
          const transfer = await supabase
            .from(config.table)
            .update({ shipper_id: primaryId, updated_at: now })
            .eq("owner_email", user.owner_email)
            .eq("shipper_id", duplicateId)
            .select("id");
          if (transfer.error) throw transfer.error;
          moved[entity] = (transfer.data || []).map((row: { id: string }) => row.id);
        }
        const updatedPrimary = await supabase
          .from("shippers")
          .update({ ...primaryPatch, updated_at: now })
          .eq("owner_email", user.owner_email)
          .eq("id", primaryId)
          .select()
          .single();
        if (updatedPrimary.error) throw updatedPrimary.error;
        primaryUpdated = true;
        const archivedDuplicate = await supabase
          .from("shippers")
          .update({
            status: "archived",
            updated_at: now,
            metadata: { ...objectRecord(duplicate.metadata), merged_into_shipper_id: primaryId, merged_at: now }
          })
          .eq("owner_email", user.owner_email)
          .eq("id", duplicateId)
          .select("id,shipper_name,status")
          .single();
        if (archivedDuplicate.error) throw archivedDuplicate.error;
        try {
          await writeAuditLog(
            supabase,
            user,
            "shipper_accounts_merged",
            "shipper",
            primaryId,
            `Consolidated shipper ${duplicate.shipper_name} into ${primary.shipper_name}.`,
            { duplicate_shipper_id: duplicateId, moved_records: Object.fromEntries(Object.entries(moved).map(([entity, ids]) => [entity, ids.length])) }
          );
        } catch (auditError) {
          console.error("Could not record shipper consolidation audit", auditError);
        }
        return jsonResponse({
          target: updatedPrimary.data,
          archived_source: archivedDuplicate.data,
          moved_records: Object.fromEntries(Object.entries(moved).map(([entity, ids]) => [entity, ids.length]))
        });
      } catch (error) {
        if (primaryUpdated) {
          await supabase.from("shippers").update({ ...primaryBackup, updated_at: new Date().toISOString() })
            .eq("owner_email", user.owner_email).eq("id", primaryId);
        }
        for (const [entity, ids] of Object.entries(moved)) {
          if (!ids.length) continue;
          await supabase.from(SHIPPER_CHILD_CONFIG[entity as ShipperChildEntity].table)
            .update({ shipper_id: duplicateId, updated_at: new Date().toISOString() })
            .eq("owner_email", user.owner_email).in("id", ids);
        }
        throw error;
      }
    }

    if (body.action === "shipper_relationship_pipeline") {
      const limit = Math.min(Math.max(Number(body.limit) || 500, 1), 750);
      const search = safeShipperSearch(body.search);
      const status = cleanText(body.status)?.toLowerCase();
      let query = supabase
        .from("shippers")
        .select("id,shipper_name,domain,logo_url,industry,status,relationship_stage,primary_contact_name,primary_contact_email,headquarters_city,headquarters_state,headquarters_country,updated_at", { count: "exact" })
        .eq("owner_email", user.owner_email)
        .neq("status", "archived")
        .order("updated_at", { ascending: false })
        .range(0, limit - 1);
      if (status && status !== "all") query = query.eq("status", status);
      if (search) {
        query = query.or([
          `shipper_name.ilike.%${search}%`,
          `domain.ilike.%${search}%`,
          `industry.ilike.%${search}%`,
          `primary_contact_name.ilike.%${search}%`,
          `primary_contact_email.ilike.%${search}%`,
          `headquarters_city.ilike.%${search}%`,
          `headquarters_state.ilike.%${search}%`
        ].join(","));
      }
      const shipperResult = await query;
      if (shipperResult.error) throw shipperResult.error;
      const shippers = shipperResult.data || [];
      const shipperIds = shippers.map((row) => row.id).filter(Boolean);
      let opportunities: Record<string, unknown>[] = [];
      let rfis: Record<string, unknown>[] = [];
      let actions: Record<string, unknown>[] = [];
      if (shipperIds.length) {
        const [opportunityResult, rfiResult, actionResult] = await Promise.all([
          supabase.from("shipper_opportunities")
            .select("shipper_id,stage,estimated_value,currency,due_date,next_action")
            .eq("owner_email", user.owner_email)
            .in("shipper_id", shipperIds),
          supabase.from("shipper_rfis")
            .select("shipper_id,status,due_date")
            .eq("owner_email", user.owner_email)
            .in("shipper_id", shipperIds),
          supabase.from("shipper_account_actions")
            .select("shipper_id,title,action_type,status,priority,due_date")
            .eq("owner_email", user.owner_email)
            .in("shipper_id", shipperIds)
            .in("status", ["open", "in_progress"])
            .order("due_date", { ascending: true, nullsFirst: false })
        ]);
        if (opportunityResult.error) throw opportunityResult.error;
        if (rfiResult.error) throw rfiResult.error;
        if (actionResult.error) throw actionResult.error;
        opportunities = opportunityResult.data || [];
        rfis = rfiResult.data || [];
        actions = actionResult.data || [];
      }
      const openOpportunityStages = new Set(["identified", "discovery", "rfi", "rfx", "proposal", "negotiation"]);
      const activeRfiStatuses = new Set(["draft", "sent", "in_progress", "submitted"]);
      const opportunityByShipper = new Map<string, Record<string, unknown>[]>();
      const rfiByShipper = new Map<string, Record<string, unknown>[]>();
      const actionByShipper = new Map<string, Record<string, unknown>[]>();
      opportunities.forEach((row) => {
        const shipperId = cleanText(row.shipper_id);
        if (!shipperId) return;
        opportunityByShipper.set(shipperId, [...(opportunityByShipper.get(shipperId) || []), row]);
      });
      rfis.forEach((row) => {
        const shipperId = cleanText(row.shipper_id);
        if (!shipperId) return;
        rfiByShipper.set(shipperId, [...(rfiByShipper.get(shipperId) || []), row]);
      });
      actions.forEach((row) => {
        const shipperId = cleanText(row.shipper_id);
        if (!shipperId) return;
        actionByShipper.set(shipperId, [...(actionByShipper.get(shipperId) || []), row]);
      });
      const today = new Date().toISOString().slice(0, 10);
      const rows = shippers.map((shipper) => {
        const accountOpportunities = opportunityByShipper.get(shipper.id) || [];
        const accountRfis = rfiByShipper.get(shipper.id) || [];
        const accountActions = actionByShipper.get(shipper.id) || [];
        const openOpportunities = accountOpportunities.filter((row) => openOpportunityStages.has(cleanText(row.stage)?.toLowerCase() || ""));
        const activeRfis = accountRfis.filter((row) => activeRfiStatuses.has(cleanText(row.status)?.toLowerCase() || ""));
        const nextOpportunity = openOpportunities[0] || null;
        const dueActions = accountActions.filter((row) => {
          const dueDate = cleanText(row.due_date);
          return Boolean(dueDate && dueDate <= today);
        });
        const nextAccountAction = accountActions[0] || null;
        const opportunityCurrencies = [...new Set(openOpportunities.map((row) => cleanText(row.currency)?.toUpperCase()).filter(Boolean))];
        const pipelineCurrency = opportunityCurrencies.length === 1 ? opportunityCurrencies[0] : opportunityCurrencies.length ? "mixed" : null;
        return {
          ...shipper,
          open_opportunity_count: openOpportunities.length,
          active_rfi_count: activeRfis.length,
          open_action_count: accountActions.length,
          due_action_count: dueActions.length,
          next_action: cleanText(nextAccountAction?.title) || cleanText(nextOpportunity?.next_action),
          next_due_date: cleanText(nextAccountAction?.due_date) || cleanText(nextOpportunity?.due_date),
          next_action_priority: cleanText(nextAccountAction?.priority),
          pipeline_value: pipelineCurrency === "mixed" ? null : openOpportunities.reduce((sum, row) => sum + (Number(row.estimated_value) || 0), 0),
          pipeline_currency: pipelineCurrency
        };
      });
      const stages = ["target", "qualified", "customer", "at_risk", "inactive"].map((stage) => ({
        stage,
        count: rows.filter((row) => row.relationship_stage === stage).length
      }));
      return jsonResponse({ rows, total: shipperResult.count || 0, loaded: rows.length, limit, stages });
    }

    if (body.action === "shipper_intelligence") {
      const focus = cleanText(body.focus)?.toLowerCase() || "all";
      const allowedFocus = new Set(["all", "ready", "needs_contact", "needs_lane", "due_action", "at_risk"]);
      if (!allowedFocus.has(focus)) return jsonResponse({ error: "Unknown shipper intelligence focus." }, 400);
      const limit = Math.min(Math.max(Number(body.limit) || 1000, 1), 1000);
      const search = cleanText(body.search)?.toLowerCase() || "";
      const shipperResult = await supabase
        .from("shippers")
        .select("id,shipper_name,legal_name,domain,industry,status,relationship_stage,primary_contact_name,primary_contact_email,headquarters_city,headquarters_state,headquarters_country,updated_at", { count: "exact" })
        .eq("owner_email", user.owner_email)
        .neq("status", "archived")
        .order("updated_at", { ascending: false })
        .range(0, limit - 1);
      if (shipperResult.error) throw shipperResult.error;
      const shippers = (shipperResult.data || []) as Record<string, unknown>[];
      const shipperIds = shippers.map((row) => cleanText(row.id)).filter(Boolean) as string[];
      if (!shipperIds.length) {
        return jsonResponse({
          rows: [],
          total: shipperResult.count || 0,
          loaded: 0,
          truncated: false,
          counts: { ready: 0, needs_data: 0, due_action: 0, open_pipeline_value: 0, open_pipeline_currency: null }
        });
      }

      const fetchRows = async (table: string, columns: string) => {
        const rows: Record<string, unknown>[] = [];
        for (const ids of chunkValues(shipperIds, 300)) {
          const result = await supabase.from(table).select(columns)
            .eq("owner_email", user.owner_email)
            .in("shipper_id", ids);
          if (result.error) throw result.error;
          rows.push(...((result.data || []) as unknown as Record<string, unknown>[]));
        }
        return rows;
      };

      const [contacts, locations, lanes, rfis, opportunities, actions] = await Promise.all([
        fetchRows("shipper_contacts", "shipper_id,contact_name,email,status,updated_at"),
        fetchRows("shipper_locations", "shipper_id,market,region,city,state_code,country_code,updated_at"),
        fetchRows("shipper_lanes", "shipper_id,origin,origin_market,destination,destination_market,status,updated_at"),
        fetchRows("shipper_rfis", "shipper_id,status,due_date,updated_at"),
        fetchRows("shipper_opportunities", "shipper_id,stage,estimated_value,currency,due_date,next_action,updated_at"),
        fetchRows("shipper_account_actions", "shipper_id,title,action_type,status,priority,due_date,notes,updated_at")
      ]);

      const groupByShipper = (rows: Record<string, unknown>[]) => {
        const grouped = new Map<string, Record<string, unknown>[]>();
        rows.forEach((row) => {
          const shipperId = cleanText(row.shipper_id);
          if (!shipperId) return;
          grouped.set(shipperId, [...(grouped.get(shipperId) || []), row]);
        });
        return grouped;
      };
      const contactByShipper = groupByShipper(contacts);
      const locationByShipper = groupByShipper(locations);
      const laneByShipper = groupByShipper(lanes);
      const rfiByShipper = groupByShipper(rfis);
      const opportunityByShipper = groupByShipper(opportunities);
      const actionByShipper = groupByShipper(actions);
      const openOpportunityStages = new Set(["identified", "discovery", "rfi", "rfx", "proposal", "negotiation"]);
      const activeRfiStatuses = new Set(["draft", "sent", "in_progress", "submitted"]);
      const now = new Date();
      const dueSoon = new Date(now);
      dueSoon.setDate(dueSoon.getDate() + 14);
      const dueBy = (value: unknown) => {
        const text = cleanText(value);
        const date = text ? new Date(text) : null;
        return Boolean(date && !Number.isNaN(date.getTime()) && date <= dueSoon);
      };
      const latestDate = (values: unknown[]) => values
        .map((value) => {
          const text = cleanText(value);
          const timestamp = text ? new Date(text).getTime() : Number.NaN;
          return { text, timestamp };
        })
        .filter((value) => value.text && Number.isFinite(value.timestamp))
        .sort((left, right) => right.timestamp - left.timestamp)[0]?.text || null;
      const includesSearch = (values: unknown[]) => !search || values.some((value) => String(value || "").toLowerCase().includes(search));

      const allRows = shippers.map((shipper) => {
        const shipperId = cleanText(shipper.id) || "";
        const accountContacts = contactByShipper.get(shipperId) || [];
        const accountLocations = locationByShipper.get(shipperId) || [];
        const accountLanes = laneByShipper.get(shipperId) || [];
        const accountRfis = rfiByShipper.get(shipperId) || [];
        const accountOpportunities = opportunityByShipper.get(shipperId) || [];
        const accountActions = actionByShipper.get(shipperId) || [];
        const activeRfis = accountRfis.filter((row) => activeRfiStatuses.has(cleanText(row.status)?.toLowerCase() || ""));
        const openOpportunities = accountOpportunities.filter((row) => openOpportunityStages.has(cleanText(row.stage)?.toLowerCase() || ""));
        const openActions = accountActions.filter((row) => ["open", "in_progress"].includes(cleanText(row.status)?.toLowerCase() || ""));
        const dueActions = openActions.filter((row) => dueBy(row.due_date));
        const hasContact = Boolean(cleanText(shipper.primary_contact_email) || accountContacts.some((row) => cleanText(row.email)));
        const activeLocations = accountLocations.filter((row) => cleanText(row.country_code) || cleanText(row.city) || cleanText(row.market));
        const activeLanes = accountLanes.filter((row) => cleanText(row.status)?.toLowerCase() !== "archived");
        const markets = new Set([
          ...activeLocations.map((row) => cleanText(row.market)),
          ...activeLanes.flatMap((row) => [cleanText(row.origin_market), cleanText(row.destination_market)])
        ].filter(Boolean));
        const hasProfile = Boolean(cleanText(shipper.domain) || cleanText(shipper.headquarters_city) || cleanText(shipper.industry));
        const healthScore = Math.min(100,
          (hasContact ? 28 : 0) +
          (activeLocations.length ? 24 : 0) +
          (activeLanes.length ? 24 : 0) +
          (hasProfile ? 14 : 0) +
          (activeRfis.length || openOpportunities.length ? 10 : 0)
        );
        const accountDue = Boolean(dueActions.length) || [...activeRfis, ...openOpportunities].some((row) => dueBy(row.due_date));
        const relationshipStage = cleanText(shipper.relationship_stage)?.toLowerCase() || "target";
        let priority = "complete";
        let priorityDetail = "Complete profile coverage before outbound work.";
        if (accountDue) {
          priority = "due_action";
          priorityDetail = dueActions[0] && cleanText(dueActions[0].title)
            ? `Action due: ${cleanText(dueActions[0].title)}.`
            : "Due date reached or within the next 14 days.";
        } else if (relationshipStage === "at_risk") {
          priority = "at_risk";
          priorityDetail = "Relationship stage needs commercial attention.";
        } else if (!hasContact) {
          priority = "needs_contact";
          priorityDetail = "Add a working primary contact before outreach.";
        } else if (!activeLanes.length) {
          priority = "needs_lane";
          priorityDetail = "Add declared lanes or quoted coverage.";
        } else if (healthScore >= 60) {
          priority = "ready";
          priorityDetail = "Profile, contact, and coverage are ready to engage.";
        }
        const currencies = Array.from(new Set(openOpportunities.map((row) => cleanText(row.currency)?.toUpperCase()).filter(Boolean) as string[]));
        const pipelineCurrency = currencies.length === 1 ? currencies[0] : currencies.length > 1 ? "mixed" : null;
        const pipelineValue = pipelineCurrency === "mixed" ? null : openOpportunities.reduce((sum, row) => sum + (Number(row.estimated_value) || 0), 0);
        const activity = latestDate([
          shipper.updated_at,
          ...accountContacts.map((row) => row.updated_at),
          ...accountLocations.map((row) => row.updated_at),
          ...accountLanes.map((row) => row.updated_at),
          ...accountRfis.map((row) => row.updated_at),
          ...accountOpportunities.map((row) => row.updated_at),
          ...accountActions.map((row) => row.updated_at)
        ]);
        const searchValues = [
          shipper.shipper_name,
          shipper.legal_name,
          shipper.domain,
          shipper.primary_contact_name,
          shipper.primary_contact_email,
          shipper.headquarters_city,
          shipper.headquarters_state,
          ...accountContacts.flatMap((row) => [row.contact_name, row.email]),
          ...activeLocations.flatMap((row) => [row.market, row.region, row.city, row.state_code]),
          ...activeLanes.flatMap((row) => [row.origin, row.origin_market, row.destination, row.destination_market]),
          ...accountActions.flatMap((row) => [row.title, row.action_type, row.notes])
        ];
        return {
          id: shipperId,
          shipper_name: cleanText(shipper.shipper_name),
          legal_name: cleanText(shipper.legal_name),
          domain: cleanText(shipper.domain),
          headquarters_city: cleanText(shipper.headquarters_city),
          headquarters_state: cleanText(shipper.headquarters_state),
          relationship_stage: relationshipStage,
          contact_count: accountContacts.length,
          location_count: activeLocations.length,
          lane_count: activeLanes.length,
          market_count: markets.size,
          active_rfi_count: activeRfis.length,
          open_opportunity_count: openOpportunities.length,
          open_action_count: openActions.length,
          due_action_count: dueActions.length,
          pipeline_value: pipelineValue,
          pipeline_currency: pipelineCurrency,
          health_score: healthScore,
          health_label: healthScore >= 80 ? "Operationally complete" : healthScore >= 60 ? "Ready with minor gaps" : healthScore >= 35 ? "Needs cleanup" : "Profile incomplete",
          priority,
          priority_detail: priorityDetail,
          next_action: cleanText(openActions.find((row) => cleanText(row.title))?.title) || cleanText(openOpportunities.find((row) => cleanText(row.next_action))?.next_action),
          last_activity_at: activity,
          _search_values: searchValues,
          _pipeline_currencies: currencies
        };
      }).filter((row) => includesSearch(row._search_values));

      const pipelineCurrencies = Array.from(new Set(allRows.flatMap((row) => row._pipeline_currencies)));
      const pipelineCurrency = pipelineCurrencies.length === 1 ? pipelineCurrencies[0] : pipelineCurrencies.length > 1 ? "mixed" : null;
      const counts = {
        ready: allRows.filter((row) => row.priority === "ready").length,
        needs_data: allRows.filter((row) => ["needs_contact", "needs_lane", "complete"].includes(row.priority)).length,
        due_action: allRows.filter((row) => row.priority === "due_action" || row.priority === "at_risk").length,
        open_pipeline_value: pipelineCurrency === "mixed" ? null : allRows.reduce((sum, row) => sum + (Number(row.pipeline_value) || 0), 0),
        open_pipeline_currency: pipelineCurrency
      };
      const focusedRows = focus === "all" ? allRows : allRows.filter((row) => row.priority === focus);
      const rows = focusedRows.map(({ _search_values, _pipeline_currencies, ...row }) => row);
      return jsonResponse({
        rows,
        total: shipperResult.count || 0,
        loaded: shippers.length,
        truncated: Number(shipperResult.count || 0) > shippers.length,
        counts
      });
    }

    if (body.action === "shipper_commercial_work") {
      const search = safeShipperSearch(body.search);
      const focus = cleanText(body.focus)?.toLowerCase() || "all";
      const allowedFocus = new Set(["all", "needs_rfi", "rfi_due", "deal_due", "won", "lost"]);
      if (!allowedFocus.has(focus)) return jsonResponse({ error: "Unknown commercial work focus." }, 400);
      const limit = Math.min(Math.max(Number(body.limit) || 1000, 1), 1000);
      const shipperResult = await supabase.from("shippers")
        .select("id,shipper_name,domain,relationship_stage,status")
        .eq("owner_email", user.owner_email)
        .neq("status", "archived")
        .order("updated_at", { ascending: false })
        .range(0, limit - 1);
      if (shipperResult.error) throw shipperResult.error;
      const shippers = shipperResult.data || [];
      const shipperIds = shippers.map((row) => cleanText(row.id)).filter(Boolean) as string[];
      if (!shipperIds.length) return jsonResponse({ rfis: [], opportunities: [], counts: { open_rfis: 0, unlinked_rfis: 0, open_opportunities: 0, due_soon: 0 }, loaded: 0 });
      const [rfiResult, opportunityResult] = await Promise.all([
        supabase.from("shipper_rfis")
          .select("id,shipper_id,rfi_name,external_reference,status,due_date,updated_at")
          .eq("owner_email", user.owner_email)
          .in("shipper_id", shipperIds)
          .neq("status", "archived")
          .order("due_date", { ascending: true, nullsFirst: false }),
        supabase.from("shipper_opportunities")
          .select("id,shipper_id,rfi_id,rfx_project_id,opportunity_name,stage,probability,estimated_value,currency,estimated_weekly_volume,due_date,next_action,updated_at")
          .eq("owner_email", user.owner_email)
          .in("shipper_id", shipperIds)
          .neq("stage", "archived")
          .order("due_date", { ascending: true, nullsFirst: false })
      ]);
      if (rfiResult.error) throw rfiResult.error;
      if (opportunityResult.error) throw opportunityResult.error;
      const shipperById = new Map<string, Record<string, unknown>>();
      shippers.forEach((shipper) => {
        const shipperId = cleanText(shipper.id);
        if (shipperId) shipperById.set(shipperId, shipper);
      });
      const rfxProjectIds = Array.from(new Set((opportunityResult.data || [])
        .map((row) => cleanText(row.rfx_project_id))
        .filter((id): id is string => Boolean(id))));
      const rfxProjectResult = rfxProjectIds.length
        ? await supabase.from("rfx_projects")
          .select("id,title,status,linked_rfx_event_id,due_date,updated_at")
          .eq("owner_email", user.owner_email)
          .in("id", rfxProjectIds)
        : { data: [], error: null };
      if (rfxProjectResult.error) throw rfxProjectResult.error;
      const rfxProjectById = new Map<string, Record<string, unknown>>();
      ((rfxProjectResult.data || []) as Record<string, unknown>[]).forEach((project) => {
        const projectId = cleanText(project.id);
        if (projectId) rfxProjectById.set(projectId, project);
      });
      const allOpportunities = (opportunityResult.data || []).map((row) => ({
        ...row,
        shipper_name: cleanText(shipperById.get(mapLookupKey(row.shipper_id))?.shipper_name),
        shipper_domain: cleanText(shipperById.get(mapLookupKey(row.shipper_id))?.domain),
        relationship_stage: cleanText(shipperById.get(mapLookupKey(row.shipper_id))?.relationship_stage),
        rfx_project: rfxProjectById.get(mapLookupKey(row.rfx_project_id)) || null
      }));
      const opportunityByRfiId = new Map<string, Record<string, unknown>>();
      allOpportunities.forEach((opportunity) => {
        const rfiId = cleanText(opportunity.rfi_id);
        if (rfiId) opportunityByRfiId.set(rfiId, opportunity);
      });
      const rfis = (rfiResult.data || []).map((row) => ({
        ...row,
        shipper_name: cleanText(shipperById.get(mapLookupKey(row.shipper_id))?.shipper_name),
        shipper_domain: cleanText(shipperById.get(mapLookupKey(row.shipper_id))?.domain),
        linked_opportunity: opportunityByRfiId.get(mapLookupKey(row.id)) || null
      }));
      const matchesSearch = (row: Record<string, unknown>, fields: string[]) => !search || fields.some((field) => String(row[field] || "").toLowerCase().includes(search.toLowerCase()));
      const now = new Date();
      const dueSoon = new Date(now);
      dueSoon.setDate(dueSoon.getDate() + 14);
      const dueBy = (value: unknown) => {
        const date = value ? new Date(String(value)) : null;
        return Boolean(date && !Number.isNaN(date.getTime()) && date <= dueSoon);
      };
      const openOpportunityStages = new Set(["identified", "discovery", "rfi", "rfx", "proposal", "negotiation"]);
      const openOpportunities = allOpportunities.filter((row) => openOpportunityStages.has(cleanText(row.stage)?.toLowerCase() || ""));
      const wonOpportunities = allOpportunities.filter((row) => cleanText(row.stage)?.toLowerCase() === "won");
      const lostOpportunities = allOpportunities.filter((row) => cleanText(row.stage)?.toLowerCase() === "lost");
      let filteredRfis = rfis.filter((row) => matchesSearch(row, ["shipper_name", "shipper_domain", "rfi_name", "external_reference", "status"]));
      let filteredOpportunities = openOpportunities.filter((row) => matchesSearch(row, ["shipper_name", "shipper_domain", "opportunity_name", "stage", "next_action"]));
      if (focus === "needs_rfi") filteredRfis = filteredRfis.filter((row) => !row.linked_opportunity);
      if (focus === "rfi_due") filteredRfis = filteredRfis.filter((row) => dueBy(row.due_date));
      if (focus === "deal_due") filteredOpportunities = filteredOpportunities.filter((row) => dueBy(row.due_date));
      if (focus === "won") {
        filteredRfis = [];
        filteredOpportunities = wonOpportunities.filter((row) => matchesSearch(row, ["shipper_name", "shipper_domain", "opportunity_name", "next_action"]));
      }
      if (focus === "lost") {
        filteredRfis = [];
        filteredOpportunities = lostOpportunities.filter((row) => matchesSearch(row, ["shipper_name", "shipper_domain", "opportunity_name", "next_action"]));
      }
      const allRfis = rfis;
      const totalDueSoon = [...allRfis, ...openOpportunities].filter((row) => dueBy(row.due_date)).length;
      return jsonResponse({
        rfis: filteredRfis,
        opportunities: filteredOpportunities,
        counts: {
          open_rfis: allRfis.length,
          unlinked_rfis: allRfis.filter((row) => !row.linked_opportunity).length,
          open_opportunities: openOpportunities.length,
          won_opportunities: wonOpportunities.length,
          lost_opportunities: lostOpportunities.length,
          due_soon: totalDueSoon
        },
        loaded: shippers.length
      });
    }

    if (body.action === "launch_shipper_opportunity_rfx") {
      const opportunityId = cleanText(body.id || body.opportunity_id);
      if (!opportunityId || !UUID_PATTERN.test(opportunityId)) return jsonResponse({ error: "A valid opportunity id is required." }, 400);
      const opportunityResult = await supabase.from("shipper_opportunities").select("*")
        .eq("owner_email", user.owner_email).eq("id", opportunityId).single();
      if (opportunityResult.error) throw opportunityResult.error;
      const opportunity = opportunityResult.data as Record<string, unknown>;
      const shipper = await requireOwnedShipper(supabase, user, opportunity.shipper_id);
      const existingProjectId = cleanText(opportunity.rfx_project_id);
      if (existingProjectId) {
        const existingProjectResult = await supabase.from("rfx_projects").select("*")
          .eq("owner_email", user.owner_email).eq("id", existingProjectId).single();
        if (existingProjectResult.error) throw existingProjectResult.error;
        return jsonResponse({ row: opportunity, project: existingProjectResult.data, created: false });
      }
      if (["won", "lost", "archived"].includes(cleanText(opportunity.stage)?.toLowerCase() || "")) {
        return jsonResponse({ error: "Closed opportunities cannot start a new RFx workspace." }, 400);
      }

      const projectInput = normalizeRfxProjectInput({
        title: `${cleanText(opportunity.opportunity_name) || "Commercial opportunity"} RFx`,
        customer_id: cleanText(shipper.id),
        customer_name: cleanText(shipper.shipper_name),
        customer_contact_name: cleanText(shipper.primary_contact_name),
        customer_contact_email: cleanText(shipper.primary_contact_email),
        opportunity_type: "contract",
        status: "draft",
        due_date: cleanText(opportunity.due_date),
        notes: [
          `Created from Shipper CRM opportunity ${cleanText(opportunity.opportunity_name) || opportunityId}.`,
          cleanText(opportunity.next_action) ? `Commercial next action: ${cleanText(opportunity.next_action)}.` : "",
          cleanText(opportunity.notes) ? `Commercial notes: ${cleanText(opportunity.notes)}.` : ""
        ].filter(Boolean).join("\n")
      });
      const projectResult = await supabase.from("rfx_projects")
        .insert(withOwner(projectInput, user)).select().single();
      if (projectResult.error) throw projectResult.error;
      const project = projectResult.data as Record<string, unknown>;
      const updateResult = await supabase.from("shipper_opportunities")
        .update({
          stage: "rfx",
          rfx_project_id: project.id,
          next_action: "Complete the RFx demand snapshot and package before launching Bid Room.",
          updated_at: new Date().toISOString()
        })
        .eq("owner_email", user.owner_email)
        .eq("id", opportunityId)
        .select()
        .single();
      if (updateResult.error) {
        await supabase.from("rfx_projects").delete().eq("owner_email", user.owner_email).eq("id", project.id);
        throw updateResult.error;
      }
      await writeRfxProcessAudit(
        supabase,
        user,
        project.id,
        "shipper_opportunity_rfx_created",
        "shipper_opportunity",
        opportunityId,
        `Created RFx workspace from shipper opportunity ${cleanText(opportunity.opportunity_name) || opportunityId}.`,
        { shipper_id: shipper.id, shipper_opportunity_id: opportunityId, rfi_id: cleanText(opportunity.rfi_id) }
      );
      await writeAuditLog(
        supabase,
        user,
        "shipper_opportunity_rfx_created",
        "shipper_opportunity",
        opportunityId,
        `Linked shipper opportunity to RFx workspace ${project.title}.`,
        { shipper_id: shipper.id, rfx_project_id: project.id, rfi_id: cleanText(opportunity.rfi_id) }
      );
      return jsonResponse({ row: updateResult.data, project, created: true });
    }

    if (body.action === "promote_shipper_rfi_to_opportunity") {
      const rfiId = cleanText(body.rfi_id);
      if (!rfiId || !UUID_PATTERN.test(rfiId)) return jsonResponse({ error: "A valid RFI id is required." }, 400);
      const rfiResult = await supabase.from("shipper_rfis").select("*")
        .eq("owner_email", user.owner_email).eq("id", rfiId).single();
      if (rfiResult.error) throw rfiResult.error;
      const rfi = rfiResult.data as Record<string, unknown>;
      if (cleanText(rfi.status)?.toLowerCase() === "archived") return jsonResponse({ error: "Archived RFIs cannot be promoted." }, 400);
      await requireOwnedShipper(supabase, user, rfi.shipper_id);
      const existingResult = await supabase.from("shipper_opportunities").select("*")
        .eq("owner_email", user.owner_email).eq("rfi_id", rfiId).limit(1);
      if (existingResult.error) throw existingResult.error;
      const existing = existingResult.data?.[0] as Record<string, unknown> | undefined;
      if (existing) return jsonResponse({ row: existing, rfi, created: false });
      const result = await supabase.from("shipper_opportunities").insert({
        ...withOwner({
          shipper_id: rfi.shipper_id,
          rfi_id: rfiId,
          opportunity_name: cleanText(rfi.rfi_name) || "Shipper RFI",
          stage: "rfi",
          probability: 20,
          due_date: cleanText(rfi.due_date),
          next_action: "Review RFI scope and qualify the commercial opportunity.",
          notes: cleanText(rfi.notes),
          metadata: { source: "shipper_rfi", external_reference: cleanText(rfi.external_reference) }
        }, user),
        organization_id: user.organization_id
      }).select().single();
      if (result.error) throw result.error;
      if (["draft", "sent"].includes(cleanText(rfi.status)?.toLowerCase() || "")) {
        const statusResult = await supabase.from("shipper_rfis").update({ status: "in_progress", updated_at: new Date().toISOString() })
          .eq("owner_email", user.owner_email).eq("id", rfiId);
        if (statusResult.error) throw statusResult.error;
        rfi.status = "in_progress";
      }
      await writeAuditLog(supabase, user, "shipper_rfi_promoted", "shipper_opportunity", result.data.id,
        `Promoted RFI ${cleanText(rfi.rfi_name) || rfiId} into a commercial opportunity.`, { rfi_id: rfiId, shipper_id: rfi.shipper_id });
      return jsonResponse({ row: result.data, rfi, created: true });
    }

    if (body.action === "move_shipper_opportunity_stage") {
      const opportunityId = cleanText(body.id || body.opportunity_id);
      const stage = cleanText(body.stage)?.toLowerCase();
      if (!opportunityId || !UUID_PATTERN.test(opportunityId)) return jsonResponse({ error: "A valid opportunity id is required." }, 400);
      if (!stage || !SHIPPER_ENUMS.opportunity_stage.has(stage)) return jsonResponse({ error: "Unknown opportunity stage." }, 400);
      const currentResult = await supabase.from("shipper_opportunities").select("*")
        .eq("owner_email", user.owner_email).eq("id", opportunityId).single();
      if (currentResult.error) throw currentResult.error;
      const current = currentResult.data as Record<string, unknown>;
      await requireOwnedShipper(supabase, user, current.shipper_id);
      const result = await supabase.from("shipper_opportunities").update({ stage, updated_at: new Date().toISOString() })
        .eq("owner_email", user.owner_email).eq("id", opportunityId).select().single();
      if (result.error) throw result.error;
      await writeAuditLog(supabase, user, "shipper_opportunity_stage_moved", "shipper_opportunity", opportunityId,
        `Moved shipper opportunity ${cleanText(result.data.opportunity_name) || opportunityId} to ${stage}.`, { from: current.stage, to: stage });
      return jsonResponse({ row: result.data });
    }

    if (body.action === "apply_shipper_action_playbook") {
      const shipper = await requireOwnedShipper(supabase, user, body.shipper_id || body.id);
      const playbookKey = cleanText(body.playbook)?.toLowerCase();
      const playbook = playbookKey ? SHIPPER_ACTION_PLAYBOOKS[playbookKey] : null;
      if (!playbook || !playbookKey) return jsonResponse({ error: "Unknown Shipper CRM action playbook." }, 400);

      const existingResult = await supabase
        .from("shipper_account_actions")
        .select("id,title,status")
        .eq("owner_email", user.owner_email)
        .eq("shipper_id", shipper.id)
        .in("status", ["open", "in_progress"]);
      if (existingResult.error) throw existingResult.error;

      const existingTitles = new Set(
        (existingResult.data || [])
          .map((row) => cleanText(row.title)?.toLowerCase())
          .filter(Boolean) as string[]
      );
      const assignee = cleanText(body.owner_email_assignee)
        || cleanText(shipper.account_owner_email)
        || user.owner_email;
      const actions = playbook.steps
        .filter((step) => !existingTitles.has(step.title.toLowerCase()))
        .map((step) => ({
          ...withOwner({
            shipper_id: shipper.id,
            title: step.title,
            action_type: step.action_type,
            status: "open",
            priority: step.priority,
            due_date: shipperActionDueDate(step.due_in_days),
            owner_email_assignee: assignee,
            notes: step.notes,
            metadata: { source: "shipper_action_playbook", playbook: playbookKey }
          }, user),
          organization_id: user.organization_id
        }));

      let createdRows: Record<string, unknown>[] = [];
      if (actions.length) {
        const insertResult = await supabase.from("shipper_account_actions").insert(actions).select();
        if (insertResult.error) throw insertResult.error;
        createdRows = (insertResult.data || []) as Record<string, unknown>[];
      }
      const skipped = playbook.steps.length - createdRows.length;
      await writeAuditLog(
        supabase,
        user,
        "shipper_account_playbook_applied",
        "shipper",
        shipper.id,
        `Applied ${playbook.label}: created ${createdRows.length} account action(s) and skipped ${skipped} existing action(s).`,
        { playbook: playbookKey, created: createdRows.length, skipped }
      );
      return jsonResponse({
        playbook: { key: playbookKey, label: playbook.label, description: playbook.description },
        created: createdRows.length,
        skipped,
        rows: createdRows
      });
    }

    if (body.action === "shipper_action_queue") {
      const focus = cleanText(body.focus)?.toLowerCase() || "open";
      const allowedFocus = new Set(["open", "overdue", "today", "upcoming", "done"]);
      if (!allowedFocus.has(focus)) return jsonResponse({ error: "Unknown account action queue focus." }, 400);
      const limit = Math.max(1, Math.min(1000, Number(body.limit) || 250));
      const today = new Date().toISOString().slice(0, 10);
      const upcomingDate = new Date();
      upcomingDate.setUTCDate(upcomingDate.getUTCDate() + 7);
      const nextWeek = upcomingDate.toISOString().slice(0, 10);
      const openStatuses = ["open", "in_progress"];

      let actionQuery = supabase
        .from("shipper_account_actions")
        .select("id,shipper_id,title,action_type,status,priority,due_date,owner_email_assignee,notes,updated_at")
        .eq("owner_email", user.owner_email)
        .order("due_date", { ascending: true, nullsFirst: false })
        .order("updated_at", { ascending: false })
        .order("id", { ascending: false })
        .limit(limit);
      if (focus === "done") actionQuery = actionQuery.eq("status", "done");
      else actionQuery = actionQuery.in("status", openStatuses);
      if (focus === "overdue") actionQuery = actionQuery.lt("due_date", today);
      if (focus === "today") actionQuery = actionQuery.eq("due_date", today);
      if (focus === "upcoming") actionQuery = actionQuery.gte("due_date", today).lte("due_date", nextWeek);

      const [actionsResult, countsResult] = await Promise.all([
        actionQuery,
        fetchAllShipperAccountActionCounts(supabase, user.owner_email)
      ]);
      if (actionsResult.error) throw actionsResult.error;

      const actions = (actionsResult.data || []) as Record<string, unknown>[];
      const shipperIds = [...new Set(actions.map((row) => cleanText(row.shipper_id)).filter(Boolean))] as string[];
      let accounts: Record<string, unknown>[] = [];
      if (shipperIds.length) {
        const accountsResult = await supabase.from("shippers")
          .select("id,shipper_name,domain,primary_contact_email")
          .eq("owner_email", user.owner_email)
          .in("id", shipperIds);
        if (accountsResult.error) throw accountsResult.error;
        accounts = (accountsResult.data || []) as Record<string, unknown>[];
      }
      const accountById = new Map<string, Record<string, unknown>>();
      accounts.forEach((account) => {
        const accountId = cleanText(account.id);
        if (accountId) accountById.set(accountId, account);
      });
      const search = cleanText(body.search)?.toLowerCase();
      const rows: Record<string, unknown>[] = actions.map((row) => {
        const account = accountById.get(mapLookupKey(row.shipper_id)) || {};
        return {
          ...row,
          shipper_name: cleanText(account.shipper_name),
          shipper_domain: cleanText(account.domain),
          primary_contact_email: cleanText(account.primary_contact_email)
        };
      }).filter((row) => {
        if (!search) return true;
        const searchable = objectRecord(row);
        return [searchable.shipper_name, searchable.shipper_domain, searchable.primary_contact_email, searchable.title, searchable.notes, searchable.owner_email_assignee]
          .map(cleanText).filter(Boolean).join(" ").toLowerCase().includes(search);
      });
      const counts = { open: 0, today: 0, overdue: 0, done: 0 };
      countsResult.forEach((row) => {
        const status = cleanText(row.status)?.toLowerCase();
        const dueDate = cleanText(row.due_date);
        if (["open", "in_progress"].includes(status || "")) {
          counts.open += 1;
          if (dueDate === today) counts.today += 1;
          if (dueDate && dueDate < today) counts.overdue += 1;
        }
        if (status === "done") counts.done += 1;
      });
      return jsonResponse({ rows, counts, focus, loaded: rows.length });
    }

    if (body.action === "update_shipper_account_action_status") {
      const actionId = cleanText(body.id);
      const status = cleanText(body.status)?.toLowerCase();
      if (!actionId || !UUID_PATTERN.test(actionId)) return jsonResponse({ error: "A valid account action id is required." }, 400);
      if (!status || !SHIPPER_ENUMS.shipper_action_status.has(status)) return jsonResponse({ error: "Unknown account action status." }, 400);
      const currentResult = await supabase.from("shipper_account_actions").select("*")
        .eq("owner_email", user.owner_email).eq("id", actionId).single();
      if (currentResult.error) throw currentResult.error;
      const current = currentResult.data as Record<string, unknown>;
      await requireOwnedShipper(supabase, user, current.shipper_id);
      const result = await supabase.from("shipper_account_actions")
        .update({ status, updated_at: new Date().toISOString() })
        .eq("owner_email", user.owner_email).eq("id", actionId).select().single();
      if (result.error) throw result.error;
      await writeAuditLog(supabase, user, "shipper_account_action_status_updated", "shipper_account_action", actionId,
        `Updated account action ${cleanText(result.data.title) || actionId} to ${status}.`, {
          shipper_id: current.shipper_id,
          from: current.status,
          to: status
        });
      return jsonResponse({ row: result.data });
    }

    if (body.action === "get_shipper") {
      const shipper = await requireOwnedShipper(supabase, user, body.id || body.shipper_id);
      const shipperId = cleanText(shipper.id);
      const entries = Object.entries(SHIPPER_CHILD_CONFIG) as [ShipperChildEntity, typeof SHIPPER_CHILD_CONFIG[ShipperChildEntity]][];
      const results = await mapWithConcurrency(entries, RATEBOOK_SYNC_CONCURRENCY, async ([, config]) =>
        fetchAllShipperChildRows(supabase, config.table, user.owner_email, shipperId)
      );
      const profileRequestsResult = await supabase.from("shipper_profile_requests")
        .select("id,status,expires_at,viewed_at,submitted_at,created_at,updated_at")
        .eq("owner_email", user.owner_email).eq("shipper_id", shipperId).order("created_at", { ascending: false }).limit(10);
      if (profileRequestsResult.error && profileRequestsResult.error.code !== "42P01") throw profileRequestsResult.error;
      const details = Object.fromEntries(entries.map(([entity], index) => [entity, results[index] || []]));
      details.profile_requests = profileRequestsResult.data || [];
      try {
        const listedRatebooks = await listRatebooks(supabase, user, {
          shipper_id: shipperId,
          include_routes: false,
          skip_bid_room_sync: true,
          skip_materialization: true
        });
        const sync = objectRecord(listedRatebooks.sync);
        details.ratebooks = Array.isArray(listedRatebooks.rows) ? listedRatebooks.rows : [];
        details.bid_room_events = (Array.isArray(sync.failed) ? sync.failed : []).map((failure) => ({
          id: cleanText(objectRecord(failure).event_id),
          ratebook_sync_error: cleanText(objectRecord(failure).error) || "Ratebook synchronization failed for this Bid Room event."
        }));
        details.ratebook_materialization_failures = Array.isArray(sync.materialization_failed)
          ? sync.materialization_failed
          : [];
      } catch (error) {
        // Keep the shipper profile usable until the Ratebook migration is present in every deployment.
        if ((error as { code?: string } | null)?.code !== "42P01") throw error;
        details.bid_room_events = [];
        details.ratebook_materialization_failures = [];
        details.ratebooks = [];
      }
      return jsonResponse({ row: shipper, ...details });
    }

    if (body.action === "create_shipper_profile_request") {
      const shipper = await requireOwnedShipper(supabase, user, body.shipper_id || body.id);
      const shipperId = cleanText(shipper.id)!;
      const expiresInDays = Math.min(Math.max(Number(body.expires_in_days) || 30, 1), 90);
      const rawToken = `${crypto.randomUUID().replaceAll("-", "")}${crypto.randomUUID().replaceAll("-", "")}`;
      const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(rawToken));
      const tokenHash = Array.from(new Uint8Array(digest)).map((byte) => byte.toString(16).padStart(2, "0")).join("");
      const expiresAt = new Date(Date.now() + expiresInDays * 86400000).toISOString();
      const revokeExisting = await supabase.from("shipper_profile_requests")
        .update({ status: "revoked", updated_at: new Date().toISOString() })
        .eq("owner_email", user.owner_email).eq("shipper_id", shipperId).in("status", ["active", "viewed", "submitted"]);
      if (revokeExisting.error && revokeExisting.error.code !== "42P01") throw revokeExisting.error;
      const result = await supabase.from("shipper_profile_requests").insert({
        owner_user_id: user.owner_user_id,
        owner_email: user.owner_email,
        organization_id: user.organization_id,
        shipper_id: shipperId,
        token_hash: tokenHash,
        expires_at: expiresAt,
        metadata: { generated_from: "shipper_crm", shipper_name: shipper.shipper_name }
      }).select("id,status,expires_at,created_at").single();
      if (result.error) throw result.error;
      await writeAuditLog(supabase, user, "shipper.profile_request.create", "shipper", shipperId,
        `Created shipper profile request for ${cleanText(shipper.shipper_name) || "shipper"}.`, { request_id: result.data.id, expires_at: expiresAt });
      const baseUrl = (cleanUrl(body.origin) || Deno.env.get("RATEWARE_PUBLIC_APP_URL") || "https://rateware.vercel.app").replace(/\/$/, "");
      return jsonResponse({ row: result.data, url: `${baseUrl}/shipper-profile.html?token=${encodeURIComponent(rawToken)}` });
    }

    if (body.action === "revoke_shipper_profile_request") {
      const requestId = cleanText(body.id);
      if (!requestId || !UUID_PATTERN.test(requestId)) return jsonResponse({ error: "A valid profile request id is required." }, 400);
      const current = await supabase.from("shipper_profile_requests").select("id,shipper_id")
        .eq("owner_email", user.owner_email).eq("id", requestId).single();
      if (current.error) throw current.error;
      await requireOwnedShipper(supabase, user, current.data.shipper_id);
      const result = await supabase.from("shipper_profile_requests").update({ status: "revoked", updated_at: new Date().toISOString() })
        .eq("owner_email", user.owner_email).eq("id", requestId).select("id,status").single();
      if (result.error) throw result.error;
      return jsonResponse({ row: result.data });
    }

    if (body.action === "shipper_account_activity") {
      const shipper = await requireOwnedShipper(supabase, user, body.id || body.shipper_id);
      const shipperId = cleanText(shipper.id);
      const [opportunitiesResult, rfisResult, actionsResult, auditResult] = await Promise.all([
        supabase.from("shipper_opportunities").select("id,rfx_project_id")
          .eq("owner_email", user.owner_email).eq("shipper_id", shipperId),
        supabase.from("shipper_rfis").select("id")
          .eq("owner_email", user.owner_email).eq("shipper_id", shipperId),
        supabase.from("shipper_account_actions").select("id")
          .eq("owner_email", user.owner_email).eq("shipper_id", shipperId),
        supabase.from("saas_audit_log")
          .select("id,created_at,actor_email,action,entity_type,entity_id,summary,metadata")
          .eq("owner_email", user.owner_email)
          .order("created_at", { ascending: false })
          .limit(300)
      ]);
      if (opportunitiesResult.error) throw opportunitiesResult.error;
      if (rfisResult.error) throw rfisResult.error;
      if (actionsResult.error) throw actionsResult.error;
      if (auditResult.error) throw auditResult.error;
      const opportunityIds = new Set((opportunitiesResult.data || []).map((row) => cleanText(row.id)).filter(Boolean));
      const rfiIds = new Set((rfisResult.data || []).map((row) => cleanText(row.id)).filter(Boolean));
      const actionIds = new Set((actionsResult.data || []).map((row) => cleanText(row.id)).filter(Boolean));
      const projectIds = new Set((opportunitiesResult.data || []).map((row) => cleanText(row.rfx_project_id)).filter(Boolean));
      const rows = (auditResult.data || []).filter((row) => {
        const entityId = cleanText(row.entity_id);
        const metadata = row.metadata && typeof row.metadata === "object" ? row.metadata as Record<string, unknown> : {};
        return (row.entity_type === "shipper" && entityId === shipperId)
          || (row.entity_type === "shipper_opportunity" && opportunityIds.has(entityId))
          || (row.entity_type === "shipper_rfi" && rfiIds.has(entityId))
          || (row.entity_type === "shipper_account_action" && actionIds.has(entityId))
          || (row.entity_type === "rfx_project" && projectIds.has(entityId))
          || cleanText(metadata.shipper_id) === shipperId
          || opportunityIds.has(cleanText(metadata.shipper_opportunity_id));
      }).slice(0, 120);
      return jsonResponse({ rows, shipper_id: shipperId, loaded: rows.length });
    }

    if (body.action === "create_shipper") {
      const input = objectRecord(body.shipper);
      const row = normalizeShipper(input);
      if (!cleanText(row.shipper_name)) return jsonResponse({ error: "Shipper name is required." }, 400);
      const invalid = invalidShipperValue(row);
      if (invalid) return jsonResponse({ error: invalid }, 400);
      const result = await supabase.from("shippers").insert({
        ...withOwner(row, user),
        organization_id: user.organization_id
      }).select().single();
      if (result.error) throw result.error;
      await writeAuditLog(supabase, user, "shipper_created", "shipper", result.data.id, `Created shipper ${result.data.shipper_name}.`);
      return jsonResponse({ row: result.data });
    }

    if (body.action === "import_shippers") {
      if (body.confirmed !== true) return jsonResponse({ error: "Confirm the Shipper Base import before saving." }, 400);
      const sourceRows = Array.isArray(body.rows) ? body.rows : [];
      if (!sourceRows.length) return jsonResponse({ error: "Choose at least one Shipper Base row to import." }, 400);
      if (sourceRows.length > 1000) return jsonResponse({ error: "Import up to 1,000 shippers per file. Split larger files into smaller batches." }, 400);

      const importRows: { patch: Record<string, unknown>; insert: Record<string, unknown>; sourceIndex: number }[] = [];
      const skippedRows: { row: number; reason: string }[] = [];
      const seenDomains = new Set<string>();
      sourceRows.forEach((source, index) => {
        const normalized = normalizeImportedShipper(objectRecord(source));
        if ("error" in normalized) {
          skippedRows.push({ row: index + 1, reason: normalized.error || "Invalid Shipper Base row." });
          return;
        }
        const domain = cleanText(normalized.insert.domain)?.toLowerCase();
        if (domain && seenDomains.has(domain)) {
          skippedRows.push({ row: index + 1, reason: "Duplicate domain in this import." });
          return;
        }
        if (domain) seenDomains.add(domain);
        importRows.push({ patch: normalized.patch, insert: normalized.insert, sourceIndex: index + 1 });
      });

      const domains = importRows.map(({ insert }) => cleanText(insert.domain)?.toLowerCase()).filter(Boolean) as string[];
      const existingByDomain = new Map<string, Record<string, unknown>>();
      for (const domainChunk of chunkValues(Array.from(new Set(domains)), 250)) {
        const existingResult = await supabase.from("shippers").select("*")
          .eq("owner_email", user.owner_email).in("domain", domainChunk);
        if (existingResult.error) throw existingResult.error;
        for (const existing of existingResult.data || []) {
          if (cleanText(existing.status)?.toLowerCase() === "archived") continue;
          const domain = cleanText(existing.domain)?.toLowerCase();
          if (domain) existingByDomain.set(domain, existing as Record<string, unknown>);
        }
      }

      const inserts: Record<string, unknown>[] = [];
      const updates: { id: string; row: Record<string, unknown> }[] = [];
      for (const item of importRows) {
        const domain = cleanText(item.insert.domain)?.toLowerCase();
        const existing = domain ? existingByDomain.get(domain) : null;
        if (existing && cleanText(existing.id)) {
          updates.push({ id: String(existing.id), row: mergedImportedShipper(existing, item.patch) });
        } else {
          inserts.push({ ...withOwner(item.insert, user), organization_id: user.organization_id });
        }
      }

      let inserted = 0;
      for (const insertChunk of chunkValues(inserts, 100)) {
        if (!insertChunk.length) continue;
        const result = await supabase.from("shippers").insert(insertChunk).select("id");
        if (result.error) throw result.error;
        inserted += result.data?.length || 0;
      }

      let updated = 0;
      for (const updateChunk of chunkValues(updates, 25)) {
        const results = await Promise.all(updateChunk.map(async (item) => await supabase.from("shippers")
          .update(item.row).eq("owner_email", user.owner_email).eq("id", item.id).select("id").single()));
        results.forEach((result) => {
          if (result.error) throw result.error;
          updated += 1;
        });
      }

      await writeAuditLog(
        supabase,
        user,
        "shipper_base_imported",
        "shipper_import",
        null,
        `Imported ${inserted} Shipper Base account(s) and updated ${updated} existing domain match(es).`,
        { inserted, updated, skipped: skippedRows.length, total_rows: sourceRows.length }
      );
      return jsonResponse({
        inserted,
        updated,
        skipped: skippedRows.length,
        total_rows: sourceRows.length,
        skipped_rows: skippedRows.slice(0, 100)
      });
    }

    if (body.action === "import_shipper_crm_workbook") {
      if (body.confirmed !== true) return jsonResponse({ error: "Confirm the relational Shipper CRM import before saving." }, 400);
      const accountSources = Array.isArray(body.accounts) ? body.accounts : [];
      const contactSources = Array.isArray(body.contacts) ? body.contacts : [];
      const opportunitySources = Array.isArray(body.opportunities) ? body.opportunities : [];
      const totalRows = accountSources.length + contactSources.length + opportunitySources.length;
      if (!accountSources.length) return jsonResponse({ error: "A relational workbook needs at least one Accounts row." }, 400);
      if (accountSources.length > 1000 || contactSources.length > 1000 || opportunitySources.length > 1000 || totalRows > 3000) {
        return jsonResponse({ error: "Import up to 1,000 Accounts, Contacts, and Opportunities per workbook (3,000 total rows)." }, 400);
      }

      const externalSource = normalizeShipperCrmImportSource(body.source_system || "pipedrive");
      const skippedRows: { entity: string; row: number; reason: string }[] = [];
      const accounts: { sourceIndex: number; patch: Record<string, unknown>; insert: Record<string, unknown>; externalSourceId: string | null }[] = [];
      const seenAccountIds = new Set<string>();
      accountSources.forEach((source, index) => {
        const normalized = normalizeShipperCrmWorkbookAccount(objectRecord(source), externalSource);
        if ("error" in normalized) {
          skippedRows.push({ entity: "account", row: index + 1, reason: normalized.error || "Invalid account row." });
          return;
        }
        const account = normalized as { patch: Record<string, unknown>; insert: Record<string, unknown>; externalSourceId: string | null };
        if (account.externalSourceId && seenAccountIds.has(account.externalSourceId)) {
          skippedRows.push({ entity: "account", row: index + 1, reason: "Duplicate external account id in this workbook." });
          return;
        }
        if (account.externalSourceId) seenAccountIds.add(account.externalSourceId);
        accounts.push({ sourceIndex: index + 1, ...account });
      });

      const referencedAccountIds = [
        ...accounts.map((item) => item.externalSourceId),
        ...contactSources.map((source) => importedShipperValue(objectRecord(source), ["external_account_id", "account_id", "organization_id", "org_id"])),
        ...opportunitySources.map((source) => importedShipperValue(objectRecord(source), ["external_account_id", "account_id", "organization_id", "org_id"]))
      ].filter(Boolean) as string[];
      const existingByExternalKey = new Map<string, Record<string, unknown>>();
      for (const idChunk of chunkValues(Array.from(new Set(referencedAccountIds)), 250)) {
        const existingResult = await supabase.from("shippers").select("*")
          .eq("owner_email", user.owner_email).eq("external_source", externalSource).in("external_source_id", idChunk);
        if (existingResult.error) throw existingResult.error;
        for (const existing of existingResult.data || []) {
          const id = cleanText(existing.external_source_id);
          if (id && cleanText(existing.status)?.toLowerCase() !== "archived") existingByExternalKey.set(`${externalSource}:${id}`, existing as Record<string, unknown>);
        }
      }
      const domains = accounts.map((item) => cleanText(item.insert.domain)?.toLowerCase()).filter(Boolean) as string[];
      const existingByDomain = new Map<string, Record<string, unknown>>();
      for (const domainChunk of chunkValues(Array.from(new Set(domains)), 250)) {
        const existingResult = await supabase.from("shippers").select("*")
          .eq("owner_email", user.owner_email).in("domain", domainChunk);
        if (existingResult.error) throw existingResult.error;
        for (const existing of existingResult.data || []) {
          const domain = cleanText(existing.domain)?.toLowerCase();
          if (domain && cleanText(existing.status)?.toLowerCase() !== "archived") existingByDomain.set(domain, existing as Record<string, unknown>);
        }
      }

      const accountInserts: Record<string, unknown>[] = [];
      const accountUpdates: { id: string; row: Record<string, unknown> }[] = [];
      for (const item of accounts) {
        const domain = cleanText(item.insert.domain)?.toLowerCase();
        const existing = (item.externalSourceId ? existingByExternalKey.get(`${externalSource}:${item.externalSourceId}`) : null)
          || (domain ? existingByDomain.get(domain) : null);
        if (existing && cleanText(existing.id)) {
          const patch = mergedImportedShipper(existing, item.patch);
          patch.external_source = externalSource;
          patch.external_source_id = item.externalSourceId || cleanText(existing.external_source_id);
          accountUpdates.push({ id: String(existing.id), row: patch });
        } else {
          accountInserts.push({ ...withOwner(item.insert, user), organization_id: user.organization_id });
        }
      }
      const accountRows: Record<string, unknown>[] = [];
      for (const insertChunk of chunkValues(accountInserts, 100)) {
        if (!insertChunk.length) continue;
        const result = await supabase.from("shippers").insert(insertChunk).select();
        if (result.error) throw result.error;
        accountRows.push(...(result.data || []) as Record<string, unknown>[]);
      }
      for (const updateChunk of chunkValues(accountUpdates, 25)) {
        const results = await Promise.all(updateChunk.map((item) => supabase.from("shippers").update(item.row)
          .eq("owner_email", user.owner_email).eq("id", item.id).select().single()));
        for (const result of results) {
          if (result.error) throw result.error;
          if (result.data) accountRows.push(result.data as Record<string, unknown>);
        }
      }
      const accountIdByExternalKey = new Map<string, string>();
      for (const row of [...existingByExternalKey.values(), ...accountRows]) {
        const id = cleanText(row.id);
        const sourceId = cleanText(row.external_source_id);
        if (id && sourceId && cleanText(row.external_source) === externalSource) accountIdByExternalKey.set(`${externalSource}:${sourceId}`, id);
      }

      const contactItems: { sourceIndex: number; row: Record<string, unknown>; externalSourceId: string | null; shipperId: string }[] = [];
      contactSources.forEach((source, index) => {
        const normalized = normalizeShipperCrmWorkbookContact(objectRecord(source), externalSource);
        if ("error" in normalized) {
          skippedRows.push({ entity: "contact", row: index + 1, reason: normalized.error || "Invalid contact row." });
          return;
        }
        const shipperId = accountIdByExternalKey.get(`${externalSource}:${normalized.externalAccountId}`);
        if (!shipperId) {
          skippedRows.push({ entity: "contact", row: index + 1, reason: "Linked account was not found in this workspace." });
          return;
        }
        contactItems.push({ sourceIndex: index + 1, row: normalized.row, externalSourceId: normalized.externalSourceId, shipperId });
      });

      const opportunityItems: { sourceIndex: number; row: Record<string, unknown>; externalSourceId: string | null; shipperId: string }[] = [];
      opportunitySources.forEach((source, index) => {
        const normalized = normalizeShipperCrmWorkbookOpportunity(objectRecord(source), externalSource);
        if ("error" in normalized) {
          skippedRows.push({ entity: "opportunity", row: index + 1, reason: normalized.error || "Invalid opportunity row." });
          return;
        }
        const shipperId = accountIdByExternalKey.get(`${externalSource}:${normalized.externalAccountId}`);
        if (!shipperId) {
          skippedRows.push({ entity: "opportunity", row: index + 1, reason: "Linked account was not found in this workspace." });
          return;
        }
        opportunityItems.push({ sourceIndex: index + 1, row: normalized.row, externalSourceId: normalized.externalSourceId, shipperId });
      });

      const importChildren = async (table: "shipper_contacts" | "shipper_opportunities", items: { row: Record<string, unknown>; externalSourceId: string | null; shipperId: string }[]) => {
        const shipperIds = Array.from(new Set(items.map((item) => item.shipperId)));
        const existingByKey = new Map<string, Record<string, unknown>>();
        for (const shipperChunk of chunkValues(shipperIds, 250)) {
          const result = await supabase.from(table).select("id,shipper_id,external_source,external_source_id,metadata")
            .eq("owner_email", user.owner_email).eq("external_source", externalSource).in("shipper_id", shipperChunk);
          if (result.error) throw result.error;
          for (const row of result.data || []) {
            const externalId = cleanText(row.external_source_id);
            if (externalId) existingByKey.set(`${row.shipper_id}:${externalSource}:${externalId}`, row as Record<string, unknown>);
          }
        }
        const inserts: Record<string, unknown>[] = [];
        const updates: { id: string; row: Record<string, unknown> }[] = [];
        for (const item of items) {
          const existing = item.externalSourceId ? existingByKey.get(`${item.shipperId}:${externalSource}:${item.externalSourceId}`) : null;
          if (existing && cleanText(existing.id)) {
            updates.push({
              id: String(existing.id),
              row: { ...item.row, metadata: { ...objectRecord(existing.metadata), ...objectRecord(item.row.metadata) } }
            });
          } else {
            inserts.push({ ...withOwner({ ...item.row, shipper_id: item.shipperId }, user), organization_id: user.organization_id });
          }
        }
        let inserted = 0;
        let updated = 0;
        for (const insertChunk of chunkValues(inserts, 100)) {
          if (!insertChunk.length) continue;
          const result = await supabase.from(table).insert(insertChunk).select("id");
          if (result.error) throw result.error;
          inserted += result.data?.length || 0;
        }
        for (const updateChunk of chunkValues(updates, 25)) {
          const results = await Promise.all(updateChunk.map((item) => supabase.from(table).update(item.row)
            .eq("owner_email", user.owner_email).eq("id", item.id).select("id").single()));
          for (const result of results) {
            if (result.error) throw result.error;
            updated += 1;
          }
        }
        return { inserted, updated };
      };

      const [contactResult, opportunityResult] = await Promise.all([
        importChildren("shipper_contacts", contactItems),
        importChildren("shipper_opportunities", opportunityItems)
      ]);
      const accountInserted = accountInserts.length;
      const accountUpdated = accountUpdates.length;
      await writeAuditLog(
        supabase,
        user,
        "shipper_crm_workbook_imported",
        "shipper_import",
        null,
        `Imported Shipper CRM workbook: ${accountInserted} account(s), ${contactResult.inserted} contact(s), and ${opportunityResult.inserted} opportunity record(s).`,
        { external_source: externalSource, accounts: { inserted: accountInserted, updated: accountUpdated }, contacts: contactResult, opportunities: opportunityResult, skipped: skippedRows.length, total_rows: totalRows }
      );
      return jsonResponse({
        source_system: externalSource,
        accounts: { inserted: accountInserted, updated: accountUpdated },
        contacts: contactResult,
        opportunities: opportunityResult,
        skipped: skippedRows.length,
        total_rows: totalRows,
        skipped_rows: skippedRows.slice(0, 100)
      });
    }

    if (body.action === "update_shipper") {
      const current = await requireOwnedShipper(supabase, user, body.id || body.shipper_id);
      const patch = normalizeShipper(objectRecord(body.patch), true);
      if (Object.prototype.hasOwnProperty.call(patch, "shipper_name") && !cleanText(patch.shipper_name)) {
        return jsonResponse({ error: "Shipper name is required." }, 400);
      }
      const invalid = invalidShipperValue(patch);
      if (invalid) return jsonResponse({ error: invalid }, 400);
      const result = await supabase.from("shippers").update(patch)
        .eq("owner_email", user.owner_email).eq("id", current.id).select().single();
      if (result.error) throw result.error;
      await writeAuditLog(supabase, user, "shipper_updated", "shipper", result.data.id, `Updated shipper ${result.data.shipper_name}.`);
      return jsonResponse({ row: result.data });
    }

    if (body.action === "move_shipper_relationship_stage") {
      const current = await requireOwnedShipper(supabase, user, body.id || body.shipper_id);
      const relationshipStage = cleanText(body.relationship_stage)?.toLowerCase();
      if (!relationshipStage || !SHIPPER_ENUMS.relationship_stage.has(relationshipStage)) {
        return jsonResponse({ error: "Unknown shipper relationship stage." }, 400);
      }
      const result = await supabase.from("shippers")
        .update({ relationship_stage: relationshipStage, updated_at: new Date().toISOString() })
        .eq("owner_email", user.owner_email).eq("id", current.id).select().single();
      if (result.error) throw result.error;
      await writeAuditLog(
        supabase,
        user,
        "shipper_relationship_stage_moved",
        "shipper",
        result.data.id,
        `Moved shipper ${result.data.shipper_name} to ${relationshipStage}.`,
        { from: current.relationship_stage, to: relationshipStage }
      );
      return jsonResponse({ row: result.data });
    }

    if (body.action === "archive_shippers") {
      const ids = normalizeBulkIds(body.ids, { label: "Shipper ids", limit: BULK_SELECTED_ID_LIMIT });
      if (!ids.length) return jsonResponse({ updated: 0, rows: [] });
      requireBulkConfirmation(body, { action: "archive_shippers", label: "Shipper archive", count: ids.length, threshold: 1 });
      const result = await supabase.from("shippers")
        .update({ status: "archived", updated_at: new Date().toISOString() })
        .eq("owner_email", user.owner_email).in("id", ids).select("id,shipper_name,status");
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "shipper.bulk.archive", "shippers", ids.join(","),
        `Archived ${result.data?.length || 0} shipper account(s)`, { requested: ids.length, updated: result.data?.length || 0, ids });
      return jsonResponse({ updated: result.data?.length || 0, rows: result.data || [] });
    }

    if (body.action === "save_shipper_record") {
      const entity = shipperChildEntity(body.entity);
      const config = SHIPPER_CHILD_CONFIG[entity];
      const shipper = await requireOwnedShipper(supabase, user, body.shipper_id);
      const recordId = cleanText(body.id || objectRecord(body.row).id);
      const patch = applyShipperChildDefaults(entity, normalizeShipperChild(entity, objectRecord(body.row)), !recordId);
      if (!cleanText(patch[config.required])) return jsonResponse({ error: `${config.required.replace(/_/g, " ")} is required.` }, 400);
      if (entity === "lanes" && !cleanText(patch.destination)) return jsonResponse({ error: "destination is required." }, 400);
      const invalid = invalidShipperChildValue(entity, patch);
      if (invalid) return jsonResponse({ error: invalid }, 400);
      if (recordId) {
        if (!UUID_PATTERN.test(recordId)) return jsonResponse({ error: "A valid record id is required." }, 400);
        const result = await supabase.from(config.table).update(patch)
          .eq("owner_email", user.owner_email).eq("shipper_id", shipper.id).eq("id", recordId).select().single();
        if (result.error) throw result.error;
        if (entity === "actions") {
          await writeAuditLog(supabase, user, "shipper_account_action_updated", "shipper_account_action", result.data.id,
            `Updated account action ${cleanText(result.data.title) || result.data.id}.`, { shipper_id: shipper.id });
        }
        return jsonResponse({ row: result.data });
      }
      const result = await supabase.from(config.table).insert({
        ...withOwner(patch, user),
        organization_id: user.organization_id,
        shipper_id: shipper.id
      }).select().single();
      if (result.error) throw result.error;
      if (entity === "actions") {
        await writeAuditLog(supabase, user, "shipper_account_action_created", "shipper_account_action", result.data.id,
          `Created account action ${cleanText(result.data.title) || result.data.id}.`, { shipper_id: shipper.id });
      }
      return jsonResponse({ row: result.data });
    }

    if (body.action === "delete_shipper_record") {
      const entity = shipperChildEntity(body.entity);
      const config = SHIPPER_CHILD_CONFIG[entity];
      const shipper = await requireOwnedShipper(supabase, user, body.shipper_id);
      const recordId = cleanText(body.id);
      if (!recordId || !UUID_PATTERN.test(recordId)) return jsonResponse({ error: "A valid record id is required." }, 400);
      requireBulkConfirmation(body, { action: "delete_shipper_record", label: "Shipper record deletion", count: 1 });
      const deletedColumns = entity === "actions" ? "id,title" : "id";
      const result = await supabase.from(config.table).delete()
        .eq("owner_email", user.owner_email).eq("shipper_id", shipper.id).eq("id", recordId).select(deletedColumns).single();
      if (result.error) throw result.error;
      const deletedRecord = result.data as unknown as Record<string, unknown>;
      if (entity === "actions") {
        await tryWriteAuditLog(supabase, user, "shipper_account_action_deleted", "shipper_account_action", deletedRecord.id,
          `Deleted account action ${cleanText(deletedRecord.title) || deletedRecord.id}.`, { shipper_id: shipper.id });
      }
      if (entity !== "actions") {
        await tryWriteAuditLog(supabase, user, "shipper.record.delete", `shipper_${entity}`, deletedRecord.id,
          `Deleted ${entity} record from shipper account`, { shipper_id: shipper.id, entity });
      }
      return jsonResponse({ row: deletedRecord });
    }

    if (body.action === "list_vendors") {
      const offset = Math.max(Number(body.offset) || 0, 0);
      const view = cleanText(body.view)?.toLowerCase() || "all";
      const requestedBaseStage = cleanText(body.base_stage)?.toLowerCase() || "";
      const viewBaseStage = ["sourcing", "procurement", "archived"].includes(view) ? view : "";
      const effectiveBaseStage = ["sourcing", "procurement", "archived"].includes(requestedBaseStage)
        ? requestedBaseStage
        : viewBaseStage;
      const lightweight = body.lightweight === true || cleanText(body.lightweight)?.toLowerCase() === "true";
      const requestedIds = normalizeUuidList(body.ids || body.vendor_ids);
      const vendorSearch = cleanText(body.search);
      const maxLimit = lightweight ? 1000 : 250;
      const limit = Math.min(Math.max(Number(body.limit) || 75, 1), maxLimit);
      const vendorSelect = lightweight
        ? "id,vendor_name,name,legal_name,contact_name,domain,primary_email,secondary_emails,whatsapp_phone,preferred_channel,whatsapp_permission_basis,whatsapp_do_not_contact,whatsapp_opt_in_status,whatsapp_group_url,whatsapp_group_name,whatsapp_meta_group_id,whatsapp_group_status,whatsapp_notes,base_stage,funnel_stage,status,tags,coverage_notes,notes,logo_url,created_at,updated_at"
        : "*";
      let searchIds: string[] | null = null;
      let searchTotal = 0;
      let searchCapped = false;

      if (vendorSearch) {
        const searchResult = await supabase.rpc("search_workspace_vendors", {
          p_owner_email: user.owner_email,
          p_search: vendorSearch,
          p_limit: 1000,
          p_offset: 0
        });
        if (searchResult.error) throw new Error(`Vendor search failed: ${searchResult.error.message}`);
        const matches = (searchResult.data || []) as Array<Record<string, unknown>>;
        searchIds = matches.map((row) => cleanText(row.id)).filter((id): id is string => Boolean(id));
        searchTotal = Number(matches[0]?.total_count || searchIds.length);
        searchCapped = searchTotal > searchIds.length;
        if (!searchIds.length) {
          return jsonResponse({ rows: [], total: 0, limit, offset, warnings: [], search_total: 0, search_capped: false });
        }
      }
      const shouldPageSearchInMemory = Boolean(searchIds);
      let query = supabase
        .from("vendors")
        .select(vendorSelect, { count: "exact" })
        .eq("owner_email", user.owner_email)
        .order("created_at", { ascending: false })
        .order("id", { ascending: false });

      const scopedIds = requestedIds.length && searchIds
        ? requestedIds.filter((id) => searchIds?.includes(id))
        : requestedIds.length
          ? requestedIds
          : searchIds;
      if (scopedIds) {
        if (!scopedIds.length) return jsonResponse({ rows: [], total: 0, limit, offset, warnings: [], search_total: searchTotal, search_capped: searchCapped });
        query = query.in("id", scopedIds);
      }

      if (body.status) query = query.eq("status", body.status);
      if (effectiveBaseStage) {
        query = query.eq("base_stage", effectiveBaseStage);
      }
      if (view === "missing-contact") {
        query = query.is("primary_email", null).is("whatsapp_phone", null);
      }
      if (view === "cross-border") {
        query = query.or("coverage_notes.ilike.%Cross-border%,notes.ilike.%Cross-border%");
      }
      if (view === "high-confidence") {
        query = query.contains("tags", ["alta"]);
      }
      if (view === "procurement-ready") {
        query = query.not("primary_email", "is", null).not("domain", "is", null).not("coverage_notes", "is", null);
      }
      if (body.channel) {
        query = query.eq("preferred_channel", String(body.channel).trim().toLowerCase());
      }
      if (body.tag) {
        const tag = String(body.tag).trim().toLowerCase();
        if (tag) query = query.contains("tags", [tag]);
      }
      if (body.coverage) {
        const coverage = String(body.coverage).trim();
        if (coverage) query = query.or(`coverage_notes.ilike.%${coverage}%,notes.ilike.%${coverage}%`);
      }
      if (shouldPageSearchInMemory) {
        query = query.limit(1000);
      } else {
        query = query.range(offset, offset + limit - 1);
      }
      const result = await query;
      if (result.error) throw result.error;
      let rows = (result.data || []) as unknown as Record<string, unknown>[];
      const filteredTotal = result.count || rows.length;
      if (shouldPageSearchInMemory && searchIds) {
        const rankById = new Map(searchIds.map((id, index) => [id, index]));
        rows = rows
          .sort((left, right) =>
            (rankById.get(cleanText(left.id) || "") ?? Number.MAX_SAFE_INTEGER)
            - (rankById.get(cleanText(right.id) || "") ?? Number.MAX_SAFE_INTEGER)
          )
          .slice(offset, offset + limit);
      }
      let enrichedRows = rows;
      let warnings: string[] = [];
      if (!lightweight && rows.length) {
        const vendorIds = rows.map((row) => row.id).filter(Boolean);
        const [metricsResult, bidMetricsResult] = await Promise.all([
          fetchVendorRateMetricsSafe(supabase, user, { vendorIds }),
          fetchVendorBidMetricsSafe(supabase, user, { vendorIds })
        ]);
        warnings = [...metricsResult.warnings, ...bidMetricsResult.warnings];
        const intelligenceRows = buildVendorIntelligenceRows(rows, metricsResult.metrics, bidMetricsResult.metrics);
        const intelligenceById = new Map(intelligenceRows.map((row) => [cleanText(row.id || row.vendor_id), row]));
        enrichedRows = rows.map((row) => ({
          ...row,
          ...(intelligenceById.get(cleanText(row.id)) || {})
        }));
      }
      return jsonResponse({
        rows: enrichedRows,
        total: vendorSearch ? searchTotal : filteredTotal,
        limit,
        offset,
        warnings,
        search_total: vendorSearch ? searchTotal : filteredTotal,
        search_capped: searchCapped
      });
    }

    if (body.action === "vendor_intelligence") {
      const result = await buildVendorIntelligence(supabase, user, objectRecord(body.options || body));
      return jsonResponse(result);
    }

    if (body.action === "vendor_funnel") {
      const result = await buildVendorFunnel(supabase, user);
      return jsonResponse(result);
    }

    if (body.action === "vendor_onboarding_gaps") {
      const result = await buildVendorOnboardingGaps(supabase, user);
      return jsonResponse(result);
    }

    if (body.action === "import_vendor_onboarding_corrections") {
      const vendors = Array.isArray(body.vendors) ? body.vendors : [];
      const result = await importVendorOnboardingCorrections(supabase, user, vendors);
      return jsonResponse(result);
    }

    if (body.action === "apply_vendor_intelligence_tags") {
      const ids = normalizeBulkIds(body.ids, { label: "Vendor ids", limit: BULK_SELECTED_ID_LIMIT });
      if (!ids.length) return jsonResponse({ updated: 0, rows: [] });

      const intelligence = await buildVendorIntelligence(supabase, user, { ids });
      const byId = new Map((intelligence.rows || []).map((row: Record<string, unknown>) => [row.vendor_id, row]));
      const current = await supabase.from("vendors").select("id,tags").eq("owner_email", user.owner_email).in("id", ids);
      if (current.error) throw current.error;

      const updates = await Promise.all(
        (current.data || []).map((vendor) => {
          const insight = byId.get(vendor.id) as Record<string, unknown> | undefined;
          const suggested = arrayValues(insight?.suggested_tags);
          const mergedTags = Array.from(new Set([...normalizeTags(vendor.tags), ...suggested]));
          return supabase
            .from("vendors")
            .update({ tags: mergedTags, updated_at: new Date().toISOString() })
            .eq("owner_email", user.owner_email)
            .eq("id", vendor.id)
            .select()
            .single();
        })
      );

      for (const update of updates) {
        if (update.error) throw update.error;
      }

      return jsonResponse({ updated: updates.length, rows: updates.map((update) => update.data) });
    }

    if (body.action === "carrier_intelligence_chat") {
      const result = await buildCarrierIntelligence(supabase, user, String(body.message || body.prompt || ""));
      return jsonResponse(result);
    }

    if (body.action === "carrier_recommendations") {
      const result = await buildCarrierRecommendations(supabase, user, objectRecord(body.config));
      return jsonResponse(result);
    }

    if (body.action === "business_intelligence_pivot") {
      const result = await buildBusinessIntelligencePivotFromDb(supabase, user, objectRecord(body.config));
      return jsonResponse(result);
    }

    if (body.action === "business_intelligence_drilldown") {
      const result = await buildBusinessIntelligenceDrilldown(supabase, user, objectRecord(body.config), objectRecord(body.cell));
      return jsonResponse(result);
    }

    if (body.action === "business_intelligence_geo_density") {
      const result = await buildBusinessIntelligenceGeoDensityFromDb(supabase, user, objectRecord(body.config));
      return jsonResponse(result);
    }

    if (body.action === "create_vendor") {
      const row = withOwner(normalizeVendor(objectRecord(body.vendor), "manual"), user);
      const result = await supabase.from("vendors").insert(row).select().single();
      if (result.error) throw result.error;
      return jsonResponse({ row: result.data });
    }

    if (body.action === "import_vendors") {
      const vendors = Array.isArray(body.vendors) ? body.vendors : [];
      const rows = vendors.map((vendor: Record<string, unknown>) => withOwner(normalizeVendor(vendor, "import"), user));
      if (!rows.length) return jsonResponse({ inserted: 0, rows: [] });

      const result = await supabase.from("vendors").insert(rows).select();

      if (result.error) throw result.error;
      return jsonResponse({ inserted: result.data.length, rows: result.data });
    }

    if (body.action === "import_vendors_google_sheet") {
      const url = cleanText(body.url);
      if (!url) return jsonResponse({ error: "Google Sheet URL is required." }, 400);
      const sheet = await fetchGoogleSheetRows(url);
      const rows = sheet.rows.map((raw: Record<string, unknown>) => {
        const normalized = normalizeImportedVendor(raw, "google_sheet");
        return withOwner(normalizeVendor({
          ...normalized,
          source_spreadsheet_url: url,
          source_spreadsheet_id: sheet.id,
          source_sheet_gid: sheet.gid,
          source_row_number: raw.source_row_number,
          source_row_hash: JSON.stringify(raw),
          last_synced_at: new Date().toISOString()
        }, "google_sheet"), user);
      });
      const validRows = rows.filter((row) => row.vendor_name);
      if (!validRows.length) return jsonResponse({ inserted: 0, rows: [], total_rows: sheet.rows.length });

      const previous = await supabase
        .from("vendors")
        .delete()
        .eq("owner_email", user.owner_email)
        .eq("source_spreadsheet_id", sheet.id)
        .eq("source_sheet_gid", sheet.gid);
      if (previous.error) throw previous.error;

      const result = await supabase.from("vendors").insert(validRows).select();
      if (result.error) throw result.error;
      return jsonResponse({ inserted: result.data.length, rows: result.data, total_rows: sheet.rows.length });
    }

    if (body.action === "bulk_update_vendors") {
      const ids = normalizeBulkIds(body.ids, { label: "Vendor ids", limit: BULK_SELECTED_ID_LIMIT });
      if (!ids.length) return jsonResponse({ updated: 0, rows: [] });

      const patchInput = objectRecord(body.patch);
      if (!Object.keys(patchInput).length) return jsonResponse({ error: "Vendor update patch is required." }, 400);
      if (ids.length >= 100 || cleanText(patchInput.base_stage) === "archived") {
        requireBulkConfirmation(body, {
          action: "bulk_update_vendors",
          label: "Vendor bulk update",
          count: ids.length,
          threshold: 1
        });
      }
      const addTags = normalizeTags(patchInput.add_tags);
      const updatedRows: Record<string, unknown>[] = [];

      for (const idBatch of chunkValues(ids, 100)) {
        const current = await supabase.from("vendors").select("*").eq("owner_email", user.owner_email).in("id", idBatch);
        if (current.error) throw current.error;

        for (const vendorBatch of chunkValues(current.data || [], 20)) {
          const updates = await Promise.all(
            vendorBatch.map((vendor) => {
              const patch = normalizeVendorPatch(patchInput, vendor || {});
              if (addTags.length) {
                patch.tags = Array.from(new Set([...normalizeTags(vendor.tags), ...addTags]));
              }
              return supabase
                .from("vendors")
                .update(patch)
                .eq("owner_email", user.owner_email)
                .eq("id", vendor.id)
                .select()
                .single();
            })
          );

          for (const update of updates) {
            if (update.error) throw update.error;
            if (update.data) updatedRows.push(update.data);
          }
        }
      }

      return jsonResponse({ updated: updatedRows.length, rows: updatedRows });
    }

    if (body.action === "apply_vendor_template_updates") {
      const rawRows = Array.isArray(body.rows) ? body.rows.map((row) => objectRecord(row)) : [];
      const dryRun = body.dry_run !== false;
      const maxRows = 10000;
      if (!rawRows.length) return jsonResponse({ received: 0, valid: 0, invalid: 0, updated: 0, skipped: 0, rows: [] });
      if (rawRows.length > maxRows) {
        return jsonResponse({ error: `Vendor CRM template update is limited to ${maxRows} row(s) per upload.` }, 400);
      }
      if (!dryRun) {
        requireBulkConfirmation(body, {
          action: "apply_vendor_template_updates",
          label: "Vendor CRM template update",
          count: rawRows.length,
          threshold: 1
        });
      }

      const editableFields = [
        "vendor_name",
        "legal_name",
        "domain",
        "contact_name",
        "primary_email",
        "secondary_emails",
        "whatsapp_phone",
        "preferred_channel",
        "status",
        "base_stage",
        "funnel_stage",
        "tags",
        "coverage_notes",
        "notes",
        "logo_url",
        "whatsapp_permission_basis",
        "whatsapp_do_not_contact",
        "whatsapp_opt_in_status",
        "whatsapp_group_name",
        "whatsapp_group_url",
        "whatsapp_group_status",
        "whatsapp_notes"
      ];
      const clearableFields = new Set(editableFields.filter((field) => !["vendor_name", "base_stage", "funnel_stage", "status"].includes(field)));
      const aliases: Record<string, string[]> = {
        vendor_id: ["vendor_id", "vendor id", "id", "vendorid"],
        vendor_name: ["vendor_name", "vendor name", "vendor", "carrier", "carrier name", "carrier_name", "name", "company", "company name", "nombre", "nombre comercial", "transportista"],
        legal_name: ["legal_name", "legal name", "legal", "razon social", "razon_social", "razón social", "nombre legal"],
        domain: ["domain", "vendor_domain", "vendor domain", "carrier domain", "dominio", "dominio vendor", "dominio carrier"],
        contact_name: ["contact_name", "contact name", "contact", "contacto", "nombre contacto"],
        primary_email: ["primary_email", "primary email", "email", "emails", "main email", "correo", "correos", "correo principal", "email principal"],
        secondary_emails: ["secondary_emails", "secondary emails", "additional emails", "extra emails", "correos secundarios", "emails secundarios", "correos adicionales"],
        whatsapp_phone: ["whatsapp_phone", "whatsapp phone", "whatsapp", "phone", "telefono", "teléfono", "celular", "numero whatsapp", "número whatsapp"],
        preferred_channel: ["preferred_channel", "preferred channel", "channel", "canal", "canal preferido"],
        status: ["status", "estado"],
        base_stage: ["base_stage", "base stage", "base", "etapa base", "base crm"],
        funnel_stage: ["funnel_stage", "funnel stage", "pipeline stage", "pipeline", "funnel", "embudo", "etapa funnel", "etapa pipeline"],
        tags: ["tags", "tag", "etiquetas"],
        add_tags: ["add_tags", "add tags", "append tags", "agregar tags", "agregar etiquetas"],
        coverage_notes: ["coverage_notes", "coverage notes", "coverage", "cobertura", "notas cobertura"],
        notes: ["notes", "notas"],
        logo_url: ["logo_url", "logo url", "logo"],
        whatsapp_permission_basis: ["whatsapp_permission_basis", "whatsapp permission basis", "whatsapp permission", "permiso whatsapp", "base permiso whatsapp"],
        whatsapp_do_not_contact: ["whatsapp_do_not_contact", "whatsapp do not contact", "do_not_contact_whatsapp", "no contactar whatsapp"],
        whatsapp_opt_in_status: ["whatsapp_opt_in_status", "whatsapp opt in status", "whatsapp opt in", "estatus opt in whatsapp"],
        whatsapp_group_name: ["whatsapp_group_name", "whatsapp group name", "group name", "grupo whatsapp"],
        whatsapp_group_url: ["whatsapp_group_url", "whatsapp group url", "group url", "link grupo whatsapp", "url grupo whatsapp"],
        whatsapp_group_status: ["whatsapp_group_status", "whatsapp group status", "group status", "estatus grupo whatsapp"],
        whatsapp_notes: ["whatsapp_notes", "whatsapp notes", "notas whatsapp"],
        clear_fields: ["clear_fields", "clear fields", "fields to clear", "limpiar campos", "campos a limpiar"],
        update_note: ["update_note", "update note", "comment", "comments", "comentario", "comentarios", "nota actualizacion", "nota actualización"]
      };
      const normalizeTemplateKey = (value: string) => cleanText(value)?.toLowerCase().replace(/[_-]+/g, " ").replace(/\s+/g, " ") || "";
      const templateValue = (row: Record<string, unknown>, field: string) => {
        const byKey = new Map(Object.entries(row).map(([key, value]) => [normalizeTemplateKey(key), value]));
        for (const alias of aliases[field] || [field]) {
          const key = normalizeTemplateKey(alias);
          if (byKey.has(key)) return byKey.get(key);
        }
        return undefined;
      };
      const splitTemplateList = (value: unknown) => String(value || "").split(/[;,|]+/).map((item) => cleanText(item)).filter(Boolean) as string[];
      const valuesMatch = (left: unknown, right: unknown) => JSON.stringify(left ?? null) === JSON.stringify(right ?? null);

      const stagedRows = rawRows.map((row, index) => {
        const reference = {
          vendor_domain: templateValue(row, "domain"),
          vendor_email: templateValue(row, "primary_email"),
          vendor_name: templateValue(row, "vendor_name"),
          legal_name: templateValue(row, "legal_name")
        };
        return {
          raw: row,
          row_number: Number(row.row_number || row.Row || row.row || index + 2),
          vendor_id: cleanText(templateValue(row, "vendor_id")),
          reference,
          references: vendorReferenceValues(reference)
        };
      });
      const ids = Array.from(new Set(stagedRows.map((row) => row.vendor_id).filter(Boolean) as string[]));
      const currentRows: Record<string, unknown>[] = [];
      for (const idBatch of chunkValues(ids, 100)) {
        const currentBatch = await supabase.from("vendors").select("*").eq("owner_email", user.owner_email).in("id", idBatch);
        if (currentBatch.error) throw currentBatch.error;
        currentRows.push(...(currentBatch.data || []));
      }
      const currentById = new Map(currentRows.map((row) => [String(row.id), row]));
      const templateCurrentById = new Map(currentById);
      const needsReferenceLookup = stagedRows.some((row) => !row.vendor_id && row.references.length);
      const referenceRows = needsReferenceLookup ? await fetchVendorReferenceRows(supabase, user) : [];

      const previewRows: Record<string, unknown>[] = [];
      const validUpdates: { id: string; patch: Record<string, unknown> }[] = [];
      const seenTemplateVendorIds = new Set<string>();

      for (const staged of stagedRows) {
        const errors: string[] = [];
        const warnings: string[] = [];
        const changedFields: string[] = [];
        const patchInput: Record<string, unknown> = {};
        const referenceMatch = !staged.vendor_id && staged.references.length
          ? resolveVendorReferencesFromRows(referenceRows, staged.references)
          : null;
        let current = staged.vendor_id ? currentById.get(staged.vendor_id) : referenceMatch?.vendor || null;
        if (!staged.vendor_id && current?.id) {
          const currentId = String(current.id);
          if (!templateCurrentById.has(currentId)) {
            const fullCurrent = await supabase
              .from("vendors")
              .select("*")
              .eq("owner_email", user.owner_email)
              .eq("id", currentId)
              .single();
            if (fullCurrent.error) throw fullCurrent.error;
            if (fullCurrent.data) templateCurrentById.set(currentId, fullCurrent.data);
          }
          current = templateCurrentById.get(currentId) || current;
        }
        const resolvedVendorId = cleanText(current?.id || staged.vendor_id);

        if (!staged.vendor_id && !staged.references.length) errors.push("Missing vendor_id, domain, email, legal_name, or vendor_name.");
        if (staged.vendor_id && !UUID_PATTERN.test(staged.vendor_id)) errors.push("vendor_id must be a valid Rateware row id.");
        if (staged.vendor_id && !current) errors.push("Vendor not found in this workspace.");
        if (!staged.vendor_id && staged.references.length && !current) errors.push("No unique vendor match by domain, email, legal name, or vendor name.");
        if (resolvedVendorId) {
          if (seenTemplateVendorIds.has(resolvedVendorId)) {
            errors.push("Duplicate vendor update row in this template. Keep one row per carrier.");
          } else {
            seenTemplateVendorIds.add(resolvedVendorId);
          }
        }

        for (const field of editableFields) {
          const value = templateValue(staged.raw, field);
          if (value === undefined) continue;
          if (String(value ?? "").trim() === "") continue;
          patchInput[field] = value;
        }

        const addTags = normalizeTags(templateValue(staged.raw, "add_tags"));
        const updateNote = cleanText(templateValue(staged.raw, "update_note"));
        const clearFields = splitTemplateList(templateValue(staged.raw, "clear_fields"));
        for (const field of clearFields) {
          const normalizedField = normalizeTemplateKey(field).replace(/\s+/g, "_");
          if (!clearableFields.has(normalizedField)) {
            warnings.push(`${field} cannot be cleared by template.`);
            continue;
          }
          patchInput[normalizedField] = normalizedField === "tags" || normalizedField === "secondary_emails" ? [] : "";
        }

        let patch: Record<string, unknown> = {};
        if (current && !errors.length) {
          try {
            patch = normalizeVendorPatch(patchInput, current);
            if (updateNote) {
              const existingNotes = cleanText(patch.notes ?? current.notes);
              patch.notes = existingNotes && !existingNotes.toLowerCase().includes(updateNote.toLowerCase())
                ? `${existingNotes}\n${updateNote}`
                : existingNotes || updateNote;
            }
            if (addTags.length) {
              patch.tags = Array.from(new Set([...normalizeTags(patch.tags ?? current.tags), ...addTags]));
            }
            for (const [field, value] of Object.entries(patch)) {
              if (field === "updated_at") continue;
              if (!valuesMatch(value, current[field])) changedFields.push(field);
            }
            if (!changedFields.length) warnings.push("No changed fields detected.");
          } catch (error) {
            errors.push(error instanceof Error ? error.message : "Vendor update could not be normalized.");
          }
        }

        const preview = {
          row_number: staged.row_number,
          vendor_id: resolvedVendorId,
          vendor_name: cleanText(current?.vendor_name || templateValue(staged.raw, "vendor_name")),
          legal_name: cleanText(current?.legal_name || templateValue(staged.raw, "legal_name")),
          domain: normalizeDomain(current?.domain || templateValue(staged.raw, "domain")),
          primary_email: normalizeEmail(current?.primary_email || templateValue(staged.raw, "primary_email")),
          matched_by: staged.vendor_id ? "vendor_id" : referenceMatch?.source || "",
          changed_fields: changedFields,
          change_count: changedFields.length,
          errors,
          warnings
        };
        previewRows.push(preview);
        if (current && resolvedVendorId && !errors.length && changedFields.length) validUpdates.push({ id: resolvedVendorId, patch });
      }

      if (dryRun) {
        const invalid = previewRows.filter((row) => (row.errors as string[]).length).length;
        return jsonResponse({
          received: rawRows.length,
          valid: validUpdates.length,
          invalid,
          updated: 0,
          skipped: rawRows.length - validUpdates.length,
          rows: previewRows
        });
      }

      const updatedRows: Record<string, unknown>[] = [];
      for (const updateBatch of chunkValues(validUpdates, 50)) {
        const updates = await Promise.all(updateBatch.map((item) => supabase
          .from("vendors")
          .update(item.patch)
          .eq("owner_email", user.owner_email)
          .eq("id", item.id)
          .select()
          .single()));
        for (const update of updates) {
          if (update.error) throw update.error;
          if (update.data) updatedRows.push(update.data);
        }
      }
      await tryWriteAuditLog(supabase, user, "vendor.template_update", "vendors", "bulk",
        `Updated ${updatedRows.length} vendor(s) from CRM template`, { requested: rawRows.length, updated: updatedRows.length });
      return jsonResponse({
        received: rawRows.length,
        valid: validUpdates.length,
        invalid: previewRows.filter((row) => (row.errors as string[]).length).length,
        updated: updatedRows.length,
        skipped: rawRows.length - updatedRows.length,
        rows: previewRows
      });
    }

    if (body.action === "remove_vendors") {
      const ids = normalizeBulkIds(body.ids, { label: "Vendor ids", limit: BULK_SELECTED_ID_LIMIT });
      if (!ids.length) return jsonResponse({ removed: 0, rows: [] });
      requireBulkConfirmation(body, {
        action: "remove_vendors",
        label: "Vendor removal",
        count: ids.length
      });
      const result = await supabase.from("vendors").delete().eq("owner_email", user.owner_email).in("id", ids).select("id");
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "vendor.bulk.remove", "vendors", ids.join(","),
        `Removed ${result.data.length} vendor(s)`, { requested: ids.length, removed: result.data.length, ids });
      return jsonResponse({ removed: result.data.length, rows: result.data });
    }

    if (body.action === "update_vendor") {
      if (!body.id) return jsonResponse({ error: "Vendor id is required." }, 400);
      const current = await supabase.from("vendors").select("*").eq("owner_email", user.owner_email).eq("id", body.id).single();
      if (current.error) throw current.error;
      const patch = normalizeVendorPatch(objectRecord(body.patch), objectRecord(current.data));
      if (patch.vendor_name === null) return jsonResponse({ error: "Vendor name is required." }, 400);
      const result = await supabase.from("vendors").update(patch).eq("owner_email", user.owner_email).eq("id", body.id).select().single();
      if (result.error) throw result.error;
      return jsonResponse({ row: result.data });
    }

    if (body.action === "replace_bounced_vendor_email") {
      const vendorId = cleanText(body.id || body.vendor_id);
      const rawBouncedEmail = cleanText(body.bounced_email)?.toLowerCase() || "";
      const rawReplacementEmail = cleanText(body.replacement_email)?.toLowerCase() || "";
      const bouncedEmail = normalizeEmail(rawBouncedEmail);
      const replacementEmail = normalizeEmail(rawReplacementEmail);
      if (!vendorId) return jsonResponse({ error: "Vendor id is required." }, 400);
      if (!bouncedEmail || !replacementEmail || bouncedEmail !== rawBouncedEmail || replacementEmail !== rawReplacementEmail) {
        return jsonResponse({ error: "Enter a valid bounced email and replacement email." }, 400);
      }
      if (bouncedEmail === replacementEmail) {
        return jsonResponse({ error: "The replacement email must be different from the bounced email." }, 400);
      }

      const current = await supabase
        .from("vendors")
        .select("*")
        .eq("owner_email", user.owner_email)
        .eq("id", vendorId)
        .single();
      if (current.error) throw current.error;

      const profileData = objectRecord(current.data?.profile_data);
      const bouncedEmails = Array.isArray(profileData.bounced_emails) ? profileData.bounced_emails : [];
      const hasBounceRecord = bouncedEmails.some((item) => normalizeEmail(objectRecord(item).email) === bouncedEmail && !objectRecord(item).resolved_at);
      if (!hasBounceRecord) {
        return jsonResponse({ error: "This vendor does not have an unresolved delivery failure for that email." }, 400);
      }

      const replacementSuppression = await supabase
        .from("email_suppression_list")
        .select("id")
        .eq("owner_email", user.owner_email)
        .eq("email", replacementEmail)
        .is("resolved_at", null)
        .in("status", blockedEmailStatuses())
        .maybeSingle();
      if (replacementSuppression.error) throw replacementSuppression.error;
      if (replacementSuppression.data) {
        return jsonResponse({ error: "That replacement email is blocked by a delivery failure. Use a different address." }, 400);
      }

      const now = new Date().toISOString();
      const primaryEmail = normalizeEmail(current.data?.primary_email);
      const secondaryEmails = normalizeEmailList(current.data?.secondary_emails)
        .filter((email) => email !== bouncedEmail && email !== replacementEmail);
      const nextPrimaryEmail = primaryEmail === bouncedEmail || !primaryEmail ? replacementEmail : primaryEmail;
      const nextSecondaryEmails = primaryEmail === bouncedEmail
        ? secondaryEmails
        : Array.from(new Set([replacementEmail, ...secondaryEmails]));
      const nextBouncedEmails = bouncedEmails.map((item) => {
        const record = objectRecord(item);
        if (normalizeEmail(record.email) !== bouncedEmail || record.resolved_at) return record;
        return {
          ...record,
          resolved_at: now,
          resolved_by: user.owner_email,
          replacement_email: replacementEmail
        };
      });
      const unresolvedBouncesRemain = nextBouncedEmails.some((item) => !objectRecord(item).resolved_at);
      const tags = normalizeTags(current.data?.tags).filter((tag) => tag !== "email_bounce");
      if (unresolvedBouncesRemain) tags.push("email_bounce");

      const result = await supabase
        .from("vendors")
        .update({
          primary_email: nextPrimaryEmail,
          secondary_emails: nextSecondaryEmails,
          tags: Array.from(new Set(tags)),
          profile_data: { ...profileData, bounced_emails: nextBouncedEmails },
          updated_at: now
        })
        .eq("owner_email", user.owner_email)
        .eq("id", vendorId)
        .select()
        .single();
      if (result.error) throw result.error;

      const suppressionUpdate = await supabase
        .from("email_suppression_list")
        .update({
          resolved_at: now,
          resolved_by: user.owner_email,
          replacement_email: replacementEmail,
          updated_at: now
        })
        .eq("owner_email", user.owner_email)
        .eq("email", bouncedEmail)
        .is("resolved_at", null);
      if (suppressionUpdate.error) throw suppressionUpdate.error;

      await tryWriteAuditLog(
        supabase,
        user,
        "vendor.email_bounce.resolve",
        "vendors",
        vendorId,
        `Replaced bounced email for ${current.data?.vendor_name || "vendor"}`,
        { bounced_email: bouncedEmail, replacement_email: replacementEmail }
      );
      return jsonResponse({ row: result.data, bounced_email: bouncedEmail, replacement_email: replacementEmail });
    }

    if (body.action === "create_vendor_profile_request") {
      const vendorId = cleanText(body.vendor_id || body.id);
      if (!vendorId) return jsonResponse({ error: "Vendor id is required." }, 400);

      const current = await supabase
        .from("vendors")
        .select("id,vendor_name,domain,primary_email,owner_user_id,owner_email")
        .eq("owner_email", user.owner_email)
        .eq("id", vendorId)
        .single();
      if (current.error) throw current.error;

      const expiresInDays = Math.min(Math.max(Number(body.expires_in_days) || 30, 1), 90);
      const expiresAt = new Date(Date.now() + expiresInDays * 86400000).toISOString();
      const tokenSeed = `${crypto.randomUUID()}${crypto.randomUUID()}`.replace(/-/g, "");
      const requestToken = tokenSeed.slice(0, 48);
      const origin = cleanUrl(body.origin) || Deno.env.get("RATEWARE_PUBLIC_APP_URL") || "https://rateware.vercel.app";
      const baseUrl = origin.replace(/\/$/, "");
      const row = {
        owner_user_id: user.owner_user_id,
        owner_email: user.owner_email,
        vendor_id: vendorId,
        request_token: null,
        request_token_hash: await hashVendorProfileRequestToken(requestToken),
        status: "active",
        expires_at: expiresAt,
        metadata: {
          vendor_name: current.data?.vendor_name,
          generated_from: "carrier_crm",
          expires_in_days: expiresInDays
        }
      };

      const result = await supabase.from("vendor_profile_requests").insert(row).select().single();
      if (result.error) throw result.error;

      await writeAuditLog(
        supabase,
        user,
        "vendor.profile_request.create",
        "vendors",
        vendorId,
        `Created carrier profile request for ${current.data?.vendor_name || "vendor"}`,
        { request_id: result.data.id, expires_at: expiresAt }
      );

      return jsonResponse({
        id: result.data.id,
        token: requestToken,
        url: `${baseUrl}/carrier-profile.html?token=${encodeURIComponent(requestToken)}`,
        expires_at: expiresAt,
        vendor: current.data
      });
    }

    if (body.action === "upload_vendor_logo") {
      const vendorId = cleanText(body.vendor_id || body.id);
      if (!vendorId) return jsonResponse({ error: "Vendor id is required." }, 400);

      const current = await supabase.from("vendors").select("*").eq("owner_email", user.owner_email).eq("id", vendorId).single();
      if (current.error) throw current.error;

      const decoded = decodeBase64Payload(body.data_url || body.base64);
      if (!decoded?.bytes?.length) return jsonResponse({ error: "Logo file is required." }, 400);
      if (decoded.bytes.byteLength > 1_500_000) return jsonResponse({ error: "Logo must be 1.5 MB or smaller." }, 400);

      const mimeType = cleanText(body.mime_type || decoded.mimeType)?.toLowerCase() || "application/octet-stream";
      const allowed = new Set(["image/png", "image/jpeg", "image/gif"]);
      if (!allowed.has(mimeType)) return jsonResponse({ error: "Logo must be PNG, JPEG, or GIF." }, 400);

      const extension = vendorLogoExtension(mimeType, body.filename);
      const ownerSegment = safeStorageSegment(user.owner_email || user.owner_user_id, "owner");
      const vendorSegment = safeStorageSegment(current.data.vendor_name || vendorId, "vendor");
      const path = `${ownerSegment}/${vendorId}/${Date.now()}-${vendorSegment}.${extension}`;
      const upload = await supabase.storage.from(VENDOR_LOGOS_BUCKET).upload(path, decoded.bytes, {
        contentType: mimeType,
        upsert: true
      });
      if (upload.error) throw upload.error;

      const publicUrl = supabase.storage.from(VENDOR_LOGOS_BUCKET).getPublicUrl(path).data.publicUrl;
      const result = await supabase
        .from("vendors")
        .update({
          logo_url: publicUrl,
          logo_storage_bucket: VENDOR_LOGOS_BUCKET,
          logo_storage_path: path,
          logo_source: "upload",
          updated_at: new Date().toISOString()
        })
        .eq("owner_email", user.owner_email)
        .eq("id", vendorId)
        .select()
        .single();
      if (result.error) throw result.error;
      await writeAuditLog(supabase, user, "vendor.logo.upload", "vendors", vendorId, "Uploaded vendor logo", { path, mime_type: mimeType });
      return jsonResponse({ row: result.data, url: publicUrl, path });
    }

    if (body.action === "list_vendor_segments") {
      const requestedSegmentType = cleanText(body.segment_type)?.toLowerCase();
      const requestedLimit = Number(body.limit);
      const limit = Number.isFinite(requestedLimit) && requestedLimit > 0
        ? Math.min(Math.floor(requestedLimit), 1000)
        : 1000;
      const offset = Math.max(Number(body.offset) || 0, 0);
      let query = supabase
        .from("vendor_segments")
        .select("*", { count: "exact" })
        .order("created_at", { ascending: false })
        .range(offset, offset + limit - 1);
      if (requestedSegmentType === "participant_template") {
        query = query.eq("owner_email", user.owner_email).eq("segment_type", "participant_template");
      } else {
        query = query.or(`owner_email.is.null,owner_email.eq.${user.owner_email}`);
      }
      const result = await query;
      if (result.error) throw result.error;
      const rows = result.data || [];
      const total = result.count || 0;
      return jsonResponse({ rows, total, limit, offset, has_more: offset + rows.length < total });
    }

    if (body.action === "create_vendor_segment") {
      const row = normalizeSegment(objectRecord(body.segment), user);
      if (row.segment_type === "participant_template") {
        if (!row.vendor_ids.length) return jsonResponse({ error: "Participant templates must include at least one carrier." }, 400);
        const conflict = await findParticipantTemplateNameConflict(supabase, user, row.segment_name);
        if (conflict) {
          return jsonResponse({ error: `A participant template named "${conflict.segment_name}" already exists. Update the existing template instead.` }, 409);
        }
      }
      const result = await supabase.from("vendor_segments").insert(row).select().single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "vendor.segment.create", "vendor_segments", result.data.id,
        `Created vendor segment ${cleanText(result.data.segment_name) || result.data.id}`, {
          segment_type: result.data.segment_type,
          vendor_count: result.data.vendor_ids?.length || 0
        });
      return jsonResponse({ row: result.data });
    }

    if (body.action === "update_vendor_segment") {
      if (!body.id) return jsonResponse({ error: "Segment id is required." }, 400);
      const patch = normalizeSegment(objectRecord(body.segment || body.patch), user);
      if (patch.segment_type === "participant_template") {
        if (!patch.vendor_ids.length) return jsonResponse({ error: "Participant templates must include at least one carrier." }, 400);
        const conflict = await findParticipantTemplateNameConflict(supabase, user, patch.segment_name, String(body.id));
        if (conflict) {
          return jsonResponse({ error: `A participant template named "${conflict.segment_name}" already exists. Choose a different name.` }, 409);
        }
      }
      const result = await supabase
        .from("vendor_segments")
        .update(patch)
        .eq("owner_email", user.owner_email)
        .eq("id", body.id)
        .select()
        .single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "vendor.segment.update", "vendor_segments", result.data.id,
        `Updated vendor segment ${cleanText(result.data.segment_name) || result.data.id}`, {
          segment_type: result.data.segment_type,
          vendor_count: result.data.vendor_ids?.length || 0
        });
      return jsonResponse({ row: result.data });
    }

    if (body.action === "delete_vendor_segment") {
      if (!body.id) return jsonResponse({ error: "Segment id is required." }, 400);
      requireBulkConfirmation(body, { action: "delete_vendor_segment", label: "Vendor segment deletion", count: 1 });
      const requestedSegmentType = cleanText(body.segment_type)?.toLowerCase();
      let query = supabase.from("vendor_segments").delete().eq("owner_email", user.owner_email).eq("id", body.id);
      if (requestedSegmentType) query = query.eq("segment_type", requestedSegmentType);
      const result = await query.select().single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "vendor.segment.delete", "vendor_segments", result.data.id,
        `Deleted vendor segment ${cleanText(result.data.segment_name || result.data.name) || result.data.id}`);
      return jsonResponse({ row: result.data });
    }

    if (body.action === "list_rfx_events") {
      const eventRows = await fetchAllOwnedRfxEvents(supabase, user.owner_email);
      const eventIds = eventRows.map((event) => cleanText(event.id)).filter(Boolean) as string[];
       const [laneRows, invitationRows] = eventIds.length
         ? await Promise.all([
             fetchAllRfxEventRows(supabase, "rfx_lanes", eventIds, "id,rfx_event_id"),
             fetchAllRfxEventRows(supabase, "rfx_lane_vendors", eventIds, "id,rfx_event_id,invitation_status,bid_rate")
           ])
         : [[], []];

       const laneCounts = new Map<string, number>();
       for (const lane of laneRows) laneCounts.set(String(lane.rfx_event_id), (laneCounts.get(String(lane.rfx_event_id)) || 0) + 1);
       const invitationCounts = new Map<string, number>();
       const bidCounts = new Map<string, number>();
       for (const invite of invitationRows) {
         const eventId = String(invite.rfx_event_id);
         invitationCounts.set(eventId, (invitationCounts.get(eventId) || 0) + 1);
         if (isQuotedInvitation(invite)) {
           bidCounts.set(eventId, (bidCounts.get(eventId) || 0) + 1);
         }
       }

      return jsonResponse({
        rows: eventRows.map((event) => ({
          ...event,
          lane_count: laneCounts.get(cleanText(event.id) || "") || 0,
          invitation_count: invitationCounts.get(cleanText(event.id) || "") || 0,
          bid_count: bidCounts.get(cleanText(event.id) || "") || 0
        }))
      });
    }

    if (body.action === "create_rfx_event") {
      const eventInput = objectRecord(body.event || body);
      const row = withOwner(normalizeRfxEvent(eventInput), user);
      const result = await supabase.from("rfx_events").insert(row).select().single();
      if (result.error) throw result.error;
      const sync = await ensureRatebookForBidRoomEvent(supabase, user, result.data as Record<string, unknown>, eventInput);
      return jsonResponse({ row: sync.event || result.data, ratebook_sync: sync });
    }

    if (body.action === "update_rfx_event") {
      const eventId = cleanText(body.id || body.event_id);
      if (!eventId) return jsonResponse({ error: "RFx event id is required." }, 400);
      const eventPatch = objectRecord(body.patch || body.event);
      const patch = normalizeRfxEventPatch(eventPatch);
      const closed = cleanText(patch.status)?.toLowerCase() === "closed";
      let closeoutStaging = null;
      let closeoutOutcomes = null;
      if (closed) {
        const decisionSnapshot = await requireCompleteRfxAwardDecisions(supabase, user, eventId);
        if (decisionSnapshot.bid_lane_count) {
          closeoutStaging = await closeoutAwardedRfxToRateware(supabase, user, {
            event_id: eventId,
            target_status: "pending_review"
          });
          closeoutOutcomes = closeoutStaging.outcomes;
        } else {
          closeoutOutcomes = await finalizeRfxBidOutcomes(supabase, user, eventId, decisionSnapshot.invitations);
        }
      }
      const result = await supabase
        .from("rfx_events")
        .update(patch)
        .eq("id", eventId)
        .eq("owner_email", user.owner_email)
        .select()
        .single();
      if (result.error) throw result.error;
      const sync = await ensureRatebookForBidRoomEvent(supabase, user, result.data as Record<string, unknown>, eventPatch);
      let closeoutNotices = null;
      let closeoutNoticeError = null;
      if (closed) {
        try {
          closeoutNotices = await generateRfxAwardNotices(supabase, user, {
            event_id: result.data.id,
            app_origin: Deno.env.get("RATEWARE_APP_URL") || "https://rateware.vercel.app",
            sender_email: GMAIL_ALLOWED_SENDER,
            sender_label: GMAIL_ALLOWED_SENDER
          });
        } catch (error) {
          closeoutNoticeError = safeOperationalError(error);
          await tryWriteAuditLog(
            supabase,
            user,
            "rfx.event.closeout_notices.error",
            "rfx_events",
            result.data.id,
            `RFx closed but closeout notice drafts could not be generated: ${closeoutNoticeError}`,
            { error: closeoutNoticeError }
          );
        }
      }
      if (closed) {
        await tryWriteAuditLog(
          supabase,
          user,
          "rfx.event.closeout_notices.generate",
          "rfx_events",
          result.data.id,
          `Generated ${closeoutNotices?.generated || 0} closeout email draft(s) on event close`,
          { generated: closeoutNotices?.generated || 0, skipped: closeoutNotices?.skipped?.length || 0 }
        );
      }
      return jsonResponse({
        row: sync.event || result.data,
        ratebook_sync: sync,
        closeout_staging: closeoutStaging,
        closeout_outcomes: closeoutOutcomes,
        closeout_notices: closeoutNotices,
        closeout_notice_error: closeoutNoticeError
      });
    }

    if (body.action === "archive_rfx_event") {
      const eventId = cleanText(body.id || body.event_id);
      if (!eventId) return jsonResponse({ error: "RFx event id is required." }, 400);
      requireBulkConfirmation(body, { action: "archive_rfx_event", label: "RFx event archive", count: 1 });
      const result = await supabase
        .from("rfx_events")
        .update({ status: "archived", updated_at: new Date().toISOString() })
        .eq("id", eventId)
        .eq("owner_email", user.owner_email)
        .select()
        .single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "rfx.event.archive", "rfx_events", result.data.id,
        `Archived RFx event ${cleanText(result.data.rfx_id || result.data.name) || result.data.id}`);
      return jsonResponse({ row: result.data });
    }

    if (body.action === "delete_rfx_event") {
      const eventId = cleanText(body.id || body.event_id);
      if (!eventId) return jsonResponse({ error: "RFx event id is required." }, 400);
      requireBulkConfirmation(body, { action: "delete_rfx_event", label: "RFx event deletion", count: 1 });
      const result = await supabase
        .from("rfx_events")
        .delete()
        .eq("id", eventId)
        .eq("owner_email", user.owner_email)
        .select("id,rfx_id,name")
        .single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "rfx.event.delete", "rfx_events", result.data.id,
        `Deleted RFx event ${cleanText(result.data.rfx_id || result.data.name) || result.data.id}`);
      return jsonResponse({ removed: result.data });
    }

    if (body.action === "duplicate_rfx_event") {
      const event = await requireOwnedRfxEvent(supabase, user, body.id || body.event_id);
      const [lanesResult, invitationsResult] = await Promise.all([
        supabase
          .from("rfx_lanes")
          .select("*")
          .eq("rfx_event_id", event.id)
          .order("lane_number", { ascending: true }),
        supabase
          .from("rfx_lane_vendors")
          .select("rfx_lane_id,vendor_id,notes")
          .eq("rfx_event_id", event.id)
          .neq("invitation_status", "archived")
      ]);
      if (lanesResult.error) throw lanesResult.error;
      if (invitationsResult.error) throw invitationsResult.error;

      const suffix = cleanText(body.name_suffix) || "Copy";
      const eventRow = withOwner({
        rfx_id: `${event.rfx_id || "RFx"}-${suffix}`.slice(0, 120),
        name: `${event.name || event.rfx_id || "RFx"} ${suffix}`.trim(),
        customer: event.customer,
        event_type: event.event_type || "spot",
        status: "draft",
        bid_visibility_mode: event.bid_visibility_mode || "anonymous_rank",
        due_date: null,
        notes: event.notes,
        source_rfx_process_project_id: event.source_rfx_process_project_id || null,
        source_rfx_package_id: event.source_rfx_package_id || null,
        source_rfx_package_name: event.source_rfx_package_name || null,
        rfx_master_package: event.rfx_master_package || {},
        updated_at: new Date().toISOString()
      }, user);
      const eventInsert = await supabase.from("rfx_events").insert(eventRow).select().single();
      if (eventInsert.error) throw eventInsert.error;

      const oldToNewLane = new Map<string, string>();
      const laneRows = (lanesResult.data || []).map((lane) => {
        const { id: _id, created_at: _createdAt, updated_at: _updatedAt, rfx_event_id: _oldEventId, ...rest } = lane;
        return {
          ...rest,
          rfx_event_id: eventInsert.data.id,
          updated_at: new Date().toISOString()
        };
      });
      let insertedLanes: Record<string, unknown>[] = [];
      if (laneRows.length) {
        const laneInsert = await supabase
          .from("rfx_lanes")
          .insert(laneRows)
          .select()
          .order("lane_number", { ascending: true });
        if (laneInsert.error) throw laneInsert.error;
        insertedLanes = laneInsert.data || [];
        (lanesResult.data || []).forEach((oldLane, index) => {
          const nextLane = insertedLanes[index];
          if (oldLane?.id && nextLane?.id) oldToNewLane.set(String(oldLane.id), String(nextLane.id));
        });
      }

      const vendorRows = await Promise.all((invitationsResult.data || [])
        .flatMap((invitation) => {
          const nextLaneId = oldToNewLane.get(String(invitation.rfx_lane_id));
          if (!nextLaneId) return [];
          return [async () => ({
            rfx_event_id: eventInsert.data.id,
            rfx_lane_id: nextLaneId,
            vendor_id: invitation.vendor_id,
            invitation_status: "drafted",
            ...(await newRfxInvitationTokenFields()),
            notes: invitation.notes
          })];
        }).map((buildRow) => buildRow()));
      let insertedVendors = 0;
      if (vendorRows.length) {
        const vendorInsert = await supabase
          .from("rfx_lane_vendors")
          .insert(vendorRows)
          .select("id");
        if (vendorInsert.error) throw vendorInsert.error;
        insertedVendors = vendorInsert.data?.length || 0;
      }

      return jsonResponse({
        row: eventInsert.data,
        lanes: insertedLanes.length,
        invitations: insertedVendors
      });
    }

    if (body.action === "import_rfx_lanes") {
      const event = await requireOwnedRfxEvent(supabase, user, body.event_id);
      if (["closed", "awarded", "archived"].includes(String(event.status || "").toLowerCase())) {
        return jsonResponse({ error: "This bid event is closed. New lanes cannot be added." }, 409);
      }
      const rows = Array.isArray(body.rows) ? body.rows.slice(0, 1000) : [];
      if (!rows.length) return jsonResponse({ inserted: 0, rows: [] });
      const existingResult = await supabase
        .from("rfx_lanes")
        .select("id,origin,destination,equipment,trailer,config,operation,service")
        .eq("rfx_event_id", event.id);
      if (existingResult.error) throw existingResult.error;
      const existingKeys = new Set((existingResult.data || []).map((row) => rfxLaneAppendKey(row)).filter(Boolean));
      const skippedRows: { row_number: number; lane_number: number }[] = [];
      const laneRows: Record<string, unknown>[] = [];
      rows.forEach((row: Record<string, unknown>, index: number) => {
        const normalized = {
          ...normalizeRfxLane(row, index),
          rfx_event_id: event.id
        };
        if (!(normalized.origin || normalized.destination)) return;
        const appendKey = rfxLaneAppendKey(normalized);
        if (appendKey && existingKeys.has(appendKey)) {
          skippedRows.push({ row_number: index + 1, lane_number: Number(normalized.lane_number) || index + 1 });
          return;
        }
        if (appendKey) existingKeys.add(appendKey);
        laneRows.push(normalized);
      });
      if (!laneRows.length) {
        return jsonResponse({ inserted: 0, skipped: skippedRows.length, skipped_rows: skippedRows, rows: [], mode: "append" });
      }
      const result = await supabase
        .from("rfx_lanes")
        .insert(laneRows)
        .select()
        .order("lane_number", { ascending: true });
      if (result.error) throw result.error;
      const sync = await ensureRatebookForBidRoomEvent(supabase, user, event, body);
      return jsonResponse({
        inserted: result.data?.length || 0,
        skipped: skippedRows.length,
        skipped_rows: skippedRows,
        rows: result.data || [],
        mode: "append",
        ratebook_sync: sync
      });
    }

    if (body.action === "update_rfx_lane") {
      const laneId = cleanText(body.id || body.lane_id);
      if (!laneId) return jsonResponse({ error: "RFx lane id is required." }, 400);
      const patch = normalizeRfxLanePatch(objectRecord(body.patch || body.lane));
      if (!Object.keys(patch).length) return jsonResponse({ error: "No RFx lane changes were provided." }, 400);
      const laneResult = await supabase
        .from("rfx_lanes")
        .select("*")
        .eq("id", laneId)
        .single();
      if (laneResult.error) throw laneResult.error;
      const lane = laneResult.data || {};
      const event = await requireOwnedRfxEvent(supabase, user, lane.rfx_event_id);
      const nextOrigin = Object.prototype.hasOwnProperty.call(patch, "origin") ? patch.origin : lane.origin;
      const nextDestination = Object.prototype.hasOwnProperty.call(patch, "destination") ? patch.destination : lane.destination;
      if (!cleanText(nextOrigin)) return jsonResponse({ error: "Origin is required before saving this lane." }, 400);
      if (!cleanText(nextDestination)) return jsonResponse({ error: "Destination is required before saving this lane." }, 400);
      const result = await supabase
        .from("rfx_lanes")
        .update(patch)
        .eq("id", laneId)
        .eq("rfx_event_id", event.id)
        .select()
        .single();
      if (result.error) throw result.error;
      await writeAuditLog(
        supabase,
        user,
        "bid_room.lane.update",
        "rfx_lanes",
        laneId,
        `Updated RFx lane ${result.data?.lane_number || ""}`.trim(),
        { fields: Object.keys(patch).filter((field) => field !== "updated_at") }
      );
      const sync = await ensureRatebookForBidRoomEvent(supabase, user, event, body);
      return jsonResponse({ row: result.data, ratebook_sync: sync });
    }

    if (body.action === "list_rfx_detail") {
      const event = await requireOwnedRfxEvent(supabase, user, body.event_id || body.id);
      const invitationColumns = "*, vendors(id,vendor_name,domain,primary_email,whatsapp_phone,preferred_channel,base_stage,status,tags,coverage_notes)";
      // Benchmarks are independent of the event lanes and invitations. Load all
      // three concurrently so opening a Bid Room pays one database round trip.
      const [eventLanes, loadedInvitationRows, benchmarkLoad] = await Promise.all([
        fetchAllRfxLaneRows(supabase, event.id, "*"),
        fetchAllRfxLaneVendorRows(supabase, event.id, invitationColumns),
        fetchRfxDetailBenchmarkRates(supabase, user, event.id)
          .then((value) => ({ value, error: null as unknown }))
          .catch((error) => ({ value: null, error }))
      ]);

      // Benchmarks enrich the lane view but must never make an RFx unavailable.
      const rates = benchmarkLoad.value?.rows || [];
      const ratewareBenchmark = benchmarkLoad.error
        ? {
            available: false,
            limited: false,
            warning: safeOperationalError(benchmarkLoad.error)
          }
        : {
            available: true,
            limited: Boolean(benchmarkLoad.value?.limited),
            warning: null as string | null
          };

      let invitationRows = loadedInvitationRows;
      const activeVendorIds = [...new Set(
        invitationRows
          .filter((invitation) => (cleanText(invitation.invitation_status) || "").toLowerCase() !== "archived")
          .map((invitation) => cleanText(invitation.vendor_id))
          .filter((vendorId): vendorId is string => Boolean(vendorId))
      )];
      let coverageInserted = 0;
      let coverageWarning = null as string | null;

      // Older active RFx events may have created only the lane that first
      // generated an invitation. Repair the complete business book before it
      // is rendered so every active participant sees every event lane.
      if ((cleanText(event.status) || "").toLowerCase() === "open" && activeVendorIds.length && eventLanes.length) {
        try {
          const coverage = await ensureRfxEventVendorCoverage(
            supabase,
            event.id,
            activeVendorIds,
            eventLanes,
            loadedInvitationRows
          );
          coverageInserted = coverage.inserted;
          if (coverageInserted) {
            invitationRows = await fetchAllRfxLaneVendorRows(supabase, event.id, invitationColumns);
          }
        } catch (error) {
          coverageWarning = safeOperationalError(error);
        }
      }

      const invitationsByLane = new Map<string, Record<string, unknown>[]>();
      for (const invitation of invitationRows) {
        const laneId = cleanText(invitation.rfx_lane_id);
        if (!laneId) continue;
        const bucket = invitationsByLane.get(laneId) || [];
        bucket.push(invitation);
        invitationsByLane.set(laneId, bucket);
      }

      const lanes = eventLanes.map((lane) => {
        const benchmark = bestRatewareBenchmark(lane, rates);
        const supplyDepth = supplyDepthForLane(lane, rates);
        const invitations = (invitationsByLane.get(cleanText(lane.id) || "") || []).map((invitation) => invitationWithComparison(invitation, benchmark));
        return {
          ...lane,
          benchmark,
          supply_depth: supplyDepth,
          invitations,
          invitation_count: invitations.length,
          bid_count: invitations.filter(isQuotedInvitation).length
        };
      });

      return jsonResponse({
        event,
        lanes,
        coverage_sync: { inserted: coverageInserted },
        coverage_warning: coverageWarning,
        rateware_benchmark: ratewareBenchmark
      });
    }

    if (body.action === "list_rfx_response_vendor_ids") {
      const event = await requireOwnedRfxEvent(supabase, user, body.rfx_event_id || body.event_id);
      return jsonResponse(await listRfxResponseVendorIds(supabase, user, event.id));
    }

    if (body.action === "list_rfx_event_context") {
      const event = await requireOwnedRfxEvent(supabase, user, body.rfx_event_id || body.event_id);
      return jsonResponse(await listRfxEventContext(supabase, user, event));
    }

    if (body.action === "list_bid_room_chat") {
      const result = await listBidRoomChat(supabase, user, body);
      const actionCompletedAt = performance.now();
      console.info(JSON.stringify({
        event: "rateware_api.performance",
        action: "list_bid_room_chat",
        authentication_ms: Math.round(authenticationCompletedAt - authenticationStartedAt),
        body_parse_ms: Math.round(bodyParsedAt - authenticationCompletedAt),
        action_ms: Math.round(actionCompletedAt - bodyParsedAt),
        handler_total_ms: Math.round(actionCompletedAt - requestStartedAt)
      }));
      return jsonResponse(result);
    }

    if (body.action === "post_bid_room_chat_message") {
      const result = await postBidRoomChatMessage(supabase, user, body);
      await writeAuditLog(
        supabase,
        user,
        "bid_room.chat.message",
        "bid_room_chat_threads",
        result.thread.id,
        `Posted Bid Room chat message to ${result.thread.title || result.thread.thread_type}`,
        { thread_type: result.thread.thread_type, google_chat_sync_status: result.message.google_chat_sync_status }
      );
      return jsonResponse(result);
    }

    if (body.action === "send_bid_room_carrier_message") {
      const result = await sendBidRoomCarrierMessage(supabase, user, body);
      return jsonResponse(result);
    }

    if (body.action === "update_bid_room_chat_thread") {
      const result = await updateBidRoomChatThreadAction(supabase, user, body);
      await writeAuditLog(
        supabase,
        user,
        "bid_room.chat.thread_action",
        "bid_room_chat_threads",
        result.row.id,
        `Updated Bid Room communication thread action: ${result.action}`,
        { communication_status: result.row.communication_status, read_status: result.row.read_status }
      );
      return jsonResponse(result);
    }

    if (body.action === "apply_bid_update_from_chat") {
      const result = await applyBidUpdateFromChat(supabase, user, body);
      await writeAuditLog(
        supabase,
        user,
        "bid_room.chat.apply_bid_update",
        "rfx_lane_vendors",
        result.row.id,
        `Applied Bid Room chat update to ${result.row.vendors?.vendor_name || result.row.vendors?.domain || "carrier bid"}`,
        {
          thread_id: result.thread.id,
          source_message_id: result.source_message?.id || null,
          before: result.before,
          after: result.after
        }
      );
      return jsonResponse(result);
    }

    if (body.action === "sync_bid_room_event_thread") {
      const result = await syncBidRoomEventThread(supabase, user, body);
      await writeAuditLog(
        supabase,
        user,
        "bid_room.chat.thread_sync",
        "bid_room_chat_threads",
        result.thread.id,
        `Synced Google Chat thread for ${result.thread.title || "Bid Room event"}`,
        { google_chat_sync_status: result.message.google_chat_sync_status }
      );
      return jsonResponse(result);
    }

    if (body.action === "retry_google_chat_sync") {
      const result = await retryGoogleChatSync(supabase, user, body);
      await writeAuditLog(
        supabase,
        user,
        "google_chat.retry_sync",
        "bid_room_chat_messages",
        "bulk",
        `Retried ${result.attempted} Google Chat message(s): ${result.synced} synced, ${result.failed} failed`,
        { synced: result.synced, failed: result.failed, skipped: result.skipped }
      );
      return jsonResponse(result);
    }

    if (body.action === "auto_shortlist_rfx_lane") {
      const lane = await requireOwnedRfxLane(supabase, user, body.lane_id);
      const limit = Math.min(Math.max(Number(body.limit) || 10, 1), 50);
      const [vendorsResult, rates] = await Promise.all([
        supabase
          .from("vendors")
          .select("id,vendor_name,domain,primary_email,secondary_emails,whatsapp_phone,preferred_channel,base_stage,status,tags,coverage_notes,notes")
          .eq("owner_email", user.owner_email)
          .neq("base_stage", "archived")
          .limit(1000),
        fetchApprovedRateRows(supabase, user)
      ]);
      if (vendorsResult.error) throw vendorsResult.error;
      const ranked = (vendorsResult.data || [])
        .map((vendor) => scoreVendorForLane(vendor, lane, rates))
        .filter((row) => Number(row.fit_score || 0) >= 35)
        .sort((a, b) => Number(b.fit_score || 0) - Number(a.fit_score || 0))
        .slice(0, limit);
      if (!ranked.length) return jsonResponse({ inserted: 0, rows: [], recommendations: [] });

      const insertRows = await Promise.all(ranked.map(async (row) => ({
        rfx_event_id: lane.rfx_event_id,
        rfx_lane_id: lane.id,
        vendor_id: row.vendor_id,
        invitation_status: "drafted",
        ...(await newRfxInvitationTokenFields()),
        notes: [`Fit score ${row.fit_score}`, ...(row.evidence || [])].join("; ")
      })));
      const result = await supabase
        .from("rfx_lane_vendors")
        .upsert(insertRows, { onConflict: "rfx_lane_id,vendor_id", ignoreDuplicates: true })
        .select("*, vendors(id,vendor_name,domain,primary_email,whatsapp_phone,preferred_channel,base_stage,status,tags,coverage_notes)");
      if (result.error) throw result.error;
      const rows = await hydrateRfxInvitationTokens(supabase, (result.data || []) as Record<string, unknown>[]);
      return jsonResponse({ inserted: rows.length, rows, recommendations: ranked });
    }

    if (body.action === "shortlist_rfx_lane_vendors") {
      const lane = await requireOwnedRfxLane(supabase, user, body.lane_id);
      const vendorIds = normalizeBulkIds(body.vendor_ids, { label: "Vendor ids", limit: BULK_SHORTLIST_VENDOR_LIMIT });
      if (!vendorIds.length) return jsonResponse({ inserted: 0, rows: [] });
      const vendorsResult = await supabase
        .from("vendors")
        .select("id")
        .eq("owner_email", user.owner_email)
        .in("id", vendorIds);
      if (vendorsResult.error) throw vendorsResult.error;
      const insertRows = await Promise.all((vendorsResult.data || []).map(async (vendor) => ({
        rfx_event_id: lane.rfx_event_id,
        rfx_lane_id: lane.id,
        vendor_id: vendor.id,
        invitation_status: "drafted",
        ...(await newRfxInvitationTokenFields())
      })));
      const result = await supabase
        .from("rfx_lane_vendors")
        .upsert(insertRows, { onConflict: "rfx_lane_id,vendor_id", ignoreDuplicates: true })
        .select("*, vendors(id,vendor_name,domain,primary_email,whatsapp_phone,preferred_channel,base_stage,status,tags,coverage_notes)");
      if (result.error) throw result.error;
      const rows = await hydrateRfxInvitationTokens(supabase, (result.data || []) as Record<string, unknown>[]);
      return jsonResponse({ inserted: rows.length, rows });
    }

    if (body.action === "invite_rfx_lane_vendors") {
      const ids = normalizeBulkIds(body.ids, { label: "RFx participant ids", limit: BULK_SELECTED_ID_LIMIT });
      if (!ids.length) return jsonResponse({ updated: 0, rows: [] });
      requireBulkConfirmation(body, {
        action: "invite_rfx_lane_vendors",
        label: "RFx participant invite update",
        count: ids.length
      });
      const ownedResult = await supabase
        .from("rfx_lane_vendors")
        .select("id,rfx_events!inner(owner_email)")
        .in("id", ids)
        .eq("rfx_events.owner_email", user.owner_email);
      if (ownedResult.error) throw ownedResult.error;
      const ownedIds = (ownedResult.data || []).map((row) => row.id);
      if (!ownedIds.length) return jsonResponse({ updated: 0, rows: [] });
      const result = await supabase
        .from("rfx_lane_vendors")
        .update({ invitation_status: "invited", invited_at: new Date().toISOString(), updated_at: new Date().toISOString() })
        .in("id", ownedIds)
        .select("*, vendors(id,vendor_name,domain,primary_email,whatsapp_phone,preferred_channel,base_stage,status)");
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "rfx.participants.invite", "rfx_lane_vendors", ownedIds.join(","),
        `Marked ${result.data?.length || 0} RFx participant(s) invited`, { requested: ids.length, updated: result.data?.length || 0, ids: ownedIds });
      return jsonResponse({ updated: result.data?.length || 0, rows: result.data || [] });
    }

    if (body.action === "update_rfx_bid") {
      const id = cleanText(body.id);
      if (!id) return jsonResponse({ error: "RFx invitation id is required." }, 400);
      const ownedResult = await supabase
        .from("rfx_lane_vendors")
        .select("id,rfx_event_id,rfx_lane_id,vendor_id,rfx_events!inner(owner_email),vendors(vendor_name,domain)")
        .eq("id", id)
        .eq("rfx_events.owner_email", user.owner_email)
        .single();
      if (ownedResult.error) throw ownedResult.error;
      const patchInput = objectRecord(body.patch);
      const bidRate = strictBidNumber(patchInput.bid_rate, "Bid rate");
      const captureSource = cleanText(patchInput.capture_source);
      const manualCapture = captureSource === "manual_operator";
      const sourceNote = cleanText(patchInput.source_note);
      const patch: Record<string, unknown> = {
        bid_rate: bidRate,
        currency: strictCurrencyCode(patchInput.currency),
        weekly_capacity: strictBidNumber(patchInput.weekly_capacity, "Weekly capacity"),
        transit_days: strictBidNumber(patchInput.transit_days, "Transit days"),
        notes: cleanText(patchInput.notes),
        invitation_status: bidRate !== null ? "quoted" : cleanText(patchInput.invitation_status) || "drafted",
        responded_at: bidRate !== null ? new Date().toISOString() : null,
        response_source: manualCapture ? "manual_operator" : "rateware_admin",
        updated_at: new Date().toISOString()
      };
      if ("valid_through" in patchInput) patch.valid_through = strictDateOnly(patchInput.valid_through, "Valid through");
      if (manualCapture && sourceNote) patch.bid_source_note = sourceNote.slice(0, 2000);
      const mirrorEnabled = cleanOptionalBoolean(patchInput.mirror_account_enabled);
      if (patchInput.commercial_model !== undefined) patch.commercial_model = normalizeCommercialModel(patchInput.commercial_model);
      if (patchInput.marksman_margin_pct !== undefined) patch.marksman_margin_pct = strictPercentNumber(patchInput.marksman_margin_pct, "MARKSMAN margin");
      if (patchInput.carrier_share_pct !== undefined) patch.carrier_share_pct = strictPercentNumber(patchInput.carrier_share_pct, "Carrier share");
      if (patchInput.best_alternative_offered !== undefined) patch.best_alternative_offered = cleanOptionalBoolean(patchInput.best_alternative_offered) === true;
      if (patchInput.alternative_equipment !== undefined) patch.alternative_equipment = cleanText(patchInput.alternative_equipment);
      if (patchInput.alternative_units !== undefined) patch.alternative_units = strictBidNumber(patchInput.alternative_units, "Alternative units");
      if (patchInput.alternative_notes !== undefined) patch.alternative_notes = cleanText(patchInput.alternative_notes);
      if (patchInput.equipment_available !== undefined) patch.equipment_available = cleanOptionalBoolean(patchInput.equipment_available);
      if (patchInput.unit_details !== undefined) patch.unit_details = cleanText(patchInput.unit_details);
      if (patchInput.eta_pickup !== undefined) patch.eta_pickup = cleanTimestamp(patchInput.eta_pickup);
      if (patchInput.eta_delivery !== undefined) patch.eta_delivery = cleanTimestamp(patchInput.eta_delivery);
      if (patchInput.availability_validation_notes !== undefined) patch.availability_validation_notes = cleanText(patchInput.availability_validation_notes);
      if ("current_unit_location" in patchInput) patch.current_unit_location = cleanText(patchInput.current_unit_location);
      if ("deadhead_distance" in patchInput) patch.deadhead_distance = strictBidNumber(patchInput.deadhead_distance, "Deadhead distance");
      if ("deadhead_unit" in patchInput) {
        const deadheadUnit = cleanText(patchInput.deadhead_unit)?.toLowerCase();
        if (deadheadUnit && !["mi", "km"].includes(deadheadUnit)) throw new Error("Deadhead unit must be mi or km.");
        patch.deadhead_unit = deadheadUnit;
      }
      if (manualCapture) {
        if (patchInput.eta_pickup !== undefined) patch.eta_pickup = cleanTimestamp(patchInput.eta_pickup);
        if (patchInput.eta_delivery !== undefined) patch.eta_delivery = cleanTimestamp(patchInput.eta_delivery);
      }
      if (mirrorEnabled !== null) {
        patch.mirror_account_enabled = mirrorEnabled;
        patch.availability_validation_status = availabilityValidationStatus(patchInput.availability_validation_status, mirrorEnabled);
      } else if (patchInput.availability_validation_status !== undefined) {
        patch.availability_validation_status = availabilityValidationStatus(patchInput.availability_validation_status, false);
      }
      const result = await supabase
        .from("rfx_lane_vendors")
        .update(patch)
        .eq("id", id)
        .select("*, vendors(id,vendor_name,domain,primary_email,whatsapp_phone,preferred_channel,base_stage,status)")
        .single();
      if (result.error) throw result.error;
      if (manualCapture) {
        await tryWriteAuditLog(
          supabase,
          user,
          "rfx.bid.manual_capture",
          "rfx_lane_vendors",
          id,
          `Recorded manual bid for ${result.data?.vendors?.vendor_name || result.data?.vendors?.domain || "carrier"}`,
          {
            rfx_event_id: result.data?.rfx_event_id,
            rfx_lane_id: result.data?.rfx_lane_id,
            vendor_id: result.data?.vendor_id,
            source_channel: cleanText(patchInput.manual_source_channel) || "other",
            bid_rate: result.data?.bid_rate,
            currency: result.data?.currency,
            valid_through: result.data?.valid_through
          }
        );
      }
      return jsonResponse({ row: result.data });
    }

    if (body.action === "reject_rfx_bid") {
      return jsonResponse(await rejectRfxBid(supabase, user, body));
    }

    if (body.action === "award_rfx_lane_vendor") {
      const result = await awardRfxLaneVendor(supabase, user, body);
      await writeAuditLog(
        supabase,
        user,
        "rfx.award.save",
        "rfx_lane_vendors",
        result.row.id,
        `Saved ${result.award_role} award for ${result.row.vendors?.vendor_name || result.row.vendors?.domain || "carrier bid"}`,
        {
          award_role: result.award_role,
          award_reason: result.row.award_reason,
          rfx_event_id: result.row.rfx_event_id,
          rfx_lane_id: result.row.rfx_lane_id
        }
      );
      return jsonResponse(result);
    }

    if (body.action === "clear_rfx_award") {
      const result = await clearRfxAward(supabase, user, body);
      await writeAuditLog(
        supabase,
        user,
        "rfx.award.clear",
        "rfx_lane_vendors",
        result.row.id,
        `Cleared award role for ${result.row.vendors?.vendor_name || result.row.vendors?.domain || "carrier bid"}`,
        {
          previous_award_role: result.before.award_role,
          rfx_event_id: result.row.rfx_event_id,
          rfx_lane_id: result.row.rfx_lane_id
        }
      );
      return jsonResponse(result);
    }

    if (body.action === "closeout_awarded_rfx_to_rateware") {
      const result = await closeoutAwardedRfxToRateware(supabase, user, body);
      await writeAuditLog(
        supabase,
        user,
        "rfx.award.closeout",
        "rfx_events",
        body.event_id || body.rfx_event_id || body.id,
        `Queued ${result.queued_for_review || 0} RFx award rate(s) for human review`,
        {
          inserted: result.inserted,
          linked: result.linked,
          skipped: result.skipped,
          queued_for_review: result.queued_for_review,
          preserved_approved: result.preserved_approved,
          already_staged: result.already_staged,
          raw_upload_id: result.raw_upload_id,
          job_id: result.job_id,
          target_status: result.target_status,
          decisions: result.decisions,
          outcomes: result.outcomes
        }
      );
      return jsonResponse(result);
    }

    if (body.action === "generate_rfx_award_notices") {
      const result = await generateRfxAwardNotices(supabase, user, body);
      await writeAuditLog(
        supabase,
        user,
        "rfx.award.notices.generate",
        "outreach_messages",
        result.campaign_id || null,
        `Prepared ${result.generated} RFx award notice(s) without replacing sent history`,
        {
          generated: result.generated,
          created: result.created,
          refreshed: result.refreshed,
          preserved: result.preserved,
          skipped: result.skipped?.length || 0,
          campaign_id: result.campaign_id,
          rfx_event_id: body.event_id || body.rfx_event_id || body.id
        }
      );
      return jsonResponse(result);
    }

    if (body.action === "archive_rfx_lane_vendors") {
      const ids = normalizeBulkIds(body.ids, { label: "RFx participant ids", limit: BULK_SELECTED_ID_LIMIT });
      if (!ids.length) return jsonResponse({ updated: 0, rows: [] });
      requireBulkConfirmation(body, {
        action: "archive_rfx_lane_vendors",
        label: "RFx participant archive",
        count: ids.length
      });
      const ownedResult = await supabase
        .from("rfx_lane_vendors")
        .select("id,rfx_events!inner(owner_email)")
        .in("id", ids)
        .eq("rfx_events.owner_email", user.owner_email);
      if (ownedResult.error) throw ownedResult.error;
      const ownedIds = (ownedResult.data || []).map((row) => row.id);
      if (!ownedIds.length) return jsonResponse({ updated: 0, rows: [] });
      const result = await supabase
        .from("rfx_lane_vendors")
        .update({ invitation_status: "archived", updated_at: new Date().toISOString() })
        .in("id", ownedIds)
        .select("id");
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "rfx.participants.archive", "rfx_lane_vendors", ownedIds.join(","),
        `Archived ${result.data?.length || 0} RFx participant(s)`, { requested: ids.length, updated: result.data?.length || 0, ids: ownedIds });
      return jsonResponse({ updated: result.data?.length || 0, rows: result.data || [] });
    }

    if (body.action === "list_outreach_templates") {
      const [globalResult, ownedResult] = await Promise.all([
        supabase
          .from("outreach_templates")
          .select("*")
          .is("owner_email", null)
          .eq("active", true)
          .order("is_default", { ascending: false })
          .order("name", { ascending: true }),
        supabase
          .from("outreach_templates")
          .select("*")
          .eq("owner_email", user.owner_email)
          .eq("active", true)
          .order("created_at", { ascending: false })
      ]);
      if (globalResult.error) throw globalResult.error;
      if (ownedResult.error) throw ownedResult.error;
      const templates = [...(ownedResult.data || []), ...(globalResult.data || [])];
      const internalWorkspace = await isInternalWhatsappWorkspace(supabase, user);
      const connectionRow = internalWorkspace
        ? await ensureInternalWhatsappConnection(supabase, user)
        : await findTenantWhatsappConnection(supabase, user);
      const mappings = connectionRow?.id
        ? await whatsappTemplateMappingsForConnection(supabase, connectionRow.id)
        : [];
      const mappingsByTemplate = new Map(
        mappings.map((mapping) => [cleanText(mapping.outreach_template_id), publicWhatsappTemplateMapping(mapping)])
      );
      return jsonResponse({
        rows: templates.map((template) => ({
          ...template,
          whatsapp_meta: mappingsByTemplate.get(cleanText(template.id)) || null
        }))
      });
    }

    if (body.action === "create_outreach_template") {
      const row = withOwner(normalizeOutreachTemplate(objectRecord(body.template)), user);
      // Canonical templates are the reusable base by channel and locale. An event
      // renders a snapshot from this base; it must never create another template.
      if (row.template_scope === "canonical" && row.canonical_language) {
        const existing = await supabase
          .from("outreach_templates")
          .select("id")
          .eq("owner_email", user.owner_email)
          .eq("channel", row.channel)
          .eq("template_scope", "canonical")
          .eq("canonical_language", row.canonical_language)
          .eq("active", true)
          .maybeSingle();
        if (existing.error) throw existing.error;
        if (existing.data?.id) {
          const updated = await supabase
            .from("outreach_templates")
            .update(row)
            .eq("id", existing.data.id)
            .eq("owner_email", user.owner_email)
            .select()
            .single();
          if (updated.error) throw updated.error;
          return jsonResponse({ row: updated.data, reused: true });
        }
      }
      const result = await supabase.from("outreach_templates").insert(row).select().single();
      if (result.error) throw result.error;
      return jsonResponse({ row: result.data });
    }

    if (body.action === "update_outreach_template") {
      const id = cleanText(body.id);
      if (!id) return jsonResponse({ error: "Template id is required." }, 400);
      const patch = normalizeOutreachTemplate(objectRecord(body.patch || body.template));
      const result = await supabase
        .from("outreach_templates")
        .update(patch)
        .eq("id", id)
        .eq("owner_email", user.owner_email)
        .select()
        .single();
      if (result.error) throw result.error;
      return jsonResponse({ row: result.data });
    }

    if (body.action === "publish_outreach_template_to_whatsapp") {
      const result = await publishOutreachTemplateToWhatsapp(supabase, user, body);
      await writeAuditLog(
        supabase,
        user,
        "outreach.template.whatsapp.publish",
        "outreach_templates",
        cleanText(body.template_id || body.id),
        `Published Outreach WhatsApp template ${result.row?.meta_template_name || "template"} to Meta`,
        {
          meta_template_status: result.row?.meta_template_status,
          meta_template_language: result.row?.meta_template_language
        }
      );
      return jsonResponse(result);
    }

    if (body.action === "archive_outreach_template") {
      const id = cleanText(body.id || body.template_id);
      if (!id) return jsonResponse({ error: "Template id is required." }, 400);
      requireBulkConfirmation(body, { action: "archive_outreach_template", label: "Outreach template archive", count: 1 });
      const result = await supabase
        .from("outreach_templates")
        .update({ active: false, updated_at: new Date().toISOString() })
        .eq("id", id)
        .eq("owner_email", user.owner_email)
        .select()
        .single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "outreach.template.archive", "outreach_templates", result.data.id,
        `Archived outreach template ${cleanText(result.data.name) || result.data.id}`);
      return jsonResponse({ row: result.data });
    }

    if (body.action === "delete_outreach_template") {
      const id = cleanText(body.id || body.template_id);
      if (!id) return jsonResponse({ error: "Template id is required." }, 400);
      requireBulkConfirmation(body, { action: "delete_outreach_template", label: "Outreach template deletion", count: 1 });
      const result = await supabase
        .from("outreach_templates")
        .delete()
        .eq("id", id)
        .eq("owner_email", user.owner_email)
        .select("id,name")
        .single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "outreach.template.delete", "outreach_templates", result.data.id,
        `Deleted outreach template ${cleanText(result.data.name) || result.data.id}`);
      return jsonResponse({ removed: result.data });
    }

    if (body.action === "duplicate_outreach_template") {
      const id = cleanText(body.id || body.template_id);
      if (!id) return jsonResponse({ error: "Template id is required." }, 400);
      const source = await fetchOutreachTemplate(supabase, user, id);
      const row = withOwner({
        name: `${source.name || "Template"} Copy`,
        channel: source.channel || "email",
        subject: source.subject,
        html_body: source.html_body,
        whatsapp_body: source.whatsapp_body,
        active: true,
        is_default: false,
        placeholders: Array.isArray(source.placeholders) ? source.placeholders : [],
        updated_at: new Date().toISOString()
      }, user);
      const result = await supabase.from("outreach_templates").insert(row).select().single();
      if (result.error) throw result.error;
      return jsonResponse({ row: result.data });
    }

    if (body.action === "list_outreach_audience_segments") {
      let query = supabase
        .from("outreach_audience_segments")
        .select("*")
        .eq("owner_email", user.owner_email)
        .eq("active", true)
        .order("updated_at", { ascending: false });
      if (body.rfx_event_id) query = query.eq("rfx_event_id", body.rfx_event_id);
      const result = await query.limit(100);
      if (result.error) throw result.error;
      return jsonResponse({ rows: result.data || [] });
    }

    if (body.action === "save_outreach_audience_segment") {
      const segment = objectRecord(body.segment);
      const name = cleanText(segment.name);
      const vendorIds = normalizeBulkIds(segment.vendor_ids, { label: "Audience vendor ids", limit: 5000 });
      const eventId = cleanText(segment.rfx_event_id || body.rfx_event_id);
      if (!name) return jsonResponse({ error: "Audience segment name is required." }, 400);
      if (!vendorIds.length) return jsonResponse({ error: "Select at least one carrier before saving an audience segment." }, 400);
      if (eventId) await requireOwnedRfxEvent(supabase, user, eventId);
      const row = withOwner({
        name,
        rfx_event_id: eventId || null,
        vendor_ids: vendorIds,
        filters: objectRecord(segment.filters),
        metadata: { source: cleanText(segment.source) || "outreach_control_center" },
        active: true,
        updated_at: new Date().toISOString()
      }, user);
      const result = await supabase.from("outreach_audience_segments").insert(row).select().single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "outreach.audience_segment.save", "outreach_audience_segments", result.data.id,
        `Saved outreach audience segment ${name}`, { rfx_event_id: eventId, vendor_count: vendorIds.length });
      return jsonResponse({ row: result.data });
    }

    if (body.action === "archive_outreach_audience_segment") {
      const segmentId = cleanText(body.id || body.segment_id);
      if (!segmentId) return jsonResponse({ error: "Audience segment id is required." }, 400);
      requireBulkConfirmation(body, { action: "archive_outreach_audience_segment", label: "Outreach audience segment archive", count: 1 });
      const result = await supabase
        .from("outreach_audience_segments")
        .update({ active: false, updated_at: new Date().toISOString() })
        .eq("id", segmentId)
        .eq("owner_email", user.owner_email)
        .select()
        .single();
      if (result.error) throw result.error;
      return jsonResponse({ row: result.data });
    }

    if (body.action === "suppress_outreach_contact") {
      const contactValue = cleanText(body.contact_value)?.toLowerCase();
      const reason = cleanText(body.reason) || "Manual suppression";
      const channel = cleanText(body.channel)?.toLowerCase() || "all";
      const vendorId = cleanText(body.vendor_id);
      if (!contactValue) return jsonResponse({ error: "Contact value is required for suppression." }, 400);
      if (!["all", "email", "whatsapp", "whatsapp_group"].includes(channel)) return jsonResponse({ error: "Invalid suppression channel." }, 400);
      if (vendorId) await requireOwnedVendorForCi(supabase, user, vendorId);
      const row = withOwner({
        vendor_id: vendorId || null,
        channel,
        contact_value: contactValue,
        reason,
        source: cleanText(body.source) || "manual",
        active: true,
        metadata: objectRecord(body.metadata),
        updated_at: new Date().toISOString()
      }, user);
      const existing = supabase
        .from("outreach_contact_suppressions")
        .select("id")
        .eq("owner_email", user.owner_email)
        .eq("channel", channel)
        .eq("contact_value", contactValue)
        .eq("active", true);
      const existingForVendor = vendorId
        ? await existing.eq("vendor_id", vendorId).maybeSingle()
        : await existing.is("vendor_id", null).maybeSingle();
      if (existingForVendor.error) throw existingForVendor.error;
      const result = existingForVendor.data?.id
        ? await supabase
          .from("outreach_contact_suppressions")
          .update(row)
          .eq("id", existingForVendor.data.id)
          .eq("owner_email", user.owner_email)
          .select()
          .single()
        : await supabase
          .from("outreach_contact_suppressions")
          .insert(row)
        .select()
        .single();
      if (result.error) throw result.error;
      return jsonResponse({ row: result.data });
    }

    if (body.action === "preview_outreach_audience") {
      const eventId = cleanText(body.rfx_event_id || body.event_id);
      const channel = cleanText(body.channel)?.toLowerCase() || "email";
      const search = cleanText(body.search)?.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase() || "";
      const statusFilter = cleanText(body.status_filter)?.toLowerCase() || "all";
      const policy = normalizeOutreachAudiencePolicy(body.audience_policy);
      if (!eventId) return jsonResponse({ error: "Select an RFx event to build an audience." }, 400);
      if (!["email", "whatsapp", "whatsapp_group"].includes(channel)) return jsonResponse({ error: "Select one outreach channel." }, 400);
      await requireOwnedRfxEvent(supabase, user, eventId);
      let selectedVendorIds = policy.vendor_ids;
      if (policy.mode === "saved_segment" && policy.saved_segment_id) {
        const segment = await supabase
          .from("outreach_audience_segments")
          .select("vendor_ids")
          .eq("id", policy.saved_segment_id)
          .eq("owner_email", user.owner_email)
          .eq("active", true)
          .maybeSingle();
        if (segment.error) throw segment.error;
        selectedVendorIds = Array.isArray(segment.data?.vendor_ids) ? segment.data.vendor_ids : [];
      }
      const [invitations, eventLaneRows] = await Promise.all([
        fetchAllRfxLaneVendorRows(
          supabase,
          eventId,
          "id,vendor_id,rfx_lane_id,invitation_status,invited_at,viewed_at,responded_at,bid_rate,vendors(id,vendor_name,domain,primary_email,secondary_emails,whatsapp_phone,whatsapp_do_not_contact),rfx_lanes(origin,destination,equipment,operation,service)"
        ),
        fetchAllRfxLaneRows(supabase, eventId, "id")
      ]);
      const activeInvitations = invitations.filter((row) => cleanText(row.invitation_status)?.toLowerCase() !== "archived");
      const eventLaneCount = eventLaneRows.length;
      const vendorIds = [...new Set(invitations.map((row) => cleanText(row.vendor_id)).filter(Boolean))] as string[];
      const [historyRows, suppressions] = await Promise.all([
        allScopedOutreachMessages(supabase, user, { rfx_event_id: eventId, channel, include_archived: false }),
        outreachSuppressionsForVendors(supabase, user, vendorIds)
      ]);
      const historyByContact = outreachHistoryByContact(historyRows);
      const groups = new Map<string, Record<string, unknown>[]>();
      for (const invitation of activeInvitations) {
        const vendorId = cleanText(invitation.vendor_id) || `invitation:${invitation.id}`;
        const bucket = groups.get(vendorId) || [];
        bucket.push(invitation);
        groups.set(vendorId, bucket);
      }
      const allRows = [...groups.entries()].map(([vendorId, group]) => {
        const first = group[0];
        const vendor = relationRecord(first.vendors);
        const emailCandidates = vendorContactEmailCandidates(vendor);
        const suppressedEmailContacts = new Set(
          suppressions
            .filter((suppression) => {
              const suppressionVendorId = cleanText(suppression.vendor_id) || "";
              return ["all", "email"].includes(cleanText(suppression.channel)?.toLowerCase() || "all")
                && (!suppressionVendorId || suppressionVendorId === vendorId);
            })
            .map((suppression) => cleanText(suppression.contact_value)?.toLowerCase())
            .filter((value) => value && value !== "*") as string[]
        );
        const firstHistoricalEmail = emailCandidates.find((email) => historyByContact.has(outreachEventDedupeKey({
          rfx_event_id: eventId,
          channel: "email",
          vendor_id: vendorId,
          recipient_email: email
        }))) || "";
        const recipientEmail = channel === "email"
          ? firstEligibleOutreachEmail(vendor, suppressedEmailContacts, eventId, vendorId, historyByContact)
          : "";
        const recipientPhone = channel === "whatsapp" ? phoneForWhatsapp(vendor.whatsapp_phone) : "";
        const contactValue = channel === "email" ? (recipientEmail || firstHistoricalEmail) : recipientPhone;
        const history = contactValue ? historyByContact.get(outreachEventDedupeKey({
          rfx_event_id: eventId,
          channel,
          vendor_id: vendorId,
          recipient_email: channel === "email" ? contactValue : undefined,
          recipient_phone: recipientPhone || undefined
        })) : null;
        const hasContact = channel === "email" ? emailCandidates.length > 0 : Boolean(contactValue) || channel === "whatsapp_group";
        const suppressionReason = outreachSuppressionReason(suppressions, channel, contactValue || "", vendorId || "");
        const invitationStatuses = [...new Set(
          group
            .map((row) => cleanText(row.invitation_status)?.toLowerCase() || "")
            .filter((status) => Boolean(status))
        )] as string[];
        const invitationStatus = invitationStatuses.find((status) => ["quoted", "bid_submitted", "awarded"].includes(status))
          || invitationStatuses.find((status) => ["responded", "viewed", "invited"].includes(status))
          || invitationStatuses.find((status) => status === "drafted")
          || invitationStatuses[0]
          || "drafted";
        const trackingState = history ? outreachMessageTrackingState(history) : "";
        let audienceStatus = "ready";
        let reason = "Eligible contact ready for review";
        if (policy.mode !== "all_eligible" && selectedVendorIds.length && !selectedVendorIds.includes(vendorId)) {
          audienceStatus = "excluded";
          reason = "Not included in the selected audience segment";
        } else if (suppressionReason || cleanBoolean(vendor.whatsapp_do_not_contact)) {
          audienceStatus = "suppressed";
          reason = suppressionReason || "Vendor is marked do-not-contact";
        } else if (policy.require_contact && !hasContact) {
          audienceStatus = "no_contact";
          reason = channel === "email" ? "No valid email contact" : "No valid WhatsApp contact";
        } else if (history && outreachBlocksAutoDraft(history)) {
          const tracking = outreachMessageTrackingState(history);
          audienceStatus = tracking === "bounced" ? "bounced" : tracking === "quoted" ? "quoted" : tracking === "replied" ? "replied" : "already_contacted";
          reason = outreachAutoDraftSkipReason(history);
        }
        let eventStatus = trackingState || "";
        let eventStatusReason = history ? outreachOutcomeReason(history) : "";
        if (!eventStatus) {
          if (audienceStatus === "bounced" || audienceStatus === "suppressed" || audienceStatus === "no_contact") {
            eventStatus = audienceStatus;
            eventStatusReason = reason;
          } else if (group.some((row) => hasSubmittedCarrierBid(row.bid_rate))) {
            eventStatus = "quoted";
            eventStatusReason = "Carrier has submitted a quote for this RFx.";
          } else if (["responded", "replied", "quoted", "bid_submitted", "awarded"].includes(invitationStatus)) {
            eventStatus = "replied";
            eventStatusReason = "Carrier responded to this RFx.";
          } else if (invitationStatus === "viewed") {
            eventStatus = "read";
            eventStatusReason = "Carrier viewed this RFx invitation.";
          } else if (invitationStatus === "invited") {
            eventStatus = "invited";
            eventStatusReason = "This RFx has been invited, but no delivery receipt is available for the selected channel yet.";
          } else {
            eventStatus = "not_invited";
            eventStatusReason = "Carrier is in this RFx but has not received a message for the selected channel.";
          }
        }
        const lanePreview = group.slice(0, 2).map((row) => {
          const lane = relationRecord(row.rfx_lanes);
          return `${cleanText(lane.origin) || "-"} -> ${cleanText(lane.destination) || "-"}`;
        });
        return {
          vendor_id: vendorId.startsWith("invitation:") ? null : vendorId,
          vendor_name: cleanText(vendor.vendor_name) || "Unnamed carrier",
          vendor_domain: cleanText(vendor.domain),
          email: recipientEmail || cleanText(vendor.primary_email),
          phone: recipientPhone,
          invitation_ids: group.map((row) => row.id).filter(Boolean),
          lane_count: eventLaneCount || group.length,
          shortlisted_lane_count: group.length,
          event_lane_count: eventLaneCount || group.length,
          lane_preview: lanePreview,
          invitation_statuses: invitationStatuses,
          invitation_status: invitationStatus,
          audience_status: audienceStatus,
          reason,
          event_status: eventStatus,
          event_status_reason: eventStatusReason,
          next_action: history ? outreachNextAction(history) : eventStatus === "not_invited" ? "Prepare this channel" : eventStatus === "invited" ? "Await response" : audienceStatus === "ready" ? "Review and send" : audienceStatus === "bounced" ? "Replace contact" : "Review carrier contact",
          last_contact_at: history?.updated_at || null,
          last_message_status: trackingState || null
        };
      });
      const rows = allRows.filter((row) => {
        const haystack = `${row.vendor_name} ${row.vendor_domain} ${row.email} ${row.phone} ${row.lane_preview.join(" ")}`.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
        const eventStatus = cleanText(row.event_status) || "";
        const statusMatches = statusFilter === "all"
          || row.audience_status === statusFilter
          || eventStatus === statusFilter
          || (statusFilter === "needs_queue" && ["not_invited", "ready"].includes(eventStatus))
          || (statusFilter === "in_delivery" && ["drafted", "queued", "sending"].includes(eventStatus))
          || (statusFilter === "contacted" && ["invited", "sent", "delivered", "read", "manual_sent", "delivery_unknown"].includes(eventStatus))
          || (statusFilter === "response" && ["replied", "quoted"].includes(eventStatus))
          || (statusFilter === "attention" && ["bounced", "failed", "suppressed", "no_contact"].includes(eventStatus))
          || (statusFilter === "delivered" && ["delivered", "read"].includes(eventStatus));
        return (!search || haystack.includes(search)) && statusMatches;
      });
      const counts = allRows.reduce((acc, row) => {
        const key = cleanText(row.event_status || row.audience_status) || "needs_review";
        acc[key] = (acc[key] || 0) + 1;
        return acc;
      }, {} as Record<string, number>);
      return jsonResponse({ rows, counts, total: allRows.length, filtered_total: rows.length, channel, rfx_event_id: eventId });
    }

    if (body.action === "list_outreach_campaigns") {
      const campaignsResult = await supabase
        .from("outreach_campaigns")
        .select("*, rfx_events(rfx_id,name,customer,status), outreach_templates(name,channel)")
        .eq("owner_email", user.owner_email)
        .neq("status", "archived")
        .order("created_at", { ascending: false })
        .limit(100);
      if (campaignsResult.error) throw campaignsResult.error;
      const campaignIds = (campaignsResult.data || []).map((campaign) => campaign.id);
      const messagesResult = campaignIds.length
        ? await supabase
            .from("outreach_messages")
            .select("id,campaign_id,status,channel")
            .in("campaign_id", campaignIds)
        : { data: [], error: null };
      if (messagesResult.error) throw messagesResult.error;
      const counts = new Map<string, { messages: number; sent: number; email: number; whatsapp: number }>();
      for (const message of messagesResult.data || []) {
        const bucket = counts.get(message.campaign_id) || { messages: 0, sent: 0, email: 0, whatsapp: 0 };
        bucket.messages += 1;
        if (message.status === "sent") bucket.sent += 1;
        if (message.channel === "email") bucket.email += 1;
        if (message.channel === "whatsapp") bucket.whatsapp += 1;
        counts.set(message.campaign_id, bucket);
      }
      return jsonResponse({
        rows: (campaignsResult.data || []).map((campaign) => ({
          ...campaign,
          message_count: counts.get(campaign.id)?.messages || 0,
          sent_count: counts.get(campaign.id)?.sent || 0,
          email_count: counts.get(campaign.id)?.email || 0,
          whatsapp_count: counts.get(campaign.id)?.whatsapp || 0
        }))
      });
    }

    if (body.action === "create_outreach_campaign") {
      const normalized = normalizeOutreachCampaign(objectRecord(body.campaign));
      if (normalized.rfx_event_id) await requireOwnedRfxEvent(supabase, user, normalized.rfx_event_id);
      if (normalized.template_id) await fetchOutreachTemplate(supabase, user, normalized.template_id);
      if (normalized.idempotency_key) {
        const existing = await supabase
          .from("outreach_campaigns")
          .select("*")
          .eq("owner_email", user.owner_email)
          .eq("idempotency_key", normalized.idempotency_key)
          .maybeSingle();
        if (existing.error) throw existing.error;
        if (existing.data) return jsonResponse({ row: existing.data, reused: true });
      }
      const row = withOwner(normalized, user);
      const result = await supabase.from("outreach_campaigns").insert(row).select().single();
      if (result.error && normalized.idempotency_key && String(result.error.code || "") === "23505") {
        const existing = await supabase
          .from("outreach_campaigns")
          .select("*")
          .eq("owner_email", user.owner_email)
          .eq("idempotency_key", normalized.idempotency_key)
          .single();
        if (existing.error) throw existing.error;
        return jsonResponse({ row: existing.data, reused: true });
      }
      if (result.error) throw result.error;
      return jsonResponse({ row: result.data });
    }

    if (body.action === "update_outreach_campaign") {
      const campaignId = cleanText(body.id || body.campaign_id);
      if (!campaignId) return jsonResponse({ error: "Campaign id is required." }, 400);
      const patch = normalizeOutreachCampaign(objectRecord(body.patch || body.campaign));
      if (patch.rfx_event_id) await requireOwnedRfxEvent(supabase, user, patch.rfx_event_id);
      if (patch.template_id) await fetchOutreachTemplate(supabase, user, patch.template_id);
      const result = await supabase
        .from("outreach_campaigns")
        .update(patch)
        .eq("id", campaignId)
        .eq("owner_email", user.owner_email)
        .select()
        .single();
      if (result.error) throw result.error;
      return jsonResponse({ row: result.data });
    }

    if (body.action === "archive_outreach_campaign") {
      const campaignId = cleanText(body.id || body.campaign_id);
      if (!campaignId) return jsonResponse({ error: "Campaign id is required." }, 400);
      requireBulkConfirmation(body, { action: "archive_outreach_campaign", label: "Outreach campaign archive", count: 1 });
      const result = await supabase
        .from("outreach_campaigns")
        .update({ status: "archived", updated_at: new Date().toISOString() })
        .eq("id", campaignId)
        .eq("owner_email", user.owner_email)
        .select()
        .single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "outreach.campaign.archive", "outreach_campaigns", result.data.id,
        `Archived outreach campaign ${cleanText(result.data.name) || result.data.id}`);
      return jsonResponse({ row: result.data });
    }

    if (body.action === "delete_outreach_campaign") {
      const campaignId = cleanText(body.id || body.campaign_id);
      if (!campaignId) return jsonResponse({ error: "Campaign id is required." }, 400);
      requireBulkConfirmation(body, { action: "delete_outreach_campaign", label: "Outreach campaign deletion", count: 1 });
      const result = await supabase
        .from("outreach_campaigns")
        .delete()
        .eq("id", campaignId)
        .eq("owner_email", user.owner_email)
        .select("id,name")
        .single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "outreach.campaign.delete", "outreach_campaigns", result.data.id,
        `Deleted outreach campaign ${cleanText(result.data.name) || result.data.id}`);
      return jsonResponse({ removed: result.data });
    }

    if (body.action === "duplicate_outreach_campaign") {
      const campaign = await requireOwnedOutreachCampaign(supabase, user, body.id || body.campaign_id);
      if (campaign.rfx_event_id) await requireOwnedRfxEvent(supabase, user, campaign.rfx_event_id);
      if (campaign.template_id) await fetchOutreachTemplate(supabase, user, campaign.template_id);
      const row = withOwner({
        rfx_event_id: campaign.rfx_event_id,
        template_id: campaign.template_id,
        name: `${campaign.name || "Campaign"} Copy`,
        channel: campaign.channel || "email",
        sender_email: campaign.sender_email,
        sender_label: campaign.sender_label,
        sender_connection_status: campaign.sender_connection_status || "draft_only",
        status: "draft",
        notes: campaign.notes,
        audience_policy: normalizeOutreachAudiencePolicy(campaign.audience_policy),
        contact_policy: normalizeOutreachContactPolicy(campaign.contact_policy),
        sequence_policy: normalizeOutreachSequencePolicy(campaign.sequence_policy),
        audience_snapshot: {},
        updated_at: new Date().toISOString()
      }, user);
      const result = await supabase.from("outreach_campaigns").insert(row).select().single();
      if (result.error) throw result.error;
      return jsonResponse({ row: result.data });
    }

    if (body.action === "generate_outreach_drafts") {
      const campaign = await requireOwnedOutreachCampaign(supabase, user, body.campaign_id);
      const template = await fetchOutreachTemplate(supabase, user, body.template_id || campaign.template_id);
      const invitationIds = normalizeBulkIds(body.invitation_ids, { label: "RFx invitation ids", limit: 5000 });
      const audiencePolicy = normalizeOutreachAudiencePolicy(body.audience_policy || campaign.audience_policy);
      const contactPolicy = normalizeOutreachContactPolicy(body.contact_policy || campaign.contact_policy);
      const sequencePolicy = normalizeOutreachSequencePolicy(body.sequence_policy || campaign.sequence_policy);
      let audienceVendorIds = audiencePolicy.vendor_ids;
      if (audiencePolicy.mode === "saved_segment" && audiencePolicy.saved_segment_id) {
        const segment = await supabase
          .from("outreach_audience_segments")
          .select("vendor_ids")
          .eq("id", audiencePolicy.saved_segment_id)
          .eq("owner_email", user.owner_email)
          .eq("active", true)
          .maybeSingle();
        if (segment.error) throw segment.error;
        audienceVendorIds = Array.isArray(segment.data?.vendor_ids) ? segment.data.vendor_ids : [];
      }
      const hasExplicitAudience = audienceVendorIds.length > 0;
      if (!invitationIds.length && audiencePolicy.mode !== "all_eligible" && !hasExplicitAudience) {
        return jsonResponse({ error: "The selected audience has no carriers. Select carriers or choose an active saved segment." }, 400);
      }
      const appOrigin = cleanText(body.app_origin) || Deno.env.get("RATEWARE_APP_URL") || "https://rateware.vercel.app";
      const senderEmail = cleanText(body.sender_email || campaign.sender_email);
      const senderLabel = cleanText(body.sender_label || campaign.sender_label || senderEmail);
      const senderConnectionStatus = cleanText(body.sender_connection_status || campaign.sender_connection_status) || "draft_only";
      // The queue request is authoritative. A stale campaign/template channel must
      // never make Gmail draft generation execute WhatsApp preparation (or vice versa).
      const requestedChannels = messageChannels(body.channel || campaign.channel || template.channel);
      if (requestedChannels.length !== 1) {
        throw new Error("Generate one outreach channel at a time. Gmail, WhatsApp Business direct, and WhatsApp groups use separate queues.");
      }
      // The selected channel owns its recipient model. This prevents a stale target
      // mode from mixing direct WhatsApp and manual group drafts into one queue.
      const targetMode = requestedChannels[0] === "whatsapp_group" ? "vendor_group" : "direct_vendor";
      const wantsEmail = requestedChannels.includes("email");
      const wantsDirectWhatsapp = requestedChannels.includes("whatsapp");
      const wantsWhatsappGroup = requestedChannels.includes("whatsapp_group");
      let gmailConnectionRow: Record<string, unknown> = {};
      if (wantsEmail && senderEmail) {
        try {
          gmailConnectionRow = await gmailConnectionIdentity(supabase, user, senderEmail) || {};
        } catch (_) {
          // Queue creation remains available in draft-only mode. Direct Gmail send
          // resolves and validates the connection again before provider delivery.
          gmailConnectionRow = {};
        }
      }
      let whatsappNotifier: Record<string, unknown> = {
        attempted: false,
        status: "not_requested"
      };
      let whatsappMapping: Record<string, unknown> | null = null;
      let whatsappConnectionRow: Record<string, unknown> = {};
      if (wantsDirectWhatsapp) {
        try {
          const notifier = await publishOutreachTemplateToWhatsapp(supabase, user, { template_id: template.id });
          whatsappMapping = notifier.row as Record<string, unknown> | null;
          whatsappNotifier = {
            attempted: true,
            status: cleanText(whatsappMapping?.meta_template_status)?.toLowerCase() || "pending",
            ready: notifier.ready,
            template_name: cleanText(whatsappMapping?.meta_template_name),
            language: cleanText(whatsappMapping?.meta_template_language),
            message: notifier.message
          };
        } catch (error) {
          whatsappNotifier = {
            attempted: true,
            status: "error",
            ready: false,
            error: safeOperationalError(error)
          };
        }
        try {
          const whatsappConnection = await listWhatsappConnections(supabase, user);
          whatsappConnectionRow = whatsappConnection.rows?.[0] || {};
          if (!whatsappMapping && whatsappConnectionRow.id) {
            whatsappMapping = await whatsappTemplateMapping(supabase, whatsappConnectionRow.id, template.id);
          }
        } catch (error) {
          whatsappNotifier = {
            attempted: true,
            status: "error",
            ready: false,
            error: safeOperationalError(error)
          };
        }
      }

      const invitationSelect = `
        *,
        vendors(id,vendor_name,domain,primary_email,secondary_emails,whatsapp_phone,preferred_channel,contact_name,whatsapp_permission_basis,whatsapp_do_not_contact,whatsapp_group_url,whatsapp_group_name,whatsapp_meta_group_id,whatsapp_group_status),
        rfx_events!inner(id,owner_email,rfx_id,name,customer,status,due_date,event_type),
        rfx_lanes(*)
      `;
      const invitationIdChunks = invitationIds.length ? chunkValues(invitationIds, 100) : [[]];
      const invitationBatches = await mapWithConcurrency(invitationIdChunks, 4, async (chunk) => {
        const batch: Record<string, unknown>[] = [];
        let offset = 0;
        while (true) {
          let invitationQuery = supabase
            .from("rfx_lane_vendors")
            .select(invitationSelect)
            .eq("rfx_events.owner_email", user.owner_email)
            .neq("invitation_status", "archived")
            .range(offset, offset + 999);
          if (campaign.rfx_event_id) invitationQuery = invitationQuery.eq("rfx_event_id", campaign.rfx_event_id);
          if (chunk.length) invitationQuery = invitationQuery.in("id", chunk);
          // An explicit selection always wins, including when the user starts from
          // "all eligible" and then narrows the wave in the audience ledger.
          if (!chunk.length && hasExplicitAudience) {
            invitationQuery = invitationQuery.in("vendor_id", audienceVendorIds);
          }

          const invitationsResult = await invitationQuery;
          if (invitationsResult.error) throw new Error(`Outreach invitation load failed: ${invitationsResult.error.message}`);
          const page = (invitationsResult.data || []) as Record<string, unknown>[];
          batch.push(...page);
          if (chunk.length || page.length < 1000) break;
          offset += 1000;
          if (offset >= 5000) throw new Error("Outreach invitation load exceeded 5000 active rows. Generate a narrower wave.");
        }
        return batch;
      });
      const invitations = invitationBatches.flat() as Record<string, unknown>[];
      let eventLaneRows: Record<string, unknown>[] = [];
       if (campaign.rfx_event_id) {
         eventLaneRows = await fetchAllRfxLaneRows(supabase, campaign.rfx_event_id, "*");
       }

      // The ledger is keyed by the actual contact, not just the carrier. This lets a
      // bounced primary email fall through to a valid secondary email without ever
      // recreating a message for a contact that was already sent or replied.
      const eventHistoryByContact = campaign.rfx_event_id
        ? outreachHistoryByContact(await allScopedOutreachMessages(supabase, user, {
          rfx_event_id: campaign.rfx_event_id,
          channels: requestedChannels,
          include_archived: false
        }))
        : new Map<string, Record<string, unknown>>();

      const rows: Record<string, unknown>[] = [];
      const skipped: Record<string, unknown>[] = [];
      const channelPreparationErrors: Record<string, string> = {};
      const invitationGroups = new Map<string, Record<string, unknown>[]>();
      for (const invitation of invitations) {
        const key = rfxInvitationVendorGroupKey(invitation);
        if (!key) continue;
        const bucket = invitationGroups.get(key) || [];
        bucket.push(invitation);
        invitationGroups.set(key, bucket);
      }

      // A carrier selected from the event audience is quoting the RFx business
      // book, not only the first lane on which it was originally shortlisted.
      // Complete its active lane coverage before hydrating the private link so
      // the email preview, invitation token, and carrier portal share one scope.
      if (campaign.rfx_event_id && eventLaneRows.length && invitations.length) {
        await ensureRfxEventVendorCoverage(
          supabase,
          campaign.rfx_event_id,
          invitations.map((invitation) => cleanText(invitation.vendor_id)).filter(Boolean) as string[],
          eventLaneRows
        );
      }

      const completeInvitationGroups = new Map<string, Record<string, unknown>[]>();
      if (campaign.rfx_event_id && invitations.length) {
        const requestedGroupKeys = new Set(invitationGroups.keys());
        const requestedVendorIds = [...new Set(invitations.map((invitation) => cleanText(invitation.vendor_id)).filter(Boolean))] as string[];
        const completeBatches = await mapWithConcurrency(chunkValues(requestedVendorIds, 100), 4, async (vendorChunk) => {
          const batch: Record<string, unknown>[] = [];
          let offset = 0;
          while (true) {
            const completeResult = await supabase
              .from("rfx_lane_vendors")
              .select(invitationSelect)
              .eq("rfx_event_id", campaign.rfx_event_id)
              .eq("rfx_events.owner_email", user.owner_email)
              .in("vendor_id", vendorChunk)
              .neq("invitation_status", "archived")
              .range(offset, offset + 999);
            if (completeResult.error) throw new Error(`Outreach lane hydration failed: ${completeResult.error.message}`);
            const page = (completeResult.data || []) as Record<string, unknown>[];
            batch.push(...page);
            if (page.length < 1000) break;
            offset += 1000;
            if (offset >= 25000) throw new Error("Outreach lane hydration exceeded the safe per-batch limit.");
          }
          return batch;
        });
        for (const invitation of completeBatches.flat()) {
          const key = rfxInvitationVendorGroupKey(invitation);
          if (!key || !requestedGroupKeys.has(key)) continue;
          const bucket = completeInvitationGroups.get(key) || [];
          bucket.push(invitation);
          completeInvitationGroups.set(key, bucket);
        }
      }

      const profileLinksByVendor = await vendorProfileLinksForInvitations(supabase, user, invitations, appOrigin, {
        rfx_event_id: campaign.rfx_event_id,
        campaign_id: campaign.id,
        template_id: template.id
      });
      const vendorIdsForGroups = wantsWhatsappGroup
        ? [...new Set(invitations.map((invitation) => cleanText(invitation.vendor_id)).filter(Boolean))]
        : [];
      const vendorGroupsByVendor = new Map<string, Record<string, unknown>>();
      if (vendorIdsForGroups.length) {
        try {
          const groupBatches = await mapWithConcurrency(chunkValues(vendorIdsForGroups, 200), 4, async (vendorChunk) => {
            const groupsResult = await supabase
              .from("vendor_whatsapp_groups")
              .select("*")
              .eq("owner_email", user.owner_email)
              .in("vendor_id", vendorChunk)
              .neq("verification_status", "blocked")
              .order("updated_at", { ascending: false });
            if (groupsResult.error) throw new Error(`Outreach WhatsApp group load failed: ${groupsResult.error.message}`);
            return groupsResult.data || [];
          });
          for (const group of groupBatches.flat()) {
            const vendorId = cleanText(group.vendor_id);
            if (vendorId && !vendorGroupsByVendor.has(vendorId)) vendorGroupsByVendor.set(vendorId, group);
          }
        } catch (error) {
          channelPreparationErrors.whatsapp_group = safeOperationalError(error);
        }
      }
      let globallySuppressedEmails = new Set<string>();
      const vendorSuppressedEmails = new Map<string, Set<string>>();
      let audienceSuppressions: Record<string, unknown>[] = [];
      try {
        audienceSuppressions = await outreachSuppressionsForVendors(
          supabase,
          user,
          [...new Set(invitations.map((invitation) => cleanText(invitation.vendor_id)).filter(Boolean))] as string[]
        );
      } catch (error) {
        throw new Error(`Outreach suppression load failed: ${safeOperationalError(error)}`);
      }
      if (wantsEmail) {
        try {
          globallySuppressedEmails = await suppressedEmailSet(
            supabase,
            user,
            invitations.flatMap((invitation) => {
              const vendor = typeof invitation.vendors === "object" && invitation.vendors ? invitation.vendors as Record<string, unknown> : {};
              return vendorContactEmailCandidates(vendor);
            })
          );
        } catch (error) {
          channelPreparationErrors.email = `Email suppression check failed: ${safeOperationalError(error)}`;
        }
        for (const suppression of audienceSuppressions) {
          const suppressionChannel = cleanText(suppression.channel)?.toLowerCase() || "all";
          const email = cleanText(suppression.contact_value)?.toLowerCase();
          if (!["all", "email"].includes(suppressionChannel) || !email || email === "*") continue;
          const vendorId = cleanText(suppression.vendor_id);
          if (!vendorId) {
            globallySuppressedEmails.add(email);
            continue;
          }
          const vendorEmails = vendorSuppressedEmails.get(vendorId) || new Set<string>();
          vendorEmails.add(email);
          vendorSuppressedEmails.set(vendorId, vendorEmails);
        }
      }
      for (const [channel, preparationError] of Object.entries(channelPreparationErrors)) {
        try {
          const sourceAction = channel === "email" ? "gmail.queue_preparation_error" : "whatsapp.queue_preparation_error";
          await writeAuditLog(
            supabase,
            user,
            sourceAction,
            channel === "email" ? "gmail_outreach_queue" : "whatsapp_outreach_queue",
            campaign.id,
            `${channel === "email" ? "Gmail" : "WhatsApp"} draft preparation failed`,
            { campaign_id: campaign.id, requested_channels: requestedChannels, error: safeOperationalError(preparationError) }
          );
        } catch (_) {
          // Channel diagnostics must never turn a recoverable provider issue into a queue failure.
        }
      }

      const channelResults = (
        generatedRows: Record<string, unknown>[] = [],
        preservedRows: Record<string, unknown>[] = []
      ) => Object.fromEntries(requestedChannels.map((channel) => {
        const candidateDrafts = rows.filter((row) => cleanText(row.channel) === channel).length;
        const generated = generatedRows.filter((row) => cleanText(row.channel) === channel).length;
        const preserved = preservedRows.filter((row) => cleanText(row.channel) === channel).length;
        const channelSkipped = skipped.filter((row) => cleanText(row.channel) === channel).length;
        return [channel, {
          requested: true,
          queue_status: candidateDrafts || generated || preserved ? "ready" : channelSkipped ? "needs_contact" : "empty",
          candidate_drafts: candidateDrafts,
          generated,
          preserved,
          skipped: channelSkipped,
          preparation_error: channelPreparationErrors[channel] || "",
          ...(channel === "whatsapp" ? {
            provider_status: cleanText(whatsappNotifier.status) || "not_requested",
            provider_ready: Boolean(whatsappNotifier.ready)
          } : {})
        }];
      }));

      for (const [groupKey, requestedInvitationGroup] of invitationGroups.entries()) {
        const invitationGroup = sortRfxInvitationGroup(completeInvitationGroups.get(groupKey) || requestedInvitationGroup);
        const invitation = invitationGroup[0];
        const vendor = typeof invitation.vendors === "object" && invitation.vendors ? invitation.vendors as Record<string, unknown> : {};
        const profileLink = profileLinksByVendor.get(cleanText(invitation.vendor_id) || "") || "";
        const context = outreachContext(
          invitation,
          appOrigin,
          invitationGroup,
          template,
          profileLink,
          outreachEventLaneRows(eventLaneRows, invitationGroup)
        );
        const subject = renderTemplateText(template.subject || campaign.name, context);
        const htmlBody = renderTemplateText(template.html_body || template.whatsapp_body || "", context);
        const textBody = htmlToText(htmlBody);
        // Gmail queues must remain usable when Meta is disconnected or misconfigured.
        // Do not render or resolve WhatsApp-specific state unless that channel was requested.
        const whatsappText = wantsDirectWhatsapp
          ? renderTemplateText(template.whatsapp_body || textBody, context)
          : "";
        const whatsappGroupText = wantsWhatsappGroup
          ? renderTemplateText(template.whatsapp_group_body || template.whatsapp_body || textBody, context)
          : "";
        const channels = requestedChannels;
        const groupInvitationIds = invitationGroup.map((item) => item.id).filter(Boolean);
        const laneIds = invitationGroup.map((item) => item.rfx_lane_id).filter(Boolean);
        const vendorId = cleanText(invitation.vendor_id);
        const permissionBasis = cleanText(vendor.whatsapp_permission_basis) || "contractual";
        const doNotContact = cleanBoolean(vendor.whatsapp_do_not_contact);
        const normalizedRecipientPhone = normalizeWhatsappPhone(vendor.whatsapp_phone);
        const needsWhatsappTemplate = wantsDirectWhatsapp || wantsWhatsappGroup;
        const whatsappTemplateName = needsWhatsappTemplate
          ? cleanText(whatsappMapping?.meta_template_name || template.meta_template_name)
          : "";
        const whatsappTemplateLanguage = needsWhatsappTemplate
          ? cleanText(whatsappMapping?.meta_template_language || template.meta_template_language) || whatsappMetaLanguage(template)
          : "";
        const whatsappTemplateStatus = needsWhatsappTemplate
          ? whatsappMetaStatus(whatsappMapping?.meta_template_status || template.meta_template_status)
          : "NOT_REQUESTED";
        const whatsappParameters = wantsDirectWhatsapp
          ? whatsappTemplateParameters(whatsappMapping, context)
          : [];

        if (channels.includes("email")) {
          const suppressedEmails = new Set([
            ...globallySuppressedEmails,
            ...(vendorSuppressedEmails.get(vendorId || "") || new Set<string>())
          ]);
          const recipientEmail = channelPreparationErrors.email ? "" : firstEligibleOutreachEmail(
            vendor,
            suppressedEmails,
            cleanText(invitation.rfx_event_id) || "",
            vendorId || "",
            eventHistoryByContact
          );
          if (channelPreparationErrors.email) {
            skipped.push({ invitation_id: invitation.id, invitation_ids: groupInvitationIds, channel: "email", reason: channelPreparationErrors.email });
          } else if (recipientEmail) {
            rows.push(withOwner({
              campaign_id: campaign.id,
              template_id: template.id,
              rfx_event_id: invitation.rfx_event_id,
              rfx_lane_id: invitation.rfx_lane_id,
              rfx_lane_vendor_id: invitation.id,
              vendor_id: invitation.vendor_id,
              channel: "email",
              recipient_email: recipientEmail,
              subject,
              html_body: htmlBody,
              text_body: textBody,
              gmail_compose_url: gmailComposeUrl(recipientEmail, subject, textBody),
              sender_email: senderEmail,
              sender_label: senderLabel,
              sender_connection_status: senderConnectionStatus,
              provider: "gmail",
              gmail_connection_id: gmailConnectionRow.id || null,
              sender_address: senderEmail || null,
              sender_connection_type: gmailConnectionRow.id ? "gmail_oauth" : "gmail_draft_only",
              provider_response_status: "drafted",
              send_result: outreachSendResult("drafted", {
                channel: "email",
                provider: "gmail",
                outcome: "drafted",
                connection_id: gmailConnectionRow.id || null,
                sender: senderEmail || null
              }),
              status: "drafted",
              metadata: {
                bid_link: context.bid_link,
                profile_link: context.profile_link,
                generated_at: new Date().toISOString(),
                lane_count: invitationGroup.length,
                lane_table_signature: context.lane_table_signature,
                rfx_lane_vendor_ids: groupInvitationIds,
                rfx_lane_ids: laneIds,
                sender_email: senderEmail,
                sender_label: senderLabel,
                sender_connection_status: senderConnectionStatus
              }
            }, user));
          } else {
            skipped.push({
              invitation_id: invitation.id,
              invitation_ids: groupInvitationIds,
              channel: "email",
          reason: vendorContactEmailCandidates(vendor).length
            ? "Every carrier email is suppressed or was already contacted for this RFx"
            : "Missing vendor email"
            });
          }
        }

        if (channels.includes("whatsapp") && targetMode !== "vendor_group") {
          const recipientPhone = cleanText(vendor.whatsapp_phone);
          if (doNotContact) {
            skipped.push({ invitation_id: invitation.id, invitation_ids: groupInvitationIds, channel: "whatsapp", reason: "Vendor is marked do-not-contact for WhatsApp" });
          } else if (phoneForWhatsapp(recipientPhone)) {
            rows.push(withOwner({
              campaign_id: campaign.id,
              template_id: template.id,
              rfx_event_id: invitation.rfx_event_id,
              rfx_lane_id: invitation.rfx_lane_id,
              rfx_lane_vendor_id: invitation.id,
              vendor_id: invitation.vendor_id,
              channel: "whatsapp",
              recipient_phone: recipientPhone,
              normalized_recipient_phone: normalizedRecipientPhone,
              whatsapp_target_mode: "direct_vendor",
              provider: "meta",
              whatsapp_connection_id: whatsappConnectionRow.id || null,
              sender_address: cleanText(whatsappConnectionRow.display_phone_number) || null,
              sender_connection_type: cleanText(whatsappConnectionRow.connection_mode) || "unresolved",
              whatsapp_template_name: whatsappTemplateName,
              whatsapp_template_language: whatsappTemplateLanguage,
              whatsapp_text: whatsappText,
              whatsapp_body: whatsappText,
              text_body: whatsappText,
              whatsapp_url: whatsappDraftUrl(recipientPhone, whatsappText),
              sender_email: senderEmail,
              sender_label: senderLabel,
              sender_connection_status: senderConnectionStatus,
              provider_response_status: "drafted",
              send_result: outreachSendResult("drafted", {
                channel: "whatsapp",
                provider: "meta",
                outcome: "drafted",
                connection_id: whatsappConnectionRow.id || null,
                sender: cleanText(whatsappConnectionRow.display_phone_number) || null,
                template_name: whatsappTemplateName || null,
                template_language: whatsappTemplateLanguage || null
              }),
              status: "drafted",
              metadata: {
                bid_link: context.bid_link,
                profile_link: context.profile_link,
                generated_at: new Date().toISOString(),
                lane_count: invitationGroup.length,
                lane_table_signature: context.lane_table_signature,
                rfx_lane_vendor_ids: groupInvitationIds,
                rfx_lane_ids: laneIds,
                sender_email: senderEmail,
                sender_label: senderLabel,
                sender_connection_status: senderConnectionStatus,
                whatsapp_permission_basis: permissionBasis,
                whatsapp_template_mapped: Boolean(whatsappTemplateName),
                whatsapp_template_status: whatsappTemplateStatus,
                whatsapp_template_parameters: whatsappParameters,
                whatsapp_connection_status: whatsappConnectionRow.status || "not_configured"
              }
            }, user));
          } else {
            skipped.push({ invitation_id: invitation.id, invitation_ids: groupInvitationIds, channel: "whatsapp", reason: "Missing WhatsApp phone" });
          }
        }

        if (channels.includes("whatsapp_group") && targetMode !== "direct_vendor") {
          const groupRow = vendorId ? vendorGroupsByVendor.get(vendorId) : null;
          const groupName = cleanText(groupRow?.group_name || vendor.whatsapp_group_name);
          const groupUrl = cleanText(groupRow?.group_url || vendor.whatsapp_group_url);
          const metaGroupId = cleanText(groupRow?.meta_group_id || vendor.whatsapp_meta_group_id);
          const groupStatus = cleanText(groupRow?.verification_status || vendor.whatsapp_group_status || "manual_only");
          const groupBlocked = cleanBoolean(groupRow?.do_not_contact) || doNotContact;
          if (channelPreparationErrors.whatsapp_group) {
            skipped.push({ invitation_id: invitation.id, invitation_ids: groupInvitationIds, channel: "whatsapp_group", reason: channelPreparationErrors.whatsapp_group });
          } else if (groupBlocked) {
            skipped.push({ invitation_id: invitation.id, invitation_ids: groupInvitationIds, channel: "whatsapp_group", reason: "Vendor WhatsApp group is marked do-not-contact" });
          } else if (groupName || groupUrl || metaGroupId) {
            rows.push(withOwner({
              campaign_id: campaign.id,
              template_id: template.id,
              rfx_event_id: invitation.rfx_event_id,
              rfx_lane_id: invitation.rfx_lane_id,
              rfx_lane_vendor_id: invitation.id,
              vendor_id: invitation.vendor_id,
              channel: "whatsapp_group",
              vendor_whatsapp_group_id: groupRow?.id || null,
              meta_whatsapp_group_id: metaGroupId,
              whatsapp_target_mode: "vendor_group",
              provider: "meta",
              whatsapp_connection_id: whatsappConnectionRow.id || null,
              sender_address: cleanText(whatsappConnectionRow.display_phone_number) || null,
              sender_connection_type: "manual_group",
              whatsapp_template_name: whatsappTemplateName,
              whatsapp_template_language: whatsappTemplateLanguage,
              recipient_phone: "",
              whatsapp_text: whatsappGroupText,
              whatsapp_body: whatsappGroupText,
              text_body: whatsappGroupText,
              whatsapp_url: groupUrl,
              sender_email: senderEmail,
              sender_label: senderLabel,
              sender_connection_status: senderConnectionStatus,
              provider_response_status: "drafted",
              send_result: outreachSendResult("drafted", {
                channel: "whatsapp_group",
                provider: "meta",
                outcome: "drafted",
                connection_id: whatsappConnectionRow.id || null,
                sender: cleanText(whatsappConnectionRow.display_phone_number) || null,
                delivery_mode: "manual_group"
              }),
              status: "drafted",
              metadata: {
                bid_link: context.bid_link,
                profile_link: context.profile_link,
                generated_at: new Date().toISOString(),
                lane_count: invitationGroup.length,
                lane_table_signature: context.lane_table_signature,
                rfx_lane_vendor_ids: groupInvitationIds,
                rfx_lane_ids: laneIds,
                group_name: groupName,
                group_url: groupUrl,
                group_status: groupStatus,
                sender_email: senderEmail,
                sender_label: senderLabel,
                sender_connection_status: senderConnectionStatus,
                whatsapp_permission_basis: cleanText(groupRow?.permission_basis) || permissionBasis,
                whatsapp_group_delivery: WHATSAPP_GROUPS_ENABLED && metaGroupId && ["api_ready", "verified"].includes(groupStatus || "") ? "api_ready" : "manual_only",
                whatsapp_template_mapped: Boolean(whatsappTemplateName),
                whatsapp_template_status: whatsappTemplateStatus,
                whatsapp_connection_status: whatsappConnectionRow.status || "not_configured"
              }
            }, user));
          } else {
            skipped.push({ invitation_id: invitation.id, invitation_ids: groupInvitationIds, channel: "whatsapp_group", reason: "Missing vendor WhatsApp group" });
          }
        }
      }

      const suppressedRows = rows.filter((row) => {
        const channel = cleanText(row.channel)?.toLowerCase() || "";
        const recipient = channel === "email"
          ? cleanText(row.recipient_email)?.toLowerCase()
          : phoneForWhatsapp(row.normalized_recipient_phone || row.recipient_phone);
        const suppression = audienceSuppressions.find((item) => {
          const suppressionChannel = cleanText(item.channel)?.toLowerCase() || "all";
          const suppressionValue = cleanText(item.contact_value)?.toLowerCase() || "";
          const suppressionVendorId = cleanText(item.vendor_id) || "";
          return (!suppressionVendorId || suppressionVendorId === cleanText(row.vendor_id))
            && ["all", channel].includes(suppressionChannel)
            && (suppressionValue === "*" || Boolean(recipient && suppressionValue === recipient));
        });
        if (!suppression) return false;
        skipped.push({
          invitation_id: row.rfx_lane_vendor_id,
          channel: row.channel,
          reason: cleanText(suppression.reason) || "Contact is suppressed",
          reason_code: "suppressed_contact"
        });
        return true;
      });
      if (suppressedRows.length) {
        const suppressedSet = new Set(suppressedRows);
        rows.splice(0, rows.length, ...rows.filter((row) => !suppressedSet.has(row)));
      }
      for (const row of rows) {
        row.contact_key = outreachDedupeContactKey(row);
        row.outcome_reason = "Eligible contact ready for review";
        row.next_action = "Review and send";
      }

      if (!rows.length) return jsonResponse({
        generated: 0,
        rows: [],
        skipped,
        requested_channels: requestedChannels,
        channel_errors: channelPreparationErrors,
        channel_results: channelResults(),
        whatsapp_notifier: whatsappNotifier,
        metrics: {
          requested_invitation_ids: invitationIds.length,
          loaded_invitations: invitations.length,
          carrier_groups: invitationGroups.size,
          candidate_drafts: 0,
          created: 0,
          refreshed: 0,
          preserved: 0
        }
      });

      const historicalPreservedMessages: Record<string, unknown>[] = [];
      if (campaign.rfx_event_id && rows.length) {
        const candidateChannels = [...new Set(rows.map((row) => cleanText(row.channel)?.toLowerCase()).filter(Boolean))] as string[];
        const candidateVendorIds = [...new Set(rows.map((row) => cleanText(row.vendor_id)).filter(Boolean))] as string[];
        const historicalMessagesByKey = new Map<string, Record<string, unknown>>();
        if (candidateChannels.length && candidateVendorIds.length) {
          const historicalBatches = await mapWithConcurrency(chunkValues(candidateVendorIds, 100), 4, async (vendorChunk) => {
            const batch: Record<string, unknown>[] = [];
            let offset = 0;
            while (true) {
              const historicalResult = await supabase
                .from("outreach_messages")
                .select("id,campaign_id,rfx_event_id,rfx_lane_vendor_id,vendor_id,channel,status,recipient_email,recipient_phone,normalized_recipient_phone,sent_at,bounce_detected_at,delivery_status,provider_response_status,updated_at,metadata")
                .eq("owner_email", user.owner_email)
                .eq("rfx_event_id", campaign.rfx_event_id)
                .in("vendor_id", vendorChunk)
                .in("channel", candidateChannels)
                .neq("status", "archived")
                .order("updated_at", { ascending: false })
                .range(offset, offset + 999);
              if (historicalResult.error) throw new Error(`Outreach history load failed: ${historicalResult.error.message}`);
              const page = (historicalResult.data || []) as Record<string, unknown>[];
              batch.push(...page);
              if (page.length < 1000) break;
              offset += 1000;
              if (offset >= 25000) throw new Error("Outreach history load exceeded the safe per-batch limit.");
            }
            return batch;
          });
          for (const historicalMessage of historicalBatches.flat()) {
            if (!outreachBlocksAutoDraft(historicalMessage)) continue;
            const key = outreachEventDedupeKey(historicalMessage);
            if (key && !historicalMessagesByKey.has(key)) historicalMessagesByKey.set(key, historicalMessage);
          }
        }
        if (historicalMessagesByKey.size) {
          const filteredRows = rows.filter((row) => {
            const existing = historicalMessagesByKey.get(outreachEventDedupeKey(row));
            if (!existing) return true;
            historicalPreservedMessages.push(existing);
            skipped.push({
              invitation_id: row.rfx_lane_vendor_id,
              channel: row.channel,
              reason: outreachAutoDraftSkipReason(existing),
              reason_code: cleanText(existing.status)?.toLowerCase() === "bounced" ? "previous_bounce" : "previous_outreach",
              existing_message_id: existing.id,
              existing_campaign_id: existing.campaign_id,
              existing_status: existing.status,
              existing_updated_at: existing.updated_at
            });
            return false;
          });
          rows.length = 0;
          rows.push(...filteredRows);
        }
      }

      if (!rows.length) return jsonResponse({
        generated: 0,
        rows: [],
        skipped,
        campaign_id: campaign.id,
        requested_channels: requestedChannels,
        channel_errors: channelPreparationErrors,
        channel_results: channelResults([], historicalPreservedMessages),
        whatsapp_notifier: whatsappNotifier,
        metrics: {
          requested_invitation_ids: invitationIds.length,
          loaded_invitations: invitations.length,
          carrier_groups: invitationGroups.size,
          candidate_drafts: 0,
          created: 0,
          refreshed: 0,
          preserved: historicalPreservedMessages.length,
          preserved_from_history: historicalPreservedMessages.length
        }
      });

      const draftKey = (row: Record<string, unknown>) => `${cleanText(row.rfx_lane_vendor_id) || ""}|${cleanText(row.channel) || ""}|${outreachContactKey(row)}`;
      const existingMessagesByKey = new Map<string, Record<string, unknown>>();
      const candidateInvitationIds = [...new Set(rows.map((row) => cleanText(row.rfx_lane_vendor_id)).filter(Boolean))] as string[];
      const existingBatches = await mapWithConcurrency(chunkValues(candidateInvitationIds, 100), 4, async (idChunk) => {
        const existingResult = await supabase
          .from("outreach_messages")
          .select("id,rfx_lane_vendor_id,channel,contact_key,recipient_email,recipient_phone,normalized_recipient_phone,vendor_id,status,metadata,next_action,outcome_reason")
          .eq("owner_email", user.owner_email)
          .eq("campaign_id", campaign.id)
          .in("rfx_lane_vendor_id", idChunk);
        if (existingResult.error) throw new Error(`Outreach existing draft load failed: ${existingResult.error.message}`);
        return existingResult.data || [];
      });
      for (const existing of existingBatches.flat()) existingMessagesByKey.set(draftKey(existing), existing);

      const protectedStatuses = new Set(["queued", "sending", "sent", "delivered", "read", "replied", "delivery_unknown", "failed", "bounced", "manual_sent", "archived"]);
      const preservedMessages: Record<string, unknown>[] = [];
      const sentBookRevisions: Record<string, unknown>[] = [];
      const rowsToUpsert = rows.filter((row) => {
        const existing = existingMessagesByKey.get(draftKey(row));
        const status = cleanText(existing?.status)?.toLowerCase() || "";
        if (!existing || !protectedStatuses.has(status)) return true;
        preservedMessages.push(existing);
        const priorSignature = cleanText(objectRecord(existing.metadata).lane_table_signature);
        const nextSignature = cleanText(objectRecord(row.metadata).lane_table_signature);
        if (priorSignature && nextSignature && priorSignature !== nextSignature && OUTREACH_SENT_OR_RESOLVED_STATUSES.has(status)) {
          sentBookRevisions.push(existing);
        }
        skipped.push({
          invitation_id: row.rfx_lane_vendor_id,
          channel: row.channel,
          reason: `Existing ${status} outreach message preserved`
        });
        return false;
      });

      // Keep the first invitation touch intentional. Existing drafts may still be
      // refreshed, but new carrier contacts respect the workspace's rolling daily
      // cap so a large audience cannot flood a carrier base by accident.
      const rollingWindowStart = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
      const messagesInRollingWindow = await allScopedOutreachMessages(supabase, user, {
        channels: requestedChannels,
        created_after: rollingWindowStart,
        include_archived: false
      });
      let remainingDailyCapacity = Math.max(0, contactPolicy.daily_limit - messagesInRollingWindow.length);
      const dailyLimitedRows = rowsToUpsert.filter((row) => {
        const existing = existingMessagesByKey.get(draftKey(row));
        if (existing) return true;
        if (remainingDailyCapacity > 0) {
          remainingDailyCapacity -= 1;
          return true;
        }
        skipped.push({
          invitation_id: row.rfx_lane_vendor_id,
          channel: row.channel,
          reason: `Daily outreach cap of ${contactPolicy.daily_limit} contacts is reached. This carrier remains eligible for the next wave.`,
          reason_code: "daily_cap"
        });
        return false;
      });

      // A sent invitation is immutable evidence of what the carrier received. When the
      // business book changes, surface a deliberate revision action instead of silently
      // overwriting or resending the original message.
      if (sentBookRevisions.length) {
        await mapWithConcurrency(chunkValues(sentBookRevisions, 100), 4, async (chunk) => {
          const ids = chunk.map((item) => cleanText(item.id)).filter(Boolean);
          if (!ids.length) return true;
          const revisionResult = await supabase
            .from("outreach_messages")
            .update({
              next_action: "Send revision",
              outcome_reason: "Business Book changed after the original invitation.",
              next_action_at: new Date().toISOString(),
              updated_at: new Date().toISOString()
            })
            .eq("owner_email", user.owner_email)
            .in("id", ids);
          if (revisionResult.error) throw new Error(`Outreach revision flag failed: ${revisionResult.error.message}`);
          return true;
        });
      }

      const generatedBatches = await mapWithConcurrency(chunkValues(dailyLimitedRows, 100), 4, async (chunk) => {
        const result = await supabase
          .from("outreach_messages")
          .upsert(chunk, { onConflict: "campaign_id,rfx_lane_vendor_id,channel,contact_key" })
          .select("id,campaign_id,vendor_id,rfx_event_id,rfx_lane_vendor_id,channel,provider,gmail_connection_id,whatsapp_connection_id,subject,text_body,whatsapp_text,html_body,sender_email,sender_label,sender_address,sender_connection_type,sender_connection_status,provider_response_status,send_result,contact_key,outcome_reason,next_action,next_action_at");
        if (result.error) throw new Error(`Outreach draft upsert failed: ${result.error.message}`);
        return result.data || [];
      });
      const generatedMessages = generatedBatches.flat() as Record<string, unknown>[];
      const createdMessages = generatedMessages.filter((message) => !existingMessagesByKey.has(draftKey(message)));

      const historyRows = createdMessages.map((message) => withOwner({
        outreach_message_id: message.id,
        campaign_id: campaign.id,
        vendor_id: message.vendor_id,
        rfx_event_id: message.rfx_event_id,
        channel: message.channel,
        direction: "outbound",
        status: "drafted",
        subject: message.subject,
        body_preview: contactPreview(message.text_body || message.whatsapp_text || message.html_body),
        gmail_connection_id: message.gmail_connection_id || null,
        whatsapp_connection_id: message.whatsapp_connection_id || null,
        metadata: {
          generated_from: "outreach_engine",
          channel: message.channel,
          provider: message.provider,
          gmail_connection_id: message.gmail_connection_id || null,
          whatsapp_connection_id: message.whatsapp_connection_id || null,
          sender_email: message.sender_email,
          sender_address: message.sender_address,
          sender_connection_type: message.sender_connection_type,
          sender_label: message.sender_label,
          sender_connection_status: message.sender_connection_status,
          provider_response_status: message.provider_response_status,
          result: objectRecord(message.send_result)
        }
      }, user));
      if (historyRows.length) {
        await mapWithConcurrency(chunkValues(historyRows, 200), 4, async (chunk) => {
          const history = await supabase.from("contact_history").insert(chunk);
          if (history.error) throw new Error(`Outreach contact history insert failed: ${history.error.message}`);
          return true;
        });
      }

      const campaignUpdate = await supabase
        .from("outreach_campaigns")
        .update({
          status: "generated",
          sender_email: senderEmail || campaign.sender_email,
          sender_label: senderLabel || campaign.sender_label,
          sender_connection_status: senderConnectionStatus,
          audience_policy: audiencePolicy,
          contact_policy: contactPolicy,
          sequence_policy: sequencePolicy,
          audience_snapshot: {
            generated_at: new Date().toISOString(),
            channel: requestedChannels[0],
            requested_invitation_ids: invitationIds.length,
            selected_vendor_count: audienceVendorIds.length,
          generated_candidates: dailyLimitedRows.length,
          rolling_window_contacts: messagesInRollingWindow.length,
          daily_limit: contactPolicy.daily_limit,
          skipped: skipped.length
          },
          updated_at: new Date().toISOString()
        })
        .eq("id", campaign.id)
        .eq("owner_email", user.owner_email);
      if (campaignUpdate.error) throw campaignUpdate.error;

      return jsonResponse({
        generated: generatedMessages.length,
        rows: [],
        skipped,
        campaign_id: campaign.id,
        requested_channels: requestedChannels,
        channel_errors: channelPreparationErrors,
        channel_results: channelResults(generatedMessages, [...historicalPreservedMessages, ...preservedMessages]),
        whatsapp_notifier: whatsappNotifier,
        metrics: {
          requested_invitation_ids: invitationIds.length,
          loaded_invitations: invitations.length,
          carrier_groups: invitationGroups.size,
          candidate_drafts: dailyLimitedRows.length,
          created: createdMessages.length,
          refreshed: generatedMessages.length - createdMessages.length,
          preserved: preservedMessages.length + historicalPreservedMessages.length,
          preserved_from_history: historicalPreservedMessages.length
        }
      });
    }

    if (body.action === "get_outreach_tracking_summary") {
      const channels = Array.isArray(body.channels)
        ? body.channels.map((value: unknown) => cleanText(value)?.toLowerCase()).filter(Boolean)
        : [];
      const summaryResult = await supabase.rpc("rateware_outreach_tracking_summary", {
        p_owner_email: user.owner_email,
        p_rfx_event_id: cleanText(body.rfx_event_id) || null,
        p_channels: channels.length ? channels : null,
        p_include_archived: body.include_archived !== false,
        p_enforce_event_scope: body.enforce_rfx_event_scope === true
      });
      if (summaryResult.error) throw summaryResult.error;
      const summary = objectRecord(summaryResult.data);
      return jsonResponse({
        total: Number(summary.total || 0),
        states: objectRecord(summary.states),
        carrier_total: Number(summary.carrier_total || 0),
        carrier_states: objectRecord(summary.carrier_states),
        next_actions: objectRecord(summary.next_actions),
        outcomes: objectRecord(summary.outcomes),
        updated_at: new Date().toISOString()
      });
    }

    if (body.action === "list_outreach_messages") {
      // Existing admin views still call this action without paging. Preserve their
      // previous 1,000-row response while the Draft Queue always passes a bounded
      // page size for responsive server-side pagination.
      const requestedLimit = Number(body.limit);
      const limit = Number.isFinite(requestedLimit) && requestedLimit > 0
        ? Math.min(Math.max(requestedLimit, 25), 250)
        : 1000;
      const offset = Math.max(Number(body.offset || 0), 0);
      const channels = Array.isArray(body.channels)
        ? body.channels.map((value: unknown) => cleanText(value)?.toLowerCase()).filter(Boolean)
        : [];
      const searchTerms = String(body.search || "")
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .split(/\s+/)
        .map((value) => value.replace(/[^a-z0-9@.+_-]/g, "").trim())
        .filter(Boolean)
        .slice(0, 6);
      const trackingStatus = normalizeOutreachTrackingStatus(body.tracking_status);
      if (trackingStatus) {
        const trackingPageResult = await supabase.rpc("rateware_outreach_tracking_page", {
          p_owner_email: user.owner_email,
          p_rfx_event_id: cleanText(body.rfx_event_id) || null,
          p_channels: channels.length ? channels : null,
          p_tracking_status: trackingStatus,
          p_search_terms: searchTerms.length ? searchTerms : null,
          p_include_archived: trackingStatus === "archived" || body.include_archived === true,
          p_enforce_event_scope: body.enforce_rfx_event_scope === true,
          p_offset: offset,
          p_limit: limit
        });
        if (trackingPageResult.error) throw trackingPageResult.error;
        const page = objectRecord(trackingPageResult.data);
        const ids = Array.isArray(page.ids) ? page.ids.map((value) => cleanText(value)).filter(Boolean) : [];
        const total = Number(page.total || 0);
        if (!ids.length) {
          return jsonResponse({ rows: [], total, offset, limit, has_more: false, tracking_status: trackingStatus });
        }
        const outreachSelect: string = body.view === "event_context"
          ? OUTREACH_MESSAGE_EVENT_SELECT
          : body.compact === true
            ? OUTREACH_MESSAGE_COMPACT_SELECT
            : OUTREACH_MESSAGE_SELECT;
        const pageResult = await supabase
          .from("outreach_messages")
          .select(outreachSelect)
          .eq("owner_email", user.owner_email)
          .in("id", ids);
        if (pageResult.error) throw pageResult.error;
        const order = new Map(ids.map((id, index) => [id, index]));
        const orderedRows = ((pageResult.data || []) as unknown as Record<string, unknown>[])
          .sort((left, right) => (order.get(cleanText(left.id)) ?? ids.length) - (order.get(cleanText(right.id)) ?? ids.length));
        const pageRows = await hydrateOutreachInvitationTokens(supabase, orderedRows);
        return jsonResponse({
          rows: pageRows.map(enrichOutreachMessage),
          total,
          offset,
          limit,
          has_more: offset + pageRows.length < total,
          tracking_status: trackingStatus
        });
      }
      const outreachSelect: string = body.view === "event_context"
        ? OUTREACH_MESSAGE_EVENT_SELECT
        : body.compact === true
          ? OUTREACH_MESSAGE_COMPACT_SELECT
          : OUTREACH_MESSAGE_SELECT;
      let query: any = supabase
        .from("outreach_messages")
        .select(outreachSelect, { count: "exact" })
        .eq("owner_email", user.owner_email)
        .order("created_at", { ascending: false })
        .order("id", { ascending: false });
      if (body.campaign_id) query = query.eq("campaign_id", body.campaign_id);
      if (body.rfx_event_id) query = query.eq("rfx_event_id", body.rfx_event_id);
      if (body.status) query = query.eq("status", body.status);
      if (!body.status && !body.include_archived) query = query.neq("status", "archived");
      if (body.channel) query = query.eq("channel", body.channel);
      if (channels.length) query = query.in("channel", channels);
      for (const term of searchTerms) {
        const pattern = `*${term}*`;
        query = query.or([
          `recipient_email.ilike.${pattern}`,
          `recipient_phone.ilike.${pattern}`,
          `subject.ilike.${pattern}`,
          `status.ilike.${pattern}`,
          `channel.ilike.${pattern}`,
          `metadata->>vendor_name.ilike.${pattern}`,
          `metadata->>vendor_domain.ilike.${pattern}`,
          `metadata->>contact_name.ilike.${pattern}`,
          `metadata->>recipient_email.ilike.${pattern}`,
          `metadata->>lane_rows_text.ilike.${pattern}`,
          `metadata->>event_name.ilike.${pattern}`,
          `metadata->>rfx_id.ilike.${pattern}`
        ].join(","));
      }
      query = query.range(offset, offset + limit - 1);
      const result = await query;
      if (result.error) throw result.error;
      const total = Number(result.count || 0);
      const rows = await hydrateOutreachInvitationTokens(supabase, (result.data || []) as Record<string, unknown>[]);
      return jsonResponse({
        rows: rows.map(enrichOutreachMessage),
        total,
        offset,
        limit,
        has_more: offset + rows.length < total
      });
    }

    if (body.action === "get_outreach_message") {
      const messageId = cleanText(body.id);
      if (!messageId) throw new Error("Outreach message id is required.");
      const result = await supabase
        .from("outreach_messages")
        .select(OUTREACH_MESSAGE_SELECT)
        .eq("owner_email", user.owner_email)
        .eq("id", messageId)
        .maybeSingle();
      if (result.error) throw result.error;
      if (!result.data) return jsonResponse({ row: null });
      const rows = await hydrateOutreachInvitationTokens(supabase, [result.data as Record<string, unknown>]);
      return jsonResponse({ row: rows[0] ? enrichOutreachMessage(rows[0]) : null });
    }

    if (body.action === "send_outreach_messages") {
      const result = await sendOutreachMessages(supabase, user, body);
      return jsonResponse(result);
    }

    if (body.action === "send_whatsapp_outreach_messages") {
      const result = await sendWhatsappOutreachMessages(supabase, user, body);
      return jsonResponse(result);
    }

    if (body.action === "send_whatsapp_group_outreach_messages") {
      const result = await sendWhatsappGroupOutreachMessages(supabase, user, body);
      return jsonResponse(result);
    }

    if (body.action === "mark_whatsapp_group_message_manually_sent") {
      const result = await markWhatsappGroupMessageManuallySent(supabase, user, body);
      return jsonResponse(result);
    }

    if (body.action === "sync_gmail_bounces") {
      const result = await syncGmailBounces(supabase, user, body);
      return jsonResponse(result);
    }

    if (body.action === "delete_outreach_messages") {
      const ids = normalizeBulkIds(body.ids, { label: "Outreach message ids", limit: BULK_SELECTED_ID_LIMIT });
      const channelFilter = normalizeOutreachChannel(body.channel);
      if (!ids.length) return jsonResponse({ removed: 0, rows: [] });
      requireBulkConfirmation(body, {
        action: "delete_outreach_messages",
        label: "Outreach message delete",
        count: ids.length
      });
      const lookup = await supabase
        .from("outreach_messages")
        .select("id,campaign_id,rfx_event_id,vendor_id,channel,recipient_email,recipient_phone,status")
        .eq("owner_email", user.owner_email)
        .in("id", ids);
      if (lookup.error) throw lookup.error;

      const lookupById = new Map<string, Record<string, unknown>>();
      for (const row of lookup.data || []) {
        const rowId = cleanText(row.id);
        if (rowId) lookupById.set(rowId, row);
      }
      const deleted: Record<string, unknown>[] = [];
      const skipped: Record<string, unknown>[] = [];
      const failures: Record<string, unknown>[] = [];
      const deletableIds: string[] = [];
      for (const id of ids) {
        const row = lookupById.get(id);
        if (!row) {
          failures.push({ id, reason: "Message was not found in your workspace." });
          continue;
        }
        const rowChannel = cleanText(row.channel) || "";
        if (channelFilter && rowChannel !== channelFilter) {
          skipped.push({ id, reason: `Message channel is ${rowChannel || "unknown"}; expected ${channelFilter}.` });
          continue;
        }
        deletableIds.push(id);
      }

      if (deletableIds.length) {
        const deleteResult = await supabase
          .from("outreach_messages")
          .delete()
          .eq("owner_email", user.owner_email)
          .in("id", deletableIds)
          .select("id,campaign_id,rfx_event_id,vendor_id,channel,recipient_email,recipient_phone,status");
        if (deleteResult.error) throw deleteResult.error;
        deleted.push(...(deleteResult.data || []));
      }

      await tryWriteAuditLog(
        supabase,
        user,
        "outreach.messages.delete",
        "outreach_messages",
        null,
        `Deleted ${deleted.length || 0} outreach draft row(s)`,
        { ids, channel: channelFilter || "all", requested: ids.length, skipped: skipped.length }
      );
      return jsonResponse({
        removed: deleted.length || 0,
        rows: deleted,
        skipped: skipped.length,
        skipped_rows: skipped,
        failures
      });
    }

    if (body.action === "mark_outreach_messages") {
      const ids = normalizeBulkIds(body.ids, { label: "Outreach message ids", limit: BULK_SELECTED_ID_LIMIT });
      const channelFilter = normalizeOutreachChannel(body.channel);
      const status = cleanText(body.status)?.toLowerCase();
      if (!ids.length) return jsonResponse({ updated: 0, rows: [] });
      if (!status || !OUTREACH_MANUAL_STATUSES.has(status)) {
        return jsonResponse({ error: "Valid message status is required." }, 400);
      }
      if (["sent", "replied", "archived"].includes(status) || ids.length >= 100) {
        requireBulkConfirmation(body, {
          action: "mark_outreach_messages",
          label: "Outreach message status update",
          count: ids.length
        });
      }
      const now = new Date().toISOString();
      const lookup = await supabase
        .from("outreach_messages")
        .select("*")
        .eq("owner_email", user.owner_email)
        .in("id", ids)
        .order("created_at", { ascending: true });
      if (lookup.error) throw lookup.error;

      const lookupById = new Map<string, Record<string, unknown>>();
      for (const row of lookup.data || []) {
        const rowId = cleanText(row.id);
        if (rowId) lookupById.set(rowId, row);
      }
      const selectedChannels = new Set((lookup.data || [])
        .map((row) => cleanText(row.channel))
        .filter(Boolean));
      if (!channelFilter && status !== "archived" && selectedChannels.size > 1) {
        return jsonResponse({
          error: "Selected messages include multiple channels. Provide a channel filter before changing delivery status."
        }, 400);
      }

      const rows: Record<string, unknown>[] = [];
      const skipped: Record<string, unknown>[] = [];
      const failures: Record<string, unknown>[] = [];
      const updatableIds: string[] = [];
      for (const id of ids) {
        const message = lookupById.get(id);
        if (!message) {
          failures.push({ id, reason: "Message was not found in your workspace." });
          continue;
        }
        const messageChannel = cleanText(message.channel);
        if (channelFilter && messageChannel !== channelFilter) {
          skipped.push({ id, reason: `Message channel is ${messageChannel || "unknown"}; expected ${channelFilter}.` });
          continue;
        }
        const current = cleanText(message.status) || "";
        if (!OUTREACH_MANUAL_STATUSES.has(current)) {
          failures.push({ id, reason: `Message has unsupported status "${current || "unknown"}" for manual updates.` });
          continue;
        }
        if (!OUTREACH_MARK_TRANSITIONS[current]?.includes(status)) {
          failures.push({ id, reason: `Cannot change status from ${current || "unknown"} to ${status}.` });
          continue;
        }
        if (current === status) {
          skipped.push({ id, reason: "No status change requested." });
          continue;
        }
        updatableIds.push(id);
      }

      let result: { data: Record<string, unknown>[] | null; error: unknown } = { data: [], error: null };
      if (!updatableIds.length) {
        return jsonResponse({
          updated: 0,
          rows: [],
          skipped: skipped.length,
          skipped_rows: skipped,
          failures
        });
      }

      const patch: Record<string, unknown> = {
        status,
        delivery_status: status,
        provider_response_status: status,
        send_result: outreachSendResult("manual_status", {
          outcome: status,
          source: "outreach_engine"
        }),
        updated_at: now
      };
      if (["sent", "delivered", "read", "manual_sent", "delivery_unknown"].includes(status)) {
        patch.sent_at = now;
        patch.last_contacted_at = now;
      }
      if (status === "delivered") patch.delivered_at = now;
      if (status === "read") patch.read_at = now;
      if (status === "manual_sent") {
        patch.manual_sent_at = now;
        patch.manual_sent_by = user.owner_email;
      }
      if (status === "failed") patch.failed_at = now;
      if (status === "bounced") {
        patch.failed_at = now;
        patch.bounce_detected_at = now;
        patch.bounce_status = "manual_bounce";
      }
      patch.next_action = outreachNextAction({ status, delivery_status: status, provider_response_status: status, send_result: patch.send_result });
      patch.outcome_reason = outreachOutcomeReason({ status, delivery_status: status, provider_response_status: status, send_result: patch.send_result });
      patch.next_action_at = now;
      result = await supabase
        .from("outreach_messages")
        .update(patch)
        .eq("owner_email", user.owner_email)
        .in("id", updatableIds)
        .select("*");
      if (result.error) throw result.error;

      const historyRows = (result.data || []).map((message) => withOwner({
        outreach_message_id: message.id,
        campaign_id: message.campaign_id,
        vendor_id: message.vendor_id,
        rfx_event_id: message.rfx_event_id,
        channel: message.channel,
        direction: status === "replied" ? "inbound" : "outbound",
        status,
        subject: message.subject,
        body_preview: contactPreview(message.text_body || message.whatsapp_text || message.html_body),
        gmail_connection_id: message.gmail_connection_id || null,
        whatsapp_connection_id: message.whatsapp_connection_id || null,
        metadata: {
          marked_from: "outreach_engine",
          channel: message.channel,
          provider: message.provider,
          gmail_connection_id: message.gmail_connection_id || null,
          whatsapp_connection_id: message.whatsapp_connection_id || null,
          sender_address: message.sender_address,
          sender_connection_type: message.sender_connection_type,
          delivery_status: status,
          outcome: status,
          next_action: patch.next_action,
          outcome_reason: patch.outcome_reason,
          result: objectRecord(message.send_result)
        }
      }, user));
      if (historyRows.length) {
        const history = await supabase.from("contact_history").insert(historyRows);
        if (history.error) throw history.error;
      }

      const linkedInvitationIds = [...new Set((result.data || [])
        .map((message) => cleanText(message.rfx_lane_vendor_id))
        .filter(Boolean))];
      if (linkedInvitationIds.length && ["sent", "delivered", "read", "manual_sent", "delivery_unknown", "replied"].includes(status)) {
        const invitationPatch: Record<string, unknown> = {
          invitation_status: status === "replied" ? "responded" : "invited",
          updated_at: now
        };
        if (status !== "replied") invitationPatch.invited_at = now;
        if (status === "replied") invitationPatch.responded_at = now;
        const invitationUpdate = await supabase
          .from("rfx_lane_vendors")
          .update(invitationPatch)
          .in("id", linkedInvitationIds)
          .not("invitation_status", "in", "(quoted,bid_submitted,awarded,archived)");
        if (invitationUpdate.error) throw invitationUpdate.error;
      }

      await tryWriteAuditLog(
        supabase,
        user,
        "outreach.messages.mark",
        "outreach_messages",
        null,
        `Marked ${result.data?.length || 0} outreach draft row(s) as ${status}`,
        {
          status,
          channel: channelFilter || "all",
          requested: ids.length,
          updated: result.data?.length || 0,
          skipped: skipped.length
        }
      );

      return jsonResponse({
        updated: result.data?.length || 0,
        rows: result.data || [],
        skipped: skipped.length,
        skipped_rows: skipped,
        failures
      });
    }

    if (body.action === "list_contact_history") {
      const offset = Math.max(Number(body.offset || 0), 0);
      const requestedLimit = Number(body.limit);
      const limit = Number.isFinite(requestedLimit) && requestedLimit > 0
        ? Math.min(Math.max(requestedLimit, 25), 1000)
        : 300;
      let query = supabase
        .from("contact_history")
        .select("*, vendors(vendor_name,domain,primary_email), outreach_campaigns(name), rfx_events(rfx_id,name)", { count: "exact" })
        .eq("owner_email", user.owner_email)
        .order("occurred_at", { ascending: false })
        .order("id", { ascending: false });
      if (body.vendor_id) query = query.eq("vendor_id", body.vendor_id);
      if (body.campaign_id) query = query.eq("campaign_id", body.campaign_id);
      if (body.rfx_event_id) query = query.eq("rfx_event_id", body.rfx_event_id);
      query = query.range(offset, offset + limit - 1);
      const result = await query;
      if (result.error) throw result.error;
      const rows = result.data || [];
      const total = Number(result.count || 0);
      return jsonResponse({ rows, total, offset, limit, has_more: offset + rows.length < total });
    }

    if (body.action === "list_vendor_support_tickets") {
      return jsonResponse(await listVendorSupportTickets(supabase, user, body));
    }

    if (body.action === "get_vendor_relationship_activity") {
      return jsonResponse(await getVendorRelationshipActivity(supabase, user, body));
    }

    if (body.action === "update_vendor_support_ticket") {
      return jsonResponse(await updateVendorSupportTicket(supabase, user, body));
    }

    if (body.action === "list_vendor_improvement_cases") {
      return jsonResponse(await listVendorImprovementCases(supabase, user, body));
    }

    if (body.action === "create_vendor_improvement_case") {
      return jsonResponse(await createVendorImprovementCase(supabase, user, body));
    }

    if (body.action === "update_vendor_improvement_case") {
      return jsonResponse(await updateVendorImprovementCase(supabase, user, body));
    }

    if (body.action === "submit_vendor_improvement_case") {
      return jsonResponse(await submitVendorImprovementCase(supabase, user, body));
    }

    if (body.action === "record_vendor_improvement_response") {
      return jsonResponse(await recordVendorImprovementResponse(supabase, user, body));
    }

    if (body.action === "resolve_vendor_improvement_case") {
      return jsonResponse(await resolveVendorImprovementCase(supabase, user, body));
    }

    if (body.action === "process_vendor_ci_reminders") {
      return jsonResponse(await processVendorImprovementReminders(supabase, user, body));
    }

    if (body.action === "upsert_vendor_value_scorecard") {
      return jsonResponse(await upsertVendorValueScorecard(supabase, user, body));
    }

    if (body.action === "refresh_vendor_value_curve") {
      return jsonResponse(await refreshVendorValueCurve(supabase, user, body));
    }

    if (body.action === "get_saas_settings") {
      const settings = await buildSaasSettings(supabase, user);
      return jsonResponse(settings);
    }

    if (body.action === "list_observability_events") {
      return jsonResponse(await buildObservabilityEvents(supabase, user, body));
    }

    if (body.action === "list_gmail_connections") {
      const result = await listGmailConnections(supabase, user);
      return jsonResponse(result);
    }

    if (body.action === "start_gmail_oauth") {
      const result = await startGmailOauth(supabase, user, body);
      if ("error" in result) return jsonResponse(result, Number(result.status) || 400);
      return jsonResponse(result);
    }

    if (body.action === "disconnect_gmail_connection") {
      const row = await disconnectGmailConnection(supabase, user);
      await writeAuditLog(supabase, user, "gmail.disconnect", "gmail_mailbox_connections", GMAIL_ALLOWED_SENDER, `Disconnected ${GMAIL_ALLOWED_SENDER} from Gmail sending`);
      return jsonResponse({ row });
    }

    if (body.action === "list_google_chat_connections") {
      const result = await listGoogleChatConnections(supabase, user);
      return jsonResponse(result);
    }

    if (body.action === "start_google_chat_oauth") {
      const result = await startGoogleChatOauth(supabase, user, body);
      if ("error" in result) return jsonResponse(result, Number(result.status) || 400);
      return jsonResponse(result);
    }

    if (body.action === "disconnect_google_chat_connection") {
      const row = await disconnectGoogleChatConnection(supabase, user);
      await writeAuditLog(supabase, user, "google_chat.disconnect", "google_chat_connections", GOOGLE_CHAT_ALLOWED_ACCOUNT, `Disconnected ${GOOGLE_CHAT_ALLOWED_ACCOUNT} from Google Chat`);
      return jsonResponse({ row });
    }

    if (body.action === "list_google_chat_spaces") {
      return jsonResponse(await listGoogleChatSpaces(supabase, user));
    }

    if (body.action === "save_google_chat_settings") {
      const row = await saveGoogleChatSettings(supabase, user, body);
      await writeAuditLog(supabase, user, "google_chat.space.update", "google_chat_connections", row.default_space_name || GOOGLE_CHAT_ALLOWED_ACCOUNT, `Updated Google Chat default space to ${row.default_space_display_name || row.default_space_name || "selected space"}`);
      return jsonResponse({ row });
    }

    if (body.action === "list_whatsapp_connections") {
      return jsonResponse(await listWhatsappConnections(supabase, user));
    }

    if (body.action === "get_whatsapp_connection_status") {
      const connections = await listWhatsappConnections(supabase, user);
      return jsonResponse({ row: connections.rows?.[0] || null });
    }

    if (body.action === "start_whatsapp_business_connection") {
      const result = await startWhatsappBusinessConnection(supabase, user, body);
      const connectionResult = objectRecord(result);
      if (cleanText(connectionResult.error) && !cleanText(connectionResult.authorization_url) && !Boolean(connectionResult.connected)) return jsonResponse(result, 400);
      return jsonResponse(result);
    }

    if (body.action === "save_whatsapp_business_connection") {
      const row = await saveTenantWhatsappBusinessConnection(supabase, user, body);
      await writeAuditLog(
        supabase,
        user,
        "whatsapp.connection.save",
        "whatsapp_business_connections",
        row.id || "meta",
        "Saved workspace WhatsApp Business connection"
      );
      return jsonResponse({ row });
    }

    if (body.action === "complete_whatsapp_business_connection") {
      const result = await completeWhatsappBusinessConnection(supabase, user, body);
      if ("error" in result) return jsonResponse(result, 400);
      return jsonResponse(result);
    }

    if (body.action === "disconnect_whatsapp_business_connection") {
      const row = await disconnectWhatsappBusinessConnection(supabase, user);
      await writeAuditLog(supabase, user, "whatsapp.disconnect", "whatsapp_business_connections", row.id || "meta", "Disconnected WhatsApp Business integration");
      return jsonResponse({ row });
    }

    if (body.action === "test_whatsapp_business_connection") {
      return jsonResponse(await testWhatsappBusinessConnection(supabase, user));
    }

    if (body.action === "sync_whatsapp_templates") {
      return jsonResponse(await syncWhatsappTemplates(supabase, user));
    }

    if (body.action === "list_whatsapp_templates") {
      return jsonResponse(await listWhatsappTemplates(supabase, user));
    }

    if (body.action === "list_whatsapp_phone_numbers") {
      return jsonResponse(await listWhatsappPhoneNumbers(supabase, user));
    }

    if (body.action === "select_whatsapp_sender") {
      const row = await selectWhatsappSender(supabase, user, body);
      return jsonResponse({ row });
    }

    if (body.action === "verify_whatsapp_webhook") {
      return jsonResponse(await verifyWhatsappWebhook(supabase, user));
    }

    if (body.action === "verify_vendor_whatsapp_group") {
      return jsonResponse(await verifyVendorWhatsappGroup(supabase, user, body));
    }

    if (body.action === "update_saas_profile") {
      const patch = normalizeSaasProfile(objectRecord(body.profile || body.patch));
      const current = await ensureSaasProfile(supabase, user);
      const result = await supabase
        .from("user_profiles")
        .update(patch)
        .eq("owner_email", user.owner_email)
        .select()
        .single();
      if (result.error) throw result.error;
      await writeAuditLog(supabase, user, "settings.profile.update", "user_profile", current.id, "Updated user profile", { changed_fields: Object.keys(patch) });
      return jsonResponse({ profile: result.data });
    }

    if (body.action === "update_saas_organization") {
      const patch = normalizeOrganization(objectRecord(body.organization || body.patch));
      const current = await ensureOrganization(supabase, user);
      const result = await supabase
        .from("organizations")
        .update(patch)
        .eq("owner_email", user.owner_email)
        .select()
        .single();
      if (result.error) throw result.error;
      await writeAuditLog(supabase, user, "settings.organization.update", "organization", current.id, "Updated organization profile", { changed_fields: Object.keys(patch) });
      return jsonResponse({ organization: result.data });
    }

    if (body.action === "update_onboarding_task") {
      const taskKey = cleanText(body.task_key);
      if (!taskKey) return jsonResponse({ error: "Onboarding task key is required." }, 400);
      const completed = body.completed === undefined ? true : cleanBoolean(body.completed);
      const row = withOwner({
        task_key: taskKey,
        completed,
        completed_at: completed ? new Date().toISOString() : null,
        notes: cleanText(body.notes),
        updated_at: new Date().toISOString()
      }, user);
      const result = await supabase
        .from("onboarding_checklist")
        .upsert(row, { onConflict: "owner_email,task_key" })
        .select()
        .single();
      if (result.error) throw result.error;
      await writeAuditLog(
        supabase,
        user,
        completed ? "onboarding.task.complete" : "onboarding.task.reopen",
        "onboarding_task",
        taskKey,
        `${completed ? "Completed" : "Reopened"} onboarding task ${taskKey}`,
        { task_key: taskKey }
      );
      const settings = await buildSaasSettings(supabase, user);
      return jsonResponse({ row: result.data, onboarding: settings.onboarding, audit: settings.audit });
    }

    if (body.action === "list_saas_audit_log") {
      let query = supabase
        .from("saas_audit_log")
        .select("*")
        .eq("owner_email", user.owner_email)
        .order("created_at", { ascending: false })
        .limit(Math.min(Math.max(Number(body.limit) || 100, 1), 300));
      if (body.action_filter) query = query.eq("action", body.action_filter);
      const result = await query;
      if (result.error) throw result.error;
      return jsonResponse({ rows: result.data || [] });
    }

    if (body.action === "list_catalog_values") {
      const category = cleanText(body.category);
      const resolvedCategory = category && MANAGED_CATALOG_CATEGORIES.has(category) ? category : null;
      const catalogRows = await fetchAllManagedCatalogRows(supabase, resolvedCategory);

      const rows = catalogRows
        .filter((item) => MANAGED_CATALOG_CATEGORIES.has(String(item.category)))
        .filter((item) => isManualCatalogOwnedBy(item, user))
        .map((item) => ({
          ...item,
          is_manual: item.source === "rateware_manual_catalog",
          can_archive: item.source === "rateware_manual_catalog" && item.active === true
        }));
      return jsonResponse({ rows });
    }

    if (body.action === "save_catalog_value") {
      const input = objectRecord(body.catalog_value || body);
      const category = cleanText(input.category);
      const rawValue = cleanText(input.raw_value || input.rawValue || input.value);
      const normalizedValue = cleanText(input.normalized_value || input.normalizedValue || rawValue);
      if (!category || !MANAGED_CATALOG_CATEGORIES.has(category)) {
        return jsonResponse({ error: "Choose a valid catalog category." }, 400);
      }
      if (!rawValue || !normalizedValue) {
        return jsonResponse({ error: "Catalog value and normalized value are required." }, 400);
      }
      const code = cleanText(input.code) || catalogCode(normalizedValue);
      const metadata = {
        owner_email: user.owner_email,
        owner_user_id: user.owner_user_id,
        note: cleanText(input.note),
        created_from: "settings_catalog_manager"
      };
      const row = {
        source: "rateware_manual_catalog",
        category,
        raw_value: rawValue,
        normalized_value: normalizedValue,
        code,
        metadata,
        active: true,
        updated_at: new Date().toISOString()
      };
      const result = await supabase
        .from("rateware_catalog_items")
        .upsert(row, { onConflict: "source,category,raw_value,normalized_value" })
        .select("id,source,category,raw_value,normalized_value,code,metadata,active,updated_at")
        .single();
      if (result.error) throw result.error;
      await writeAuditLog(
        supabase,
        user,
        "catalog.value.save",
        "rateware_catalog_items",
        result.data.id,
        `Saved ${category} catalog value "${normalizedValue}"`,
        { category, raw_value: rawValue, normalized_value: normalizedValue, code }
      );
      return jsonResponse({ row: result.data });
    }

    if (body.action === "archive_catalog_value") {
      const id = cleanText(body.id);
      if (!id) return jsonResponse({ error: "Catalog value id is required." }, 400);
      requireBulkConfirmation(body, { action: "archive_catalog_value", label: "Catalog value archive", count: 1 });
      const current = await supabase
        .from("rateware_catalog_items")
        .select("id,source,category,raw_value,normalized_value,metadata,active")
        .eq("id", id)
        .maybeSingle();
      if (current.error) throw current.error;
      if (!current.data) return jsonResponse({ error: "Catalog value was not found." }, 404);
      if (current.data.source !== "rateware_manual_catalog") {
        return jsonResponse({ error: "Only manual catalog values can be archived from Admin Catalogs." }, 400);
      }
      if (!isManualCatalogOwnedBy(current.data, user)) {
        return jsonResponse({ error: "This manual catalog value belongs to another workspace." }, 403);
      }
      const result = await supabase
        .from("rateware_catalog_items")
        .update({ active: false, updated_at: new Date().toISOString() })
        .eq("id", id)
        .select("id,source,category,raw_value,normalized_value,code,metadata,active,updated_at")
        .single();
      if (result.error) throw result.error;
      await writeAuditLog(
        supabase,
        user,
        "catalog.value.archive",
        "rateware_catalog_items",
        id,
        `Archived ${current.data.category} catalog value "${current.data.normalized_value}"`,
        { category: current.data.category, raw_value: current.data.raw_value, normalized_value: current.data.normalized_value }
      );
      return jsonResponse({ row: result.data });
    }

    if (body.action === "list_location_catalog_values") {
      const country = cleanText(body.country)?.toUpperCase();
      const activeOnly = body.active === undefined ? true : cleanBoolean(body.active);
      const resolvedCountry = country && ["US", "CA", "MX", "UNKNOWN"].includes(country) ? country : null;
      const catalogRows = await fetchAllLocationCatalogRows(supabase, { country: resolvedCountry, activeOnly });

      const state = catalogKey(body.state || body.state_code || body.stateCode);
      const market = catalogKey(body.market);
      const region = catalogKey(body.region);
      const search = catalogKey(body.search);
      const rows = catalogRows
        .filter((item) => isManualCatalogOwnedBy(item, user))
        .filter((item) => {
          const stateKey = catalogKey([item.state_code, item.state_name].filter(Boolean).join(" "));
          const marketKey = catalogKey(item.market);
          const regionKey = catalogKey(item.region);
          const searchKey = catalogKey([
            item.raw_value,
            item.zip_prefix,
            item.city,
            item.state_code,
            item.state_name,
            item.metro_city,
            item.market,
            item.region,
            item.country
          ].filter(Boolean).join(" "));
          if (state && !stateKey.includes(state)) return false;
          if (market && !marketKey.includes(market)) return false;
          if (region && !regionKey.includes(region)) return false;
          if (search && !searchKey.includes(search)) return false;
          return true;
        })
        .slice(0, Math.min(Math.max(Number(body.limit) || 500, 1), 2000))
        .map((item) => ({
          ...item,
          is_manual: item.source === "rateware_manual_catalog",
          can_archive: item.source === "rateware_manual_catalog" && item.active === true
        }));
      return jsonResponse({ rows });
    }

    if (body.action === "save_location_catalog_value") {
      const input = objectRecord(body.location_value || body.location || body);
      const normalized = normalizeLocationCatalogInput(input, user);
      const result = await supabase
        .from("rateware_locations")
        .upsert(normalized.row, { onConflict: "source,location_key" })
        .select("id,source,country,location_key,raw_value,zip_prefix,city,state_code,state_name,metro_city,market,region,metadata,active,updated_at")
        .single();
      if (result.error) throw result.error;
      await writeAuditLog(
        supabase,
        user,
        "catalog.location.save",
        "rateware_locations",
        result.data.id,
        `Saved location catalog value "${normalized.summary.raw_value}"`,
        normalized.summary
      );
      return jsonResponse({ row: { ...result.data, is_manual: true, can_archive: true } });
    }

    if (body.action === "archive_location_catalog_value") {
      const id = cleanText(body.id);
      if (!id) return jsonResponse({ error: "Location catalog id is required." }, 400);
      requireBulkConfirmation(body, { action: "archive_location_catalog_value", label: "Location catalog archive", count: 1 });
      const current = await supabase
        .from("rateware_locations")
        .select("id,source,raw_value,metadata,active")
        .eq("id", id)
        .maybeSingle();
      if (current.error) throw current.error;
      if (!current.data) return jsonResponse({ error: "Location catalog value was not found." }, 404);
      if (current.data.source !== "rateware_manual_catalog") {
        return jsonResponse({ error: "Only manual location catalog values can be archived from Admin Catalogs." }, 400);
      }
      if (!isManualCatalogOwnedBy(current.data, user)) {
        return jsonResponse({ error: "This manual location belongs to another workspace." }, 403);
      }
      const result = await supabase
        .from("rateware_locations")
        .update({ active: false, updated_at: new Date().toISOString() })
        .eq("id", id)
        .select("id,source,country,location_key,raw_value,zip_prefix,city,state_code,state_name,metro_city,market,region,metadata,active,updated_at")
        .single();
      if (result.error) throw result.error;
      await writeAuditLog(
        supabase,
        user,
        "catalog.location.archive",
        "rateware_locations",
        id,
        `Archived location catalog value "${current.data.raw_value}"`,
        { raw_value: current.data.raw_value }
      );
      return jsonResponse({ row: result.data });
    }

    if (body.action === "bulk_import_catalog_values") {
      const result = await bulkImportCatalogValues(supabase, user, body);
      return jsonResponse(result);
    }

    if (body.action === "dashboard_summary") {
      // Rate-book health cutoffs. quote_date is a date column with an index,
      // so these stay cheap head-counts like the rest of the summary.
      const dayIso = (daysAgo: number) => new Date(Date.now() - daysAgo * 86400000).toISOString().slice(0, 10);
      const freshCutoff = dayIso(30);
      const agingCutoff = dayIso(60);
      const recentCutoff = new Date(Date.now() - 7 * 86400000).toISOString();

      const [uploads, vendors, sourcingVendors, procurementVendors, archivedVendors, pending, approved, failed, rfxEvents, rfxOpen, rfxBids, outreachMessages] = await Promise.all([
        supabase.from("raw_uploads").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).neq("status", "archived"),
        supabase.from("vendors").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email),
        supabase.from("vendors").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("base_stage", "sourcing"),
        supabase.from("vendors").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("base_stage", "procurement"),
        supabase.from("vendors").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("base_stage", "archived"),
        supabase.from("rate_staging").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("status", "pending_review"),
        supabase.from("rate_staging").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("status", "approved"),
        supabase.from("raw_uploads").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("status", "failed"),
        supabase.from("rfx_events").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).neq("status", "archived"),
        supabase.from("rfx_events").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("status", "open"),
        supabase.from("rfx_lane_vendors").select("id,rfx_events!inner(owner_email)", { count: "exact", head: true }).eq("rfx_events.owner_email", user.owner_email).in("invitation_status", ["quoted", "bid_submitted"]),
        supabase.from("outreach_messages").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).neq("status", "archived")
      ]);

      for (const result of [uploads, vendors, sourcingVendors, procurementVendors, archivedVendors, pending, approved, failed, rfxEvents, rfxOpen, rfxBids, outreachMessages]) {
        if (result.error) throw result.error;
      }

      const summary: Record<string, number> = {
        raw_uploads: uploads.count || 0,
        vendors: vendors.count || 0,
        sourcing_vendors: sourcingVendors.count || 0,
        procurement_vendors: procurementVendors.count || 0,
        archived_vendors: archivedVendors.count || 0,
        pending_review: pending.count || 0,
        approved_rows: approved.count || 0,
        failed_uploads: failed.count || 0,
        rfx_events: rfxEvents.count || 0,
        rfx_open_events: rfxOpen.count || 0,
        rfx_bids: rfxBids.count || 0,
        outreach_messages: outreachMessages.count || 0
      };

      // Rate-book health counts are best-effort: they scan wider than the
      // indexed status counts and can hit statement timeouts while the table
      // digests bulk updates. If they fail, return the core summary without
      // the freshness fields — the dashboard hides the health panel.
      try {
        const [freshRates, agingRates, staleRates, recentRates, locationGapRates] = await Promise.all([
          supabase.from("rate_staging").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("status", "approved").gte("quote_date", freshCutoff),
          supabase.from("rate_staging").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("status", "approved").gte("quote_date", agingCutoff).lt("quote_date", freshCutoff),
          supabase.from("rate_staging").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("status", "approved").or(`quote_date.lt.${agingCutoff},quote_date.is.null`),
          supabase.from("rate_staging").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("status", "approved").gte("created_at", recentCutoff),
          supabase.from("rate_staging").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("status", "approved").or("origin_market.is.null,destination_market.is.null")
        ]);
        const healthResults = [freshRates, agingRates, staleRates, recentRates, locationGapRates];
        if (!healthResults.some((result) => result.error)) {
          summary.fresh_rates = freshRates.count || 0;
          summary.aging_rates = agingRates.count || 0;
          summary.stale_rates = staleRates.count || 0;
          summary.recent_rates_7d = recentRates.count || 0;
          summary.location_gap_rates = locationGapRates.count || 0;
        }
      } catch {
        // best-effort: omit freshness fields
      }

      return jsonResponse(summary);
    }

    if (body.action === "book_audit") {
      // Read-only data-quality audit of the approved rate book. Returns issue
      // counts and (optionally) row ids per fixable issue class so batch
      // repairs (renormalize / vendor match) can be driven from the client.
      try {
      const includeIds = body.include_ids === true;
      const idCap = Math.min(Math.max(Number(body.id_cap) || 5000, 100), 20000);
      const approvedHead = () => supabase.from("rate_staging").select("id", { count: "exact", head: true }).eq("owner_email", user.owner_email).eq("status", "approved");

      const countQueries: Array<[string, () => PromiseLike<{ count: number | null; error: unknown }>]> = [
        ["approved_total", () => approvedHead()],
        ["staging_total_estimated", () => supabase.from("rate_staging").select("id", { count: "estimated", head: true }).eq("owner_email", user.owner_email)],
        ["market_gaps", () => approvedHead().or("origin_market.is.null,destination_market.is.null")],
        ["vendor_unmatched", () => approvedHead().is("vendor_id", null)],
        ["missing_quote_date", () => approvedHead().is("quote_date", null)],
        ["catalog_unmatched", () => approvedHead().eq("catalog_match_status", "unmatched")]
      ];
      const counts: Record<string, number> = {};
      for (const [key, build] of countQueries) {
        let result = await build();
        if (result.error) {
          // Transient pooler drops surface as empty-body errors on HEAD
          // counts; retry once before failing.
          await new Promise((resolve) => setTimeout(resolve, 350));
          result = await build();
        }
        if (result.error) {
          const meta = result as unknown as { status?: number; statusText?: string };
          const detail = JSON.stringify({ error: result.error, status: meta.status, statusText: meta.statusText }).slice(0, 300);
          return jsonResponse({ error: `book_audit count '${key}' failed: ${detail}` }, 500);
        }
        counts[key] = result.count || 0;
      }

      return jsonResponse({
        counts,
        include_ids: includeIds,
        id_cap: idCap
      });
      } catch (auditError) {
        const detail = auditError && typeof auditError === "object"
          ? JSON.stringify({ message: (auditError as Error).message, ...(auditError as Record<string, unknown>) }).slice(0, 500)
          : String(auditError);
        return jsonResponse({ error: `book_audit failed: ${detail}` }, 500);
      }
    }

    if (body.action === "list_vendor_unmatched_ids") {
      // Cursor-paged ids of approved rows without a linked vendor, for
      // driving match_rate_vendors in id batches (the filter RPC variant
      // exceeds statement timeouts on large books).
      const unmatchedCursor = cleanText(body.cursor) || "";
      const pageLimit = Math.min(Math.max(Number(body.limit) || 5000, 100), 10000);
        let unmatchedQuery = supabase
          .from("rate_staging")
          .select("id")
          .eq("owner_email", user.owner_email)
          .eq("status", "approved")
        .is("vendor_id", null)
        .order("id", { ascending: true })
        .limit(pageLimit);
      if (unmatchedCursor) unmatchedQuery = unmatchedQuery.gt("id", unmatchedCursor);
      const unmatchedResult = await unmatchedQuery;
      if (unmatchedResult.error) throw unmatchedResult.error;
      const unmatchedRows = unmatchedResult.data || [];
      return jsonResponse({
        ids: unmatchedRows.map((row) => String(row.id)),
        cursor: unmatchedRows.length ? String(unmatchedRows[unmatchedRows.length - 1].id) : unmatchedCursor,
        done: unmatchedRows.length < pageLimit
      });
    }

    if (body.action === "book_audit_scan") {
      // Incremental slice of the normalized-lane mismatch / market-gap scan.
      // Kept small per invocation to stay inside edge CPU limits; the client
      // loops with the returned cursor until done=true.
      const cursorStart = cleanText(body.cursor) || "";
      const maxPages = Math.min(Math.max(Number(body.max_pages) || 10, 1), 20);
      const pageSize = 1000;

      // Accent-folded, bidirectional containment: only flag rows where the
      // normalized city and the raw text share no token in either direction
      // (true corruption like raw "Laredo, TX" normalized to "Amarillo"),
      // not legitimate canonicalization ("Cd Juarez" -> "Ciudad Juárez").
      const fold = (value: unknown) =>
        String(value || "")
          .normalize("NFD")
          .replace(/[̀-ͯ]/g, "")
          .toLowerCase();
      const cityToken = (value: unknown) => fold(value).split(",")[0].replace(/\b[a-z]{2}\b\s*$/g, "").trim();
      const isMismatch = (raw: unknown, normalized: unknown) => {
        const token = cityToken(normalized);
        const rawFold = fold(raw);
        const rawCity = cityToken(raw);
        if (!token || token.length < 3 || !rawFold) return false;
        if (rawFold.includes(token)) return false;
        if (rawCity && rawCity.length >= 3 && token.includes(rawCity)) return false;
        return true;
      };

      let mismatchCount = 0;
      let zipGapCount = 0;
      let currencyGapCount = 0;
      let ratelessCount = 0;
      let scanned = 0;
      const mismatchIds: string[] = [];
      const marketGapIds: string[] = [];
      let cursor = cursorStart;
      let done = false;
      for (let page = 0; page < maxPages; page += 1) {
        let pageQuery = supabase
          .from("rate_staging")
          .select("id,origin,destination,normalized_origin,normalized_destination,origin_market,destination_market,origin_zip_prefix,destination_zip_prefix,currency,all_in_rate,mx_linehaul,us_linehaul")
          .eq("owner_email", user.owner_email)
          .eq("status", "approved")
          .order("id", { ascending: true })
          .limit(pageSize);
        if (cursor) pageQuery = pageQuery.gt("id", cursor);
        const pageResult = await pageQuery;
        if (pageResult.error) throw pageResult.error;
        const rows = pageResult.data || [];
        if (!rows.length) {
          done = true;
          break;
        }
        cursor = String(rows[rows.length - 1].id);
        scanned += rows.length;
        for (const row of rows) {
          if (isMismatch(row.origin, row.normalized_origin) || isMismatch(row.destination, row.normalized_destination)) {
            mismatchCount += 1;
            mismatchIds.push(String(row.id));
          }
          if (!row.origin_market || !row.destination_market) marketGapIds.push(String(row.id));
          if (!row.origin_zip_prefix || !row.destination_zip_prefix) zipGapCount += 1;
          const hasAnyRate = row.all_in_rate !== null || row.mx_linehaul !== null || row.us_linehaul !== null;
          if (!row.currency && row.all_in_rate !== null) currencyGapCount += 1;
          if (!hasAnyRate) ratelessCount += 1;
        }
        if (rows.length < pageSize) {
          done = true;
          break;
        }
      }

      return jsonResponse({
        scanned,
        mismatch_count: mismatchCount,
        zip_gap_count: zipGapCount,
        currency_gap_count: currencyGapCount,
        rateless_count: ratelessCount,
        mismatch_ids: mismatchIds,
        market_gap_ids: marketGapIds,
        cursor,
        done
      });
    }

    if (body.action === "list_uploads") {
      const requestedLimit = Number(body.limit);
      const limit = Number.isFinite(requestedLimit) && requestedLimit > 0
        ? Math.min(Math.floor(requestedLimit), 1000)
        : 1000;
      const offset = Math.max(Number(body.offset) || 0, 0);
      let query = supabase
        .from("raw_uploads")
        .select("*, vendors(vendor_name, domain, primary_email, base_stage, status)", { count: "exact" })
        .order("created_at", { ascending: false })
        .range(offset, offset + limit - 1);
      if (body.status === "current" || body.status === undefined) query = query.neq("status", "archived");
      else if (body.status) query = query.eq("status", body.status);
      const result = await query;
      if (result.error) throw result.error;
      const rows = result.data || [];
      const total = result.count || 0;
      return jsonResponse({ rows, total, limit, offset, has_more: offset + rows.length < total });
    }

    if (body.action === "list_upload_staged_rows") {
      const rawUploadId = cleanText(body.raw_upload_id);
      if (!rawUploadId) return jsonResponse({ error: "raw_upload_id is required." }, 400);
      const limit = Math.min(Math.max(Number(body.limit) || 500, 1), 1000);
      const offset = Math.max(Number(body.offset) || 0, 0);
      const result = await supabase
        .from("rate_staging")
        .select("id,row_id,status,vendor_domain,rfx_id,quote_date,origin,destination,equipment,trailer,operation,service,mx_linehaul,us_linehaul,fsc,fuel,border_crossing_fee,all_in_rate,currency,weekly_capacity,confidence,audit_flags,source_evidence,created_at", { count: "exact" })
        .eq("raw_upload_id", rawUploadId)
        .neq("status", "archived")
        .order("row_id", { ascending: true, nullsFirst: false })
        .order("created_at", { ascending: true })
        .range(offset, offset + limit - 1);
      if (result.error) throw result.error;
      const rows = result.data || [];
      const total = result.count || 0;
      return jsonResponse({ rows, total, limit, offset, has_more: offset + rows.length < total });
    }

    if (body.action === "bulk_import_upload_template") {
      const rawUploadId = cleanText(body.raw_upload_id);
      const result = await bulkImportStructuredUpload(
        supabase,
        user,
        rawUploadId || "",
        Array.isArray(body.template_rows) ? body.template_rows : [],
        Array.isArray(body.template_warnings) ? body.template_warnings : [],
        {
          replace_existing: body.replace_existing,
          expected_rate_rows: body.expected_rate_rows,
          batch_index: body.batch_index,
          batch_count: body.batch_count,
          imported_before: body.imported_before,
          skipped_before: body.skipped_before
        }
      );
      return jsonResponse(result);
    }

    if (body.action === "list_interpretation_memory") {
      const rawUploadId = cleanText(body.raw_upload_id);
      let upload: Record<string, unknown> | null = null;
      let vendor: Record<string, unknown> | null = null;

      if (rawUploadId) {
        const uploadResult = await supabase
          .from("raw_uploads")
          .select("id,vendor_id,vendor_hint,rfx_hint")
          .eq("id", rawUploadId)
          .single();
        if (uploadResult.error) throw uploadResult.error;
        upload = uploadResult.data || null;

        if (upload?.vendor_id) {
          const vendorResult = await supabase
            .from("vendors")
            .select("id,vendor_name,domain,primary_email")
            .eq("id", upload.vendor_id)
            .maybeSingle();
          if (vendorResult.error) throw vendorResult.error;
          vendor = vendorResult.data || null;
        }
      }

      const [globalResult, ownedResult] = await Promise.all([
        supabase
          .from("interpretation_memory")
          .select("*")
          .is("owner_email", null)
          .eq("active", true)
          .order("created_at", { ascending: true }),
        supabase
          .from("interpretation_memory")
          .select("*")
          .eq("owner_email", user.owner_email)
          .eq("active", true)
          .order("created_at", { ascending: false })
      ]);
      if (globalResult.error) throw globalResult.error;
      if (ownedResult.error) throw ownedResult.error;

      const vendorDomain = normalizeDomain(vendor?.domain || upload?.vendor_hint);
      const rfxHint = cleanText(upload?.rfx_hint || body.rfx_hint);
      const baseRows = [...(ownedResult.data || []), ...(globalResult.data || [])].filter((rule) => {
        if (!upload) return true;
        if (rule.scope === "global") return true;
        if (rule.scope === "upload") return rule.raw_upload_id === upload.id;
        if (rule.scope === "rfx") return cleanText(rule.rfx_hint) && cleanText(rule.rfx_hint) === rfxHint;
        if (rule.scope === "vendor") {
          if (rule.vendor_id && upload.vendor_id && rule.vendor_id === upload.vendor_id) return true;
          const ruleDomain = normalizeDomain(rule.vendor_domain);
          return Boolean(ruleDomain && vendorDomain && ruleDomain === vendorDomain);
        }
        return false;
      });

      const usedRuleIds = baseRows.map((rule) => rule.id).filter(Boolean);
      const uploadAuditResult = usedRuleIds.length
        ? await supabase
            .from("raw_uploads")
            .select("id,status,created_at,interpreted_at,interpreted_rate_rows,expected_rate_rows,audit_status,audit_warnings,interpretation_audit")
            .not("interpretation_audit", "is", null)
            .order("interpreted_at", { ascending: false })
            .limit(500)
        : { data: [], error: null };
      if (uploadAuditResult.error) throw uploadAuditResult.error;

      const rows = baseRows.map((rule) => {
        const effectiveness = memoryEffectivenessSummary(rule, uploadAuditResult.data || []);
        const conflicts = memoryConflictSignals(rule, baseRows);
        return {
          ...rule,
          effectiveness,
          conflicts,
          recommendation: memoryRecommendation(rule, effectiveness, conflicts)
        };
      });
      return jsonResponse({ rows, upload, vendor });
    }

    if (body.action === "list_interpretation_memory_audit") {
      const memoryId = cleanText(body.id);
      let query = supabase
        .from("saas_audit_log")
        .select("*")
        .eq("owner_email", user.owner_email)
        .eq("entity_type", "interpretation_memory")
        .order("created_at", { ascending: false })
        .limit(Math.min(Math.max(Number(body.limit) || 80, 1), 250));
      if (memoryId) query = query.ilike("entity_id", `%${memoryId}%`);
      const result = await query;
      if (result.error) throw result.error;
      return jsonResponse({ rows: result.data || [] });
    }

    if (body.action === "create_interpretation_memory") {
      const instruction = cleanText(body.instruction);
      if (!instruction) return jsonResponse({ error: "Instruction is required." }, 400);
      const scope = ["global", "vendor", "rfx", "upload"].includes(String(body.scope || "")) ? String(body.scope) : "global";
      let upload: Record<string, unknown> | null = null;
      let vendor: Record<string, unknown> | null = null;

      if (body.raw_upload_id) {
        const uploadResult = await supabase
          .from("raw_uploads")
          .select("id,vendor_id,vendor_hint,rfx_hint")
          .eq("id", body.raw_upload_id)
          .maybeSingle();
        if (uploadResult.error) throw uploadResult.error;
        upload = uploadResult.data || null;
        if (upload?.vendor_id) {
          const vendorResult = await supabase
            .from("vendors")
            .select("id,domain")
            .eq("id", upload.vendor_id)
            .maybeSingle();
          if (vendorResult.error) throw vendorResult.error;
          vendor = vendorResult.data || null;
        }
      }

      const row = withOwner({
        scope,
        vendor_id: scope === "vendor" ? upload?.vendor_id || null : null,
        vendor_domain: scope === "vendor" ? normalizeDomain(vendor?.domain || upload?.vendor_hint || body.vendor_domain) : null,
        rfx_hint: scope === "rfx" ? cleanText(upload?.rfx_hint || body.rfx_hint) : null,
        raw_upload_id: scope === "upload" ? cleanText(upload?.id || body.raw_upload_id) : null,
        title: cleanText(body.title) || `${scope} interpretation rule`,
        instruction,
        active: true
      }, user);
      const result = await supabase.from("interpretation_memory").insert(row).select().single();
      if (result.error) throw result.error;
      await writeAuditLog(supabase, user, "create", "interpretation_memory", result.data.id, `Created ${scope} interpretation memory rule`, {
        scope,
        raw_upload_id: body.raw_upload_id || null
      });
      return jsonResponse({ row: result.data });
    }

    if (body.action === "simulate_interpretation_memory") {
      let rule: Record<string, unknown> | null = null;
      if (body.id) {
        const result = await supabase
          .from("interpretation_memory")
          .select("*")
          .eq("id", body.id)
          .or(`owner_email.eq.${user.owner_email},owner_email.is.null`)
          .maybeSingle();
        if (result.error) throw result.error;
        rule = result.data || null;
      } else {
        rule = {
          scope: ["global", "vendor", "rfx", "upload"].includes(String(body.scope || "")) ? String(body.scope) : "global",
          vendor_domain: normalizeDomain(body.vendor_domain),
          rfx_hint: cleanText(body.rfx_hint),
          raw_upload_id: cleanText(body.raw_upload_id),
          title: cleanText(body.title) || "Draft rule",
          instruction: cleanText(body.instruction) || ""
        };
      }
      if (!rule) return jsonResponse({ error: "Memory rule not found." }, 404);

      const uploadsResult = await supabase
        .from("raw_uploads")
        .select("id,original_filename,status,created_at,interpreted_at,vendor_id,vendor_hint,rfx_hint,document_type,interpreted_rate_rows,expected_rate_rows,audit_status,audit_warnings,vendors(vendor_name,domain)")
        .neq("status", "archived")
        .order("created_at", { ascending: false })
        .limit(500);
      if (uploadsResult.error) throw uploadsResult.error;

      const matches = (uploadsResult.data || []).filter((upload) => memoryRuleMatchesUpload(rule!, upload));
      const warningCount = matches.reduce((sum, upload) => sum + (Array.isArray(upload.audit_warnings) ? upload.audit_warnings.length : 0), 0);
      const stagedRows = matches.reduce((sum, upload) => sum + (Number(upload.interpreted_rate_rows || 0) || 0), 0);
      const expectedRows = matches.reduce((sum, upload) => sum + (Number(upload.expected_rate_rows || upload.interpreted_rate_rows || 0) || 0), 0);
      return jsonResponse({
        rule,
        impact: {
          upload_count: matches.length,
          staged_rows: stagedRows,
          expected_rows: expectedRows,
          warning_count: warningCount,
          failed_count: matches.filter((upload) => upload.status === "failed" || upload.audit_status === "failed").length,
          current_scope: rule.scope
        },
        rows: matches.slice(0, 25).map((upload) => {
          const vendorRelation = Array.isArray(upload.vendors) ? upload.vendors[0] : upload.vendors;
          const vendor = objectRecord(vendorRelation);
          return {
            id: upload.id,
            filename: upload.original_filename,
            status: upload.status,
            vendor: vendor.vendor_name || upload.vendor_hint || "",
            vendor_domain: vendor.domain || upload.vendor_hint || "",
            rfx_hint: upload.rfx_hint,
            document_type: upload.document_type,
            interpreted_rate_rows: upload.interpreted_rate_rows,
            expected_rate_rows: upload.expected_rate_rows,
            audit_status: upload.audit_status,
            created_at: upload.created_at
          };
        })
      });
    }

    if (body.action === "update_interpretation_memory") {
      const id = cleanText(body.id);
      if (!id) return jsonResponse({ error: "Memory rule id is required." }, 400);
      const patchInput = objectRecord(body.patch);
      const patch: Record<string, unknown> = { updated_at: new Date().toISOString() };
      if (patchInput.title !== undefined) patch.title = cleanText(patchInput.title) || "Interpretation rule";
      if (patchInput.instruction !== undefined) {
        const instruction = cleanText(patchInput.instruction);
        if (!instruction) return jsonResponse({ error: "Instruction is required." }, 400);
        patch.instruction = instruction;
      }
      if (patchInput.active !== undefined) patch.active = Boolean(patchInput.active);
      if (patchInput.scope !== undefined && ["global", "vendor", "rfx", "upload"].includes(String(patchInput.scope))) {
        patch.scope = String(patchInput.scope);
        if (patch.scope === "global") {
          patch.vendor_id = null;
          patch.vendor_domain = null;
          patch.rfx_hint = null;
          patch.raw_upload_id = null;
        }
      }

      const currentResult = await supabase
        .from("interpretation_memory")
        .select("id,scope,title,vendor_domain,rfx_hint,raw_upload_id")
        .eq("id", id)
        .eq("owner_email", user.owner_email)
        .maybeSingle();
      if (currentResult.error) throw currentResult.error;
      if (!currentResult.data) return jsonResponse({ error: "Memory rule not found." }, 404);

      const result = await supabase
        .from("interpretation_memory")
        .update(patch)
        .eq("id", id)
        .eq("owner_email", user.owner_email)
        .select()
        .single();
      if (result.error) throw result.error;
      const promotedToGlobal = currentResult.data.scope !== "global" && result.data.scope === "global";
      await writeAuditLog(
        supabase,
        user,
        promotedToGlobal ? "promote" : "update",
        "interpretation_memory",
        id,
        promotedToGlobal ? "Promoted interpretation memory rule to global" : "Updated interpretation memory rule",
        {
          prior_scope: currentResult.data.scope,
          next_scope: result.data.scope,
          changed_fields: Object.keys(patch).filter((key) => key !== "updated_at")
        }
      );
      return jsonResponse({ row: result.data });
    }

    if (body.action === "archive_interpretation_memory") {
      const ids = normalizeBulkIds(Array.isArray(body.ids) ? body.ids : [body.id], {
        label: "Interpretation memory ids",
        limit: 250
      });
      if (!ids.length) return jsonResponse({ updated: 0, rows: [] });
      requireBulkConfirmation(body, { action: "archive_interpretation_memory", label: "Interpretation memory archive", count: ids.length });
      const result = await supabase
        .from("interpretation_memory")
        .update({ active: false, updated_at: new Date().toISOString() })
        .eq("owner_email", user.owner_email)
        .in("id", ids)
        .select();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "archive", "interpretation_memory", ids.join(","), `Archived ${result.data?.length || 0} interpretation memory rule(s)`, {
        ids,
        archived_count: result.data?.length || 0
      });
      return jsonResponse({ updated: result.data?.length || 0, rows: result.data || [] });
    }

    if (body.action === "archive_upload") {
      if (!body.id) return jsonResponse({ error: "Upload id is required." }, 400);
      requireBulkConfirmation(body, { action: "archive_upload", label: "Upload archive", count: 1 });
      const result = await supabase
        .from("raw_uploads")
        .update({ status: "archived" })
        .eq("id", body.id)
        .eq("owner_email", user.owner_email)
        .select("*, vendors(vendor_name, domain)")
        .single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "upload.archive", "raw_uploads", result.data.id,
        `Archived upload ${cleanText(result.data.original_filename) || result.data.id}`);
      return jsonResponse({ row: result.data });
    }

    if (body.action === "get_upload_source_url") {
      if (!body.id) return jsonResponse({ error: "Upload id is required." }, 400);
      const upload = await supabase
        .from("raw_uploads")
        .select("id,original_filename,storage_bucket,storage_path,mime_type")
        .eq("id", body.id)
        .eq("owner_email", user.owner_email)
        .single();
      if (upload.error) throw upload.error;
      if (!upload.data?.storage_bucket || !upload.data?.storage_path) {
        return jsonResponse({ error: "Source file is missing from storage." }, 404);
      }

      const signed = await supabase.storage
        .from(upload.data.storage_bucket)
        .createSignedUrl(upload.data.storage_path, 60 * 10, {
          download: upload.data.original_filename || undefined
        });
      if (signed.error) throw signed.error;
      return jsonResponse({
        url: signed.data.signedUrl,
        expires_in_seconds: 600,
        filename: upload.data.original_filename,
        mime_type: upload.data.mime_type
      });
    }

    if (body.action === "remove_upload") {
      if (!body.id) return jsonResponse({ error: "Upload id is required." }, 400);
      requireBulkConfirmation(body, { action: "remove_upload", label: "Upload removal", count: 1 });
      const upload = await supabase
        .from("raw_uploads")
        .select("id,original_filename,storage_bucket,storage_path")
        .eq("id", body.id)
        .eq("owner_email", user.owner_email)
        .single();
      if (upload.error) throw upload.error;

      if (upload.data?.storage_bucket && upload.data?.storage_path) {
        const storage = await supabase.storage.from(upload.data.storage_bucket).remove([upload.data.storage_path]);
        if (storage.error) throw storage.error;
      }

      const result = await supabase.from("raw_uploads").delete().eq("id", body.id).eq("owner_email", user.owner_email).select("id").single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "upload.remove", "raw_uploads", result.data.id,
        `Removed upload ${cleanText(upload.data.original_filename) || result.data.id}`, { storage_removed: Boolean(upload.data.storage_path) });
      return jsonResponse({ removed: result.data });
    }

    if (body.action === "list_staging") {
      const limit = Math.min(Math.max(Number(body.limit) || 500, 1), 1000);
      const offset = Math.max(Number(body.offset) || 0, 0);
      const search = (cleanText(body.search) || "").replace(/[(),]/g, " ").trim();
      const columnFilters = objectRecord(body.column_filters);
      const reviewFilter = cleanText(body.review_filter) || "all";
      const usesGlobalFilters = Object.keys(columnFilters).length > 0 || reviewFilter !== "all";
      const filterPayload = {
        mode: "staging",
        status: cleanText(body.status),
        raw_upload_id: cleanText(body.raw_upload_id),
        search,
        review_filter: reviewFilter,
        column_filters: columnFilters
      };

      if (usesGlobalFilters && !canUseSqlRateFilters(filterPayload)) {
        const filtered = await fetchRateRowIdsByFilter(supabase, filterPayload, {
          limit,
          offset,
          ownerEmail: user.owner_email
        });
        const rows = await fetchRateRowsForIds(supabase, filtered.ids, RATE_ROW_LIST_SELECT, user.owner_email);

        return jsonResponse({
          rows,
          total: filtered.database_count,
          database_count: filtered.database_count,
          limit,
          offset,
          has_more: offset + rows.length < filtered.database_count,
          hard_limit_reached: filtered.hard_limit_reached
        });
      }

      let query = supabase
        .from("rate_staging")
        .select(RATE_ROW_LIST_SELECT, { count: "exact" })
        .eq("owner_email", user.owner_email)
        .order("created_at", { ascending: false })
        .order("id", { ascending: false })
        .range(offset, offset + limit - 1);
      query = applySqlRateFilters(query, filterPayload);
      const result = await query;
      if (result.error) throw result.error;
      const rows = result.data || [];
      const total = result.count || 0;
      return jsonResponse({
        rows,
        total,
        limit,
        offset,
        has_more: offset + rows.length < total
      });
    }

    if (body.action === "list_staging_filter_values") {
      const field = cleanText(body.field);
      if (!field) return jsonResponse({ error: "Filter field is required." }, 400);
      const limit = Math.min(Math.max(Number(body.limit) || 5000, 1), 5000);
      const valueSearch = cleanText(body.value_search)?.toLowerCase() || "";
      const columnFilters = objectRecord(body.column_filters);
      delete columnFilters[field];
      const filterPayload = {
        mode: "staging",
        status: cleanText(body.status),
        raw_upload_id: cleanText(body.raw_upload_id),
        search: (cleanText(body.search) || "").replace(/[(),]/g, " ").trim(),
        review_filter: cleanText(body.review_filter) || "all",
        column_filters: columnFilters
      };

      const sqlValues = await fetchSqlRateFilterValues(supabase, filterPayload, field, valueSearch, limit, user.owner_email);
      if (sqlValues) return jsonResponse(sqlValues);

      return jsonResponse(await fetchRateFilterValuesByRpc(supabase, filterPayload, field, valueSearch, limit, user.owner_email));
    }

    if (body.action === "list_rateware") {
      const limit = Math.min(Math.max(Number(body.limit) || 500, 1), 1000);
      const offset = Math.max(Number(body.offset) || 0, 0);
      const search = (cleanText(body.search) || "").replace(/[(),]/g, " ").trim();
      const quickFilter = cleanText(body.quick_filter) || "all";
      const columnFilters = objectRecord(body.column_filters);
      const filterPayload = {
        mode: "rateware",
        search,
        operation: cleanText(body.operation),
        service: cleanText(body.service),
        quick_filter: quickFilter,
        column_filters: columnFilters
      };
      const usesGlobalFilters = hasActiveRatewareFilters(filterPayload);

      if (usesGlobalFilters) {
        try {
          const filtered = await fetchRateRowIdsByFilter(supabase, filterPayload, {
            limit,
            offset,
            ownerEmail: user.owner_email
          });
          const rows = await fetchRateRowsForIds(supabase, filtered.ids, RATE_ROW_LIST_SELECT, user.owner_email);

          return jsonResponse({
            rows,
            total: filtered.database_count,
            database_count: filtered.database_count,
            limit,
            offset,
            has_more: offset + rows.length < filtered.database_count,
            hard_limit_reached: filtered.hard_limit_reached
          });
        } catch (error) {
          console.warn("rateware list RPC failed; attempting SQL fallback", {
            message: safeOperationalError(error)
          });
          if (canUseSqlRateFilters(filterPayload)) {
            return jsonResponse(await fetchRatewareRowsBySql(supabase, filterPayload, limit, offset, user.owner_email));
          }
          throw error;
        }
      }

      return jsonResponse(await fetchRatewareRowsBySql(supabase, filterPayload, limit, offset, user.owner_email));
    }

    if (body.action === "list_rateware_filter_values") {
      const field = cleanText(body.field);
      if (!field) return jsonResponse({ error: "Filter field is required." }, 400);
      const limit = Math.min(Math.max(Number(body.limit) || 5000, 1), 5000);
      const valueSearch = cleanText(body.value_search)?.toLowerCase() || "";
      const columnFilters = objectRecord(body.column_filters);
      delete columnFilters[field];
      const filterPayload = {
        mode: "rateware",
        search: (cleanText(body.search) || "").replace(/[(),]/g, " ").trim(),
        operation: cleanText(body.operation),
        service: cleanText(body.service),
        quick_filter: cleanText(body.quick_filter) || "all",
        column_filters: columnFilters
      };

      const sqlValues = await fetchSqlRateFilterValues(supabase, filterPayload, field, valueSearch, limit, user.owner_email);
      if (sqlValues) return jsonResponse(sqlValues);

      try {
        return jsonResponse(await fetchRateFilterValuesByRpc(supabase, filterPayload, field, valueSearch, limit, user.owner_email));
      } catch (error) {
        console.warn("rateware filter values RPC failed; using SQL fallback", {
          field,
          message: safeOperationalError(error)
        });
        throw error;
      }
    }

    if (body.action === "list_rateware_audit") {
      const rateId = cleanText(body.id);
      let query = supabase
        .from("saas_audit_log")
        .select("*")
        .eq("owner_email", user.owner_email)
        .eq("entity_type", "rate_staging")
        .order("created_at", { ascending: false })
        .limit(Math.min(Math.max(Number(body.limit) || 80, 1), 250));
      if (rateId) query = query.ilike("entity_id", `%${rateId}%`);
      const result = await query;
      if (result.error) throw result.error;
      return jsonResponse({ rows: result.data || [] });
    }

    if (body.action === "get_rate_row_detail") {
      const rateId = cleanText(body.id);
      if (!rateId) return jsonResponse({ error: "Rate row id is required." }, 400);
      let query = supabase
        .from("rate_staging")
        .select(RATE_ROW_RESPONSE_WITH_LEGS_SELECT)
        .eq("id", rateId)
        .eq("owner_email", user.owner_email);
      const status = cleanText(body.status);
      if (status) query = query.eq("status", status);
      const result = await query.single();
      if (result.error) throw result.error;
      return jsonResponse({ row: result.data });
    }

    if (body.action === "bulk_update_rateware") {
      const ids = normalizeBulkIds(body.ids, { label: "Approved rate ids", limit: BULK_SELECTED_ID_LIMIT });
      if (!ids.length) return jsonResponse({ error: "At least one approved rate id is required." }, 400);
      if (ids.length >= 100) {
        requireBulkConfirmation(body, {
          action: "bulk_update_rateware",
          label: "Rateware selected bulk update",
          count: ids.length,
          threshold: 100
        });
      }

      const currentRows = (await fetchRateRowsForIds(
        supabase,
        ids,
        "id,trailer,hazmat,temperature_controlled,status,vendor_id,vendor_domain",
        user.owner_email
      )).filter((row) => cleanText(row.status) === "approved");

      const updatedRows: Record<string, unknown>[] = [];
      for (const current of currentRows) {
        const patchInput = objectRecord(body.patch);
        const currentRow = objectRecord(current);
        const patch = normalizeStagingPatch(patchInput, currentRow);
        Object.assign(patch, await vendorLinkPatch(supabase, user, patchInput, currentRow));
        delete patch.status;
        if (!Object.keys(patch).length) continue;

        const result = await supabase
          .from("rate_staging")
          .update(patch)
          .eq("id", current.id)
          .eq("owner_email", user.owner_email)
          .eq("status", "approved")
          .select("*, vendors(vendor_name, domain, primary_email, base_stage, status)")
          .single();
        if (result.error) throw result.error;
        updatedRows.push(result.data);
      }

      if (updatedRows.length) {
        await tryWriteAuditLog(supabase, user, "rateware.bulk_update", "rate_staging", updatedRows.map((row) => row.id).join(","), `Bulk updated ${updatedRows.length} approved Rateware row(s)`, {
          ids: updatedRows.map((row) => row.id),
          changed_fields: Object.keys(body.patch || {})
        });
      }
      return jsonResponse({ updated: updatedRows.length, rows: updatedRows });
    }

    if (body.action === "list_rateware_rows_by_ids") {
      const ids = normalizeBulkIds(body.ids, { label: "Approved rate ids", limit: BULK_SELECTED_ID_LIMIT });
      if (!ids.length) return jsonResponse({ rows: [] });
      const rows = (await fetchRateRowsForIds(
        supabase,
        ids,
        RATE_ROW_LIST_SELECT,
        user.owner_email
      )).filter((row) => cleanText(row.status) === "approved");
      return jsonResponse({ rows });
    }

    if (body.action === "list_rateware_versions") {
      let query = supabase
        .from("rateware_book_versions")
        .select("id,created_at,owner_email,name,description,filter_summary,row_count")
        .order("created_at", { ascending: false })
        .limit(20);
      if (user.owner_email) query = query.eq("owner_email", user.owner_email);
      const result = await query;
      if (result.error) throw result.error;
      return jsonResponse({ rows: result.data || [] });
    }

    if (body.action === "get_rateware_version") {
      const id = cleanText(body.id);
      if (!id) return jsonResponse({ error: "Rateware version id is required." }, 400);
      let query = supabase
        .from("rateware_book_versions")
        .select("*")
        .eq("id", id)
        .single();
      const result = await query;
      if (result.error) throw result.error;
      if (user.owner_email && result.data?.owner_email !== user.owner_email) {
        return jsonResponse({ error: "Rateware version not found." }, 404);
      }
      return jsonResponse({ version: result.data });
    }

    if (body.action === "create_rateware_version") {
      const ids = normalizeBulkIds(body.ids, { label: "Approved rate ids", limit: 1000 });
      const filters = objectRecord(body.filters);
      let rows: Record<string, unknown>[] = [];

      if (ids.length) {
        let query = supabase
          .from("rate_staging")
          .select("*, vendors(vendor_name, domain, primary_email, base_stage, status)")
          .eq("owner_email", user.owner_email)
          .eq("status", "approved")
          .order("quote_date", { ascending: false, nullsFirst: false })
          .order("created_at", { ascending: false })
          .limit(1000);
        query = query.in("id", ids);
        const rowsResult = await query;
        if (rowsResult.error) throw rowsResult.error;
        rows = rowsResult.data || [];
      } else if (Object.keys(filters).length) {
        const filtered = await fetchRateRowIdsByFilter(
          supabase,
          { ...filters, mode: "rateware" },
          { limit: 50000, ownerEmail: user.owner_email }
        );
        rows = await fetchRateRowsForIds(
          supabase,
          filtered.ids,
          "*, vendors(vendor_name, domain, primary_email, base_stage, status)",
          user.owner_email
        );
      } else {
        const rowsResult = await supabase
          .from("rate_staging")
          .select("*, vendors(vendor_name, domain, primary_email, base_stage, status)")
          .eq("owner_email", user.owner_email)
          .eq("status", "approved")
          .order("quote_date", { ascending: false, nullsFirst: false })
          .order("created_at", { ascending: false })
          .limit(1000);
        if (rowsResult.error) throw rowsResult.error;
        rows = rowsResult.data || [];
      }
      if (!rows.length) return jsonResponse({ error: "No approved Rateware rows found for this version." }, 400);

      const name = cleanText(body.name) || `Rateware ${new Date().toISOString().slice(0, 10)}`;
      const description = cleanText(body.description);
      const filterSummary = typeof body.filter_summary === "object" && body.filter_summary !== null ? body.filter_summary : {};
      const version = withOwner({
        name,
        description,
        filter_summary: filterSummary,
        row_count: rows.length,
        rows_snapshot: rows
      }, user);

      const result = await supabase
        .from("rateware_book_versions")
        .insert(version)
        .select("id,created_at,owner_email,name,description,filter_summary,row_count")
        .single();
      if (result.error) throw result.error;
      await writeAuditLog(supabase, user, "rateware.snapshot", "rate_staging", rows.map((row) => row.id).join(","), `Created Rateware snapshot "${name}"`, {
        version_id: result.data.id,
        row_count: rows.length,
        name
      });
      return jsonResponse({ version: result.data });
    }

    if (body.action === "renormalize_rate_rows") {
      const ids = normalizeBulkIds(body.ids, { label: "Rate row ids", limit: BULK_SELECTED_ID_LIMIT });
      requireBulkConfirmation(body, { action: "renormalize_rate_rows", label: "Rate row normalization", count: ids.length });
      const status = cleanText(body.status);
      const rows = await renormalizeRateRows(supabase, user.owner_email, ids, status);
      await tryWriteAuditLog(supabase, user, "rateware.bulk_renormalize", "rate_staging", ids.slice(0, 50).join(","),
        `Renormalized ${rows.length} rate row(s)`, { requested: ids.length, affected: rows.length });
      return jsonResponse({ updated: rows.length, rows });
    }

    if (body.action === "match_rate_vendors") {
      const ids = normalizeBulkIds(body.ids, { label: "Rate row ids", limit: BULK_SELECTED_ID_LIMIT });
      requireBulkConfirmation(body, { action: "match_rate_vendors", label: "Rate vendor match", count: ids.length });
      const status = cleanText(body.status);
      const result = await matchRateVendorRows(supabase, user, ids, status);
      await tryWriteAuditLog(supabase, user, "rateware.bulk_match_vendors", "rate_staging", ids.slice(0, 50).join(","),
        `Matched vendors on ${result.updated || 0} rate row(s)`, { requested: ids.length, affected: result.updated || 0 });
      return jsonResponse(result);
    }

    if (body.action === "match_rate_vendors_by_filter") {
      const filters = objectRecord(body.filters);
      const dryRun = body.dry_run === true;
      const maxRows = normalizeBulkMaxRows(body.max_rows);
      const mode = cleanText(filters.mode) === "rateware" ? "rateware" : "staging";
      if (!dryRun) {
        const preview = await fetchRateRowIdsByFilter(supabase, filters, { limit: 1, ownerEmail: user.owner_email });
        requirePreviewCountForFilteredBulk(body, preview.database_count || 0, `${mode} filtered vendor match`);
      }
      const result = await matchRateVendorRowsByFilter(supabase, user, filters, { dryRun, maxRows });

      if (!dryRun && result.updated) {
        await tryWriteAuditLog(
          supabase,
          user,
          `${mode}.bulk_match_vendors_filtered`,
          "rate_staging",
          result.rows.map((row) => cleanText(row.id)).filter(Boolean).slice(0, 50).join(","),
          `Matched vendors for ${result.updated} ${mode} row(s) using active filters`,
          {
            matched_count: result.matched,
            candidates_count: result.candidates,
            matchable_count: result.matchable,
            updated_count: result.updated,
            filters,
            hard_limit_reached: result.hard_limit_reached
          }
        );
      }

      return jsonResponse(result);
    }

    if (body.action === "enrich_missing_location_zips") {
      const ids = normalizeBulkIds(body.ids, { label: "Rate row ids", limit: 250 });
      requireBulkConfirmation(body, { action: "enrich_missing_location_zips", label: "Location ZIP enrichment", count: ids.length });
      const status = cleanText(body.status);
      const result = await enrichMissingLocationZips(supabase, user.owner_email, ids, status);
      await tryWriteAuditLog(supabase, user, "rateware.bulk_enrich_locations", "rate_staging", ids.slice(0, 50).join(","),
        `Enriched locations on ${result.rows.length} rate row(s)`, { requested: ids.length, affected: result.rows.length, enriched_fields: result.enriched });
      return jsonResponse({ updated: result.rows.length, enriched: result.enriched, rows: result.rows });
    }

    if (body.action === "update_rateware") {
      if (!body.id) return jsonResponse({ error: "Approved rate id is required." }, 400);
      const currentResult = await supabase
        .from("rate_staging")
        .select("trailer,hazmat,temperature_controlled,status,vendor_id,vendor_domain")
        .eq("id", body.id)
        .eq("owner_email", user.owner_email)
        .eq("status", "approved")
        .single();
      if (currentResult.error) throw currentResult.error;

      const patchInput = objectRecord(body.patch);
      const currentRow = objectRecord(currentResult.data);
      const patch = normalizeStagingPatch(patchInput, currentRow);
      Object.assign(patch, await vendorLinkPatch(supabase, user, patchInput, currentRow));
      delete patch.status;
      if (!Object.keys(patch).length) return jsonResponse({ error: "No approved rate updates provided." }, 400);

      const result = await supabase
        .from("rate_staging")
        .update(patch)
        .eq("id", body.id)
        .eq("owner_email", user.owner_email)
        .eq("status", "approved")
        .select("*, vendors(vendor_name, domain, primary_email, base_stage, status)")
        .single();
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "rateware.update", "rate_staging", body.id, "Updated approved Rateware row", {
        changed_fields: Object.keys(patch)
      });
      return jsonResponse({ row: result.data });
    }

    if (body.action === "return_rateware_to_staging") {
      const ids = normalizeBulkIds(body.ids, { label: "Approved rate ids", limit: BULK_SELECTED_ID_LIMIT });
      if (!ids.length) return jsonResponse({ error: "At least one approved rate id is required." }, 400);
      requireBulkConfirmation(body, {
        action: "return_rateware_to_staging",
        label: "Return approved rates to staging",
        count: ids.length
      });
      const reason = cleanText(body.reason) || "Needs correction or re-review from Rateware Final";
      const returnedNote = `Returned to staging ${new Date().toISOString().slice(0, 10)}: ${reason}`;

      const currentResult = await supabase
        .from("rate_staging")
        .select("id,notes")
        .eq("owner_email", user.owner_email)
        .in("id", ids)
        .eq("status", "approved");
      if (currentResult.error) throw currentResult.error;

      const updatedRows: Record<string, unknown>[] = [];
      for (const current of currentResult.data || []) {
        const notes = [cleanText(current.notes), returnedNote].filter(Boolean).join(" | ");
        const result = await supabase
          .from("rate_staging")
          .update({ status: "pending_review", notes })
          .eq("id", current.id)
          .eq("owner_email", user.owner_email)
          .eq("status", "approved")
          .select("id");
        if (result.error) throw result.error;
        updatedRows.push(...(result.data || []));
      }

      if (updatedRows.length) {
        await tryWriteAuditLog(supabase, user, "rateware.return_to_staging", "rate_staging", updatedRows.map((row) => row.id).join(","), `Returned ${updatedRows.length} approved Rateware row(s) to staging`, {
          ids: updatedRows.map((row) => row.id),
          reason
        });
      }
      return jsonResponse({ updated: updatedRows.length, rows: updatedRows, reason });
    }

    if (body.action === "bulk_rate_rows_by_filter") {
      const filters = objectRecord(body.filters);
      const targetAction = cleanText(body.target_action);
      const dryRun = body.dry_run === true;
      const maxRows = normalizeBulkMaxRows(body.max_rows);
      if (!["archive", "remove"].includes(targetAction || "")) {
        return jsonResponse({ error: "Bulk target action must be archive or remove." }, 400);
      }
      const actionFilters = {
        ...filters,
        exclude_archived: targetAction === "archive"
      };
      if (!dryRun) {
        const preview = await fetchRateRowIdsByFilter(supabase, actionFilters, { limit: 1, ownerEmail: user.owner_email });
        requirePreviewCountForFilteredBulk(body, preview.database_count || 0, `${targetAction} filtered rate rows`);
      }
      const filtered = dryRun
        ? await fetchRateRowIdsByFilter(supabase, actionFilters, { limit: 1, ownerEmail: user.owner_email })
        : await collectRateRowIdsByFilter(supabase, actionFilters, { maxRows, ownerEmail: user.owner_email });
      const ids = filtered.ids;
      if (dryRun) {
        return jsonResponse({
          action: targetAction,
          matched: filtered.database_count || ids.length,
          database_count: filtered.database_count,
          hard_limit_reached: false,
          max_rows: maxRows
        });
      }
      if (!ids.length) {
        return jsonResponse({
          action: targetAction,
          matched: 0,
          targeted: 0,
          updated: 0,
          removed: 0,
          remaining: 0,
          completed: true,
          rows: []
        });
      }

      let affected = 0;
      for (const chunk of chunkValues(ids, 500)) {
        const result = targetAction === "archive"
          ? await supabase.from("rate_staging").update({ status: "archived" }).eq("owner_email", user.owner_email).in("id", chunk).select("id")
          : await supabase.from("rate_staging").delete().eq("owner_email", user.owner_email).in("id", chunk).select("id");
        if (result.error) throw result.error;
        affected += result.data?.length || 0;
      }

      const mode = cleanText(filters.mode) === "rateware" ? "rateware" : "staging";
      await tryWriteAuditLog(
        supabase,
        user,
        `${mode}.bulk_${targetAction}_filtered`,
        "rate_staging",
        ids.slice(0, 50).join(","),
        `${targetAction === "archive" ? "Archived" : "Removed"} ${affected} ${mode} row(s) using active filters`,
        {
          ids_count: ids.length,
          database_count: filtered.database_count,
          filters: actionFilters,
          hard_limit_reached: filtered.hard_limit_reached
        }
      );

      return jsonResponse({
        action: targetAction,
        matched: filtered.database_count || ids.length,
        targeted: ids.length,
        updated: targetAction === "archive" ? affected : 0,
        removed: targetAction === "remove" ? affected : 0,
        remaining: Math.max(0, (filtered.database_count || ids.length) - ids.length),
        completed: ids.length >= (filtered.database_count || ids.length),
        max_rows: maxRows,
        hard_limit_reached: filtered.hard_limit_reached
      });
    }

    if (body.action === "bulk_update_rate_rows_by_filter") {
      const filters = objectRecord(body.filters);
      const patchInput = objectRecord(body.patch);
      const dryRun = body.dry_run === true;
      const maxRows = normalizeBulkMaxRows(body.max_rows);
      const mode = cleanText(filters.mode) === "rateware" ? "rateware" : "staging";
      if (!Object.keys(patchInput).length) return jsonResponse({ error: "Bulk update patch is required." }, 400);
      if (mode === "rateware" && patchInput.status !== undefined) {
        return jsonResponse({ error: "Filtered Rateware updates cannot change approved status." }, 400);
      }

      if (!dryRun) {
        const preview = await fetchRateRowIdsByFilter(supabase, filters, { limit: 1, ownerEmail: user.owner_email });
        requirePreviewCountForFilteredBulk(body, preview.database_count || 0, `${mode} filtered rate update`);
      }
      const filtered = dryRun
        ? await fetchRateRowIdsByFilter(supabase, filters, { limit: 1, ownerEmail: user.owner_email })
        : await collectRateRowIdsByFilter(supabase, filters, { maxRows, ownerEmail: user.owner_email });
      const ids = filtered.ids;
      if (dryRun) {
        return jsonResponse({
          matched: filtered.database_count || ids.length,
          database_count: filtered.database_count,
          hard_limit_reached: false,
          max_rows: maxRows
        });
      }
      if (!ids.length) {
        return jsonResponse({
          matched: 0,
          targeted: 0,
          updated: 0,
          remaining: 0,
          completed: true,
          rows: []
        });
      }

      const requiresRowSpecificPatch = patchInput.vendor_domain !== undefined
        || patchInput.trailer !== undefined
        || patchInput.hazmat !== undefined
        || patchInput.temperature_controlled !== undefined;
      const updatedRows: Record<string, unknown>[] = [];

      if (requiresRowSpecificPatch) {
        const currentRows = await fetchRateRowsForIds(supabase, ids, BULK_RATE_ROW_SELECT, user.owner_email);
        for (const current of currentRows) {
          const patch = normalizeStagingPatch(patchInput, current || {});
          Object.assign(patch, await vendorLinkPatch(supabase, user, patchInput, current || {}));
          if (mode === "rateware") delete patch.status;
          if (!Object.keys(patch).length) continue;

          const result = await supabase
            .from("rate_staging")
            .update(patch)
            .eq("id", current.id)
            .eq("owner_email", user.owner_email)
            .select("id,status")
            .single();
          if (result.error) throw result.error;
          updatedRows.push(result.data);
        }
      } else {
        const patch = normalizeStagingPatch(patchInput, {});
        if (mode === "rateware") delete patch.status;
        if (!Object.keys(patch).length) return jsonResponse({ error: "No valid bulk updates provided." }, 400);

        for (const chunk of chunkValues(ids, 500)) {
          const result = await supabase
            .from("rate_staging")
            .update(patch)
            .eq("owner_email", user.owner_email)
            .in("id", chunk)
            .select("id,status");
          if (result.error) throw result.error;
          updatedRows.push(...(result.data || []));
        }
      }

      await tryWriteAuditLog(
        supabase,
        user,
        `${mode}.bulk_update_filtered`,
        "rate_staging",
        ids.slice(0, 50).join(","),
        `Updated ${updatedRows.length} ${mode} row(s) using active filters`,
        {
          ids_count: ids.length,
          database_count: filtered.database_count,
          updated_count: updatedRows.length,
          changed_fields: Object.keys(patchInput),
          filters,
          hard_limit_reached: filtered.hard_limit_reached
        }
      );

      return jsonResponse({
        matched: filtered.database_count || ids.length,
        targeted: ids.length,
        updated: updatedRows.length,
        rows: updatedRows.slice(0, 100),
        remaining: Math.max(0, (filtered.database_count || ids.length) - ids.length),
        completed: ids.length >= (filtered.database_count || ids.length),
        max_rows: maxRows,
        hard_limit_reached: filtered.hard_limit_reached
      });
    }

    if (body.action === "archive_staging") {
      const ids = normalizeBulkIds(body.ids, { label: "Staging row ids", limit: BULK_SELECTED_ID_LIMIT });
      if (!ids.length) return jsonResponse({ error: "At least one staging row id is required." }, 400);
      requireBulkConfirmation(body, {
        action: "archive_staging",
        label: "Staging archive",
        count: ids.length
      });

      const result = await supabase
        .from("rate_staging")
        .update({ status: "archived" })
        .eq("owner_email", user.owner_email)
        .in("id", ids)
        .select("id");
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "staging.archive", "rate_staging", ids.slice(0, 50).join(","),
        `Archived ${result.data?.length || 0} staging row(s)`, { requested: ids.length, affected: result.data?.length || 0 });
      return jsonResponse({ updated: result.data?.length || 0, rows: result.data || [] });
    }

    if (body.action === "remove_staging") {
      const ids = normalizeBulkIds(body.ids, { label: "Staging row ids", limit: BULK_SELECTED_ID_LIMIT });
      if (!ids.length) return jsonResponse({ error: "At least one staging row id is required." }, 400);
      requireBulkConfirmation(body, {
        action: "remove_staging",
        label: "Staging remove",
        count: ids.length
      });

      const result = await supabase
        .from("rate_staging")
        .delete()
        .eq("owner_email", user.owner_email)
        .in("id", ids)
        .select("id");
      if (result.error) throw result.error;
      await tryWriteAuditLog(supabase, user, "staging.remove", "rate_staging", ids.slice(0, 50).join(","),
        `Removed ${result.data?.length || 0} staging row(s)`, { requested: ids.length, affected: result.data?.length || 0 });
      return jsonResponse({ removed: result.data?.length || 0, rows: result.data || [] });
    }

    if (body.action === "save_location_alias") {
      const result = await saveRatewareLocationAlias(supabase, user, body);
      return jsonResponse(result);
    }

    if (body.action === "search_staging_locations") {
      const search = (cleanText(body.search) || "").replace(/[(),%_]/g, " ").trim();
      const country = cleanText(body.country)?.toUpperCase();
      const limit = Math.min(Math.max(Number(body.limit) || 20, 1), 50);
      if (search.length < 2) return jsonResponse({ rows: [] });
      let query = supabase
        .from("rateware_locations")
        .select("id,source,raw_value,zip_prefix,metro_city,city,state_code,state_name,country,market,region")
        .eq("active", true)
        .or([
          `raw_value.ilike.%${search}%`,
          `zip_prefix.ilike.%${search}%`,
          `city.ilike.%${search}%`,
          `metro_city.ilike.%${search}%`,
          `state_code.ilike.%${search}%`,
          `state_name.ilike.%${search}%`,
          `market.ilike.%${search}%`,
          `region.ilike.%${search}%`
        ].join(","))
        .order("raw_value", { ascending: true })
        .order("id", { ascending: true })
        .limit(limit * 4);
      if (["MX", "US", "CA", "UNKNOWN"].includes(country || "")) query = query.eq("country", country);
      const result = await query;
      if (result.error) throw result.error;
      const unique = new Map<string, Record<string, unknown>>();
      for (const location of result.data || []) {
        const option = locationOptionPayload(location);
        const key = [option.country, option.city, option.state_code, option.zip_prefix, option.market].map(cleanText).join("|");
        if (!unique.has(key)) unique.set(key, option);
        if (unique.size >= limit) break;
      }
      return jsonResponse({ rows: [...unique.values()] });
    }

    if (body.action === "list_staging_options") {
      const managedOptionCategories = new Set(["equipment", "trailer", "config", "operation", "service", "driver", "mx_border_crossing", "us_border_crossing", "border_crossing"]);
      const [catalogRows, locations, borderPairs, vendors] = await Promise.all([
        fetchAllManagedCatalogRows(supabase, null),
        supabase
          .from("rateware_locations")
          .select("id,source,raw_value,zip_prefix,metro_city,city,state_code,state_name,country,market,region")
          .eq("active", true)
          .order("country", { ascending: false })
          .order("market", { ascending: true })
          .limit(250),
        supabase
          .from("border_crossing_pairs")
          .select("mx_city,mx_state,us_city,us_state,crossing_name")
          .eq("active", true)
          .order("default_rank", { ascending: true })
          .limit(200),
        supabase
          .from("vendors")
          .select("vendor_name,domain,primary_email,base_stage,status")
          .eq("owner_email", user.owner_email)
          .limit(1000)
      ]);

      for (const result of [locations, borderPairs, vendors]) {
        if (result.error) throw result.error;
      }

      const categoryMaps: Record<string, Map<string, { value: string; source: string }>> = {};
      const catalogData = catalogRows
        .filter((item) => managedOptionCategories.has(String(item.category)))
        .filter((item) => isManualCatalogOwnedBy(item, user));
      for (const item of catalogData) {
        const category = String(item.category);
        const value = cleanText(item.normalized_value || item.raw_value || item.code);
        if (!value) continue;
        if (!categoryMaps[category]) categoryMaps[category] = new Map();
        const existing = categoryMaps[category].get(value);
        if (!existing || sourceRank(item.source) < sourceRank(existing.source)) {
          categoryMaps[category].set(value, { value, source: String(item.source || "") });
        }
      }

      const categories: Record<string, string[]> = {};
      for (const category of Object.keys(categoryMaps)) {
        categories[category] = [...categoryMaps[category].values()]
          .map((item) => item.value)
          .sort((a, b) => a.localeCompare(b));
      }

      const locationMap = new Map<string, Record<string, unknown>>();
      for (const location of locations.data || []) {
        const value = cleanText(location.raw_value || location.metro_city || [location.city, location.state_code].filter(Boolean).join(", "));
        if (!value) continue;
        const cityKey = String(location.city || location.metro_city || value).trim().toUpperCase();
        const stateKey = String(location.state_code || location.state_name || "").trim().toUpperCase();
        const key = `${cityKey}|${stateKey}|${location.market || ""}`;
        const existing = locationMap.get(key);
        if (!existing || optionQuality(location) > optionQuality(existing)) {
          locationMap.set(key, locationOptionPayload(location));
        }
      }

      const locationOptions = [...locationMap.values()]
        .sort((a, b) => String(a.label || a.value).localeCompare(String(b.label || b.value)))
        .slice(0, 5000);

      const manualMxCrossings = (categoryMaps.mx_border_crossing ? [...categoryMaps.mx_border_crossing.values()].map((item) => item.value) : []);
      const manualUsCrossings = (categoryMaps.us_border_crossing ? [...categoryMaps.us_border_crossing.values()].map((item) => item.value) : []);
      const manualGenericCrossings = (categoryMaps.border_crossing ? [...categoryMaps.border_crossing.values()].map((item) => item.value) : []);

      const mxCrossings = Array.from(new Set([
        ...manualMxCrossings,
        ...manualGenericCrossings,
        ...(borderPairs.data || []).map((pair) => [pair.mx_city, pair.mx_state].filter(Boolean).join(", "))
      ].filter(Boolean))).sort((a, b) => a.localeCompare(b));

      const usCrossings = Array.from(new Set((borderPairs.data || [])
        .map((pair) => [pair.us_city, pair.us_state].filter(Boolean).join(", "))
        .concat(manualUsCrossings, manualGenericCrossings)
        .filter(Boolean))).sort((a, b) => a.localeCompare(b));

      const vendorOptions = (vendors.data || []).flatMap((vendor) => {
        const label = [vendor.vendor_name, vendor.primary_email, vendor.base_stage, vendor.status].filter(Boolean).join(" | ");
        return [
          vendor.domain ? { value: vendor.domain, label } : null,
          vendor.primary_email ? { value: vendor.primary_email, label } : null
        ].filter(Boolean);
      });

      return jsonResponse({
        categories,
        locations: locationOptions,
        vendors: vendorOptions,
        mx_crossings: mxCrossings,
        us_crossings: usCrossings,
        currencies: ["USD", "MXN", "CAD"]
      });
    }

    if (body.action === "update_staging") {
      const currentResult = await supabase
        .from("rate_staging")
        .select("trailer,hazmat,temperature_controlled,vendor_id,vendor_domain,status")
        .eq("id", body.id)
        .eq("owner_email", user.owner_email)
        .single();
      if (currentResult.error) throw currentResult.error;

      const patchInput = objectRecord(body.patch);
      const currentRow = objectRecord(currentResult.data);
      const patch = normalizeStagingPatch(patchInput, currentRow);
      Object.assign(patch, await vendorLinkPatch(supabase, user, patchInput, currentRow));
      if (!Object.keys(patch).length) return jsonResponse({ error: "No staging updates provided." }, 400);

      const result = await supabase
        .from("rate_staging")
        .update(patch)
        .eq("id", body.id)
        .eq("owner_email", user.owner_email)
        .select("*, vendors(vendor_name, domain, primary_email, base_stage, status)")
        .single();
      if (result.error) throw result.error;
      const priorStatus = cleanText(currentResult.data?.status);
      const nextStatus = cleanText(result.data?.status);
      if (priorStatus !== nextStatus || nextStatus === "approved") {
        await tryWriteAuditLog(
          supabase,
          user,
          nextStatus === "approved" ? "rateware.approve" : "staging.status_update",
          "rate_staging",
          body.id,
          nextStatus === "approved" ? "Approved staging row into Rateware" : `Updated staging row status to ${nextStatus}`,
          {
            prior_status: priorStatus,
            next_status: nextStatus,
            changed_fields: Object.keys(patch)
          }
        );
      }
      return jsonResponse({ row: result.data });
    }

    if (body.action === "bulk_update_staging") {
      const ids = normalizeBulkIds(body.ids, { label: "Staging row ids", limit: BULK_SELECTED_ID_LIMIT });
      if (!ids.length) return jsonResponse({ error: "At least one staging row id is required." }, 400);
      requireBulkConfirmation(body, {
        action: "bulk_update_staging",
        label: "Staging selected bulk update",
        count: ids.length
      });
      const patchInput = objectRecord(body.patch);
      if (!Object.keys(patchInput).length) return jsonResponse({ error: "No staging updates provided." }, 400);

      const currentRows = await fetchRateRowsForIds(
        supabase,
        ids,
        "id,trailer,hazmat,temperature_controlled,vendor_id,vendor_domain,status",
        user.owner_email
      );
      const updatedRows: Record<string, unknown>[] = [];
      for (const current of currentRows) {
        const patch = normalizeStagingPatch(patchInput, current || {});
        Object.assign(patch, await vendorLinkPatch(supabase, user, patchInput, current || {}));
        if (!Object.keys(patch).length) continue;
        const result = await supabase
          .from("rate_staging")
          .update(patch)
          .eq("id", current.id)
          .eq("owner_email", user.owner_email)
          .select("id,status")
          .single();
        if (result.error) throw result.error;
        updatedRows.push(result.data);
      }

      await tryWriteAuditLog(
        supabase,
        user,
        "staging.bulk_update",
        "rate_staging",
        ids.slice(0, 50).join(","),
        `Bulk updated ${updatedRows.length} staging row(s)`,
        { ids_count: ids.length, changed_fields: Object.keys(patchInput) }
      );
      return jsonResponse({ updated: updatedRows.length, rows: updatedRows });
    }

    return jsonResponse({ error: "Unknown action." }, 400);
  } catch (error) {
    const errorInfo = apiErrorInfo(error);
    const errorMessage = safeOperationalError(errorInfo.message);
    const errorDetails = safeOperationalValue(errorInfo.details, 900);
    const errorHint = safeOperationalValue(errorInfo.hint, 700);
    const errorStage = safeOperationalValue(errorInfo.stage, 160);
    const errorTable = safeOperationalValue(errorInfo.table, 120);
    const errorConstraint = safeOperationalValue(errorInfo.constraint, 160);
    const errorCauseChain = safeOperationalList(errorInfo.cause_chain, 900);
    const errorCause = errorCauseChain.find((value) => value !== errorMessage) || null;
    const incidentId = crypto.randomUUID();
    const failedApiAction = cleanText(body.action) || "unknown";
    const errorStatus = apiErrorStatus(errorInfo);
    console.error(JSON.stringify({
      event: "rateware_api.error",
      incident_id: incidentId,
      action: failedApiAction,
      status: errorStatus,
      actor: auditUser ? {
        owner_email: auditUser.owner_email,
        organization_id: auditUser.organization_id
      } : null,
      error: {
        message: errorMessage,
        cause: errorCause,
        cause_chain: errorCauseChain,
        code: safeOperationalValue(errorInfo.code, 80),
        details: errorDetails,
        hint: errorHint,
        stage: errorStage,
        table: errorTable,
        constraint: errorConstraint,
        name: safeOperationalValue(errorInfo.name, 80),
        stack: safeOperationalValue(errorInfo.stack, 2400)
      }
    }));
    if (auditSupabase && auditUser) {
      try {
        const failedAction = failedApiAction === "generate_outreach_drafts" ? "outreach_queue.error" : "api.error";
        const failedEntityType = failedAction === "outreach_queue.error" ? "outreach_queue" : "rateware_api";
      await tryWriteAuditLog(
          auditSupabase,
          auditUser,
          failedAction,
          failedEntityType,
          failedApiAction,
          failedAction === "outreach_queue.error"
            ? "Outreach draft queue failed"
            : `Rateware API action failed: ${failedApiAction}`,
          {
            incident_id: incidentId,
            action: failedApiAction,
            status: errorStatus,
            error: errorMessage,
            cause: errorCause,
            cause_chain: errorCauseChain,
            code: safeOperationalValue(errorInfo.code, 80),
            details: errorDetails,
            hint: errorHint,
            stage: errorStage,
            table: errorTable,
            constraint: errorConstraint,
            name: safeOperationalValue(errorInfo.name, 80)
          }
        );
      } catch (_) {
        // Avoid masking the original API error if audit persistence is unavailable.
      }
    }
    return jsonResponse({
      error: errorMessage,
      cause: errorCause,
      code: safeOperationalValue(errorInfo.code, 80),
      details: errorDetails,
      hint: errorHint,
      incident_id: incidentId,
      action: failedApiAction,
      stage: errorStage
    }, errorStatus);
  }
});
